package com.ll.collection;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.*;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;

// The persistent "what I own" ledger - Loadout Lab's first differentiator.
// <p>Container snapshots (equipment, inventory, bank, looting bag), each
// replaced wholesale when its container is seen, merged on demand into one
// itemId → quantity view. Persisted through RuneLite's ConfigManager so the
// ledger survives sessions: your bank from LAST visit still counts today,
// no re-scan required (unlike per-session scanners).
// <p>Scoping: RuneLite config profiles already isolate the backing
// .properties per profile; on top of that, keys carry a world-type prefix so
// a leagues/seasonal login never pollutes the standard-world ledger.
// <p>Write discipline (learned on goal-planner): saves are per-snapshot and
// only when that snapshot actually changed - callers coalesce container
// events per tick before calling {@link #update}.
// <p>Item ids are stored RAW. Variant canonicalization (degraded/charged
// forms mapping to the engine's canonical gear ids via equipment aliases)
// happens at query time once the data pipeline vendors the alias table.
public class CollectionLedger implements ScopedStore {
static final String CONFIG_GROUP = "loadoutlab";
static final TypeToken<Map<Integer, Integer>> MAP_TYPE = new TypeToken<Map<Integer, Integer>>() {};

// Ledger sources, each persisted under its own key.
@lombok.RequiredArgsConstructor
public enum Source {
    EQUIPMENT("equipment", net.runelite.api.InventoryID.EQUIPMENT.getId()),
    INVENTORY("inventory", net.runelite.api.InventoryID.INVENTORY.getId()), BANK("bank", net.runelite.api.InventoryID.BANK.getId()),
    // Seen when the bag is opened or checked; vital for UIM accounts.
    // The classic InventoryID enum lacks the newer containers; the
    // gameval ids are the authoritative modern constants.
    LOOTING_BAG("lootingBag", InventoryID.LOOTING_BAG),
    // POH costume storage: one shared container covering the armour
    // case, wardrobes, treasure chest, and cape rack, seen when a
    // costume storage interface is opened.
    POH_COSTUMES("pohCostumes", InventoryID.POH_COSTUMES),
    // Not container-backed: filled units' default items, read from
    // the STASH chart (see LoadoutLabPlugin.scanStashChart). The -1
    // container sentinel makes the per-tick drain's null-container
    // check clear a stray dirty flag, and keeps STASH out of the
    // {@link #forContainer} reverse lookup.
    STASH("stash", -1),
    // The rune pouch: varbit-backed (RunePouchScan), never a container.
    RUNE_POUCH("runePouch", -1),
    // Sailing boat cargo holds, one container per boat slot.
    CARGO_HOLD_1("cargoHold1", InventoryID.SAILING_BOAT_1_CARGOHOLD), CARGO_HOLD_2("cargoHold2", InventoryID.SAILING_BOAT_2_CARGOHOLD),
    CARGO_HOLD_3("cargoHold3", InventoryID.SAILING_BOAT_3_CARGOHOLD), CARGO_HOLD_4("cargoHold4", InventoryID.SAILING_BOAT_4_CARGOHOLD),
    CARGO_HOLD_5("cargoHold5", InventoryID.SAILING_BOAT_5_CARGOHOLD);

    final String key;
    final int containerId;

    // The item-container id this source is scanned from, or -1 when
    // the source is not container-backed (STASH).
    public int containerId() { return containerId; }

    // Reverse lookup: the source scanned from {@code containerId}, or
    // null when no source uses it. Callers pass an UNMASKED container
    // id (the 0x8000 modified-container bit already stripped).
    public static Source forContainer(int containerId) {
        // Guard the STASH sentinel: without it, -1 would resolve to
        // STASH instead of "no such container".
        return containerId < 0 ? null : Arrays.stream(values()).filter(s -> s.containerId == containerId).findFirst().orElse(null);
    }

    // The persisted config-key segment; also the storage name in the
    // storages-response PluginMessage (see StoragesApi).
    public String key() { return key; }
}

final ConfigManager cfg;
final Gson gson;

// "std" or "seasonal" - set on login before any update/load.
String ws = "std";

final Map<Source, Map<Integer, Integer>> snapshots = new HashMap<>();

// Cached fingerprint of the merged view; recomputed lazily.
transient Integer fingerprint;

public CollectionLedger(ConfigManager cfg, Gson gson) {
    this.cfg = cfg;
    this.gson = gson;
    for (Source s : Source.values()) snapshots.put(s, new HashMap<>());
}

// Point the ledger at a world scope ("std" or "seasonal") and load that
// scope's persisted snapshots, replacing in-memory state.
public void loadScope(String scope) {
    ws = scope;
    for (Source s : Source.values()) {
        // One-time adoption of pre-account-scoping data ("std.*"): the
        // FIRST character to load it takes it and the legacy entry is
        // removed. Copying instead of moving is what let a second account
        // open on the main's scanned bank (field report 2026-08-26).
        // A corrupt entry starts that snapshot fresh rather than failing.
        int dot = scope.indexOf('.');
        String legacy = (dot > 0 ? scope.substring(0, dot) : scope) + ".collection." + s.key;
        Map<Integer, Integer> loaded = ScopedKeys.parse(gson,
            ScopedKeys.adopt(cfg, CONFIG_GROUP, key(s), legacy), MAP_TYPE.getType());
        snapshots.put(s, loaded != null ? loaded : new HashMap<>());
    }
    fingerprint = null;
}

// Replace one source's snapshot. Persists only when the content actually
// changed; returns true in that case (callers use it to invalidate caches).
public boolean update(Source source, Map<Integer, Integer> items) {
    Map<Integer, Integer> next = new HashMap<>(items);
    if (next.equals(snapshots.get(source))) return false;
    snapshots.put(source, next);
    cfg.setConfiguration(CONFIG_GROUP, key(source), gson.toJson(next, MAP_TYPE.getType()));
    fingerprint = null;
    return true;
}

// One source's current snapshot, read-only (itemId → quantity).
public Map<Integer, Integer> snapshot(Source source) { return Collections.unmodifiableMap(snapshots.get(source)); }

// Merged itemId → total quantity across all sources.
public Map<Integer, Integer> owned() {
    Map<Integer, Integer> merged = new HashMap<>();
    snapshots.values().forEach(snap -> snap.forEach((id, n) -> merged.merge(id, n, Integer::sum)));
    return merged;
}

// True once a bank snapshot exists (this session or any previous one).
public boolean bankKnown() { return !snapshots.get(Source.BANK).isEmpty(); }

// Stable fingerprint of the merged view - the optimizer cache key
// component. Changes iff ownership actually changed.
public int fingerprint() {
    if (fingerprint == null) fingerprint = owned().hashCode();
    return fingerprint;
}

public String key(Source s) { return ws + ".collection." + s.key; }
}

package com.ll.collection;

import lombok.Getter;
import java.util.*;

// Live link to "Dude, Where's My Stuff?" over RuneLite's PluginMessage
// bus (DWMS ships the contract since 2.11.5 - the old best-effort config
// read is retired).
// <p>Contract (version 1, authored upstream): we post a request
// (namespace "dudewheresmystuff", name "storages-request", data
// {"source": "Loadout Lab"}); DWMS replies with "storages-response"
// carrying "target" (our source echoed back - responses meant for other
// plugins are ignored), "version" and "storages", a list of maps with
// "category"/"name"/"lastUpdated" plus "items" ({"id": canonical item
// id, "quantity"}). Requests are fire-and-forget: an absent or older
// DWMS never replies and {@link #isLive()} stays false - its storages
// then simply do not count as owned.
// <p>Responses arrive on DWMS's client thread; parsing is defensive
// (drop, never guess) and the snapshot swap is a volatile write, so no
// marshalling is needed here.
public class DwmsLink {
// PluginMessage namespace = DWMS's config group, per RuneLite convention.
public static final String DWMS_NAMESPACE = "dudewheresmystuff";
public static final String REQUEST_NAME = "storages-request";
public static final String RESPONSE_NAME = "storages-response";
// The one contract version this consumer understands; anything else
// is rejected so the fallback under-counts rather than miscounts.
static final int SUPPORTED_VERSION = 1;
// Our display name - sent as "source", echoed back as "target".
static final String SOURCE = "Loadout Lab";

volatile Map<Integer, Integer> items = Map.of();
// Response "category" (carryable/death/poh/stash/world...) -> items -
// the location-hint provenance families.
volatile Map<String, Map<Integer, Integer>> families = Map.of();
// True once DWMS has answered for the current identity.
@Getter
volatile boolean live;

// The request payload for PluginMessage(DWMS_NAMESPACE, REQUEST_NAME, ...).
public static Map request() { return Collections.singletonMap("source", SOURCE); }

// Consume a candidate storages-response payload (namespace/name gating
// happens at the caller). Returns true - and replaces the snapshot -
// only for a well-formed version-1 response addressed to us.
public boolean accept(Map data) {
    if (data == null || !SOURCE.equals(data.get("target")) || !(data.get("version") instanceof Number)
        || ((Number) data.get("version")).intValue() != SUPPORTED_VERSION || !(data.get("storages") instanceof List)) {
        return false;
    }
    Map<Integer, Integer> next = new HashMap<>();
    Map<String, Map<Integer, Integer>> nextFamilies = new HashMap<>();
    for (Object storage : (List<?>) data.get("storages")) {
        if (!(storage instanceof Map)) continue;
        Object storageItems = ((Map<?, ?>) storage).get("items");
        if (!(storageItems instanceof List)) continue;
        Object category = ((Map<?, ?>) storage).get("category");
        Map<Integer, Integer> family = nextFamilies.computeIfAbsent(
            category instanceof String ? (String) category : "world", k -> new HashMap<>());
        for (Object item : (List<?>) storageItems) {
            mergeItem(item, next);
            mergeItem(item, family);
        }
    }
    items = next.isEmpty() ? Map.of() : next;
    families = nextFamilies.isEmpty() ? Map.of() : nextFamilies;
    live = true;
    return true;
}

// One {"id", "quantity"} entry; anything malformed is dropped.
static void mergeItem(Object item, Map<Integer, Integer> into) {
    if (!(item instanceof Map)) return;
    Object id = ((Map<?, ?>) item).get("id");
    Object quantity = ((Map<?, ?>) item).get("quantity");
    if (!(id instanceof Number) || !(quantity instanceof Number)) return;
    int itemId = ((Number) id).intValue();
    long amount = ((Number) quantity).longValue();
    if (itemId <= 0 || amount <= 0) return;
    into.merge(itemId, (int) Math.min(amount, Integer.MAX_VALUE), (a, b) -> (int) Math.min((long) a + b, Integer.MAX_VALUE));
}

// A different account/profile: nothing from the previous one survives.
public void reset() {
    items = Map.of();
    families = Map.of();
    live = false;
}

// Category -> merged items, for the location-hint provenance.
public Map<String, Map<Integer, Integer>> families() { return families; }

// Item id -> quantity from the latest response, merged across storages.
public Map<Integer, Integer> snapshot() { return items; }

// Distinct live item count - the panel's provenance line.
int count() { return items.size(); }

// Fold the live items into an owned map (quantities sum).
public Map<Integer, Integer> mergeInto(Map<Integer, Integer> owned) {
    items.forEach((id, n) -> owned.merge(id, n, Integer::sum));
    return owned;
}
}

package com.ll.collection;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.*;
import net.runelite.client.config.ConfigManager;

// A scoped set of item ids: the exclusions ("excludedItems"), the dream
// items ("dreamItems") and the protect-only items ("protectOnlyItems").
public class IdSetStore implements ScopedStore {
static final String CONFIG_GROUP = "loadoutlab";

ConfigManager cfg;
Gson gson;
Set<Integer> ids = new LinkedHashSet<>();
// "std" / "seasonal", plus ".<accountHash>" once a character is known.
// Field report 2026-08-25: switching from a main to a test account showed
// the SAME exclude and sim lists, because these keys were global while the
// bank ledger next door was already per-character.
String ws;

// The unscoped key this store used before 0.4.1 - read once so an
// existing install keeps its list when the key gains the account hash.
String lk;

public IdSetStore(ConfigManager cfg, Gson gson, String lk) {
    this.cfg = cfg;
    this.gson = gson;
    this.lk = lk;
    load();
}

String key() { return ScopedKeys.key(ws, lk); }

public synchronized void loadScope(String scope) {
    ws = scope;
    load();
}

public synchronized void reload() { load(); }

final void load() {
    ids.clear();
    Set<Integer> stored = ScopedKeys.parse(gson, ScopedKeys.read(cfg, CONFIG_GROUP, ws, lk),
        new TypeToken<Set<Integer>>(){}.getType());
    if (stored != null) ids.addAll(stored);
}

final void save() { cfg.setConfiguration(CONFIG_GROUP, key(), gson.toJson(ids)); }

public synchronized boolean toggle(int itemId) {
    boolean added = !ids.remove(itemId) && ids.add(itemId);
    save();
    return added;
}

public synchronized void clear() {
    ids.clear();
    save();
}

public synchronized boolean contains(int itemId) { return ids.contains(itemId); }

public synchronized Set<Integer> snapshot() { return new LinkedHashSet<>(ids); }
}

package com.ll.collection;

import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

// Where each owned item lives - the per-source view the flattened owned
// map erases. Built from the ledger's source snapshots plus the manual
// stored-elsewhere list and the DWMS import families; lookups are
// variant-aware, so a STASH'd ornamented variant answers for the base id
// the optimizer suggests.
@lombok.AllArgsConstructor
public class ItemLocations {
// Suffix convention for origins the DWMS import contributed.
public static final String VIA_DWMS = " (via DWMS)";

// Origin label -> itemId -> quantity, in display order.
Map<String, Map<Integer, Integer>> origins;

// id -> all ids interchangeable with it for ownership (incl. itself);
// null means exact-id matching only (dataset still loading).
Function<Integer, Set<Integer>> equivalents;

// Origin labels holding this item or an interchangeable variant.
List<String> where(int itemId) {
    Set<Integer> ids = equivalents == null ? Set.of(itemId) : equivalents.apply(itemId);
    return origins.entrySet().stream().filter(origin -> ids.stream().anyMatch(origin.getValue()::containsKey))
        .map(Map.Entry::getKey).collect(Collectors.toList());
}

// Legend label for the item's primary origin: the first origin in
// display order, with DWMS families folded onto their native twin
// ("STASH (via DWMS)" -> "STASH") and DWMS-only families bucketed as
// "DWMS". "" when the location is unknown.
public String primary(int itemId) {
    List<String> where = where(itemId);
    if (where.isEmpty()) return "";
    String label = where.get(0);
    if (!label.endsWith(VIA_DWMS)) return label;
    String base = label.substring(0, label.length() - VIA_DWMS.length());
    switch (base) {
        case "POH costume room":
        case "STASH":
        case "cargo hold":
            return base;
        default:
            return "DWMS";
    }
}

}

package com.ll.collection;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.ll.data.*;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Stream;
import net.runelite.client.config.ConfigManager;
import com.ll.model.CommandEngine;
import static com.ll.data.Monster.*;

// Per-monster user profiles: the preferences the optimizer cannot infer,
// remembered per mob. Each profile carries PINS (slot -> item the player
// always brings THERE), a free-text NOTE, and extra ITEMS unioned into
// the Show-in-bank / Filter-bank sets (trip supplies no suggestion would
// contain). Pins and filter items are SCOPED: "ALL" applies to every
// style card, or a specific style ("MELEE"/"RANGED"/"MAGIC") applies to
// that card only - a super combat for melee, a ranged potion for ranged.
// The effective view overlays ALL with the style scope (style wins a
// pin-slot collision).
// <p>Scope-free config in v1 like dreams/exclusions: trip preferences
// follow the player. Empty profiles are pruned on save.
public class MonsterProfileStore implements CommandEngine.MobProfiles, ScopedStore {
static final String CONFIG_GROUP = "loadoutlab";
static final String KEY = "monsterProfiles";

// Per-character scope ("std"/"seasonal" plus ".<accountHash>"). Global
// before 0.4.1, which is why a main and a test account shared this list.
String ws;

String key() { return ScopedKeys.key(ws, KEY); }

public synchronized void loadScope(String scope) {
    ws = scope;
    load();
}
// The every-style scope key. Style scopes use Style names.
public static final String ALL = "ALL";

// Serialized form: scope -> slot-name -> id for pins; scope -> id ->
// display name for filter items (names captured at add time - id
// resolution later needs the client thread).
Stored stored(int monsterId) {
    return profiles.computeIfAbsent(profileIdOf(monsterId), id -> new Stored());
}

Stored get(int monsterId) { return profiles.get(profileIdOf(monsterId)); }

static class Stored {
    Map<String, Map<String, Integer>> pins;
    String note;
    Map<String, Map<Integer, String>> filterItems;
    // Per-mob simulated items (id -> add-time name) - counted as
    // owned for THIS mob only.
    Map<Integer, String> sims;
    // Pinned autocast spell name for the magic card ("" / null = auto).
    String spell;
    // Pinned SPEC weapon id (0 / null = auto-pick).
    Integer spec;
    // Per-mob exclusions: scope -> item ids the suggestions here must
    // never contain (the global exclusion list handles "everywhere").
    Map<String, Set<Integer>> exclusions;
    // Per-mob trip-supply overrides: Trip category ->
    // mode/option key ("DETECT_BEST", "NONE", "SANFEW_SERUM"...).
    // Absent category = the wrench-panel default applies.
    Map<String, String> supplies;
    // Degrades chip: skip degradable gear here (null = panel default).
    Boolean skipDegradable;
}

Set<Integer> degradableIds = Set.of();

public synchronized void setDegradableIds(Set<Integer> ids) { degradableIds = ids; }

public synchronized boolean skipDegradable(int monsterId, boolean fallback) {
    return read(monsterId, p -> p.skipDegradable, fallback);
}

public synchronized void setSkipDegradable(int monsterId, boolean skip) {
    stored(monsterId).skipDegradable = skip;
    save();
}

ConfigManager cfg;
Gson gson;
Map<Integer, Stored> profiles = new HashMap<>();

public MonsterProfileStore(ConfigManager cfg, Gson gson) {
    this.cfg = cfg;
    this.gson = gson;
    load();
}

// Re-read from config - the active RuneLite profile may have changed.
// The reset-customisations control: every profile in this scope goes.
public synchronized void clear() {
    profiles.clear();
    save();
}

public synchronized void reload() { load(); }

void load() {
    profiles.clear();
    Map<Integer, Stored> stored = ScopedKeys.parse(gson, ScopedKeys.read(cfg, CONFIG_GROUP, ws, KEY),
        new TypeToken<Map<Integer, Stored>>(){}.getType());
    if (stored != null) {
        // Entries saved under a phase variant's synthetic id (before
        // 2026-10-14 every write keyed the lensed card's raw id) fold
        // into the real monster's profile; its own entry wins.
        stored.forEach((id, profile) -> {
            if (id < SYNTHETIC_ID_BASE) profiles.put(id, profile);
        });
        stored.forEach((id, profile) -> profiles.putIfAbsent(profileIdOf(id), profile));
    }
}

// A read-only copy, Map.of() for nothing.
static <K, V> Map<K, V> copyOf(Map<K, V> m) {
    return m == null || m.isEmpty() ? Map.of() : new LinkedHashMap<>(m);
}

// A profile field, or the fallback when the mob has no profile or the field is unset.
<T> T read(int monsterId, Function<Stored, T> field, T fallback) {
    Stored profile = get(monsterId);
    T value = profile == null ? null : field.apply(profile);
    return value == null ? fallback : value;
}

// One scope's inner collection of a scoped field, or null.
<V> V inner(int monsterId, Function<Stored, Map<String, V>> field, String scope) {
    Map<String, V> scoped = read(monsterId, field, null);
    return scoped == null ? null : scoped.get(scope);
}

// A scoped field for the manage menus: scope -> the copied inner
// collection, the empties dropped (the copy says null); Map.of() for none.
static <V, W> Map<String, W> byScope(Map<String, V> scoped, Function<V, W> copy) {
    if (scoped == null || scoped.isEmpty()) return Map.of();
    Map<String, W> out = new LinkedHashMap<>();
    scoped.forEach((scope, value) -> {
        W copied = value == null ? null : copy.apply(value);
        if (copied != null) out.put(scope, copied);
    });
    return out;
}

// Effective pins for one style card: ALL overlaid by the style scope.
public synchronized Map<Slot, Integer> pinsFor(int monsterId, String style) {
    Map<String, Map<String, Integer>> scoped = read(monsterId, p -> p.pins, Map.of());
    var pins = new EnumMap<Slot, Integer>(Slot.class);
    copyPins(scoped.get(ALL), pins);
    copyPins(scoped.get(style), pins);
    return pins.isEmpty() ? Map.of() : pins;
}

static void copyPins(Map<String, Integer> from, EnumMap<Slot, Integer> into) {
    if (from == null) return;
    for (var entry : from.entrySet()) {
        try {
            into.put(Slot.valueOf(entry.getKey()), entry.getValue());
        } catch (IllegalArgumentException ignored) {
            // Unknown slot name in config: drop that pin.
        }
    }
}

// Raw pins by scope, for the manage menu: scope -> slot -> id.
public synchronized Map<String, Map<Slot, Integer>> allPins(int monsterId) {
    return byScope(read(monsterId, p -> p.pins, null), slots -> {
        var pins = new EnumMap<Slot, Integer>(Slot.class);
        copyPins(slots, pins);
        return pins.isEmpty() ? null : pins;
    });
}

public synchronized void pin(int monsterId, String scope, Slot slot, int itemId) {
    Stored profile = stored(monsterId);
    if (profile.pins == null) profile.pins = new LinkedHashMap<>();
    profile.pins.computeIfAbsent(scope, s -> new LinkedHashMap<>()) .put(slot.name(), itemId);
    save();
}

public synchronized void unpin(int monsterId, String scope, Slot slot) {
    Map<String, Integer> slots = inner(monsterId, p -> p.pins, scope);
    if (slots != null) {
        slots.remove(slot.name());
        save();
    }
}

// The user's note for this monster ("" when none).
public synchronized String note(int monsterId) { return read(monsterId, p -> p.note, ""); }

public synchronized void setNote(int monsterId, String note) {
    Stored profile = stored(monsterId);
    profile.note = note == null || note.trim().isEmpty() ? null : note.trim();
    save();
}

// The pinned autocast spell for this monster ("" = auto-pick).
public synchronized String pinnedSpell(int monsterId) { return read(monsterId, p -> p.spell, ""); }

public synchronized void setPinnedSpell(int monsterId, String spellName) {
    Stored profile = stored(monsterId);
    profile.spell = spellName == null || spellName.trim().isEmpty() ? null : spellName.trim();
    save();
}

// The pinned SPEC weapon id for this monster (0 = auto-pick).
public synchronized int pinnedSpec(int monsterId) { return read(monsterId, p -> p.spec, 0); }

public synchronized void setPinnedSpec(int monsterId, int itemId) {
    Stored profile = stored(monsterId);
    profile.spec = itemId <= 0 ? null : itemId;
    save();
}


// Raw filter items by scope: scope -> id -> display name.
public synchronized Map<String, Map<Integer, String>> allFilterItems(int monsterId) {
    return byScope(read(monsterId, p -> p.filterItems, null), items -> items.isEmpty() ? null : copyOf(items));
}

// Effective per-mob exclusions for one style card: ALL plus the style
// scope. The caller unions in the global exclusion list.
public synchronized Set<Integer> exclusionsFor(int monsterId, String style) {
    Stored profile = get(monsterId);
    if (profile == null) return Set.of();
    var merged = new LinkedHashSet<Integer>();
    if (Boolean.TRUE.equals(profile.skipDegradable)) merged.addAll(degradableIds);
    for (String scope : new String[]{ALL, style}) {
        Set<Integer> ids = profile.exclusions == null ? null : profile.exclusions.get(scope);
        if (ids != null) merged.addAll(ids);
    }
    return merged.isEmpty() ? Set.of() : merged;
}

// Raw per-mob exclusions by scope, for the manage menu.
public synchronized Map<String, Set<Integer>> allExclusions(int monsterId) {
    return byScope(read(monsterId, p -> p.exclusions, null),
        ids -> ids.isEmpty() ? null : new LinkedHashSet<>(ids));
}

// Per-mob sims: counted as owned for THIS mob only.
public synchronized Set<Integer> simsFor(int monsterId) { return allSims(monsterId).keySet(); }

// Raw per-mob sims (id -> add-time name), for the manage menu.
public synchronized Map<Integer, String> allSims(int monsterId) {
    return copyOf(read(monsterId, p -> p.sims, null));
}

public synchronized void addSim(int monsterId, int itemId, String name) {
    Stored profile = stored(monsterId);
    if (profile.sims == null) profile.sims = new LinkedHashMap<>();
    profile.sims.put(itemId, name == null ? ("item " + itemId) : name);
    save();
}

public synchronized void removeMobSim(int monsterId, int itemId) {
    Map<Integer, String> sims = read(monsterId, p -> p.sims, null);
    if (sims != null) {
        sims.remove(itemId);
        save();
    }
}

// Per-mob trip-supply overrides (category -> mode/option key);
// empty when the wrench-panel defaults apply untouched.
public synchronized Map<String, String> supplyOverrides(int monsterId) {
    return copyOf(read(monsterId, p -> p.supplies, null));
}

// Set one category's override; null/empty choice returns the category
// to the wrench-panel default.
public synchronized void setSupplyOverride(int monsterId, String category, String choice) {
    if (choice == null || choice.isEmpty()) {
        Map<String, String> supplies = read(monsterId, p -> p.supplies, null);
        if (supplies != null) {
            supplies.remove(category);
            save();
        }
        return;
    }
    Stored profile = stored(monsterId);
    if (profile.supplies == null) profile.supplies = new LinkedHashMap<>();
    profile.supplies.put(category, choice);
    save();
}

public synchronized void exclude(int monsterId, String scope, int itemId) {
    Stored profile = stored(monsterId);
    if (profile.exclusions == null) profile.exclusions = new LinkedHashMap<>();
    profile.exclusions.computeIfAbsent(scope, s -> new LinkedHashSet<>()).add(itemId);
    save();
}

public synchronized void removeMobExclusion(int monsterId, String scope, int itemId) {
    Set<Integer> ids = inner(monsterId, p -> p.exclusions, scope);
    if (ids != null) {
        ids.remove(itemId);
        save();
    }
}

public synchronized void addFilterItem(int monsterId, String scope, int itemId, String name) {
    Stored profile = stored(monsterId);
    if (profile.filterItems == null) profile.filterItems = new LinkedHashMap<>();
    profile.filterItems.computeIfAbsent(scope, s -> new LinkedHashMap<>()) .put(itemId, name == null ? ("item " + itemId) : name);
    save();
}

public synchronized void removeMobFilter(int monsterId, String scope, int itemId) {
    Map<Integer, String> items = inner(monsterId, p -> p.filterItems, scope);
    if (items != null) {
        items.remove(itemId);
        save();
    }
}

void save() {
    Map<Integer, Stored> out = new LinkedHashMap<>();
    for (var entry : profiles.entrySet()) {
        Stored profile = entry.getValue();
        prune(profile.pins);
        prune(profile.filterItems);
        if (profile.exclusions != null) profile.exclusions.values().removeIf(s -> s == null || s.isEmpty());
        // EVERY field participates (field bug 2026-07-18: sims was
        // missing here, so a sims-only profile was judged empty and the
        // retainAll below erased the sim in the same call that added it
        // - "Sim here" appeared to do nothing).
        boolean empty = Stream.of(profile.pins, profile.filterItems, profile.exclusions, profile.sims, profile.supplies)
            .allMatch(m -> m == null || m.isEmpty()) && (profile.note == null || profile.note.isEmpty())
            && (profile.spell == null || profile.spell.isEmpty()) && profile.spec == null && profile.skipDegradable == null;
        if (!empty) out.put(entry.getKey(), profile);
    }
    profiles.keySet().retainAll(out.keySet());
    cfg.setConfiguration(CONFIG_GROUP, key(), gson.toJson(out));
}

static void prune(Map<String, ? extends Map<?, ?>> scoped) {
    if (scoped != null) scoped.values().removeIf(m -> m == null || m.isEmpty());
}
}

package com.ll.collection;

import com.google.gson.JsonObject;
import com.ll.data.Json;
import java.util.*;
import java.util.function.IntUnaryOperator;

// The bank's potion storage is varbits, not an item container: one
// POTIONSTORE_VILE_SIZE_* varbit per potion holding the doses stored.
// potion_storage.json maps each varbit the plugin cares about to the
// 4-dose item it detects (Andrew 2026-10-19: super antifires kept there
// were invisible, so Detect best said shield).
public class PotionStorage {
// varbit id -> 4-dose item id.
static final Map<Integer, Integer> BY_VARBIT = new LinkedHashMap<>();
// The master scroll book's scrolls (ISS-01M5VDZXT4W4D5DP468R5R7NSW): shown as the book when held only there.
static final Set<Integer> SCROLLS = new HashSet<>();

static {
    JsonObject root = Json.objectOrThrow("potion_storage.json");
    Json.ints(root, "_scrolls", SCROLLS);
    for (String key : root.keySet()) if (!key.startsWith("_")) BY_VARBIT.put(Integer.parseInt(key), root.get(key).getAsInt());
}


public static boolean tracks(int varbitId) { return BY_VARBIT.containsKey(varbitId); }

public static boolean isScroll(int itemId) { return SCROLLS.contains(itemId); }

// item id -> 4-dose equivalents, for every stored potion with doses.
public static Map<Integer, Integer> owned(IntUnaryOperator dosesOf) {
    Map<Integer, Integer> owned = new HashMap<>();
    BY_VARBIT.forEach((varbit, item) -> {
        int doses = dosesOf.applyAsInt(varbit);
        if (doses > 0) owned.merge(item, (doses + 3) / 4, Integer::sum);
    });
    return owned;
}
}

package com.ll.collection;

import java.util.*;
import java.util.function.IntUnaryOperator;

// The rune pouch as a ledger source (field report 2026-10-10: runes
// moved into the pouch vanished and Fire Wave fell off the magic set).
// The pouch is not an item container: each slot is a TYPE varbit (a key
// into the client's RUNEPOUCH_RUNE enum, 0 = empty) and a QUANTITY varbit.
// Pure over the two value arrays so the plugin's varbit reads stay thin.
public class RunePouchScan {

// itemId -> quantity for every filled slot; an empty or zero slot adds nothing.
public static Map<Integer, Integer> items(int[] types, int[] quantities, IntUnaryOperator typeToItem) {
    Map<Integer, Integer> out = new HashMap<>();
    for (int i = 0; i < types.length && i < quantities.length; i++) {
        if (types[i] > 0 && quantities[i] > 0) {
            int item = typeToItem.applyAsInt(types[i]);
            if (item > 0) out.merge(item, quantities[i], Integer::sum);
        }
    }
    return out;
}
}

package com.ll.collection;

import com.google.gson.Gson;
import java.lang.reflect.Type;
import net.runelite.client.config.ConfigManager;

// Per-character config keys, plus the one-time adoption of the pre-0.4.1
// unscoped entry.
// <p>Field report 2026-08-26: on an install upgraded from 0.4.0 the alt still
// showed the main's exclude list. The first cut fell back to the unscoped key
// whenever the scoped one was empty, which is true for EVERY new character -
// so every character adopted the main's list. Adoption has to happen once and
// then stop, which means MOVING the entry into the first character that loads
// it rather than copying it.
class ScopedKeys {

// A scope with no account hash behaves as the pre-0.4.1 bucket, so edits
// made before login are adopted by the first character instead of landing
// in a key nothing reads.
static String key(String scope, String lk) {
    return scope == null || scope.isEmpty() ? lk : scope + "." + lk;
}

// Stored JSON for this scope, adopting the legacy entry once.
static String read(ConfigManager cfg, String group, String scope, String lk) {
    return adopt(cfg, group, key(scope, lk), lk);
}

// A stored JSON value, or null when the entry is empty or corrupt (a
// corrupt entry starts the store fresh rather than failing the plugin).
static <T> T parse(Gson gson, String json, Type type) {
    try {
        return json == null || json.isEmpty() ? null : gson.fromJson(json, type);
    } catch (RuntimeException ex) { return null; }
}

// As {@link #read}, for a store whose legacy key is not simply the
// scoped key without its prefix.
static String adopt(ConfigManager cfg, String group, String key, String lk) {
    String json = cfg.getConfiguration(group, key);
    if (json != null && !json.isEmpty()) return json;
    if (key.equals(lk)) return null;
    String legacy = cfg.getConfiguration(group, lk);
    if (legacy == null || legacy.isEmpty()) return null;
    // A move, not a copy: the second character must find nothing here.
    cfg.setConfiguration(group, key, legacy);
    cfg.unsetConfiguration(group, lk);
    return legacy;
}
}

package com.ll.collection;

import com.google.gson.Gson;
import java.lang.reflect.Type;
import java.util.*;
import net.runelite.client.config.ConfigManager;

// A per-character map persisted as one JSON config entry: the always-filter
// list and the supply defaults share this exact shape (scoped key, load on
// scope change, unset when empty, corrupt JSON starts fresh).
abstract class ScopedMapStore<K, V> implements ScopedStore {
static final String CONFIG_GROUP = "loadoutlab";

ConfigManager cfg;
Gson gson;
String configKey;
Type type;
String ws;
Map<K, V> items = new LinkedHashMap<>();

ScopedMapStore(ConfigManager cfg, Gson gson, String configKey, Type type) {
    this.cfg = cfg;
    this.gson = gson;
    this.configKey = configKey;
    this.type = type;
    load();
}

String key() { return ScopedKeys.key(ws, configKey); }

// Per-character scope ("std"/"seasonal" plus ".<accountHash>").
public synchronized void loadScope(String scope) {
    ws = scope;
    load();
}

// Re-read from config - the active RuneLite profile may have changed.
public synchronized void reload() { load(); }

public synchronized void clear() {
    items.clear();
    save();
}

void load() {
    items.clear();
    Map<K, V> stored = ScopedKeys.parse(gson, ScopedKeys.read(cfg, CONFIG_GROUP, ws, configKey), type);
    if (stored != null) items.putAll(stored);
}

void save() {
    if (items.isEmpty()) {
        cfg.unsetConfiguration(CONFIG_GROUP, key());
        return;
    }
    cfg.setConfiguration(CONFIG_GROUP, key(), gson.toJson(items));
}
}

package com.ll.collection;

// A per-character store: re-keyed when the logged-in character changes.
public interface ScopedStore {
void loadScope(String scope);

// Re-read from config - the active RuneLite profile may have changed.
default void reload() {
}

// The reset-customisations control: a store that holds customisations
// wipes this scope's; bank memory (the ledger) is no customisation and stays.
default void clear() {
}
}

package com.ll.collection;

import com.ll.data.Json;
import java.util.*;
import java.util.function.IntUnaryOperator;

// Loadout Lab's half of the bidirectional storages contract: other
// plugins can ask US for the owned-gear ledger the same way we ask
// Dude, Where's My Stuff - identical request/response shape, each
// plugin under its own namespace (reciprocity decided 2026-07-11;
// the config keys in the README's "Tables sharing" section stay as the
// works-while-disabled fallback).
// <p>Request: namespace "loadoutlab", name "storages-request", data
// {"source": requesting plugin's display name (required)}. Response:
// name "storages-response" with "source" ("Loadout Lab"), "target"
// (the requester's source echoed), "version" (1), and "storages" -
// one entry per non-empty source with "category", "name",
// "lastUpdated" (-1; the ledger keeps no timestamps) and "items"
// ({"id": canonical item id, "quantity": Long}).
// <p>This class is the pure, testable part; the plugin gathers the
// snapshots and posts on the client thread (ids canonicalize there).
public class StoragesApi {
public static final String NAMESPACE = "loadoutlab";
public static final String REQUEST_NAME = "storages-request";
public static final String RESPONSE_NAME = "storages-response";
static final int VERSION = 1;
static final String SOURCE = "Loadout Lab";


// The validated requester name from a storages-request payload,
// or null when the request carries no usable source.
public static String requester(Map data) {
    if (data == null) return null;
    Object source = data.get("source");
    return source instanceof String && !((String) source).isEmpty() ? (String) source : null;
}

// One storage entry for the response: items canonicalized (variants
// that collapse to one id sum), non-positive entries dropped.
// Returns null when nothing survives - empty storages are omitted,
// matching the DWMS side of the contract.
public static Map storage(String category, String name, long lastUpdated,
    Map<Integer, Integer> items, IntUnaryOperator canonicalize) {
    Map<Integer, Long> canonical = new LinkedHashMap<>();
    for (var e : items.entrySet()) {
        if (e.getKey() <= 0 || e.getValue() <= 0) continue;
        canonical.merge(canonicalize.applyAsInt(e.getKey()), (long) e.getValue(), Long::sum);
    }
    if (canonical.isEmpty()) return null;
    List<Map> itemList = new ArrayList<>(canonical.size());
    for (var e : canonical.entrySet()) itemList.add(Json.map("id", e.getKey(), "quantity", e.getValue()));
    return Json.map("category", category, "name", name, "lastUpdated", lastUpdated, "items", itemList);
}

// The response envelope addressed back to the requester.
public static Map response(String target, List<Map> storages) {
    return Json.map("source", SOURCE, "target", target, "version", VERSION, "storages", storages);
}
}

package com.ll.collection;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.Map;
import net.runelite.client.config.ConfigManager;

// The GLOBAL trip-supply defaults, set from the grey filter chip's menu
// (field direction 2026-07-20: "set from the button instead of the panel").
// Every category defaults to DETECT_BEST - always on - so only categories
// the player changed are persisted; clearing back to Detect best removes
// the entry.
public class SupplyDefaultsStore extends ScopedMapStore<String, String> {
static final String KEY = "supplyDefaults";
public static final String DETECT_BEST = "DETECT_BEST";

public SupplyDefaultsStore(ConfigManager cfg, Gson gson) {
    super(cfg, gson, KEY, new TypeToken<Map<String, String>>(){}.getType());
}

// The category's default: DETECT_BEST (always on) unless changed.
public synchronized String choice(String category) { return items.getOrDefault(category, DETECT_BEST); }

public synchronized void setChoice(String category, String choice) {
    if (choice == null || choice.isEmpty() || DETECT_BEST.equals(choice)) {
        items.remove(category);
    } else items.put(category, choice);
    save();
}
}

package com.ll.command;

// A reversible user action on Loadout Lab's persistent state.
// <p>Commands carry the state needed to revert themselves at construction
// time - typically a snapshot of "before" values plus the parameters of the
// action - so applying the command does not depend on any external state
// that may have changed by the time {@link #revert()} runs.
// <p>Both {@link #apply()} and {@link #revert()} return a boolean. False
// means "the operation failed at the store level" (e.g. the entity it was
// trying to mutate is gone). The {@code CommandHistory} treats a false
// return on revert as a failed undo: it logs the failure and drops the
// entry from history rather than crashing or rolling further back.
// <p>{@link #getDescription()} is a short user-facing string for the
// undo/redo button tooltip ("Undo: Exclude Dragon dart").
// <p>Scan-driven mutations (bank/inventory/equipment snapshots, storage
// captures, DWMS imports) do NOT go through Command - they call the
// underlying store primitives directly so they never appear in undo
// history. Only deliberate user actions are undoable.
// <p>Ported from goal planner's {@code com.goalplanner.command} - keep the
// semantics in lockstep so the module stays shareable between the plugins.
public interface Command {
// Run the action. Returns true if it actually changed state.
boolean apply();

// Reverse the action. Returns true if the revert succeeded.
boolean revert();

// Short user-facing label, e.g. "Exclude Dragon dart".
String getDescription();
}

package com.ll.command;

import java.util.*;
import lombok.extern.slf4j.Slf4j;

// In-memory undo / redo stack for {@link Command} entries.
// <p>Standard semantics:
// <ul>
//   <li>{@link #execute(Command)} runs the command and pushes onto the
//       undo stack. Any pending redo entries are cleared (forking history).
//   <li>{@link #undo()} pops the most recent undo entry, calls
//       {@code revert()}, and pushes onto the redo stack. If revert returns
//       false the entry is dropped without being pushed onto redo.
//   <li>{@link #redo()} pops the most recent redo entry, calls
//       {@code apply()}, and pushes back onto the undo stack. If apply
//       returns false the entry is dropped.
// </ul>
// <p>The undo stack is bounded - once it exceeds {@link #CAP} entries, the
// oldest entries are dropped (the redo stack is implicitly bounded by what
// the user has undone). Both stacks are session-only; they are never
// persisted. Cleared wholesale on config-profile change, since entries
// captured against another profile's stores would corrupt this one.
// <p>Not thread-safe - all calls must come from the EDT (or whichever
// single thread owns the plugin's panel hooks).
// <p>Ported from goal planner's command module - keep in lockstep.
@Slf4j
public class CommandHistory {
static final int CAP = 50;

Deque<Command> undoStack = new ArrayDeque<>();
Deque<Command> redoStack = new ArrayDeque<>();

// Run a command and push it onto the undo stack on success.
// Forking behavior: any pending redo entries are cleared.
// @return whatever {@link Command#apply()} returned
public boolean execute(Command cmd) {
    if (!attempt(cmd, true, "apply")) return false;
    undoStack.push(cmd);
    redoStack.clear();
    while (undoStack.size() > CAP) undoStack.pollLast();
    return true;
}

// Pop the most recent undo entry and revert it. On success the entry
// moves to the redo stack. On failure the entry is dropped - fail-open.
// @return true if an entry was reverted, false if the stack was empty
//         or the revert failed
public boolean undo() { return move(undoStack, redoStack, false, "revert"); }

// Pop the most recent redo entry and re-apply it. On success the entry
// moves back to the undo stack. On failure the entry is dropped.
public boolean redo() { return move(redoStack, undoStack, true, "re-apply"); }

// Pop from one stack, run the command, push onto the other; a refusal
// or a throw drops the entry (fail-open).
static boolean move(Deque<Command> from, Deque<Command> to, boolean apply, String verb) {
    if (from.isEmpty()) return false;
    Command cmd = from.pop();
    if (!attempt(cmd, apply, verb)) return false;
    to.push(cmd);
    return true;
}

// Runs apply or revert; false - and a warning - when it refused or threw.
static boolean attempt(Command cmd, boolean apply, String verb) {
    try {
        if (apply ? cmd.apply() : cmd.revert()) return true;
        log.warn("Command {} returned false, dropping: {}", verb, cmd.getDescription());
    } catch (Exception ex) {
        log.warn("Command {} threw, dropping: {}", verb, cmd.getDescription(), ex);
    }
    return false;
}

public boolean canUndo() { return !undoStack.isEmpty(); }
public boolean canRedo() { return !redoStack.isEmpty(); }

// Description of the next undo target, or null if the stack is empty.
public String peekUndoDescription() { return undoStack.isEmpty() ? null : undoStack.peek().getDescription(); }

// Description of the next redo target, or null if the stack is empty.
public String peekRedoDescription() { return redoStack.isEmpty() ? null : redoStack.peek().getDescription(); }

// Wipe both stacks.
public void clear() {
    undoStack.clear();
    redoStack.clear();
}
}

package com.ll.command;

import java.util.function.BooleanSupplier;

// The one {@link Command} factory the engine records with: a label and
// two lambdas. Each command captures the before-state it needs to
// revert AT CONSTRUCTION (per the Command contract), so build the
// command at the moment of the user's action and hand it straight to
// {@link CommandHistory#execute}.
// <p>The store-backed factories that once lived here (the flag toggles,
// pins, notes, mob exclusions, sims, filter items) had no main-source
// caller: the plugin's StoreOps built them only to call apply() and
// throw the revert away, since the ENGINE's history is the one live
// stack. They live on verbatim in the test tree's TestCommands, so main
// source stays under the Plugin Hub bot's token budget.
public class Commands {

// A Command from two lambdas plus a label - the shape every factory returns.
public static Command of(String description, BooleanSupplier apply, BooleanSupplier revert) {
    return new Command() {
        public boolean apply() { return apply.getAsBoolean(); }
        public boolean revert() { return revert.getAsBoolean(); }
        public String getDescription() { return description; }
    };
}
}

package com.ll.data;

import com.google.gson.JsonObject;
import com.ll.data.Json;
import java.util.*;
import net.runelite.api.gameval.SpriteID;
import com.ll.engine.Style;

// Icon lookups for the compact "assumes" rows: prayer names to prayer-book
// sprites, boost labels to potion/heart item ids, and spell names to
// spellbook sprites - so the panel can show a small icon instead of a
// sentence. Names must match PrayerBonuses / BoostProfile / Spell
// exactly; unmapped names fall back to plain text.
public class AssumeIcons {
// Generated by scripts/gen_assume_icons.py; drift-guarded by
// AssumeIconsDriftTest, which re-reflects the SpriteID constants at
// build time so an upstream renumbering goes red instead of quietly
// painting the wrong icon.
static final String RESOURCE = "assume_icons.json";

static final Map<String, Integer> PRAYERS = new HashMap<>();
static final Map<String, Integer> BOOST_ITEMS = new HashMap<>();
static final Map<String, Integer> SPELLS = new HashMap<>();
static final Map<String, String> PRAYER_IMAGES = new HashMap<>();

static {
    // Fail-soft on purpose: these are decoration, and an unmapped name
    // already has a plain-text fallback below.
    JsonObject root = Json.object(RESOURCE);
    Json.intMap(root, "prayers", PRAYERS);
    Json.intMap(root, "boostItems", BOOST_ITEMS);
    Json.intMap(root, "spells", SPELLS);
    Json.stringMap(root, "prayerImages", PRAYER_IMAGES);
}


// Prayer-book sprite id for this prayer name, or -1. A compound
// picker label ("Ultimate Strength + Incredible Reflexes") wears its
// LEAD prayer's icon (field ask 2026-08-20: no letter fallbacks).
public static int prayerSprite(String name) {
    Integer exact = PRAYERS.get(name);
    if (exact != null) return exact;
    int plus = name == null ? -1 : name.indexOf(" + ");
    if (plus > 0) return PRAYERS.getOrDefault(name.substring(0, plus), -1);
    return -1;
}

// Skill icon for a combat style - melee wears the Attack icon. Sprites,
// never font glyphs (Tahoe tofu rule); tooltips carry the words.
public static int styleSprite(Style style) {
    switch (style) {
        case RANGED:
            return SpriteID.Staticons.RANGED;
        case MAGIC:
            return SpriteID.Staticons.MAGIC;
        default:
            return SpriteID.Staticons.ATTACK;
    }
}

// Item id whose icon represents this boost label, or -1.
public static int boostItem(String label) { return BOOST_ITEMS.getOrDefault(label, -1); }

// A bundled image for a prayer with no api sprite yet (Zeal), or null.
public static String prayerImage(String name) {
    int plus = name == null ? -1 : name.indexOf(" + ");
    return PRAYER_IMAGES.get(plus > 0 ? name.substring(0, plus) : name);
}

// Spellbook sprite id for this spell name, or -1.
public static int spellSprite(String name) { return SPELLS.getOrDefault(name, -1); }
}

package com.ll.data;

import com.google.gson.*;
import com.ll.engine.*;
import java.util.*;
import lombok.*;
import static com.ll.data.Json.*;

// Combat achievement tasks whose restrictions shape a set (combat_achievements.json,
// ISS-01M5XC7XYMMEN3Q4QC6CGZFVPK): each task's rules as Rules, by id and by mob.
// The file's names are lowercase already and its keys are SetRules' field names.
public class CombatAchievements {
@Value
public static class Task {
    int id;
    String name, tier, desc;
    Set<String> mobs;
    // A fragment the mob's version must contain, or "".
    String version;
    Rules rules;
    // Per-mob weapon lists (Betrayal: each moon's own drop), or null.
    JsonObject mobWeapons;

    // The rules on these mobs: a per-mob weapon list narrows to theirs
    // (a group of them allows any of their weapons).
    public Rules rulesFor(Collection<Monster> on) {
        if (mobWeapons == null) return rules;
        Set<String> weapons = new HashSet<>();
        for (Monster m : on) strings(mobWeapons, m.lname, weapons);
        if (weapons.isEmpty()) mobWeapons.keySet().forEach(m -> strings(mobWeapons, m, weapons));
        return rules.toBuilder().weapons(weapons).build();
    }

    public boolean isFor(Monster mob) {
        return mobs.contains(mob.lname) && (version.isEmpty() || Names.lower(mob.version).contains(version));
    }
}

static final Map<Integer, Task> BY_ID = new LinkedHashMap<>();

// A task row as Gson reads it: absent sets stay null (no restriction).
static class Row {
    int id, levelCap;
    String name, tier, desc, version, attackType, spellbook;
    Set<String> mobs, styles, spells, banned, weapons, weaponCategories;
    List<JsonArray> rules;
    boolean demonbaneWeapon, bannedDemonbane, oneHanded, unarmed, noWeaponMagic, noPrayerRestore, poisonWeapon, f2p;
    JsonObject mobWeapons;
}

static class Root {
    List<Row> tasks = List.of();
}

static {
    for (Row t : read("combat_achievements.json", Root.class).tasks) {
        List<Rules.Rule> rules = new ArrayList<>();
        if (t.rules != null) for (JsonArray a : t.rules) rules.add(new Rules.Rule(a.get(0).getAsString(), a.get(1).getAsString(), a.get(2).getAsDouble()));
        Set<Style> allowed = null;
        if (t.styles != null) {
            allowed = EnumSet.noneOf(Style.class);
            for (String s : t.styles) allowed.add(Style.valueOf(s.toUpperCase(Locale.ROOT)));
        }
        Rules set = Rules.builder().rules(rules).banned(t.banned == null ? Set.of() : t.banned)
            .weapons(t.weapons).weaponCategories(t.weaponCategories).demonbaneWeapon(t.demonbaneWeapon)
            .bannedDemonbane(t.bannedDemonbane).oneHanded(t.oneHanded).unarmed(t.unarmed)
            .noWeaponMagic(t.noWeaponMagic).styles(allowed).attackType(t.attackType)
            .noPrayerRestore(t.noPrayerRestore).spellbook(t.spellbook).spells(t.spells == null ? null : List.copyOf(t.spells))
            .levelCap(t.levelCap).poisonWeapon(t.poisonWeapon).f2p(t.f2p).build();
        BY_ID.put(t.id, new Task(t.id, t.name, t.tier, t.desc, t.mobs, t.version == null ? "" : t.version, set, t.mobWeapons));
    }
}

public static Task byId(int id) { return BY_ID.get(id); }

// Every task, in file order.
public static Collection<Task> all() { return BY_ID.values(); }

// The tasks for a monster (its name, and its version where a task names one).
public static List<Task> tasksFor(Monster mob) {
    List<Task> out = new ArrayList<>();
    for (Task t : BY_ID.values()) if (t.isFor(mob)) out.add(t);
    return out;
}
}

// Derived from guccifurs/best-dps (BSD-2-Clause, Copyright (c) 2026, Noid) - see licenses/best-dps-LICENSE.
package com.ll.data;

import com.google.gson.reflect.TypeToken;
import java.util.*;

import static com.ll.data.Json.*;

public class DataService {
static final String GEAR_RESOURCE = "gear_prices.json.gz";
static final String REQUIREMENTS_RESOURCE = "equipment_requirements.json.gz";
static final String MONSTER_RESOURCE = "monsters.json.gz";
static final String SPELL_RESOURCE = "spells.json.gz";
static final String ALIAS_RESOURCE = "equipment_aliases.json.gz";
static final String NAME_RULES_RESOURCE = "name_rules.json";
static final String COMPONENT_RESOURCE = "component_prices.json";

// Name-matching tables, generated by scripts/gen_name_rules.py. Quest
// rules stay in resource order: a quest named by two rules must still
// dedup at its FIRST position in the LinkedHashSet that questsFor builds.
static class NameRules {
    Map<String, Integer> spellLevels = Map.of();
    List<String> slayerContains = List.of(), slayerStartsWith = List.of();
    List<QuestRule> questRules = List.of();
}

static class QuestRule {
    List<String> terms = List.of();
    String quest;
}

static final NameRules RULES = read(NAME_RULES_RESOURCE, NameRules.class);

static {
    // Fail LOUD, unlike the fail-soft tables elsewhere. An empty table here
    // would silently pin every spell to level 1 and drop every quest
    // requirement - that changes DPS and gear recommendations with no
    // visible error.
    if (RULES.spellLevels.isEmpty() || RULES.slayerContains.isEmpty() || RULES.slayerStartsWith.isEmpty() || RULES.questRules.isEmpty()) throw new IllegalStateException("Empty table in " + NAME_RULES_RESOURCE);
}

public Tables load() {
    List<Gear> gear = priceChargedTwins(loadGear());
    priceComponents(gear);
    List<Monster> monsters = normalizeQuestVersions(loadMonsters());
    List<Spell> spells = loadSpells();
    Map<Integer, Gear> gbi = new HashMap<>();
    gear.forEach(item -> gbi.put(item.id, item));
    return new Tables(gear, monsters, spells, gbi, loadAliases(gear));
}

// Variant id -> base id (ornament/locked/degraded, identical stats),
// plus every uncharged, inactive, broken or locked WEAPON version behind
// its charged twin (ISS-01M5QQV2TGQ5X730T0JJ75S1RD, Andrew 2026-10-24:
// "let's only consider charged versions of weapons, don't think about eye
// of ayak uncharged or obligator uncharged"): never suggested, and owning
// one is owning the twin you charge before the trip.
Map<Integer, Integer> loadAliases(List<Gear> gear) {
    Map<Integer, Integer> aliases = read(ALIAS_RESOURCE, new TypeToken<Map<Integer, Integer>>() { }.getType());
    aliases.entrySet().removeIf(e -> e.getKey().intValue() == e.getValue());
    for (var twin : chargedTwins(gear).entrySet()) if (!aliases.containsKey(twin.getKey().id)) aliases.put(twin.getKey().id, aliases.getOrDefault(twin.getValue().id, twin.getValue().id));
    return aliases;
}

// Every dead weapon version -> its live twin of the same name: the
// "charged" one, else active, normal, fixed or regular, else the first.
static Map<Gear, Gear> chargedTwins(List<Gear> gear) {
    Map<String, List<Gear>> weapons = new HashMap<>();
    for (Gear item : gear) if (item.slot == Slot.WEAPON) weapons.computeIfAbsent(item.lname, k -> new ArrayList<>()).add(item);
    Map<Gear, Gear> twins = new HashMap<>();
    for (List<Gear> family : weapons.values()) {
        Gear charged = null;
        for (String want : new String[]{"charged", "active", "normal", "fixed", "regular", ""}) {
            for (Gear item : family) if (charged == null && !deadVersion(item) && (want.isEmpty() || item.ver.equals(want))) charged = item;
        }
        for (Gear item : family) if (charged != null && deadVersion(item)) twins.put(item, charged);
    }
    return twins;
}

// The charged twin inherits the tradeable dead twin's price: the
// uncharged Obligator is how you buy the Obligator, so the charged one
// passes the untradeable gate and the budget modes can afford it.
static List<Gear> priceChargedTwins(List<Gear> gear) {
    Map<Integer, Gear> priced = new HashMap<>();
    for (var twin : chargedTwins(gear).entrySet()) {
        Gear dead = twin.getKey();
        Gear charged = twin.getValue();
        if (dead.tradeable && dead.estimatedPrice != null && (!charged.tradeable || charged.estimatedPrice == null)) priced.putIfAbsent(charged.id, charged.priced(dead.estimatedPrice));
    }
    List<Gear> out = new ArrayList<>(gear.size());
    for (Gear item : gear) out.add(priced.getOrDefault(item.id, item));
    return out;
}

// What a task's price rule counts for what has no price of its own (wiki,
// Budget_Cutter: "this is not the case for the Slayer helmet or imbued items;
// the value of its components will be used instead"): "X (i)" is the cheapest
// tradeable X, every slayer helmet the cheapest tradeable Black mask, the one
// part worth counting (ISS-01M674YPVT5GFVSAT2PAK8RXS1); an untradeable made
// from what is not equipment reads scripts/refresh_data.py's table, priced at
// the refresh (ISS-01M67RHJ7WAT6PZ186FES3CGY8, field report 2026-10-30:
// Ferocious gloves "(8M cost)" - their Hydra leather).
static void priceComponents(List<Gear> gear) {
    Map<String, Integer> prices = read(COMPONENT_RESOURCE, new TypeToken<Map<String, Integer>>() {}.getType());
    for (Gear item : gear) if (item.tradeable && item.estimatedPrice != null) prices.merge(item.lname, item.getPriceOrZero(), Math::min);
    for (Gear item : gear) {
        String name = item.lname;
        String base = prices.containsKey(name) && !item.tradeable ? name : name.contains("slayer helmet") ? "black mask" : name.endsWith(" (i)") ? name.substring(0, name.length() - 4) : null;
        if (base != null) item.componentPrice = prices.getOrDefault(base, 0);
    }
}

// A weapon version that cannot attack as it is.
static boolean deadVersion(Gear item) {
    String version = item.ver;
    return version.contains("uncharged") || version.contains("inactive") || version.contains("broken") || version.contains("locked");
}

// One wiki gear row as Gson reads it (gear_prices.json.gz).
static class GearRow {
    int id, speed;
    String name, version, slot, category, examine;
    boolean isTwoHanded, tradeable, isStandardGear = true, members = true;
    // A price past int range (one 2.45b item) caps instead of wrapping negative.
    Long estimatedPrice;
    Double weight;
    Map<String, Integer> offensive, defensive, bonuses;
}

List<Gear> loadGear() {
    GearRow[] rows = read(GEAR_RESOURCE, GearRow[].class);
    Map<Integer, Map<String, Integer>> sr = loadSkillRequirements();
    List<Gear> result = new ArrayList<>(rows.length);
    for (GearRow row : rows) {
        Slot slot = Slot.fromJson(nz(row.slot));
        if (slot == null) continue;
        if (isLeaguesReward(row.name, row.examine)) continue;
        if (isMinigameOnly(row.name)) continue;

        Gear item = new Gear(row.id, row.name, row.version, slot, nz(row.category), row.speed, row.isTwoHanded,
            row.isStandardGear || isWronglyFlaggedUsable(row.name), row.tradeable, row.members,
            row.estimatedPrice == null ? null : (int) Math.min(Integer.MAX_VALUE, row.estimatedPrice),
            parseOffensive(row.offensive), parseDefensive(row.defensive), parseBonuses(row.bonuses),
            requirementsFor(row.id, row.name, row.version, sr));
        if (row.weight != null) item.setWeight(row.weight);
        result.add(item);
    }
    result.sort(Comparator.comparing(Gear::getName).thenComparingInt(Gear::getId));
    return result;
}

static String nz(String s) { return s == null ? "" : s; }

// Upstream's curated isStandardGear flag marks these permanent main-game
// upgrades as non-standard (audited 2026-07-05): the Avernic treads
// upgrade combinations carry real ranged/magic strength, and the
// Confliction gauntlets are a 7% magic damage glove. Force them usable.
static boolean isWronglyFlaggedUsable(String name) {
    String n = name == null ? "" : name.toLowerCase();
    return n.startsWith("avernic treads") || n.equals("confliction gauntlets");
}

// Leagues-only rewards never enter the corpus - the optimizer suggests
// main-game gear only. The stat-relevant offenders are the Leagues V
// "Echo" set (wrongly flagged isStandardGear in the wiki data); the
// Trailblazer outfits, banners, and trophies are zero-stat cosmetics.
// The wiki examine text says "league" only on leagues rewards.
static class Leagues {
    List<String> prefixes = List.of(), contains = List.of(), minigameOnly = List.of();
}

static final Leagues LEAGUES = read("leagues_items.json", Leagues.class);

static boolean isLeaguesReward(String name, String examine) {
    String n = name == null ? "" : name.toLowerCase();
    return LEAGUES.prefixes.stream().anyMatch(n::startsWith) || LEAGUES.contains.stream().anyMatch(n::contains)
        || (examine != null && examine.toLowerCase().contains("league"));
}

// Items that only function inside a minigame never enter the corpus.
// The Barbarian Assault arrows carry ranged strength 125 - stronger
// than dragon arrows - but can only be fired at penance inside BA
// (upstream best-dps flagged only two of the four non-standard).
static boolean isMinigameOnly(String name) {
    return LEAGUES.minigameOnly.contains(name == null ? "" : name.toLowerCase());
}

static class ReqRow {
    int id;
    Map<String, Integer> skills = Map.of();
}

Map<Integer, Map<String, Integer>> loadSkillRequirements() {
    Map<Integer, Map<String, Integer>> result = new HashMap<>();
    for (ReqRow row : read(REQUIREMENTS_RESOURCE, ReqRow[].class)) {
        Map<String, Integer> levels = new LinkedHashMap<>();
        for (var entry : row.skills.entrySet()) if (entry.getValue() != null) levels.put(entry.getKey(), Math.max(1, entry.getValue()));
        if (!levels.isEmpty()) result.put(row.id, levels);
    }
    return result;
}

static GearRequirements requirementsFor(int id, String name, String version, Map<Integer, Map<String, Integer>> sr) {
    Map<String, Integer> skills = sr.getOrDefault(id, Map.of());
    Set<String> quests = questsFor(name, version);
    return skills.isEmpty() && quests.isEmpty() ? GearRequirements.NONE : new GearRequirements(skills, quests);
}

// Version-label normalization (field spec 2026-07-18): the noise
// tokens go ("Awake"; "Post-quest" becomes the bare name - the
// everyday fight owns it), quest-only rows read "QUEST" loudly
// (either the literal Quest token, or - for a two-row pair like
// Vorkath's 'Dragon Slayer II' next to 'Post-quest' - the sibling
// that is not the post-quest fight). versionTier already sorts
// anything containing "quest" to the bottom of a bare-name search.
static List<Monster> normalizeQuestVersions(List<Monster> monsters) {
    Map<String, List<Monster>> bn = new LinkedHashMap<>();
    for (Monster monster : monsters) bn.computeIfAbsent(monster.lname, k -> new ArrayList<>()).add(monster);
    List<Monster> out = new ArrayList<>(monsters.size());
    for (List<Monster> group : bn.values()) {
        boolean pairWithPostQuest = group.size() == 2 && group.stream()
            .anyMatch(m -> Names.lower(m.version).contains("post-quest"));
        for (Monster monster : group) {
            String version = monster.version;
            if (version == null || version.isEmpty()) {
                out.add(monster);
                continue;
            }
            List<String> kept = new ArrayList<>();
            boolean quest = false;
            for (String token : version.split(",\\s*")) {
                if (token.equalsIgnoreCase("awake") || token.equalsIgnoreCase("post-quest")) continue;
                if (token.equalsIgnoreCase("quest")) {
                    quest = true;
                    continue;
                }
                kept.add(token);
            }
            if (pairWithPostQuest && !quest && !Names.lower(version).contains("post-quest")) {
                // The non-post-quest half of the pair IS the quest fight.
                quest = true;
                kept.clear();
            }
            String normalized = String.join(", ", kept);
            if (quest) normalized = normalized.isEmpty() ? "QUEST" : normalized + ", QUEST";
            out.add(normalized.equals(version) ? monster : monster.withVersion(normalized));
        }
    }
    return out;
}

// One wiki monster row as Gson reads it (monsters.json.gz); the stat
// blocks stay maps so a group key can print them whole.
static class MonsterRow {
    int id = -1, level, speed = 4, size = 1;
    String name, version, max_hit;
    List<String> style = List.of(), attributes = List.of();
    Map<String, Integer> skills, offensive, defensive;
    Map<String, String> immunities;
    Map<String, Object> weakness;
    boolean is_slayer_monster;

    // Leagues echo bosses are seasonal, never main-game (Andrew 2026-09-03:
    // "should not be able to search 'echo' version in main mode").
    // Nightmare Zone versions too (Andrew 2026-09-04: "nobody needs theory
    // crafting for that") - they swamped a search for the Nightmare.
    boolean echo() { return nz(name).contains("(Echo)") || nz(name).contains("(Nightmare Zone)"); }

    // Everything the engine reads from a monster - rows agreeing on this
    // are one entry. The Wardens' Core-ejected rows are stat-identical to
    // their Active siblings, but the engine reads that version as a
    // MECHANIC (the core's always-max rule) - collapsing them would erase
    // the spec-dump phase from the corpus entirely.
    String statKey() {
        String mechanicVersion = "Core-ejected".equals(version) ? "Core-ejected" : "";
        return v(skills, "def", 1) + "|" + v(skills, "magic", 1) + "|" + v(offensive, "magic", 0) + "|" + defensive + "|" + attributes
            + "|" + is_slayer_monster + "|" + weakness + "|" + size + "|" + mechanicVersion;
    }
}

List<Monster> loadMonsters() {
    MonsterRow[] rows = read(MONSTER_RESOURCE, MonsterRow[].class);
    // The wiki data lists one row per SPAWN - Tormented Demon (1)..(4)
    // are four combat-identical rows. Collapse same-name rows whose
    // combat-relevant stats match, and drop the version label entirely
    // when a name has only one distinct stat block (Dusk keeps its
    // First/Second form; the four TDs become one unlabeled entry).
    Map<String, Set<String>> skbn = new HashMap<>();
    // Collapsed groups display the HIGHEST combat level among their spawns.
    Map<String, Integer> mlbg = new HashMap<>();
    for (MonsterRow row : rows) {
        if (row.echo()) continue;
        String nk = Names.lower(row.name);
        String sk = row.statKey();
        skbn.computeIfAbsent(nk, k -> new LinkedHashSet<>()).add(sk);
        mlbg.merge(nk + "|" + sk, row.level, Math::max);
    }

    Set<String> emitted = new HashSet<>();
    List<Monster> result = new ArrayList<>(rows.length);
    for (MonsterRow row : rows) {
        if (row.echo()) continue;
        String nk = Names.lower(row.name);
        String groupKey = nk + "|" + row.statKey();
        // Emit the HIGHEST-LEVEL spawn of each collapsed group, so the
        // offensive sheet (used for incoming dps) matches the combat
        // level the label displays.
        if (row.level != mlbg.get(groupKey) || !emitted.add(groupKey)) continue;
        boolean distinctVersions = skbn.get(nk).size() > 1;
        List<String> attributes = new ArrayList<>();
        if (row.attributes != null) for (String attr : row.attributes) if (attr != null) attributes.add(attr);
        // Burn immunity rides the attribute list as a synthetic marker
        // (no Monster signature churn): the eclipse/scorching burn
        // class is a NORMAL burn, blocked by Normal or Strong immunity
        // (official calc isImmuneToNormalBurns; Weak does not block it).
        String burn = row.immunities == null ? "" : nz(row.immunities.get("burn"));
        if ("normal".equalsIgnoreCase(burn) || "strong".equalsIgnoreCase(burn)) attributes.add("burn_immune");

        // The Maggot King fights at range until ~65% hp - melee CANNOT
        // land on the Far phase (wiki: "cannot be attacked with melee
        // until it falls below ~980 hitpoints"; field report 2026-08-20:
        // Far recommended a melee set). The corpus carries no attribute
        // for it, so the marker rides here like burn_immune.
        if ("Maggot King".equals(row.name) && "Far".equalsIgnoreCase(row.version)) attributes.add("immune_melee");

        // The ejected core is a 1x1 target - the wiki row carries the
        // Warden's 5x5 frame, which handed the crystal halberd's sweep a
        // phantom second hit and outranked the DDS dump (field report
        // 2026-08-06). Size is the one stat the always-max rule still
        // reads (halberd sweep, scythe cleave).
        int size = "Core-ejected".equals(row.version) ? 1 : row.size;
        result.add(new Monster(row.id, nz(row.name), distinctVersions ? nz(row.version) : "", mlbg.get(groupKey), v(row.skills, "hp", 1),
            size, v(row.skills, "def", 1), v(row.skills, "magic", 1), v(row.offensive, "magic", 0),
            parseMonsterDefences(row.defensive), new MonsterOffence(v(row.skills, "atk", 1),
                v(row.skills, "str", 1), v(row.skills, "ranged", 1), v(row.skills, "magic", 1),
                v(row.offensive, "atk", 0), v(row.offensive, "str", 0), v(row.offensive, "ranged", 0),
                v(row.offensive, "ranged_str", 0), v(row.offensive, "magic", 0),
                v(row.offensive, "magic_str", 0), row.speed, styleList(row.style),
                MaxHits.parse(nz(row.max_hit))), attributes,
            row.is_slayer_monster || knownSlayerMonster(row.name),
            row.weakness == null ? "" : nz((String) row.weakness.get("element")), v(row.weakness, "severity", 0)));
    }
    result.sort(Comparator.comparing(Monster::getName).thenComparing(Monster::getVersion).thenComparingInt(Monster::getId));
    return result;
}

static List<String> styleList(List<String> raw) {
    List<String> styles = new ArrayList<>();
    if (raw != null) for (String e : raw) {
        if (e == null) continue;
        // "Ranged <br/> Typeless" is two styles; stray DEL characters
        // (Araxxor, Dusk) are wiki noise.
        for (String style : e.replace('\u007f', ' ').split("(?i)<br\\s*/?>")) if (!style.trim().isEmpty()) styles.add(style.trim());
    }
    return styles;
}

static class SpellRow {
    String name, spellbook, element;
    int max_hit;
    boolean unselectable;
}

List<Spell> loadSpells() {
    List<Spell> result = new ArrayList<>();
    for (SpellRow row : read(SPELL_RESOURCE, SpellRow[].class)) {
        String name = nz(row.name);
        if (row.max_hit <= 0 && !"Magic Dart".equals(name)) continue;
        // Effect-only spells (leagues echoes, boss mechanics - e.g.
        // Flames of Cerberus) are flagged unselectable in the wiki data;
        // a player can never cast them, so they never enter the corpus.
        if (row.unselectable) continue;
        result.add(new Spell(name, "Magic Dart".equals(name) ? 1 : row.max_hit, spellLevel(name), nz(row.spellbook), nz(row.element)));
    }
    result.sort(Comparator.comparingInt(Spell::getMaxHit).thenComparing(Spell::getName));
    return result;
}

// Casting level for a spell name; unknown names fall back to 1.
static int spellLevel(String name) { return RULES.spellLevels.getOrDefault(name == null ? "" : name, 1); }

static Stats parseOffensive(Map<String, Integer> m) {
    if (m == null) return Stats.ZERO;
    int[] c = combat(m);
    return new Stats(c[0], c[1], c[2], c[3], c[4], 0, 0, 0, 0);
}

static Stats parseDefensive(Map<String, Integer> m) {
    if (m == null) return Stats.ZERO;
    int[] c = combat(m);
    return new Stats(c[0], c[1], c[2], c[3], c[4], 0, v(m, "light", 0), v(m, "standard", 0), v(m, "heavy", 0));
}

static MonsterDefences parseMonsterDefences(Map<String, Integer> m) {
    if (m == null) return MonsterDefences.ZERO;
    int[] c = combat(m);
    return new MonsterDefences(c[0], c[1], c[2], c[3], c[4], v(m, "flat_armour", 0), v(m, "light", 0), v(m, "standard", 0), v(m, "heavy", 0));
}

static Stats parseBonuses(Map<String, Integer> m) {
    if (m == null) return Stats.ZERO;
    return new Stats(0, 0, 0, 0, 0, v(m, "str", 0), v(m, "ranged_str", 0), v(m, "magic_str", 0), v(m, "prayer", 0));
}

// stab, slash, crush, magic, ranged - the five every stat block shares.
static int[] combat(Map<String, Integer> m) {
    return new int[]{v(m, "stab", 0), v(m, "slash", 0), v(m, "crush", 0), v(m, "magic", 0), v(m, "ranged", 0)};
}

// A stat block's number, the fallback where the block or the key is missing (or null).
static int v(Map<String, ?> m, String key, int fallback) {
    Object x = m == null ? null : m.get(key);
    return x instanceof Number ? ((Number) x).intValue() : fallback;
}

static boolean knownSlayerMonster(String name) {
    String normalized = name == null ? "" : Names.lower(name);
    return RULES.slayerContains.stream().anyMatch(normalized::contains) || RULES.slayerStartsWith.stream().anyMatch(normalized::startsWith);
}

// Quest unl implied by an item's name and version, in resource rule
// order. LinkedHashSet, so a quest named by two rules keeps the position of
// its first match - the same behaviour the old requireIf chain had.
static Set<String> questsFor(String name, String version) {
    String item = ((name == null ? "" : name) + " " + (version == null ? "" : version)) .toLowerCase(Locale.ROOT);
    Set<String> quests = new LinkedHashSet<>();
    for (QuestRule rule : RULES.questRules) {
        for (String term : rule.terms) {
            if (item.contains(term)) {
                quests.add(rule.quest);
                break;
            }
        }
    }
    return quests;
}
}

package com.ll.data;

import com.google.gson.*;
import java.util.*;

// Per-boss defence floors for drain valuation (competitor audit
// 2026-08-08): the official calculator hard-stops DWH/BGS/maul
// stacking per boss, and without the floor our drain-fishing model
// overvalues drain specs - at Nex (base 260, floor 250) a DWH is worth
// almost nothing, at Verzik and Vardorvis exactly nothing. Id arrays
// in defence_floors.json are copied verbatim from the wiki calc's
// constants - the same weirdgloop ids our corpus carries.
public class DefenceFloors {
// Sentinel: the floor IS the boss's base defence (undrainable).
static final int BASE = -1;

static final Map<Integer, Integer> BY_ID = new HashMap<>();
// Bosses a Death Charge does nothing on (a row's "deathCharge": false).
static final Set<Integer> NO_DEATH_CHARGE = new HashSet<>();

static {
    JsonObject root = Json.objectOrThrow( "defence_floors.json");
    for (JsonElement e : root.getAsJsonArray("rules")) {
        JsonObject row = e.getAsJsonObject();
        int floor = "base".equals(row.get("floor").getAsString()) ? BASE : row.get("floor").getAsInt();
        boolean charge = !row.has("deathCharge") || row.get("deathCharge").getAsBoolean();
        for (JsonElement id : row.getAsJsonArray("ids")) {
            BY_ID.put(id.getAsInt(), floor);
            if (!charge) NO_DEATH_CHARGE.add(id.getAsInt());
        }
    }
    if (BY_ID.isEmpty()) throw new IllegalStateException("defence_floors.json loaded empty");
}


// Whether a Death Charge pays out on this monster (the Moons: no).
public static boolean deathChargeWorks(Monster monster) { return monster == null || !NO_DEATH_CHARGE.contains(monster.profileId()); }

// The defence level a drain cannot pass for this monster - 0 when
// unfloored. Synthetic group rows resolve through profileId().
public static int floorFor(Monster monster) {
    if (monster == null) return 0;
    Integer floor = BY_ID.get(monster.profileId());
    if (floor == null) return 0;
    return floor == BASE ? monster.defence : floor;
}
}

package com.ll.data;

import com.google.gson.JsonObject;
