package com.ll.data;

import com.google.gson.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.function.*;
import java.util.zip.GZIPInputStream;
import java.lang.reflect.Type;

// Loaders for the bundled JSON data tables (the hub token cap keeps data
// in resources, not source). All fail SOFT - a malformed table must never
// take the client down; the table's tests fail loudly on emptiness instead.
// The one exception is {@link #gz}: the gzipped corpus is not optional.
public class Json {
// The client's Gson, handed over by LoadoutLabPlugin at startup (the hub
// bans new Gson()); the test tree registers a GsonSource for its own.
interface GsonSource { Gson gson(); }

static Gson gson;

public static void use(Gson g) { gson = g; }

public static Gson gson() {
    if (gson == null) for (GsonSource s : ServiceLoader.load(GsonSource.class)) gson = s.gson();
    if (gson == null) throw new IllegalStateException("no Gson handed to JsonResources");
    return gson;
}

// The player-facing prose - tooltips, captions, notes - by key (render's
// text.tsv; the Plugin Hub's review bot counts source tokens, and words
// are data, not code). A missing key reads null, which UiTextTest catches.
static final Map<String, String> TEXT = tsv("/com/ll/render/text.tsv");

public static String text(String key) { return TEXT.get(key); }

// key<TAB>value rows of a resource ('#' lines are comments; a value keeps
// its edge spaces - a sentence fragment joins its neighbours).
public static Map<String, String> tsv(String name) {
    Map<String, String> out = new LinkedHashMap<>();
    try (InputStream in = Json.class.getResourceAsStream(name)) {
        if (in != null) {
            for (String line : new String(in.readAllBytes(), StandardCharsets.UTF_8).split("\r?\n")) {
                int tab = line.indexOf('\t');
                if (tab > 0 && !line.startsWith("#")) out.put(line.substring(0, tab), line.substring(tab + 1));
            }
        }
    } catch (IOException ignored) {
    }
    return out;
}

// A resource (gzipped when it ends in .gz) read straight into a type
// (ISS-01M65SN2SAXVSR9EBVB1R831SV, slim 12: Gson fills the row classes).
public static <T> T read(String resource, Class<T> type) { return read(resource, (Type) type); }

public static <T> T read(String resource, Type type) {
    try (InputStream in = Json.class.getResourceAsStream(resource)) {
        if (in == null) throw new IllegalStateException("Missing resource " + resource);
        InputStream src = resource.endsWith(".gz") ? new GZIPInputStream(in) : in;
        return gson().fromJson(new InputStreamReader(src, StandardCharsets.UTF_8), type);
    } catch (IOException ex) { throw new IllegalStateException("Could not load " + resource, ex); }
}

// The parsed resource, or null when missing/malformed.
static JsonElement parse(String resource) {
    try (InputStream in = Json.class.getResourceAsStream(resource)) {
        return new JsonParser().parse(new InputStreamReader(in, StandardCharsets.UTF_8));
    } catch (Exception e) { return null; }
}

// The parsed root object, or null when missing/malformed.
public static JsonObject object(String resource) {
    JsonElement root = parse(resource);
    return root != null && root.isJsonObject() ? root.getAsJsonObject() : null;
}

// The parsed root object, or an IllegalStateException when the resource is
// missing or malformed. For tables where an empty map would silently
// change results (rather than merely degrade a display), which is the one
// case the fail-soft object() above must not be used for.
public static JsonObject objectOrThrow(String resource) {
    JsonObject root = object(resource);
    if (root == null) throw new IllegalStateException("Could not load " + resource);
    return root;
}

// The gzipped JSON resource beside this class, parsed; a missing or
// unreadable bundle throws - the corpus is not optional.
public static JsonElement gz(String resource) {
    try (InputStream in = Json.class.getResourceAsStream(resource)) {
        if (in == null) throw new IllegalStateException("Missing resource " + resource);
        return new JsonParser().parse(new InputStreamReader( new GZIPInputStream(in), StandardCharsets.UTF_8));
    } catch (IOException ex) { throw new IllegalStateException("Could not load " + resource, ex); }
}

// Copy the string array at root[key] into the collection.
public static void strings(JsonObject root, String key, Collection<String> into) {
    each(root, key, JsonElement::getAsString, into);
}

// Copy the int array at root[key] into the collection.
public static void ints(JsonObject root, String key, Collection<Integer> into) {
    each(root, key, JsonElement::getAsInt, into);
}

static <T> void each(JsonObject root, String key, Function<JsonElement, T> read, Collection<T> into) {
    if (root != null && root.has(key)) root.getAsJsonArray(key).forEach(e -> into.add(read.apply(e)));
}

// A JSON int array as an int[].
public static int[] ints(JsonArray array) {
    int[] out = new int[array.size()];
    for (int i = 0; i < out.length; i++) out[i] = array.get(i).getAsInt();
    return out;
}

// Copy the {"name": "text"} object at root[key] into the map.
public static void stringMap(JsonObject root, String key, Map<String, String> into) {
    entries(root, key, (k, v) -> into.put(k, v.getAsString()));
}

// Copy the {"name": int} object at root[key] into the map.
public static void intMap(JsonObject root, String key, Map<String, Integer> into) {
    entries(root, key, (k, v) -> into.put(k, v.getAsInt()));
}

// Each member of the object at root[key]; nothing when absent.
static void entries(JsonObject root, String key, BiConsumer<String, JsonElement> fn) {
    JsonObject obj = root == null ? null : root.getAsJsonObject(key);
    if (obj != null) obj.entrySet().forEach(e -> fn.accept(e.getKey(), e.getValue()));
}

// A JSON-safe node from key/value pairs, in argument order (the rows
// the trip kit and the pages carry; a LinkedHashMap, so gson's reflective
// adapter and the canonical page JSON both see a plain ordered map).
public static Map map(Object... kv) {
    Map node = new LinkedHashMap<>();
    for (int i = 0; i < kv.length; i += 2) node.put((String) kv[i], kv[i + 1]);
    return node;
}
}

package com.ll.data;

import com.google.gson.*;
import java.util.*;
import java.util.function.IntPredicate;

import static com.ll.data.Json.*;

// Loot containers worth carrying (ISS-01M5JJ0Z4M988DR0M0ZGJHD139, Andrew 2026-10-22: "for
// monsters that are predomant droppers of things that can be bags, suggest
// to bring bags in inventory" - "killerwatts have a predominant herb drop
// table so i wish i had my herb sack before"). Which monsters drop enough
// of what a container holds comes from loot_containers.json, generated from
// the wiki's drop data by scripts/gen_loot_containers.py. Suggested only
// when owned.
public class LootContainers {
@lombok.AllArgsConstructor
static class Container {
    String name;
    int[] ids;
    String holds;
    // What it does with them - "holds them" for a bag; the bonecrusher,
    // ash sanctifier and soul bearer (ISS-01M5TNBSP28AAHJTYWAWJHHZKB) say their own.
    String does;
    Map<String, Double> perKill;
}

static final List<Container> CONTAINERS = new ArrayList<>();
static Container lootingBag;

// A container row as Gson reads it (loot_containers.json).
static class Row {
    String name, holds, does = "holds them";
    int[] ids;
    Map<String, Double> monsters = Map.of();
}

static class Root {
    List<Row> containers = List.of();
    Row lootingBag;
}

static {
    Root root = read("loot_containers.json", Root.class);
    for (Row row : root.containers) CONTAINERS.add(new Container(row.name, row.ids, row.holds, row.does, row.monsters));
    lootingBag = new Container(root.lootingBag.name, root.lootingBag.ids, "loot", "", Map.of());
    if (CONTAINERS.isEmpty()) throw new IllegalStateException("loot_containers.json loaded empty");
}


// The containers this monster's drops are worth that you own, each a
// trip-kit row: id (the one you own), name, qty, why. The looting bag
// rides on a wilderness trip.
public static List<Map> picks(Monster monster, IntPredicate owns, boolean wilderness) {
    List<Map> out = new ArrayList<>();
    if (monster == null || owns == null) return out;
    String key = monster.lname;
    for (Container container : CONTAINERS) {
        Double rate = container.perKill.get(key);
        int id = rate == null ? -1 : ownedId(container, owns);
        if (id > 0) {
            out.add(row(id, container.name, Names.cap(container.holds) + " drop here (" + often(rate) + ") - the "
                + Names.lower(container.name) + " " + container.does));
        }
    }
    if (wilderness || monster.isWildernessMonster()) {
        int id = ownedId(lootingBag, owns);
        if (id > 0) out.add(row(id, lootingBag.name, "Wilderness: the looting bag stores loot as you fight"));
    }
    return out;
}

// Whether the monster drops enough of what a container holds, by its
// holds word ("ashes": the Demonic Offering book, ISS-01M5TQ977R0MXBMSQ3VBHS29GB).
public static boolean drops(Monster monster, String holds) {
    String key = monster.lname;
    return CONTAINERS.stream().anyMatch(c -> c.holds.equals(holds) && c.perKill.containsKey(key));
}

static int ownedId(Container container, IntPredicate owns) {
    return Arrays.stream(container.ids).filter(owns).findFirst().orElse(-1);
}

// "about 1 per 4 kills", "about 1 per kill" (bones, ashes), or "about
// 2 per kill" for the generous.
static String often(double perKill) {
    long every = Math.round(1 / perKill);
    return perKill >= 1 ? String.format("about %.0f per kill", perKill)
        : every <= 1 ? "about 1 per kill" : "about 1 per " + every + " kills";
}

static Map row(int id, String name, String why) {
    return map("id", id, "name", name, "qty", 1, "why", why, "owned", true);
}
}

package com.ll.data;

import java.util.Arrays;
import java.util.regex.*;

// The wiki infobox's listed max hits, per attack family (ISS-01M5FZ3KYCGEMMX1A45D3J9NQ9).
// The corpus field is free text - "13 (Ranged)", "30-37 (Melee)", "7x2 (Magic)",
// "26 (melee)<br/> 15x2 (ranged)<br/> 65 (special attack)", "32 total 4+8+20" -
// so each entry is read for its value and labels: ranges and alternatives take
// the larger, multi-hits count their total (same expected damage), specials and
// dragonfire are left to curated data, and an unlabelled value is GENERAL.
public class MaxHits {
public enum Family { MELEE, RANGED, MAGIC, GENERAL }

static final MaxHits NONE = new MaxHits(new int[]{-1, -1, -1, -1});

static final Pattern ENTRY = Pattern.compile(
    "(\\d+)(?:\\s*([-/+])\\s*(\\d+))?(?:\\s*x\\s*(\\d+))?(?!\\s*%)\\+?\\??\\s*((?:\\([^)]*\\)\\s*)*)"
        + "(melee|ranged|magic)?", Pattern.CASE_INSENSITIVE);
static final Pattern LABEL = Pattern.compile("\\(([^)]*)\\)");
static final Pattern TIMES = Pattern.compile("x\\s*(\\d+)");
static final Pattern MELEE = Pattern.compile("\\b(melee|slash|crush|stab|bite)\\b");
static final Pattern RANGED = Pattern.compile("\\b(ranged|range|flies|missiles?)\\b");
static final Pattern MAGIC = Pattern.compile("\\b(magic|magical|fire blast|fire wave|wind strike)\\b");
static final Pattern SPECIAL = Pattern.compile(
    "special|charge|dragonfire|recoil|stomp|phase|aoe|knockback|whirlwind|cloud|crash|draining|typeless|not defeated|attack\\b(?<!magic attack)");
static final Pattern GENERAL = Pattern.compile( "normal|standard|default|regular|auto|approx|unconfirmed");

int[] max;

MaxHits(int[] max) { this.max = max; }

// The listed max for this family, or -1 when the wiki lists none.
public int of(Family family) { return max[family.ordinal()]; }

boolean isEmpty() { return Arrays.stream(max).allMatch(v -> v < 0); }

static MaxHits parse(String raw) {
    if (raw == null || raw.isEmpty()) return NONE;
    int[] max = {-1, -1, -1, -1};
    String text = raw.replace('\u007f', ' ').replace("&thinsp;", " ").replace("&thinsp", " ")
        .replaceAll("(?i)<br\\s*/?>", "\n").replaceAll("<[^>]*>", "\n").replace('*', '\n');
    for (String line : text.split("\n")) {
        // "32 total 4+8+20": the total is the hit; the parts are its pieces.
        line = line.trim().replaceAll("(?i)^(\\d+)\\s*total.*", "$1");
        Matcher m = ENTRY.matcher(line);
        while (m.find()) record(max, m);
    }
    return new MaxHits(max);
}

static void record(int[] max, Matcher m) {
    int value = Integer.parseInt(m.group(1));
    if (m.group(3) != null) {
        int other = Integer.parseInt(m.group(3));
        value = "+".equals(m.group(2)) ? value + other : Math.max(value, other);
    }
    if (m.group(4) != null) value *= Integer.parseInt(m.group(4));
    boolean[] families = new boolean[4];
    boolean labelled = false;
    Matcher label = LABEL.matcher(m.group(5));
    while (label.find()) {
        String text = label.group(1).trim().toLowerCase();
        Matcher times = TIMES.matcher(text);
        if (times.matches()) {
            value *= Integer.parseInt(times.group(1));
            continue;
        }
        if (text.contains("attack") && text.contains("not") || text.contains("doesn't attack") || SPECIAL.matcher(text).find()) return; // a special, dragonfire or a non-attacker - not a regular max
        boolean melee = MELEE.matcher(text).find();
        boolean ranged = RANGED.matcher(text).find();
        boolean magic = MAGIC.matcher(text).find();
        if (!melee && !ranged && !magic && !GENERAL.matcher(text).find()) return; // a named attack we cannot place
        families[Family.MELEE.ordinal()] |= melee;
        families[Family.RANGED.ordinal()] |= ranged;
        families[Family.MAGIC.ordinal()] |= magic;
        labelled |= melee || ranged || magic;
    }
    if (m.group(6) != null) {
        Matcher word = MELEE.matcher(m.group(6).toLowerCase());
        families[word.find() ? 0 : "ranged".equalsIgnoreCase(m.group(6)) ? 1 : 2] = true;
        labelled = true;
    }
    if (value <= 0) return;
    if (!labelled) families[Family.GENERAL.ordinal()] = true;
    for (int f = 0; f < 4; f++) if (families[f]) max[f] = Math.max(max[f], value);
}
}

