// "kreearra" finds Kree'arra.
static String normalizeQuery(String text) {
    var sb = new StringBuilder(text.length());
    for (char c : Names.lower(text).toCharArray()) if (Character.isLetterOrDigit(c) || c == ' ') sb.append(c);
