package com.ll.data;

import com.google.gson.*;
import java.util.*;

import static com.ll.data.Json.*;

// Ship-combat data (see naval_combat.json): the seven cannon tiers, the
// eight cannonball tiers, and the curated list of ship-eligible monsters.
// Wiki-verified 2026-08-31; the resource's $comment records the revisions
// that matter (dragon ball +174 -> +270 on 2026-03-18, and the stale
// crewmate formula flag).
// <p>The corpus carries no naval attribute, so eligibility is this list -
// every name resolves against a corpus row (NavalCombatTest proves it).
public class NavalCombat {
// One cannon tier. Cannons are FACILITIES, not items; itemId is the
// skill-guide item that carries the illustration (32199..32205).
@lombok.AllArgsConstructor
public static class Cannon {
    public String tier;
    public int itemId;
    public int sailing;
    public int ranged;
    public int heavyAccuracy;
    public int strength;
    public int privateering;
}

// One cannonball tier. Steel is the classic Cannonball (item 2).
@lombok.AllArgsConstructor
public static class Ball {
    public String tier;
    public int itemId;
    public int accuracy;
    public int strength;
}

static final Map<String, Cannon> CANNONS = new LinkedHashMap<>();
static final Map<String, Ball> BALLS = new LinkedHashMap<>();
static final List<String> BALL_ORDER = new ArrayList<>();
public static final Set<String> NAVAL = new HashSet<>();
static final List<String> KEELS = new ArrayList<>();
// Pre-0.5.0 builds named the keel columns after the hull woods; a
// character's persisted ship.shipKeel may still say so. Same column,
// right name - nobody's saved keel resets.
static final List<String> LEGACY_WOOD_KEELS = new ArrayList<>();
static final Map<String, int[]> KEEL_MAX_HITS = new LinkedHashMap<>();
static final boolean CREW_FORMULA_STALE;
public static final int ATTACK_TICKS;

// naval_combat.json as Gson reads it; the cannon and ball rows are the
// classes themselves (their field names are the file's keys).
static class Root {
    int attackTicks;
    boolean crewFormulaStale;
    List<Cannon> cannons = List.of();
    List<Ball> cannonballs = List.of();
    List<String> ballTierOrder = List.of(), navalMonsters = List.of(), keels = List.of(), legacyWoodKeels = List.of();
    Map<String, int[]> keelMaxHits = Map.of();
}

static {
    Root root = read("naval_combat.json", Root.class);
    ATTACK_TICKS = root.attackTicks;
    CREW_FORMULA_STALE = root.crewFormulaStale;
    for (Cannon c : root.cannons) CANNONS.put(c.tier, c);
    for (Ball b : root.cannonballs) BALLS.put(b.tier, b);
    BALL_ORDER.addAll(root.ballTierOrder);
    for (String m : root.navalMonsters) NAVAL.add(Names.lower(m));
    KEELS.addAll(root.keels);
    LEGACY_WOOD_KEELS.addAll(root.legacyWoodKeels);
    root.keelMaxHits.forEach((keel, hits) -> KEEL_MAX_HITS.put(Names.lower(keel), hits));
}


public static Cannon cannon(String tier) { return CANNONS.get(tier); }

public static Ball ball(String tier) { return BALLS.get(tier); }

public static List<Cannon> cannons() { return List.copyOf(CANNONS.values()); }

public static List<Ball> balls() { return List.copyOf(BALLS.values()); }

// True when a cannon of {@code cannonTier} may fire {@code ballTier}:
// at or below its own tier in the firing order (granite rides between
// mithril and adamant, so mithril cannons cannot fire it).
public static boolean canFire(String cannonTier, String ballTier) {
    int c = BALL_ORDER.indexOf(cannonTier);
    int b = BALL_ORDER.indexOf(ballTier);
    return c >= 0 && b >= 0 && b <= c;
}

// The best ball a set of cannons can SHARE (REQ-SC-2: one ammo tier for
// all): the highest tier every cannon can fire, or null for no cannons.
public static String bestSharedBall(List<String> cannonTiers) {
    if (cannonTiers == null || cannonTiers.isEmpty()) return null;
    int min = Integer.MAX_VALUE;
    for (String tier : cannonTiers) {
        int i = BALL_ORDER.indexOf(tier);
        if (i < 0) return null;
        min = Math.min(min, i);
    }
    return BALL_ORDER.get(min);
}

// Ship-eligible per the wiki's Ship combat roster (curated - the corpus
// has no naval attribute). Case-insensitive on the corpus name.
public static boolean nav(String monsterName) {
    return monsterName != null && NAVAL.contains(Names.lower(monsterName));
}

public static List<String> keels() { return Collections.unmodifiableList(KEELS); }

public static String normalizeKeel(String keel) {
    int i = keel == null ? -1 : LEGACY_WOOD_KEELS.indexOf(Names.lower(keel));
    return i >= 0 && i < KEELS.size() ? KEELS.get(i) : keel;
}

// The monster's effective max hit against this keel (armour already
// applied, from the wiki's Boat combat table), or -1 for an unknown
// monster/keel. A 0 means this keel cannot be hit by it at all.
public static int keelMaxHit(String monsterName, String keelTier) {
    int[] row = monsterName == null ? null : KEEL_MAX_HITS.get(Names.lower(monsterName));
    int i = KEELS.indexOf(keelTier);
    return row == null || i < 0 || i >= row.length ? -1 : row[i];
}

// Crew-fired numbers are estimates while the wiki flags the crewmate
// formula out-of-date; the UI cites this on crew tooltips.
public static boolean crewFormulaStale() { return CREW_FORMULA_STALE; }
}

package com.ll.data;

import com.google.gson.*;
import java.util.*;
import java.util.stream.Collectors;

import static com.ll.data.Json.*;
import java.util.function.IntPredicate;

// Mandatory protective slayer gear per monster (field request
// 2026-08-08: "some tasks where u need to equip something. would be
// cool if it was autopinned"): a mirror shield vs a basilisk's gaze, a
// lit bug lantern to harm harpies at all. The optimizer enforces the
// slot exactly like the dragonfire shield - the pool collapses to the
// acceptable items and non-complying weapon lines die - whenever the
// request can actually field one; a user pin on the slot outranks.
// Tables-driven from required_gear.json (a resource - token-free), every
// row wiki-verified before encoding.
public class RequiredGear {
// One monster family's requirement: the slot, the acceptable item
// specs (corpus names, optionally name#Version), and the why.
@lombok.RequiredArgsConstructor
public static class Rule {
    public final Slot slot;
    public final String note;
    final List<String> itemSpecs;
    // A waiver key that lifts the rule (KOUREND_ELITE), or null.
    final String waivedBy;
    // A convention, not a must (the Barrows hilt, the Shayzien set):
    // enforced from what you own, never forced unowned.
    public final boolean soft;
    // Resolved once per corpus - the corpus never changes post-load.
    volatile Set<Integer> resolved;

    // The acceptable item ids, resolved against the loaded corpus
    // (standard-gear rows only; variants fold via the candidate
    // pool's own canonicalization).
    public Set<Integer> ids(Tables data) {
        Set<Integer> out = resolved;
        if (out != null) return out;
        out = new LinkedHashSet<>();
        for (String spec : itemSpecs) {
            String name = spec;
            String version = null;
            int hash = spec.indexOf('#');
            if (hash >= 0) {
                name = spec.substring(0, hash);
                version = spec.substring(hash + 1);
            }
            for (Gear item : data.gearItems) {
                if (item.lname.equals(name) && item.standardGear
                    && (version == null || version.equals(item.version))) {
                    out.add(item.id);
                }
            }
        }
        resolved = out;
        return out;
    }
}

static final Map<String, List<Rule>> BY_NAME = new HashMap<>();

// The elite Kourend & Kebos diary (varbit KOUREND_DIARY_ELITE_COMPLETE):
// once its rewards are claimed Karuulm's floor no longer burns (wiki,
// Karuulm Slayer Dungeon) - the boots rule's waiver.
public static final String KOUREND_ELITE = "kourendElite";

// A carried slayer item the kill needs - the finishing blow (rock
// hammer, fungicide, salt, ice cooler): acceptable items best first,
// each with its ids (not gear, so ids rather than corpus names).
@lombok.RequiredArgsConstructor
public static class Carried {
    public final String note;
    final List<String> names;
    final List<int[]> ids;
    // A swap picked by kind rather than id: "fastRanged" = the best 2-tick
    // ranged weapon (ISS-01M65N6WS5N2V9TQC0MJ03NKY8, Hespori's sprouts).
    public final String category;
}

static final Map<String, List<Carried>> CARRIED_BY_NAME = new HashMap<>();
static final Map<String, List<Carried>> SWAPS_BY_NAME = new HashMap<>();
static final Set<String> WARD = new HashSet<>();

// required_gear.json as Gson reads it: slot rules, the ward list, the
// carried finishing items and the fight swaps.
static class Root {
    List<RuleRow> rules = List.of();
    List<String> ward = List.of();
    List<CarriedRow> carried = List.of(), swaps = List.of();
}

static class RuleRow {
    String slot, note = "", waivedBy;
    List<String> items = List.of(), monsters = List.of();
    public boolean soft;
}

static class CarriedRow {
    List<String> monsters = List.of();
    List<ItemRow> items = List.of();
    public String note = "", category;
}

static class ItemRow {
    String name;
    int[] ids;
}

static {
    // Fail LOUD (the name_rules pattern): a silently empty table would
    // drop every requirement with no visible error.
    Root root = read("required_gear.json", Root.class);
    for (RuleRow row : root.rules) {
        var rule = new Rule(Slot.valueOf(row.slot), row.note, row.items, row.waivedBy, row.soft);
        for (String m : row.monsters) BY_NAME.computeIfAbsent(m, k -> new ArrayList<>()).add(rule);
    }
    if (BY_NAME.isEmpty()) throw new IllegalStateException("required_gear.json loaded empty");
    WARD.addAll(root.ward);
    for (var table : List.of(root.carried, root.swaps)) {
        for (CarriedRow row : table) {
            List<String> names = new ArrayList<>();
            List<int[]> ids = new ArrayList<>();
            for (ItemRow item : row.items) {
                names.add(item.name);
                ids.add(item.ids);
            }
            var carried = new Carried(row.note, names, ids, row.category);
            for (String m : row.monsters) (table == root.swaps ? SWAPS_BY_NAME : CARRIED_BY_NAME).computeIfAbsent(m, k -> new ArrayList<>()).add(carried);
        }
    }
}

// The fight's swap rules (ISS-01M5VCXYGF51P5NJCDNC1QJZD1): Cerberus' spectral spirit shield.
public static List<Carried> swaps(Monster monster) {
    return monster == null ? List.of() : SWAPS_BY_NAME.getOrDefault(monster.lname, List.of());
}

// Every swap id for the monster, each rule's best first.
public static List<Integer> swapIds(Monster monster) {
    List<Integer> out = new ArrayList<>();
    for (Carried rule : swaps(monster)) {
        for (int[] ids : rule.ids) for (int id : ids) out.add(id);
    }
    return out;
}

// What a carried swap is for, or "carried swap" for any other bench item.
public static String swapNote(int id) {
    for (List<Carried> rules : SWAPS_BY_NAME.values()) {
        for (Carried rule : rules) {
            for (int[] ids : rule.ids) for (int i : ids) if (i == id) return rule.note;
        }
    }
    return "carried swap";
}

// A fight whose prayer drain is demonic: Ward of Arceuus rides the trip (ISS-01M5VCXYGF51P5NJCDNC1QJZD1).
public static boolean ward(Monster monster) { return monster != null && WARD.contains(monster.lname); }

// The requirement for this monster, or null. Name-keyed like the
// notes, so RequiredGearTest pins every key against loaded rows.
// Every rule for the monster (a full armour set is one rule per slot).
public static List<Rule> rulesFor(Monster monster) {
    return monster == null ? List.of() : BY_NAME.getOrDefault(monster.lname, List.of());
}

// The rules still standing once the player's waivers lift theirs.
public static List<Rule> rulesFor(Monster monster, Set<String> waivers) {
    return rulesFor(monster).stream().filter(rule -> rule.waivedBy == null || waivers == null
        || !waivers.contains(rule.waivedBy)).collect(Collectors.toList());
}

// slot -> acceptable ids, empty when nothing is required.
public static Map<Slot, Set<Integer>> requiredIds(Monster monster, Tables data) {
    return requiredIds(monster, data, Set.of());
}

// slot -> acceptable ids, the waived rules lifted.
public static Map<Slot, Set<Integer>> requiredIds(Monster monster, Tables data, Set<String> waivers) {
    Map<Slot, Set<Integer>> out = new EnumMap<>(Slot.class);
    for (Rule rule : rulesFor(monster, waivers)) out.put(rule.slot, rule.ids(data));
    return out;
}

// The carried slayer items this monster's kill needs, one per rule:
// the best one you own, else the best one there is, flagged unowned
// (Andrew 2026-10-22: "show them as necessary even when the player
// doesn't own those items"). Each row: id, name, qty, why, owned.
public static List<Map> carriedPicks(Monster monster, IntPredicate owns) {
    List<Map> out = new ArrayList<>();
    if (monster == null) return out;
    for (Carried rule : CARRIED_BY_NAME.getOrDefault(monster.lname, List.of())) {
        int pick = -1;
        for (int i = 0; i < rule.ids.size() && pick < 0; i++) {
            for (int id : rule.ids.get(i)) {
                if (owns.test(id)) {
                    pick = i;
                    break;
                }
            }
        }
        boolean owned = pick >= 0;
        int at = owned ? pick : 0;
        out.add(map("id", rule.ids.get(at)[0], "name", rule.names.get(at), "qty", 1,
            "why", rule.note + (owned ? "" : " - not owned: get one before the trip"), "owned", owned));
    }
    return out;
}
}

