package com.ll.data;

import java.util.*;
import java.util.stream.Collectors;

import lombok.Getter;
import java.util.regex.Pattern;
import com.google.gson.JsonObject;

@Getter
public class Tables {
public List<Gear> gearItems;
public List<Monster> monsters;
public List<Spell> spells;
Map<Integer, Gear> gearById;
Map<Integer, Integer> toBase;
// Corpus partitioned by equip slot, corpus order preserved - so slot
// scans (every optimizer pool build) skip the other ~5k rows.
Map<Slot, List<Gear>> gearBySlot;

Tables( List<Gear> gearItems, List<Monster> monsters, List<Spell> spells,
    Map<Integer, Gear> gearById, Map<Integer, Integer> toBase) {
    this.gearItems = Collections.unmodifiableList(gearItems);
    this.monsters = Collections.unmodifiableList(monsters);
    this.spells = Collections.unmodifiableList(spells);
    this.gearById = Collections.unmodifiableMap(gearById);
    this.toBase = Collections.unmodifiableMap(toBase);
    var bySlot = new EnumMap<Slot, List<Gear>>(Slot.class);
    for (Slot slot : Slot.values()) {
        bySlot.put(slot, Collections.unmodifiableList(this.gearItems.stream()
            .filter(item -> item.slot == slot).collect(Collectors.toList())));
    }
    this.gearBySlot = Collections.unmodifiableMap(bySlot);
}

// A view of this dataset containing only free-to-play gear and standard-
// spellbook spells (monsters unchanged) - drives the non-members filter.
// Ancient/Arceuus books are members-only wholesale; the F2P card was
// recommending Arceuus Dark Demonbane (audit A3.5/A1.2). Members spells
// WITHIN the standard book still pass - a finer F2P spell table can
// tighten that later.
public Tables freeToPlayView() {
    List<Gear> free = gearItems.stream().filter(g -> !g.members).collect(Collectors.toList());
    Map<Integer, Gear> byId = new HashMap<>();
    free.forEach(g -> byId.put(g.id, g));
    return new Tables(free, monsters, spells.stream()
        .filter(spell -> "standard".equalsIgnoreCase(spell.spellbook)).collect(Collectors.toList()), byId, toBase);
}

// True for ornament/locked/degraded variants of a base item with the
// same stats - never suggested; the base version stands in for them.
public boolean isVariant(int itemId) { return toBase.containsKey(itemId); }

// Owned quantities with every variant also credited to its base item,
// so an owned "Abyssal whip (or)" satisfies an "Abyssal whip" pick.
static final Pattern CHARGE = Pattern.compile("\\(*i?\\d+\\)*");

// The result cache's ownership key with charge counts folded
// (ISS-01M5V7W28574DBWHTR5ATE37Q8, Andrew 2026-10-25: "when i teleport it
// should stay the same and should be able to fully rely on the cache"):
// a teleport turns a games necklace (8) into (7), a new id. Gear counts
// as its name and its version with a bare charge number folded; any
// other version (Charged, Uncharged) and every non-gear id stays itself.
public int chargeFreeFingerprint(Map<Integer, Integer> owned) {
    var keys = new TreeSet<String>();
    for (var e : owned.entrySet()) {
        if (e.getValue() == null || e.getValue() <= 0) continue;
        Gear g = getGear(e.getKey());
        keys.add(g == null ? String.valueOf(e.getKey())
            : g.lname + "|" + (CHARGE.matcher(g.ver).matches() ? "#" : g.ver));
    }
    return keys.hashCode();
}

public Map<Integer, Integer> canonicalizeOwned(Map<Integer, Integer> owned) {
    Map<Integer, Integer> result = new HashMap<>(owned);
    for (var entry : owned.entrySet()) {
        Integer base = toBase.get(entry.getKey());
        if (base != null) result.merge(base, entry.getValue(), Integer::sum);
    }
    return result;
}

// Community nicknames and activity names -> the monster to show.
// Raids and wave activities map to their final boss - a defensible
// anchor for "what do I wear there". Keys and values are in
// normalizeQuery form.
static final Map<String, String> SEARCH_ALIASES = new HashMap<>();
// Extra search words for one version ("name|version" -> words): the
// Wardens' "p2 phase 2" (ISS-01M5HKWBZNJF0V8ZD58FH9XS5B).
static final Map<String, String> VERSION_TERMS = new HashMap<>();

static {
    JsonObject aliases = Json.objectOrThrow("search_aliases.json");
    Json.stringMap(aliases, "aliases", SEARCH_ALIASES);
    Json.stringMap(aliases, "version_terms", VERSION_TERMS);
}

public List<Monster> searchMonsters(String query, int limit) {
    String text = query == null ? "" : Monster.normalizeQuery(query.trim());
    text = SEARCH_ALIASES.getOrDefault(text, text);
    if (text.isEmpty()) return List.of();

    var exact = new ArrayList<Monster>();
    var prefix = new ArrayList<Monster>();
    var contains = new ArrayList<Monster>();
    for (Monster monster : monsters) {
        String name = Monster.normalizeQuery(monster.name);
        if (name.equals(text) || String.valueOf(monster.id).equals(text)) {
            exact.add(monster);
        } else if (name.startsWith(text)) {
            prefix.add(monster);
        } else if (monster.searchText().contains(text) || wordsMatch(text, monster)) contains.add(monster);
    }

    // Among same-name versions, surface the fight a player MEANS by the
    // bare name first: post-quest/normal over quest, Awakened, Enraged,
    // Entry/Hard mode or Deep Delve rows (which sort first alphabetically
    // and used to be the silent default for vorkath, the DT2 four, zuk
    // and verzik). Stable sort - corpus order breaks ties, and every
    // version stays reachable further down the hit list.
    // ...and the same rule holds when the query is PARTIAL (field
    // report 2026-08-16: "whisperer" kept returning the Awakened row -
    // "the whisperer" is not an exact match for it, so the version
    // sort never ran on the bucket it landed in).
    exact.sort(Comparator.comparingInt(m -> versionTier(m.version)));
    prefix.sort(Comparator.comparingInt(m -> versionTier(m.version)));
    contains.sort(Comparator.comparingInt(m -> versionTier(m.version)));

    var result = new ArrayList<Monster>(limit);
    addLimited(result, exact, limit);
    addLimited(result, prefix, limit);
    addLimited(result, contains, limit);
    return result;
}

// Every typed word starts a word of the monster's name, version, id or
// version terms, a trailing "s" forgiven - "tumeken warden" ("tumekens
// warden"), "wardens", "elidinis active", "warden p2" (Andrew 2026-10-22:
// the phase-2 Warden was unsearchable without "toa").
static boolean wordsMatch(String text, Monster monster) {
    String terms = VERSION_TERMS.get(Monster.normalizeQuery(monster.name)
        + "|" + Monster.normalizeQuery(monster.version));
    String[] words = (monster.searchText() + (terms == null ? "" : " " + terms)).split(" +");
    for (String typed : text.split(" +")) {
        if (typed.isEmpty()) continue;
        boolean found = false;
        for (String word : words) {
            if (word.startsWith(typed)
                || typed.length() > 2 && typed.endsWith("s") && word.equals(typed.substring(0, typed.length() - 1))) {
                found = true;
                break;
            }
        }
        if (!found) return false;
    }
    return true;
}

// Lower = a better default for a bare-name search.
static int versionTier(String version) {
    if (version == null || version.isEmpty()) return 1;
    String v = Names.lower(version);
    if (v.contains("post-quest")) return 0;   // the everyday fight
    if (v.contains("normal") || v.contains("serpentine")) return 1;   // normal mode / Zulrah's spawn form
    if (v.contains("awakened") || v.contains("enraged") || v.contains("entry mode")
        || v.contains("deep delve") || v.contains("quest")) {
        return 3;   // scaled/hard variants and quest-only rows: never the default
    }
    // "Hard mode" stays neutral (tier 2): where a true Normal row exists it
    // outranks hard at tier 1 anyway, and ToB's Normal rows stat-collapse
    // INTO the Hard-labeled ones (same defensive block), so for Verzik the
    // hard-labeled row IS the everyday fight's numbers.
    return 2;
}

static <T> void addLimited(List<T> target, List<T> source, int limit) {
    for (T entry : source) {
        if (target.size() >= limit) return;
        target.add(entry);
    }
}

// All ids interchangeable with this one for OWNERSHIP purposes: the
// base plus every variant that canonicalizes to it - so a bank
// highlight for "Abyssal whip" also lights the (or) version.
public Set<Integer> equivalentIds(int itemId) {
    Integer base = toBase.getOrDefault(itemId, itemId);
    Set<Integer> ids = new HashSet<>(List.of(itemId, base));
    toBase.forEach((variant, b) -> {
        if (b.equals(base)) ids.add(variant);
    });
    return ids;
}

public Gear getGear(int id) { return gearById.get(id); }


// The corpus items for one equip slot, in getGearItems() order.
public List<Gear> getGearItems(Slot slot) { return gearBySlot.get(slot); }


}

package com.ll.data;

import com.google.gson.*;
import java.util.*;
import java.util.function.*;

import static com.ll.data.Json.*;

// Trip supplies (food, fast food, prayer restores, surge, anti-venom): the
// curated tier tables behind the persistent supply defaults. Tiers live in
// trip_supplies.json (hub token cap), best first per category; "Detect best"
// walks a category in order and picks the first option the player owns any
// dose of. Anti-venom only applies against the wiki Venom page's inflictor
// list (the only monsters able to inflict venom).
public class Trip {
public static final String FOOD = "food";
static final String FAST_FOOD = "fastFood";
public static final String PRAYER_RESTORE = "prayerRestore";
public static final String SURGE = "surge";
static final String SPELLBOOK_CAPE = "spellbookCape";
public static final String ANTIVENOM = "antivenom";
public static final String SHIP_REPAIR_KIT = "shipRepairKit";
public static final String ANTIPOISON = "antipoison";
// The dwarf multicannon as a five-cell kit (miko 2026-10-17): no dps, no placement rules, never auto-detected.
public static final String CANNON = "cannon";
// Getting there (ISS-01M5JJ0Z4M988DR0M0ZGJHD139, Andrew 2026-10-22): the teleport capes,
// best first, the Crafting cape an explicit choice.
static final String TELEPORT_CAPE = "teleportCape";
// A boss's own teleport, carried in the inventory (ISS-01M5RMNK62507Q42KKCJ9A7AEE).
public static final String BOSS_TELEPORT = "bossTeleport";
public static final String[] CATEGORY_KEYS = {FOOD, FAST_FOOD, PRAYER_RESTORE, SURGE, SPELLBOOK_CAPE, TELEPORT_CAPE, BOSS_TELEPORT, ANTIVENOM, ANTIPOISON, SHIP_REPAIR_KIT, CANNON};

// One supply choice: ids best-first, ids[0] the display/cell id and the
// full list the bank-filter membership (every dose matches).
@lombok.AllArgsConstructor
public static class Option {
    public String key;
    public String name;
    public int[] ids;
    // False = only selectable explicitly (prayer regeneration's
    // over-time mechanism should never win an auto-detect).
    public boolean detect;
    // True = fight-relevant gear that is neither worn nor carried
    // (spellbook capes): the bank layout's third strip, below the
    // cross and the inventory block (field spec 2026-07-20).
    public boolean utility;
    // True = usable only in the wilderness (blighted supplies): detect
    // prefers it on a wilderness trip and never picks it elsewhere.
    boolean wildyOnly;
    // Per-item names for a kit (one card cell each); empty for doses.
    public String[] names;
    // A kit cell's ids - the display id first, then its variants (the
    // ornamented cannon parts, granite cannonballs); null = ids[i] alone.
    public int[][] cells;
    // The bosses (exact lower-case names) a boss-specific option serves; empty = any trip.
    public String[] monsters;
    // A varbit that must be set before the option works (the ring of shadows' tablets); 0 = none.
    int unlock;
}

static final Map<String, List<Option>> CATEGORIES = new LinkedHashMap<>();
static final Map<String, String> LABELS = new LinkedHashMap<>();
static final Set<String> VENOMOUS = new HashSet<>();
static final Set<String> POISONOUS = new HashSet<>();
static final Set<String> NO_CANNON = new HashSet<>();

static {
    JsonObject root = object("trip_supplies.json");
    if (root != null) {
        for (String category : CATEGORY_KEYS) {
            List<Option> options = new ArrayList<>();
            JsonArray arr = root.getAsJsonArray(category);
            if (arr != null) {
                for (Row o : gson().fromJson(arr, Row[].class)) {
                    options.add(new Option(o.key, o.name, o.ids, o.detect, "utility".equals(o.placement), o.wildyOnly,
                        o.names, o.cells, o.monsters, o.unlock));
                }
            }
            CATEGORIES.put(category, options);
        }
        stringMap(root, "labels", LABELS);
        strings(root, "venomousMonsters", VENOMOUS);
        strings(root, "poisonMonsters", POISONOUS);
        strings(root, "noCannonMonsters", NO_CANNON);
    }
}

// An option row as Gson reads it (trip_supplies.json).
static class Row {
    String key, name = "", placement;
    public int[] ids;
    public boolean detect = true, wildyOnly;
    public String[] names = new String[0], monsters = new String[0];
    public int[][] cells;
    int unlock;
}


// The grey chip's submenu label, or null for a category the menu never
// shows (ship repair kits ride the sea card).
public static String label(String category) { return LABELS.get(category); }

// The category's options, best first.
public static List<Option> options(String category) { return CATEGORIES.getOrDefault(category, List.of()); }

// The option a config-enum constant names, or null (NONE/DETECT_BEST
// and unknown keys resolve to null).
public static Option option(String category, String key) {
    return options(category).stream().filter(o -> o.key.equals(key)).findFirst().orElse(null);
}

// Detect best for a trip: in the wilderness a banked blighted variant
// wins outright (cheap to lose, wilderness-only); on land no
// wilderness-only option is ever picked (Andrew 2026-09-01).
public static Option detectBest(List<Option> options, IntPredicate owns, boolean inWilderness) {
    Option pick = null;
    for (Option o : options) {
        if (!o.detect || (o.wildyOnly && !inWilderness)) continue;
        for (int id : o.ids) {
            if (owns.test(id)) {
                if (o.wildyOnly) return o;
                if (pick == null) pick = o;
                break;
            }
        }
    }
    return pick;
}

// Detect best on land: the first detectable option the player owns
// any dose of, or null when they own none.
public static Option detectBest(String category, IntPredicate owns) { return detectBest(options(category), owns, false); }

// The options that fit a trip: any general one; a boss-specific one when a
// trip mob is one of its bosses and its unlock (if any) is set.
public static List<Option> fitting(String category, List<Monster> mobs, IntPredicate unlocked) {
    List<Option> out = new ArrayList<>();
    for (Option o : options(category)) {
        if ((o.monsters.length == 0 || mobs.stream().anyMatch(m -> Arrays.asList(o.monsters).contains(m.lname)))
            && (o.unlock == 0 || unlocked.test(o.unlock))) { out.add(o); }
    }
    return out;
}

// The options' unlock varbits that are set.
public static Set<Integer> unlocked(IntUnaryOperator varbit) {
    Set<Integer> out = new HashSet<>();
    CATEGORIES.values().forEach(list -> list.forEach(o -> { if (o.unlock > 0 && varbit.applyAsInt(o.unlock) > 0) { out.add(o.unlock); } }));
    return out;
}

// True when the monster can inflict venom (wiki Venom page inflictor
// list, matched by name so araxyte/snakeling variants count).
public static boolean inflictsVenom(Monster monster) { return named(monster, VENOMOUS); }

// Poisons but does not envenom (the Kings' spinolyps, KQ...) - the
// antipoison category; venomous mobs keep anti-venom.
public static boolean inflictsPoison(Monster monster) {
    return named(monster, POISONOUS) && !named(monster, VENOMOUS);
}

// No cannon here: a prohibited arena or cannon-immune (exact names).
public static boolean noCannon(Monster monster) {
    return monster != null && NO_CANNON.contains(monster.lname);
}

static boolean named(Monster monster, Set<String> tokens) {
    if (monster == null) return false;
    String name = monster.lname;
    return tokens.stream().anyMatch(name::contains);
}
}

package com.ll.data;

import java.util.*;
import com.google.gson.JsonObject;

// Monsters fought in the Wilderness, where dying to a PKer risks your
// gear. Verified vs the wiki (Items Kept on Death, 2026-07-07): death
// keeps your 3 highest-GE/alch-value items (4 with Protect Item; 0/1
// skulled); since the June 2026 rework most untradeables are kept in
// the Wilderness, with combat-capable ones returning broken/mangled
// for a coin repair above level 20. A low-risk set therefore wears NO
// MORE tradeables than the kept count - value ranking then cannot
// drop any of them - and untradeables everywhere else.
// Curated list: the boss ring, escape-cave counterparts, KBD, the
// Revenant Caves, and the non-boss monsters players actually fight in
// the Wilderness (Slayer Cave dwellers, dragons, Krystilia-task and
// moneymaker mobs) - many also exist elsewhere, but the low-risk
// toggles default off, so offering them costs nothing outside.
public class WildernessMonsters {
// Curated lists live in wilderness_monsters.json (hub token cap).
