package com.ll.engine;

// A potion/prayer-free stat boost applied on top of the base levels.
// <p>Every non-live profile is the same shape - floor(flat + level * factor)
// added to a fixed set of skills - so each constant just carries its flat
// term, its factor, and which skills it touches as letters over the alphabet
// a(ttack) s(trength) d(efence) r(anged) m(agic). Magic potion's flat +4 is
// encoded as factor 0.0, which makes floor(4 + level * 0.0) exactly 4.
@lombok.AllArgsConstructor
public enum BoostProfile {
NONE("No boosts", 0, 0, ""), LIVE_CURRENT("Current boosted levels", 0, 0, ""),
// Label deliberately avoids " + " - the assumes chips split on it.
F2P_COMBAT("Attack & strength potions", 3, 0.10, "as"), SUPER_COMBAT("Super combat", 5, 0.15, "asd"),
// The pair a super combat replaces, for a bank with none left (field report 2026-10-29).
SUPER_ATTACK_STRENGTH("Super attack & strength", 5, 0.15, "as"),
// Divine variants boost identically; they hold the boost at ceiling
// for 5 minutes instead of decaying, so they are the preferred assumption.
DIVINE_SUPER_COMBAT("Divine super combat", 5, 0.15, "asd"), RANGING("Ranging potion", 4, 0.10, "r"),
DIVINE_RANGING("Divine ranging potion", 4, 0.10, "r"),
// Same ranged numbers as the ranging potion; the super-defence half
// is deliberately unmodeled here (outgoing dps never reads it).
BASTION("Bastion potion", 4, 0.10, "r"), DIVINE_BASTION("Divine bastion potion", 4, 0.10, "r"),
SUPER_RANGING("Super ranging", 5, 0.15, "r"), SATURATED_HEART("Saturated heart", 4, 0.10, "m"),
IMBUED_HEART("Imbued heart", 1, 0.10, "m"), MAGIC("Magic potion", 4, 0.0, "m"), DIVINE_MAGIC("Divine magic potion", 4, 0.0, "m"),
// Magic potion's flat +4 with the unmodeled super-defence half.
BATTLEMAGE("Battlemage potion", 4, 0.0, "m"), DIVINE_BATTLEMAGE("Divine battlemage potion", 4, 0.0, "m"),
SUPER_MAGIC("Super magic", 5, 0.15, "m"), OVERLOAD("Overload", 5, 0.13, "asdrm"),
OVERLOAD_PLUS("Overload (+)", 6, 0.16, "asdrm"), SMELLING_SALTS("Smelling salts", 11, 0.16, "asdrm");

String label;
int flat;
double factor;
// Which skills this profile boosts, as letters from "asdrm".
String skills;

public Levels apply(Levels base, Levels current) {
    Levels source = base == null ? Levels.MAXED : base;
    if (this == LIVE_CURRENT) return current == null ? source : current;
    // NONE boosts nothing and must hand back the SAME instance: the
    // general path below always allocates a fresh Levels.
    if (skills.isEmpty()) return source;
    return source.withBoosts( boostIf('a', source.attack), boostIf('s', source.strength),
        boostIf('d', source.defence), boostIf('r', source.ranged), boostIf('m', source.magic));
}

// True when this profile boosts the skill letter (from "asdrm") - the
// assume-chip picker filters style-relevant boosts with it.
public boolean boosts(char skill) { return skills.indexOf(skill) >= 0; }

// floor(flat + level * factor), or 0 when this profile skips the skill.
int boostIf(char skill, int level) {
    return skills.indexOf(skill) < 0 ? 0 : (int) Math.floor(flat + level * factor);
}

public String toString() { return label; }
}

package com.ll.engine;

import com.ll.data.*;
import lombok.*;
import com.google.gson.*;
import com.google.gson.reflect.TypeToken;
import java.util.*;

// Curated incoming-damage sheets for bosses the corpus describes badly
// (boss_incoming.json): each boss's attacks with their share of the
// rotation, max hit, speed, prayer behaviour, layered damage, the heal
// they give the boss off what lands, and a note. Gson fills the rows;
// the defaults a key can leave out are the field initialisers.
public class BossIncomingOverrides {
static final String RESOURCE = "boss_incoming.json";

@Getter
static class Attack {
    String style;
    int maxHit, speedTicks, hits = 1;
    double share, leak;
    boolean prayable = true, avoidable, flicked, chain;
    // Null in the data = 0 when prayable, 1 when not.
    Double prayerFactor;
    String name = "";
    Map<String, int[]> layers;
    Heal heal;
}

// The boss heals factor x the damage landed, at least min, at most max.
static class Heal {
    double factor, min, max = Double.POSITIVE_INFINITY;
}

@Getter
public static class BossOverride {
    List<Attack> attacks = List.of();
    String note = "";
    // The share of the fight the boss can be hit; 1 = always.
    public double uptime = 1;
    // A fixed time the fight adds whatever you hit with (Hespori's
    // flower rounds), in seconds, and what it is.
    public double downtime;
    public String downtimeNote = "";
    transient boolean heals;
}

static final Map<String, BossOverride> OVERRIDES = new HashMap<>();
static final Map<String, String> UNPRICED = new HashMap<>();

static {
    Map<String, JsonElement> root = Json.read(RESOURCE, new TypeToken<Map<String, JsonElement>>() { }.getType());
    for (var entry : root.entrySet()) {
        if ("_unpriced".equals(entry.getKey())) {
            for (var why : entry.getValue().getAsJsonObject().entrySet()) UNPRICED.put(Names.lower(why.getKey()), why.getValue().getAsString());
        } else if (!entry.getKey().startsWith("_")) OVERRIDES.put(Names.lower(entry.getKey()), parse(entry.getValue().getAsJsonObject()));
    }
}

static BossOverride parse(JsonObject json) {
    BossOverride o = Json.gson().fromJson(json, BossOverride.class);
    for (Attack a : o.attacks) {
        a.style = Names.lower(a.style);
        a.hits = Math.max(1, a.hits);
        if (a.prayerFactor == null) a.prayerFactor = a.prayable ? 0.0 : 1.0;
        o.heals |= a.heal != null;
    }
    return o;
}


static BossOverride overridesFor(Monster monster) { return lookup(OVERRIDES, monster); }

static boolean heals(Monster monster) {
    BossOverride override = overridesFor(monster);
    return override != null && override.heals;
}

static String unpricedReason(Monster monster) { return lookup(UNPRICED, monster); }

static final BossOverride NONE = new BossOverride();

// The boss's override, or the no-op one: its uptime, downtime and note.
public static BossOverride of(Monster monster) {
    BossOverride override = overridesFor(monster);
    return override == null ? NONE : override;
}

static <T> T lookup(Map<String, T> map, Monster monster) {
    if (monster == null) return null;
    String version = monster.version;
    if (version != null && !version.isEmpty()) {
        T byForm = map.get((monster.lname + "|" + version).toLowerCase(Locale.ROOT));
        if (byForm != null) return byForm;
    }
    return map.get(monster.lname);
}

static Set<String> names() { return Collections.unmodifiableSet(OVERRIDES.keySet()); }
}

