package com.ll.engine;

import lombok.Getter;
import com.ll.data.*;
import java.util.*;

@Getter
public class Kit {
EnumMap<Slot, Gear> gear;
public Stats offensive;
public Stats defensive;
public Stats bonuses;
public int cost;
// The worn items (a null is an empty slot): the name-fragment checks
// scan these, so a trial builds no joined name string (that was 27% of
// the optimizer's allocation).
Gear[] worn;
// Gear.marks of the worn items, built on the first check; the
// active variant (uncharged crystal skipped) cached beside it.
volatile int[] marks, activeMarks;

public Kit(Map<Slot, Gear> gear) { this(copyOf(gear), true); }

// Adopt the given map WITHOUT copying: the caller hands over ownership
// and must never mutate it afterward. The optimizer builds a fresh
// EnumMap per beam trial - the public constructor's defensive copy
// doubled that work across hundreds of thousands of trials.
static Kit adopting(EnumMap<Slot, Gear> gear) { return new Kit(gear, true); }

static EnumMap<Slot, Gear> copyOf(Map<Slot, Gear> gear) {
    var copy = new EnumMap<Slot, Gear>(Slot.class);
    copy.putAll(gear);
    return copy;
}

// The marker keeps this overload from ever being chosen by a plain
// {@code new Kit(enumMap)} - adoption must be an explicit opt-in.
public Kit(EnumMap<Slot, Gear> gear, boolean adoptMarker) {
    this.gear = gear;

    // Summed into an int array, not Stats.plus chains - the chain
    // allocated ~3 blocks per worn item per trial (top allocation site).
    int[] off = new int[9];
    int[] def = new int[9];
    int[] bon = new int[9];
    // Long, then capped: one capped price plus anything would wrap negative,
    // which Dps shows as free.
    long totalCost = 0;
    for (Gear item : this.gear.values()) {
        if (item == null) continue;
        add(off, item.offensive);
        add(def, item.defensive);
        add(bon, item.bonuses);
        totalCost += item.getPriceOrZero();
    }
    offensive = block(off);
    defensive = block(def);
    bonuses = block(bon);
    cost = (int) Math.min(Integer.MAX_VALUE, totalCost);
    worn = gear.values().toArray(new Gear[0]);
}

static void add(int[] acc, Stats block) {
    acc[0] += block.stab;
    acc[1] += block.slash;
    acc[2] += block.crush;
    acc[3] += block.magic;
    acc[4] += block.ranged;
    acc[5] += block.strength;
    acc[6] += block.rangedStrength;
    acc[7] += block.magicDamage;
    acc[8] += block.prayer;
}

static Stats block(int[] acc) {
    return new Stats(acc[0], acc[1], acc[2], acc[3], acc[4], acc[5], acc[6], acc[7], acc[8]);
}

// Ammunition carried IN a Dizana's quiver rather than the ammo slot
// (see QuiverAmmo). Set once by the display post-pass on final
// results - never inside the beam - so the field stays off the hot
// path. Deliberately OUTSIDE the stat sums: QuiverAmmo.strength adds
// it in the max-hit chain, mirroring the blowpipe's loaded dart.
public Gear quiverAmmo;

// A copy with ammunition moved into the quiver (see QuiverAmmo).
Kit withQuiverAmmo(Gear carried) {
    var copy = new Kit(copyOf(gear), true);
    copy.quiverAmmo = carried;
    return copy;
}

// A copy with one slot changed (null empties it); the quiver's
// carried ammo rides along.
public Kit with(Slot slot, Gear item) {
    EnumMap<Slot, Gear> copy = copyOf(gear);
    if (item == null) {
        copy.remove(slot);
    } else copy.put(slot, item);
    var out = new Kit(copy, true);
    out.quiverAmmo = quiverAmmo;
    return out;
}

// The worn items, empty slots skipped.
public List<Gear> items() {
    List<Gear> items = new ArrayList<>(gear.size());
    for (Gear item : gear.values()) if (item != null) items.add(item);
    return items;
}

// The worn item ids.
public Set<Integer> ids() {
    Set<Integer> ids = new HashSet<>();
    for (Gear item : items()) ids.add(item.id);
    return ids;
}

public Gear get(Slot slot) { return gear.get(slot); }

public Gear getWeapon() { return gear.get(Slot.WEAPON); }

public Map<Slot, Gear> getGear() { return Collections.unmodifiableMap(gear); }

// A worn item's name holds the lower-case marker; active = "Inactive"
// versions (uncharged crystal) never match.
boolean wears(String marker, boolean active) { return wears(Gear.markerBit(marker), active); }

// The hot form: the marker's bit resolved once by the caller
// (Calc's constants and rule rows), no map lookup per check.
boolean wears(int bit, boolean active) {
    int[] m = active ? activeMarks : marks;
    if (m == null || m[0] <= bit) {
        m = Gear.marks(worn, active);
        if (active) activeMarks = m;
        else marks = m;
    }
    return (m[1 + (bit >> 5)] >>> bit & 1) != 0;
}
}

