package com.ll.engine;

import com.ll.data.*;
import java.util.*;
import net.runelite.api.*;
import static net.runelite.api.Skill.*;

public class RequirementProfile {
public static final RequirementProfile MAXED = new RequirementProfile(maxedLevels(), allQuests());

Map<Skill, Integer> levels;
Set<String> cq;

// Items worn whatever their requirements: the simmed max capes, whose
// 99-in-every-skill rule the seven-level stat sim cannot meet
// (ISS-01M5RYC2TB43AEGQ96TTNEKEJN).
Set<Integer> waived;

public RequirementProfile(Map<Skill, Integer> levels, Set<String> cq) { this(levels, cq, Set.of()); }

public RequirementProfile(Map<Skill, Integer> levels, Set<String> cq, Set<Integer> waived) {
    this.waived = Set.copyOf(waived);
    var copy = new EnumMap<Skill, Integer>(Skill.class);
    if (levels != null) copy.putAll(levels);
    this.levels = copy;
    this.cq = new HashSet<>(cq == null ? Set.of() : cq);
}

// The same levels with every quest done - the game-best ceiling never
// trims on the quest log (Andrew 2026-09-09).
public RequirementProfile withAllQuests() { return new RequirementProfile(levels, allQuests(), waived); }

public RequirementProfile waiving(Set<Integer> ids) { return new RequirementProfile(levels, cq, ids); }

public boolean canWear(Gear item) { return waived.contains(item.id) || canEquip(item.requirements); }

// The same quests with the seven combat levels replaced: the stat
// sim's gear gate (ISS-01M5QY13K6YHTYDW1CCYD30CSY) - 99 Attack admits the
// fang, 60 drops it; the other skills ride along unchanged.
public RequirementProfile withLevels(Levels simmed) {
    Map<Skill, Integer> next = new EnumMap<>(Skill.class);
    next.putAll(levels);
    next.put(ATTACK, simmed.attack);
    next.put(STRENGTH, simmed.strength);
    next.put(DEFENCE, simmed.defence);
    next.put(RANGED, simmed.ranged);
    next.put(MAGIC, simmed.magic);
    next.put(PRAYER, simmed.prayer);
    next.put(HITPOINTS, simmed.hitpoints);
    return new RequirementProfile(next, cq, waived);
}

// Both already unmodifiable (the constructor wraps its copies).
public Map<Skill, Integer> getLevels() { return levels; }

public Set<String> getCq() { return cq; }

public boolean canEquip(GearRequirements requirements) {
    if (requirements == null || requirements.isEmpty()) return true;
    for (var entry : requirements.getSkills().entrySet()) {
        Skill skill = skill(entry.getKey());
        if (skill != null && levels.getOrDefault(skill, 1) < entry.getValue()) return false;
    }
    for (String quest : requirements.getQuests()) if (!cq.contains(quest)) return false;
    return true;
}

int level(Skill skill) { return levels.getOrDefault(skill, 1); }

static Skill skill(String name) {
    if (name == null) return null;
    String normalized = name.toUpperCase(Locale.ROOT);
    if ("RUNECRAFTING".equals(normalized)) normalized = "RUNECRAFT";
    try {
        return Skill.valueOf(normalized);
    } catch (IllegalArgumentException ex) { return null; }
}

static Map<Skill, Integer> maxedLevels() {
    var result = new EnumMap<Skill, Integer>(Skill.class);
    for (Skill skill : Skill.values()) if (skill != OVERALL) result.put(skill, 99);
    return result;
}

static Set<String> allQuests() {
    Set<String> result = new HashSet<>();
    for (Quest quest : Quest.values()) result.add(quest.name());
    return result;
}
}

// Derived from guccifurs/best-dps (BSD-2-Clause, Copyright (c) 2026, Noid) - see licenses/best-dps-LICENSE.
package com.ll.engine;
import static java.lang.Math.*;

public class RollMath {
static final double SECONDS_PER_TICK = 0.6;


static double normalAccuracy(long ar, long dr) {
    double atk = ar;
    double def = dr;
    if (atk < 0) atk = min(0, atk + 2);
    if (def < 0) def = min(0, def + 2);
    if (atk >= 0 && def >= 0) return atk > def ? 1.0 - ((def + 2.0) / (2.0 * (atk + 1.0))) : atk / (2.0 * (def + 1.0));
    if (atk >= 0) return 1.0 - 1.0 / ((-def + 1.0) * (atk + 1.0));
    if (def >= 0) return 0.0;
    double swappedAtk = -def;
    double swappedDef = -atk;
    return swappedAtk > swappedDef ? 1.0 - ((swappedDef + 2.0) / (2.0 * (swappedAtk + 1.0))) : swappedAtk / (2.0 * (swappedDef + 1.0));
}

static int effectiveLevel(int level, double prayer, int stanceBonus) {
    return (int) floor(level * prayer) + stanceBonus + 8;
}

static int maxHitFromEffective(int effectiveLevel, int strengthBonus) {
    return max(0, (int) floor((effectiveLevel * (strengthBonus + 64.0) + 320.0) / 640.0));
}

static long ar(int effectiveLevel, int attackBonus) {
    return (long) effectiveLevel * (attackBonus + 64L);
}

static long dr(int effectiveLevel, int defenceBonus) {
    return (long) effectiveLevel * (defenceBonus + 64L);
}

static double normalExpectedHit(double accuracy, int maxHit) {
    if (maxHit <= 0 || accuracy <= 0.0) return 0.0;
    return accuracy * (maxHit / 2.0 + 1.0 / (maxHit + 1.0));
}

// The venator bow's chain in multi (wiki): two bounces, each rolled on
// its own accuracy at a max of two-thirds of the first, floored - so
// the whole arrow is worth 1 + 2 x E(floor(2m/3)) / E(m) single hits
// (accuracy cancels). One target: 1.
public static double venatorFactor(int maxHit) {
    if (maxHit <= 0) return 1.0;
    return 1.0 + 2.0 * normalExpectedHit(1.0, maxHit * 2 / 3) / normalExpectedHit(1.0, maxHit);
}

// Expected hit under the monster's FLAT ARMOUR, official-calc
// semantics (flatAddTransformer, verified 2026-08-21): POSITIVE
// armour clamps EVERY roll to max(0, k - armour) - the low rolls
// become zeros, which the old shifted-bounds model missed
// (Eclipse Moon overpriced ~16%, grey golem ~15%). Negative
// armour (Blood/Blue Moon's flat bonus) is an exact bound shift,
// delegated so armour-free numbers stay bit-identical. Bounds are
// RAW (pre-armour).
static double expectedHitWithFlatArmour(double accuracy, int minHit, int maxHit, int armour) {
    if (armour <= 0) {
        // NEGATIVE armour is a flat damage BONUS, and their
        // transformer applies it after the accurate-zero rule (a
        // landed 0 counts as 1). Shifting the bounds instead
        // silently dropped that bump - every Blood/Blue Moon set ran
        // 0.1-0.5% low (field 2026-08-21). Riding the bonus on top
        // of the normal expectation keeps the bump AND the shift.
        return eh(accuracy, minHit, maxHit) + accuracy * -armour;
    }
    if (maxHit <= 0 || accuracy <= 0.0) return 0.0;
    int lo = max(0, min(minHit, maxHit));
    // sum(max(0, k - armour)) over k in [lo, maxHit], closed form: the
    // rolls at or under the armour contribute nothing, the rest are a
    // run of consecutive integers. Walking the rolls gave the same
    // total, but this runs on EVERY melee and ranged trial.
    long first = max((long) lo, (long) armour + 1);
    long sum = first > maxHit ? 0 : triangle(maxHit - armour) - triangle(first - armour - 1);
    return accuracy * ((double) sum / (maxHit - lo + 1));
}

// The best of several damage rolls on one landed hit (the Obligator's
// Lunge): P(best = v) weights each roll's damage under the same flat
// armour rule as expectedHitWithFlatArmour; best of one is that hit.
static double bestOfExpected(double accuracy, int maxHit, int rolls, int armour) {
    if (maxHit <= 0 || accuracy <= 0.0) return 0.0;
    double total = 0;
    double below = 0;
    for (int v = 0; v <= maxHit; v++) {
        double atMost = pow((v + 1.0) / (maxHit + 1.0), rolls);
        total += (atMost - below) * (armour > 0 ? max(0, v - armour) : max(1, v) - armour);
        below = atMost;
    }
    return accuracy * total;
}

// 0 + 1 + ... + n; n below zero is an empty run.
static long triangle(long n) { return n <= 0 ? 0 : n * (n + 1) / 2; }

static double eh(double accuracy, int minHit, int maxHit) {
    if (maxHit <= 0 || accuracy <= 0.0) return 0.0;
    if (minHit <= 0) return normalExpectedHit(accuracy, maxHit);
    int minimum = min(minHit, maxHit);
    return accuracy * ((minimum + maxHit) / 2.0);
}

// Confliction gauntlets (official BaseCalc): casting one-handed
// grants a SECOND accuracy roll, resolved as
// double / (1 + double - single) - the same double-roll the fang
// uses, folded so the extra roll cannot exceed certainty.
static double conflictionAccuracy(long ar, long dr) {
    double single = normalAccuracy(ar, dr);
    double doubleRoll = fangAccuracy(ar, dr);
    double denominator = 1 + doubleRoll - single;
    return denominator <= 0 ? single : doubleRoll / denominator;
}

static double fangAccuracy(long ar, long dr) {
    double atk = ar;
    double def = dr;
    if (atk < 0) atk = min(0, atk + 2);
    if (def < 0) def = min(0, def + 2);
    if (atk >= 0 && def >= 0) {
        return atk > def ? 1.0 - (def + 2.0) * (2.0 * def + 3.0) / (atk + 1.0) / (atk + 1.0) / 6.0
            : atk * (4.0 * atk + 5.0) / 6.0 / (atk + 1.0) / (def + 1.0);
    }
    if (atk >= 0) return 1.0 - 1.0 / (-def + 1.0) / (atk + 1.0);
    if (def >= 0) return 0.0;
    double reversedAttack = -def;
    double revDef = -atk;
    return reversedAttack < revDef
        ? reversedAttack * (revDef * 6.0 - 2.0 * reversedAttack + 5.0) / 6.0 / (revDef + 1.0) / (revDef + 1.0)
        : 1.0 - (revDef + 2.0) * (2.0 * revDef + 3.0) / 6.0 / (revDef + 1.0) / (reversedAttack + 1.0);
}
}

package com.ll.engine;

import com.ll.data.*;
import java.util.*;
import lombok.*;
import java.util.regex.Pattern;

// Rules a set must keep (ISS-01M5XA7NVZYGVR3EVTM05XHXKP): thresholds over the
// worn set's totals, banned item names and an optional weapon allow-list - a
// combat achievement's restrictions or the player's own ("at least 12
// prayer"). Names match case-insensitively on the item name, every version.
// The task-wide kinds (ISS-01M5ZQH7H4ZS95N6274QQ7EAJB): the styles allowed,
// weapon categories, demonbane, one-handed, no weapon, one melee attack type,
// no prayer, one spellbook, spell families and a level cap.
@Getter
@ToString
@Builder(toBuilder = true)
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class Rules {
// {stat, op, value}: op is >=, <=, > or <.
@Value
public static class Rule {
    String stat;
    String op;
    double value;

    public boolean holds(double total) {
        switch (op) {
            case ">=": return total >= value;
            case "<=": return total <= value;
            case ">": return total > value;
            default: return total < value;
        }
    }

    // Whether some total in [lo, hi] could still hold.
    boolean reachable(double lo, double hi) { return op.startsWith(">") ? holds(hi) : holds(lo); }

    // This rule wants named items worn.
    boolean names() { return op.startsWith(">") && stat.startsWith("has:"); }
}

@Builder.Default
final List<Rule> rules = List.of();
@Builder.Default
final Set<String> banned = Set.of();
// Weapon names allowed; null = no name list.
final Set<String> weapons;
// Weapon categories allowed (lowercase: "spear", "salamander"); null = none.
final Set<String> weaponCategories;
// A demonbane weapon is allowed (with the lists above, any one match does).
final boolean demonbaneWeapon;
final boolean bannedDemonbane;
final boolean oneHanded;
// No weapon at all: melee punches, magic casts manually.
final boolean unarmed;
// Magic may search an empty weapon slot, casting manually.
final boolean noWeaponMagic;
// The combat styles allowed (other styles get no set); null = every style.
final Set<Style> styles;
// The one melee attack type ("stab", "crush"), or null.
final String attackType;
// No prayer-restoring supplies (The Praying Mantis: pray, never restore).
public final boolean noPrayerRestore;
// The one spellbook ("arceuus"), or null.
public final String spellbook;
// Fragments a spell's name must contain (any one), or null.
final List<String> spells;
// No item may need a level above this; 0 = no cap.
final int levelCap;
// The weapon must poison or envenom (A Slow Death, ISS-01M60HTYZT9DTZKDSFAGRNNK53).
final boolean poisonWeapon;
// A free-to-play world: the page's F2P lock rides the task.
public final boolean f2p;
// Further weapon allow-lists and spell families, each of which must also
// hold - what and() keeps apart, since one list is an OR within itself.
@Builder.Default
final List<Rules> also = List.of();

public static Rules of(List<Rule> rules, Set<String> banned, Set<String> weapons) {
    return builder().rules(rules).banned(lower(banned)).weapons(weapons == null ? null : lower(weapons)).build();
}

// "prayer>=12;def_ranged>=100" -> rules, in order; a part that does not parse is skipped.
public static List<Rule> parse(String text) {
    List<Rule> out = new ArrayList<>();
    if (text == null) return out;
    for (String part : text.split(";")) {
        var m = Pattern.compile("\\s*([a-z_:]+)\\s*(>=|<=|>|<)\\s*(-?[0-9.]+)\\s*").matcher(part);
        if (m.matches() && STATS.contains(m.group(1))) out.add(new Rule(m.group(1), m.group(2), Double.parseDouble(m.group(3))));
    }
    return out;
}

// The stats a rule may name.
static final List<String> STATS = List.of("stab", "slash", "crush", "magic", "ranged", "def_stab", "def_slash",
    "def_crush", "def_magic", "def_ranged", "str", "ranged_str", "magic_str", "prayer", "weight");

// These rules plus more thresholds (everything else kept).
public Rules plus(List<Rule> more) {
    List<Rule> all = new ArrayList<>(rules);
    all.addAll(more);
    return toBuilder().rules(List.copyOf(all)).build();
}

static Set<String> lower(Set<String> names) {
    Set<String> out = new HashSet<>();
    for (String n : names) out.add(Names.lower(n));
    return out;
}

// These rules AND another set's (ISS-01M601Z57QM43W7SHNHCRMWDCE: two tasks at once, Andrew 2026-10-27:
// "the challenge cards in the requirements seem to operate on an OR basis
// but can and should be able to be AND"): thresholds and bans add up, the
// styles narrow, and each weapon list must hold on its own.
public Rules and(Rules o) {
    if (o == null) return this;
    List<Rule> all = new ArrayList<>(rules);
    all.addAll(o.rules);
    Set<String> bans = new HashSet<>(banned);
    bans.addAll(o.banned);
    Set<Style> both = styles == null ? o.styles : o.styles == null ? styles : EnumSet.copyOf(styles);
    if (styles != null && o.styles != null) both.retainAll(o.styles);
    List<Rules> parts = new ArrayList<>(also);
    parts.addAll(o.also);
    boolean mine = hasWeaponList(), theirs = o.hasWeaponList();
    if (theirs && mine || o.spells != null && spells != null) parts.add(o.weaponsAndSpellsOnly());
    int cap = levelCap == 0 ? o.levelCap : o.levelCap == 0 ? levelCap : Math.min(levelCap, o.levelCap);
    var b = toBuilder().rules(List.copyOf(all)).banned(bans).styles(both).also(List.copyOf(parts))
        .bannedDemonbane(bannedDemonbane || o.bannedDemonbane).oneHanded(oneHanded || o.oneHanded)
        .unarmed(unarmed || o.unarmed).noPrayerRestore(noPrayerRestore || o.noPrayerRestore)
        .attackType(attackType != null ? attackType : o.attackType).spellbook(spellbook != null ? spellbook : o.spellbook)
        .levelCap(cap).poisonWeapon(poisonWeapon || o.poisonWeapon).f2p(f2p || o.f2p)
        // Empty hands only when some task asks for them and no weapon list forbids them.
        .noWeaponMagic((noWeaponMagic || o.noWeaponMagic) && (noWeaponMagic || !mine) && (o.noWeaponMagic || !theirs));
    if (!mine && theirs) b.weapons(o.weapons).weaponCategories(o.weaponCategories).demonbaneWeapon(o.demonbaneWeapon);
    if (spells == null && o.spells != null) b.spells(o.spells);
    return b.build();
}

boolean hasWeaponList() { return weapons != null || weaponCategories != null || demonbaneWeapon; }

Rules weaponsAndSpellsOnly() {
    return builder().weapons(weapons).weaponCategories(weaponCategories).demonbaneWeapon(demonbaneWeapon).spells(spells).build();
}

// May this style have a set at all?
boolean allowsStyle(Style style) { return styles == null || styles.contains(style); }

// May this item be worn at all (bans, the level cap, and the weapon rules for weapons)?
boolean allows(Gear item) {
    if (item == null) return true;
    if (banned.contains(item.lname)) return false;
    if (levelCap > 0 && item.requirements.getSkills().values().stream().anyMatch(level -> level > levelCap)) return false;
    if (item.slot != Slot.WEAPON) return true;
    if (unarmed || bannedDemonbane && item.demonbane || oneHanded && item.twoh) return false;
    if (attackType != null && WeaponStyles.melee(item).stream().noneMatch(s -> s.attackType.equals(attackType))) return false;
    if (poisonWeapon && !poisons(item)) return false;
    for (Rules part : also) if (!part.allows(item)) return false;
    if (weapons == null && weaponCategories == null && !demonbaneWeapon) return true;
    return weapons != null && weapons.contains(item.lname)
        || weaponCategories != null && weaponCategories.contains(item.categoryLower)
        || demonbaneWeapon && item.demonbane;
}

// A poisoned version, or a charged venom weapon (toxic blowpipe, toxic staff).
static boolean poisons(Gear weapon) {
    if (weapon.poisonTier() > 0) return true;
    String version = Names.lower(weapon.version);
    return weapon.lname.startsWith("toxic ") && !version.contains("uncharged") && !version.contains("empty");
}

// May magic cast with no weapon?
boolean emptyHanded(Style style) {
    return unarmed && style != Style.RANGED || noWeaponMagic && style == Style.MAGIC;
}

// May this spell be cast?
boolean allowsSpell(String spellNameLower) {
    return (spells == null || spells.stream().anyMatch(spellNameLower::contains))
        && also.stream().allMatch(part -> part.allowsSpell(spellNameLower));
}

// One item's contribution to a stat: a bonus, weight, price, "has:<name>"
// (1 when the name starts with it) or "slot:<slot>" (1 in that slot).
public static double of(Gear item, String stat) {
    if (item == null) return 0;
    if (stat.startsWith("has:")) return item.lname.startsWith(stat.substring(4)) ? 1 : 0;
    if (stat.startsWith("slot:")) return item.slot.name().equalsIgnoreCase(stat.substring(5)) ? 1 : 0;
    Stats off = item.offensive, def = item.defensive, bon = item.bonuses;
    switch (stat) {
        case "weight": return item.weight;
        case "price": return item.getRulePrice();
        case "str": return bon.strength;
        case "ranged_str": return bon.rangedStrength;
        case "magic_str": return bon.magicDamage;
        case "prayer": return bon.prayer;
        default:
            return stat.startsWith("def_") ? def.getAttackBonus(stat.substring(4)) : off.getAttackBonus(stat);
    }
}

public static double total(Kit loadout, String stat) {
    double sum = 0;
    for (Gear item : loadout.getGear().values()) sum += of(item, stat);
    return sum;
}

// How far this set has come on the rules that want named items worn: a met
// rule counts the same however far past it the set is, and more than any
// unmet count (a set holds 11 items), so two of one do not outrank
// one each of two rules. The beam keeps lines at every count.
int namedProgress(Kit loadout) {
    int sum = 0;
    for (Rule r : rules) if (r.names()) sum += r.holds(total(loadout, r.stat)) ? 12 : (int) total(loadout, r.stat);
    return sum;
}

// Every item is allowed and every rule holds on this finished set.
public boolean holds(Kit loadout) {
    for (Gear item : loadout.getGear().values()) if (!allows(item)) return false;
    if (poisonWeapon && loadout.getWeapon() == null) return false;
    for (Rule rule : rules) if (!rule.holds(total(loadout, rule.getStat()))) return false;
    return true;
}
}

package com.ll.engine;

// Boat-cannon math (wiki: Boat combat / Cannons, verified 2026-08-31). Pure
// formulas; the data (per-tier strengths, accuracies, tick rate) lives in
// NavalCombat and callers pass numbers in.
// <p>Player-fired: max hit rides the player's EFFECTIVE ranged level - the
// caller applies prayer/void through the engine's existing effective-level
// machinery, exactly as land ranged does - and the worn ranged strength
// bonus counts EXCLUDING the weapon, shield and ammo slots (wiki: those
// three are ignored at the cannon).
// <p>Crew-fired: the last documented formula scales a base max hit by the
// crew's Privateering level, (priv + 13) / 20. The wiki flags this formula
// out-of-date with the real one unknown, so it is isolated HERE and marked
// by NavalCombat.crewFormulaStale() - when the corrected formula lands,
// this one method changes and every caller stays put.
public class ShipCannon {
// All cannons fire on the same cycle regardless of tier.
static final double ATTACK_SECONDS = 4.2;


// Max hit for a player-fired cannon:
// floor((level * (cannonStr + ballStr + wornStr + 64) + 320) / 640),
// plus one when a perildance bitter keg is aboard.
public static int playerMaxHit(int effectiveRanged, int cannonStrength, int ballStrength, int wornRangedStrength, boolean perildance) {
    long strength = cannonStrength + ballStrength + wornRangedStrength + 64L;
    int hit = (int) ((effectiveRanged * strength + 320L) / 640L);
    return hit + (perildance ? 1 : 0);
}

// The stale-but-documented crew scaling: floor(base * (priv + 13) / 20).
public static int crewMaxHit(int baseMaxHit, int privateering) {
    return (int) (baseMaxHit * (privateering + 13L) / 20L);
}

// The cannon's equipment accuracy: its heavy-ranged accuracy plus the
// ball's, plus worn ranged accuracy excluding weapon/shield/ammo. Rolls
// against the monster's HEAVY defence through the standard machinery.
public static int equipmentAccuracy(int cannonHeavyAccuracy, int ballAccuracy, int wornRangedAccuracy) {
    return cannonHeavyAccuracy + ballAccuracy + wornRangedAccuracy;
}

// Hit chance vs the monster's HEAVY ranged defence, through the same
// roll math the land engine uses. Effective level is visible ranged
// + 8 (no stance bonus at a cannon); prayer accuracy multipliers are
// the caller's concern, matching how the wiki's calculator treats
// prayer as an input to the level term.
public static double hitChance(int effectiveRanged, int equipmentAccuracy, int monsterDefence, int monsterHeavyBonus) {
    long attack = RollMath.ar(effectiveRanged + 8, equipmentAccuracy);
    long defence = RollMath.dr(monsterDefence + 9, monsterHeavyBonus);
    return RollMath.normalAccuracy(attack, defence);
}

// DPS of one cannon: average landed damage over the 7-tick cycle.
// hitChance in [0,1]; a landed hit averages (maxHit / 2) with the
// uniform damage roll the game uses.
public static double dps(int maxHit, double hitChance) { return hitChance * (maxHit / 2.0) / ATTACK_SECONDS; }
}

package com.ll.engine;

import lombok.*;
import com.ll.data.*;
import java.util.*;
import static java.lang.Math.*;

// Special-attack definitions and expected-damage math.
// <p>Every entry's cost/modifiers were verified against the OSRS Wiki
// "Special attacks" page (and individual weapon pages) on 2026-07-05.
// Accuracy modifiers multiply the ATTACK ROLL (not the final hit chance),
// matching in-game mechanics; damage modifiers scale the max hit.
// <p>Expected damage is per single use of the special attack, against the
// monster the base result was computed for. Utility effects (defence
// drains, heals, bolt procs) are described in {@link #getNote()} but not
// folded into the number.
@AllArgsConstructor(access = AccessLevel.PRIVATE)
@Getter
public class SpecialAttack {
enum Kind {
    // One hit: accuracy and/or damage multipliers.
    SINGLE,
    // Two fully independent hits (dragon dagger, dragon knife).
    DOUBLE_INDEPENDENT,
    // Two hits that share one accuracy outcome (abyssal dagger).
    LINKED_DOUBLE,
    // Guaranteed damage, uniform 50-150% of max (voidwaker).
    VOIDWAKER,
    // Up to 4 accuracy rolls; damage tier by which roll landed (dragon claws).
    CLAWS,
    // Two hits, boosted damage roll with a minimum per hit, capped at 48 (dark bow).
    DARK_BOW,
    // Two arrows; custom prayer-less max-hit formula, 10/7 accuracy (magic shortbow).
    MSB_SNAPSHOT,
    // +10% damage; a second hit at 75% accuracy vs large monsters (halberds).
    HALBERD_SWEEP,
    // An instant extra normal attack (granite maul).
    EXTRA_ATTACK,
    // Level-scaled unique damage roll (volatile nightmare staff).
    VOLATILE,
    // One accuracy roll; a hit deals EXACTLY damageMultiplier * max, no damage roll (sunspear).
    FIXED_FRACTION,
    // Four independent accuracy rolls; damage tier scales with successes (crimson kisten).
    MULTI_ROLL_TIERED,
    // Claws-style cascade with tier means 1.25/1.00/0.75 of max (burning claws).
    CASCADE_CLAWS,
    // A landed cast buffs the next three, fired every two ticks (Zorya's tome).
    BUFFED_FOLLOWUPS,
}

static final int DARK_BOW_CAP = 48;

String[] namePrefixes;
String displayName;
public Style style;
Kind kind;
public int energyCost;
double accuracyMultiplier;
double damageMultiplier;
String note;
// Defence drained on a damaging hit, as a fraction of CURRENT defence
// (DWH 0.30, elder maul 0.35); 0 for non-drain specs. BGS drains by
// damage dealt - modeled via {@link #drainsByDamage}.
double defenceDrainFraction;
boolean drainsByDamage;
// Drains DEFENCE by this fraction of the target's MAGIC level per
// landed spec (Tonalztics of ralos' Division - wiki 2026-08-09:
// 12.5% per glaive hit, two glaives charged = 25% per spec).
double magicDrainFraction;
// Targets the spec hits in a multi area (wiki); 0 = single-target.
int multiTargets;

// Wiki-verified entries live in special_attacks.json (hub token cap:
// data rides resources, not source). Order matters: more specific
// prefixes ("magic shortbow (i)") come first in the file.
static final List<SpecialAttack> REGISTRY = loadRegistry();

// A special_attacks.json row as Gson reads it.
static class Row {
    List<String> prefixes = List.of();
    String name, style, kind, note;
    int cost, multi;
    double accuracy, damage, drainFraction, drainMagicFraction;
    boolean drainsByDamage;
}

static List<SpecialAttack> loadRegistry() {
    List<SpecialAttack> specs = new ArrayList<>();
    try {
        for (Row row : Json.read("special_attacks.json", Row[].class)) {
            specs.add(new SpecialAttack(row.prefixes.toArray(new String[0]), row.name, Style.valueOf(row.style), Kind.valueOf(row.kind),
                row.cost, row.accuracy, row.damage, row.note, row.drainFraction, row.drainsByDamage, row.drainMagicFraction, row.multi));
        }
    } catch (Exception e) {
        // A malformed table must never take the client down; the spec
        // tests fail loudly on an empty registry instead.
        return List.of();
    }
    return specs;
}


// The definition for this weapon at this combat style, or null.
public static SpecialAttack match(Gear item, Style style) {
    SpecialAttack spec = match(item);
    return spec != null && spec.style == style ? spec : null;
}

// Style-free match: the spec swap is its own weapon switch, so every
// spec weapon is a candidate for ANY set (field request 2026-07-17 -
// "sometimes you want to use magic + chally").
public static SpecialAttack match(Gear item) {
    if (item == null || item.slot != Slot.WEAPON) return null;
    String name = item.lname;
    for (SpecialAttack spec : REGISTRY) {
        for (String prefix : spec.namePrefixes) if (name.startsWith(prefix)) return spec;
    }
    return null;
}

// Expected damage of ONE special attack, given the normal-attack result
// for the same loadout (source of max hit and attack/defence rolls).
// The spec's multiplier at a stack of targets (the Multi card, Andrew
// 2026-10-19): the stack capped at the targets it hits; 1 single-target.
public double multiFactor(int stack) { return multiTargets <= 0 ? 1 : max(1, min(stack, multiTargets)); }

public double expectedDamage(Dps base, Monster monster, Levels levels) {
    // The Wardens' ejected core (wiki): melee "will always deal their
    // max hit" - hitChance and every damage roll collapse to their
    // caps. Without this, the rolls below would halve every spec's
    // value at the one place the game is built around spec dumping.
    if (style == Style.MELEE && MonsterMechanics.isWardenCore(monster)) return coreMaxDamage(base, monster);
    long ar = base.ar;
    long dr = base.dr;
    double hitChance = RollMath.normalAccuracy( (long) (ar * accuracyMultiplier), dr);
    int max = base.maxHit;
    // One boosted hit's mean, and its expectation over the accuracy roll.
    double boosted = mean((int) (max * damageMultiplier));
    double hit = hitChance * boosted;

    switch (kind) {
        case SINGLE:
            return hit;
        case DOUBLE_INDEPENDENT:
            return 2 * hit;
        case LINKED_DOUBLE:
            // One accuracy outcome for both hits.
            return hit * 2;
        case VOIDWAKER:
            // Uniform 50-150% of max, no accuracy roll: averages exactly max.
            return max;
        case CLAWS:
            return clawsExpected(hitChance, max);
        case DARK_BOW:
            return darkBowExpected(hitChance, max, usesDragonArrows(base));
        case MSB_SNAPSHOT:
            return 2 * hitChance * mean(snapshotMax(base, levels));
        case HALBERD_SWEEP:
            // A second hit at 75% accuracy vs large monsters.
            return monster != null && monster.size > 1
                ? hit + RollMath.normalAccuracy((long) (ar * 0.75), dr) * boosted : hit;
        case EXTRA_ATTACK:
            return base.eh;
        case FIXED_FRACTION:
            // No damage roll: a hit deals exactly damageMultiplier * max.
            return hitChance * damageMultiplier * max;
        case MULTI_ROLL_TIERED:
            return multiRollTieredExpected(hitChance, max);
        case CASCADE_CLAWS:
            return cascadeClawsExpected(hitChance, max);
        case BUFFED_FOLLOWUPS:
            return hit * (1 + 3 * hitChance);
        case VOLATILE:
        default:
            return hitChance * mean(volatileMax(base, levels));
    }
}

// Every melee hit at the Warden's core deals its max (wiki) - each
// kind collapses to its hit count at the TOP of its damage range:
// doubles land both boosted hits, the claw cascades sit at their
// tier-1 cap, the voidwaker's uniform roll caps at 150%. The 1x1
// core denies the halberd sweep its second hit - which is exactly
// why the DDS dump beats a chally there (field report 2026-08-06).
double coreMaxDamage(Dps base, Monster monster) {
    int max = base.maxHit;
    switch (kind) {
        case HALBERD_SWEEP:
            return (monster.size > 1 ? 2.0 : 1.0)
                * (int) (max * damageMultiplier);
        case DOUBLE_INDEPENDENT:
        case LINKED_DOUBLE:
            return 2.0 * (int) (max * damageMultiplier);
        case CLAWS:
            return 2.0 * max; // tier-1 cascade cap (max + halves/quarters)
        case CASCADE_CLAWS:
            return 1.5 * max; // tier-1 cap of the 1.25-mean uniform
        case MULTI_ROLL_TIERED:
            return 1.7 * max; // four successes, top of the k=4 range
        case VOIDWAKER:
            return 1.5 * max;
        case EXTRA_ATTACK:
            return base.eh; // already max via calculate()
        case SINGLE:
        case FIXED_FRACTION:
        default:
            return (int) (max * damageMultiplier);
    }
}

// Dragon claws cascade: accuracy is rolled up to four times; the tier of
// the successful roll sets the damage-roll modifier (100/75/50/25% of
// max added to the minimum). Expected totals per tier: 1.5max-1,
// 1.25max, max, 0.75max; a full miss averages ~1.
static double clawsExpected(double p, int max) {
    double miss = 1 - p;
    return p * (1.5 * max - 1) + miss * p * (1.25 * max) + miss * miss * p * max
        + miss * miss * miss * p * (0.75 * max) + pow(miss, 4) * 1.0;
}

// Crimson kisten Brutal Swing: four independent accuracy rolls; with
// k >= 1 successes damage is uniform in [(50+20k)%, (90+20k)%] of max
// (mean (0.7 + 0.2k) * max); zero successes deal nothing.
static double multiRollTieredExpected(double p, int max) {
    // Binomial coefficients C(4, k) for k = 0..4.
    int[] choose = {1, 4, 6, 4, 1};
    double expected = 0;
    for (int k = 1; k <= 4; k++) {
        expected += choose[k] * pow(p, k) * pow(1 - p, 4 - k)
            * (0.7 + 0.2 * k) * max;
    }
    return expected;
}

// Burning claws cascade: the first successful roll (of up to three)
// sets the tier - uniform damage with means 1.25/1.00/0.75 of max; a
// full miss deals 0/1/2 with 20/40/40% odds (expected 1.2). The burn
// damage-over-time is described in the note, not counted here.
static double cascadeClawsExpected(double p, int max) {
    double miss = 1 - p;
    return p * (1.25 * max) + miss * p * (1.00 * max) + miss * miss * p * (0.75 * max) + miss * miss * miss * 1.2;
}

// Dark bow: two hits, each rolled 0..boostedMax then clamped [min, 48].
static double darkBowExpected(double p, int max, boolean dragonArrows) {
    int boosted = (int) (max * (dragonArrows ? 1.5 : 1.3));
    int min = dragonArrows ? 8 : 5;
    double sum = 0;
    for (int d = 0; d <= boosted; d++) sum += min(DARK_BOW_CAP, max(min, d));
    return 2 * p * (sum / (boosted + 1));
}

static boolean usesDragonArrows(Dps base) {
    Gear ammo = base.loadout.get(Slot.AMMO);
    return ammo != null && ammo.lname.startsWith("dragon arrow");
}

// Snapshot max hit ignores prayers and void:
// floor(0.5 + (visible ranged + 10) * (ammo ranged str + 64) / 640).
static int snapshotMax(Dps base, Levels levels) {
    Gear ammo = base.loadout.get(Slot.AMMO);
    int ammoStrength = ammo == null ? 0 : ammo.bonuses.rangedStrength;
    return (int) floor(0.5 + (levels.ranged + 10) * (ammoStrength + 64) / 640.0);
}

// Volatile spec max: spell max is min(floor(58 * level / 99) + 1, 58)
// - 58 from level 98 up - then the loadout's magic damage bonus
// (tenths of a percent) scales it. Wiki anchors: level 84 gives spell
// max 50 (57 with the staff's 15% bonus); level 99 gives 58 (66).
static int volatileMax(Dps base, Levels levels) {
    int spellMax = min((int) floor(58.0 * levels.magic / 99.0) + 1, 58);
    double gearBonus = 1 + base.loadout.bonuses.magicDamage / 1000.0;
    return (int) floor(spellMax * gearBonus);
}

static double mean(int maxHit) { return maxHit / 2.0; }

// Ticks a spec spends beyond its own cast: the tome's follow-ups.
public double extraTicks(Dps base) { return kind == Kind.BUFFED_FOLLOWUPS ? 6 * landChance(base) : 0; }

// Chance this spec lands a damaging hit, from the base result's rolls.
public double landChance(Dps base) {
    if (kind == Kind.VOIDWAKER) return 1.0;
    return RollMath.normalAccuracy( (long) (base.ar * accuracyMultiplier), base.dr);
}

// The monster's Defence level after ONE successful use of this spec, or
// the unchanged level for non-drain specs. BGS drains by damage dealt.
public int drainedDefence(int currentDefence, double specExpectedDamage) {
    if (drainsByDamage) return max(0, currentDefence - (int) specExpectedDamage);
    if (defenceDrainFraction > 0) return currentDefence - (int) (currentDefence * defenceDrainFraction);
    return currentDefence;
}

// Monster-aware drain: the Division spec measures its DEFENCE drain
// off the target's MAGIC level, so it shines exactly where a DWH
// cannot reach (the wiki's example: Zulrah's 300 Magic).
public int drainedDefence(Monster monster, double specExpectedDamage) {
    if (magicDrainFraction > 0) return max(0, monster.defence - (int) (monster.magic * magicDrainFraction));
    return drainedDefence(monster.defence, specExpectedDamage);
}

public boolean drainsDefence() { return drainsByDamage || defenceDrainFraction > 0 || magicDrainFraction > 0; }
}

