package com.ll.engine;

import com.ll.data.*;
import java.util.*;

// The slayer-task bracelet preference (field report 2026-10-17: "include
// ... Expeditious bracelet for all setups"; Andrew: an option for slayer
// tasks, reachable from the settings panel and the bracelet slot). On task
// every style card's hands slot is pinned to it unless the mob pins its
// own hands slot; off task, and on raids (never a task context), nothing
// changes. Unpriced like any pin - the model cannot value a task bracelet.
public enum TaskBracelet {
NONE(0), EXPEDITIOUS_BRACELET(21177), BRACELET_OF_SLAUGHTER(21183);

int itemId;

TaskBracelet(int itemId) { this.itemId = itemId; }

// The mob's pins with this bracelet in HANDS for every concrete style
// that has no hands pin of its own; the input is never mutated. Only a
// slayer monster on task counts - the task param can outlive the chip
// (Andrew 2026-10-18: Orca wore the bracelet).
public static Map<Style, Map<Slot, Integer>> overlay(
    Map<Style, Map<Slot, Integer>> pins, Monster monster, boolean onTask, TaskBracelet choice) {
    if (!onTask || monster == null || !monster.slayerMonster || choice == null || choice == NONE) return pins;
    var out = new EnumMap<Style, Map<Slot, Integer>>(Style.class);
    out.putAll(pins);
    for (Style style : Style.concreteValues()) {
        var mine = new EnumMap<Slot, Integer>(Slot.class);
        Map<Slot, Integer> had = pins.get(style);
        if (had != null) mine.putAll(had);
        mine.putIfAbsent(Slot.HANDS, choice.itemId);
        out.put(style, mine);
    }
    return out;
}
}

package com.ll.engine;

import com.ll.data.*;

// Tormented Demon mechanics, matching the official calculator's default
// phase view (verified against weirdgloop's engine 2026-07-05):
// <ul>
// <li>Player accuracy is effectively 100% (their shield phases leave them
//     defenceless to properly-aimed attacks; only the active 'Shielded'
//     phase resists, which the official calc's default also ignores).</li>
// <li>They take 20% reduced damage unless hit by a demonbane weapon/spell
//     or an abyssal weapon (whip, tentacle, dagger, bludgeon).</li>
// </ul>
// Not modeled: the Unshielded-phase bonus for crush/heavy/spell attacks.
public class TormentedDemonRules {
static final String[] ABYSSAL = {
    "abyssal whip", "abyssal tentacle", "abyssal dagger", "abyssal bludgeon", };


static boolean applies(Monster monster) {
    return monster != null && "Tormented Demon".equalsIgnoreCase(monster.name);
}

// The flat 20% reduction, bypassed by demonbane and abyssal weapons.
static double damageFactor(Monster monster, Style style, Gear weapon, String spellName) {
    if (!applies(monster)) return 1.0;
    return bypassesReduction(style, weapon, spellName) ? 1.0 : 0.8;
}

static boolean bypassesReduction(Style style, Gear weapon, String spellName) {
    if (style == Style.MAGIC) return spellName != null && spellName.contains("Demonbane");
    // The demonbane weapon vocabulary lives on Gear (one list with
    // MonsterMechanics and the optimizer's demon bump); a melee name
    // can never be the weapon of a RANGED attack, so one flag serves
    // both remaining styles.
    if (weapon == null) return false;
    if (weapon.demonbane) return true;
    for (String abyssal : ABYSSAL) if (weapon.lname.startsWith(abyssal)) return true;
    return false;
}
}

package com.ll.engine;

import com.ll.data.*;
import com.google.gson.*;
import java.util.*;

// What dying to another player above level 20 Wilderness costs per worn
// UNTRADEABLE item, under the June 2026 Items Kept on Death rework
// (wiki: Trouver parchment + Items Kept on Death, verified 2026-07-07):
// - Category 1 (no combat benefit): never lost, costs nothing.
// - Category 2 (some combat bonuses): breaks; the victim pays the item's
//   own repair/replacement fee (per-item, wiki-sourced). This bucket also
//   carries the component-drop items (crystal armour reverts to a seed for
//   the killer, slayer helm drops as a black mask, imbued rings drop the
//   base ring, ...) priced at the component's value.
// - Category 3 (strong combat bonuses): trouver-locked once (permanent);
//   each PvP death above 20 Wilderness mangles the item and the victim
//   pays 500,000 coins to restore it (the killer receives the fee). We
//   assume the one-time lock has already been done, so the per-death cost
//   is the flat 500k mangle fee.
// Entries in untradeable_death.json are keyed by lowercase item name
// (Gear.name, no version suffix). An UNLISTED untradeable that
// carries any combat stats falls back to a conservative 500,000 default:
// unknowns must not smuggle into "low-risk" sets for free - curation
// whittles the list, the default keeps the risk budget honest meanwhile.
// Untradeables with no combat stats (graceful class) cost nothing.
public class UntradeableDeathCosts {
static final String RESOURCE = "untradeable_death.json";

// Conservative fallback for combat untradeables we have not curated.
static final long UNKNOWN_COMBAT_UNTRADEABLE_GP = 500_000L;

static final Map<String, Long> COST_BY_NAME = new HashMap<>();
static final Map<String, Integer> CATEGORY_BY_NAME = new HashMap<>();
// Curated rebuild-errand proxies (re-obtain/re-enchant/re-imbue time,
// NOT gp - imbue points refund since April 2024). Counted into the
// risk total and the risk cap so "free but a 25-minute errand" items
// never read as safe (field request).
static final Map<String, Long> FRICTION_BY_NAME = new HashMap<>();

static {
    JsonObject root = Json.object(RESOURCE);
    if (root == null) {
        throw new IllegalStateException("Could not load " + RESOURCE);
    } {
        for (var entry : root.entrySet()) {
            JsonObject row = entry.getValue().getAsJsonObject();
            String name = Names.lower(entry.getKey());
            COST_BY_NAME.put(name, row.get("costGp").getAsLong());
            CATEGORY_BY_NAME.put(name, row.get("category").getAsInt());
            if (row.has("frictionGp")) FRICTION_BY_NAME.put(name, row.get("frictionGp").getAsLong());
        }
    }
}


// Per-death gp cost of wearing this item into PvP above 20 Wilderness.
// Tradeables cost 0 here - their loss is priced by the kept-slot
// ranking in PvpRisk - EXCEPT category 5 (destroyed on any death,
// protection does not help), which charges regardless of tradeability.
static long costFor(Gear item) {
    if (item == null) return 0L;
    if (item.tradeable) {
        Long destroyed = categoryFor(item) == 5 ? COST_BY_NAME.get(item.lname) : null;
        return destroyed == null ? 0L : destroyed;
    }
    Long listed = COST_BY_NAME.get(item.lname);
    if (listed != null) return listed;
    return hasCombatStats(item) ? UNKNOWN_COMBAT_UNTRADEABLE_GP : 0L;
}

// Rebuild-errand proxy for a death loss (0 when none curated).
static long frictionFor(Gear item) {
    if (item == null) return 0L;
    Long friction = FRICTION_BY_NAME.get(item.lname);
    return friction == null ? 0L : friction;
}

// Category 5: destroyed on any death - never protectable.
static boolean dod(Gear item) { return categoryFor(item) == 5; }

// Category 4: converts to a tradeable component dropped for the
// killer (slayer helm -> black mask, crystal -> seed). These are
// LOSABLE, so they compete for kept-on-death protection slots at
// their component value - protecting one prevents the drop.
static boolean isConvertible(Gear item) { return categoryFor(item) == 4; }

// Curated category (1, 2, 3 or 4-converts), or 0 when unlisted.
static int categoryFor(Gear item) {
    if (item == null) return 0;
    Integer listed = CATEGORY_BY_NAME.get(item.lname);
    return listed == null ? 0 : listed;
}

static boolean hasCombatStats(Gear item) {
    return nonZero(item.offensive) || nonZero(item.defensive) || nonZero(item.bonuses);
}

static boolean nonZero(Stats block) {
    return block.stab != 0 || block.slash != 0 || block.crush != 0 || block.magic != 0 || block.ranged != 0
        || block.strength != 0 || block.rangedStrength != 0 || block.magicDamage != 0 || block.prayer != 0;
}
}

package com.ll.engine;

import com.google.gson.JsonObject;
import com.ll.data.*;
import java.util.*;
import static com.ll.data.Json.*;
import static com.ll.engine.Style.*;

// Vampyres at parity with the official calculator's engine
// (ISS-01M5RM2A7FFR9XWKATPX877TDD; osrs-dps-calc 89c3e25b). Tier 1 takes
// every weapon, silver ones at +10%; tier 2 only vampyrebane weapons, silver
// weapons (each hit capped at 10, PR #671) or anything with Efaritay's aid
// (each hit halved); tier 3 only a vampyrebane weapon in melee or the
// blisterwood stake - never a spell (wiki: "no spells are capable of dealing
// damage to vampyres"). The names and numbers ride vampyre_weapons.json,
// whose comment carries every place this follows the wiki over the calc.
public class VampyreRules {
static final Map<String, List<String>> NAMES = new HashMap<>();
static final Map<String, Integer> N = new HashMap<>();

static {
    JsonObject data = objectOrThrow("vampyre_weapons.json");
    for (String key : List.of("silver", "silverRanged", "bane2", "bane3")) strings(data, key, NAMES.computeIfAbsent(key, k -> new ArrayList<>()));
    intMap(data, "numbers", N);
}

static final int EFARITAY = N.get("efaritay");


// 1-3 for a vampyre's tier, 0 for anything else.
static int tier(Monster m) {
    return m == null ? 0 : m.vampyreTier;
}

static String name(Gear item) { return item == null ? "" : item.lname; }

static boolean in(String list, Gear item) { return NAMES.get(list).contains(name(item)); }

// Vampyrebane at a tier: the stake in ranged; the listed weapons in
// melee, and vs tier 2 in any style (the calc's wearingVampyrebane).
static boolean bane(int tier, Style style, Gear weapon) {
    return style == RANGED ? in("silverRanged", weapon) : (tier == 2 || style == MELEE) && in(tier == 2 ? "bane2" : "bane3", weapon);
}

// Silver: the listed weapons in melee; silver ammo or the stake in ranged.
static boolean silver(Style style, Kit loadout) {
    return style == RANGED ? in("silverRanged", loadout.get(Slot.AMMO)) || bane(0, style, loadout.getWeapon())
        : style == MELEE && in("silver", loadout.getWeapon());
}

static boolean ring(Kit loadout) { return name(loadout.get(Slot.RING)).equals("efaritay's aid"); }

// The weapon-level tier-3 bar the pool filter shares: a tier-3
// weapon, and never a spell (ISS-01M5RGMT70PG86MWHPF28DBJ3V).
static boolean canDamage(Monster monster, Style style, Gear weapon) {
    return tier(monster) != 3 || bane(3, style, weapon);
}

// The calc's isImmune: tier 3 without vampyrebane; tier 2 without
// vampyrebane, Efaritay's aid or a silver weapon.
static boolean immune(Monster monster, Style style, Kit loadout) {
    int tier = tier(monster);
    return tier == 3 ? !bane(3, style, loadout.getWeapon())
        : tier == 2 && !bane(2, style, loadout.getWeapon()) && !ring(loadout) && !silver(style, loadout);
}

// The melee roll vs any vampyre, after the post rules (the calc's
// order): the weapon's own bonus, then a silver weapon with the ring.
static long accuracy(Monster monster, Kit loadout, long roll) {
    if (tier(monster) == 0) return roll;
    roll = roll * N.getOrDefault("acc " + name(loadout.getWeapon()), 100) / 100;
    return silver(MELEE, loadout) && ring(loadout) ? roll * N.get("efaritayAccuracy") / 100 : roll;
}

// A result vs a vampyre with each hit through the calc's map - the
// weapon's scale (the ring's first), the raised accurate 0, then tier
// 2's halving or cap. Exact for one uniform hit: the expectation scales
// by the mapped sum over the plain one, where an accurate 0 already
// counts as 1.
static Dps apply(Monster monster, Style style, Kit loadout, Dps result) {
    int tier = tier(monster), top = result.maxHit;
    if (tier == 0) return result;
    Gear weapon = loadout.getWeapon();
    boolean ring = ring(loadout), silver = silver(style, loadout);
    int scale = N.getOrDefault("dmg " + name(weapon), silver && tier == 1 ? N.get("silverTier1") : 0);
    boolean half = tier == 2 && ring && !bane(2, style, weapon), cap = tier == 2 && !half && silver;
    if (tier == 0 || top <= 0 || scale == 0 && !half && !cap) return result;
    int ringScale = ring ? N.get("efaritayDamage") : 100, v = 0;
    double plain = 0, mapped = 0;
    for (int d = 0; d <= top; d++) {
        v = Math.max(1, scale == 0 ? d : d * ringScale / 100 * scale / 100);
        mapped += v = half ? v / 2 : cap ? Math.min(v, N.get("tier2Cap")) : v;
        plain += Math.max(1, d);
    }
    double r = mapped / plain;
    return result.withHit(result.dps * r, result.accuracy, result.eh * r, v, Dist.scaled(result.hd, r));
}
}

