// The classic activeSupplies, core-side: config defaults overlaid
// by the lensed mob's overrides, Detect = best owned tier, antivenom
// only for venomous rosters. Each node carries the category's full
// option list for the override menu.
// Wilderness carried-kit fates for the risk lists (Andrew 2026-08-31:
// the inventory is part of what is lost/kept). Trip quantities are
// unknown, so items are listed by fate, not priced: a trouver-locked
// pouch and the untradeable cape are kept; the runes (a locked pouch
// does not protect its contents - wiki (l)) and every supply pick are
// lost. Keys "kept" and "lost".
static Map<String, List<String>> wildyCarriedFates(int pouch, boolean cape, List<String> supplies, boolean utilityRunes) {
    List<String> kept = new ArrayList<>();
    List<String> lost = new ArrayList<>();
    if (pouch == 27509) {
        kept.add(text("divine.rune"));
    } else if (pouch == 24416) kept.add("Rune pouch (locked - kept)");
    if (cape) kept.add("Magic cape (kept)");
    if (utilityRunes) lost.add("Trip runes (lost)");
    for (String supply : supplies) lost.add(supply + " (lost)");
    return Map.of("kept", kept, "lost", lost);
}

List<Map> suppliesNode(List<Monster> mobs) {
    Supplier<Map<String, String>> ds = supplyDefaults;
    StoreOps ops = storeOps;
    IntPredicate owns = ownedCheck;
    Monster lensed = lmob();
    List<Map> nodes = new ArrayList<>();
    // The dragonfire assumption is a supply too (Andrew 2026-10-18: "when
    // the super antifire is selected it should be put into the inventory").
    int antifire = intParam("antifireMode");
    if (antifire > 0 && mobs.stream().anyMatch(DragonfireRules::breathesFire)) {
        int[] doses = antifire == 2 ? DragonfireRules.SUPER_ANTIFIRE_IDS : DragonfireRules.REGULAR_ANTIFIRE_IDS;
        nodes.add(map("category", "antifire", "name", antifire == 2 ? "Super antifire potion" : "Antifire potion", "itemId", doses[0],
            "ids", Arrays.stream(doses).boxed().collect(toList()), "options", List.of()));
    }
    if (ds == null || ops == null || owns == null || lensed == null) return nodes;
    Map<String, String> defaults = ds.get();
    Map<String, String> overrides = ops.mobs().supplyOverrides(lensed.profileId());
    // At sea the BOAT takes the hits (Andrew 2026-09-02): a sea-only
    // trip packs repair kits and nothing edible; a mixed roster keeps
    // the land categories for its land half.
    boolean seaOnly = !mobs.isEmpty() && mobs.stream().allMatch(m -> nav(m.name));
    boolean ob = reliesOnAnotherBook(lensed);
    for (var e : defaults.entrySet()) {
        String category = e.getKey();
        String mode = overrides.getOrDefault(category, e.getValue());
        if (ob && "CURE_ME".equals(mode)) mode = "DETECT_BEST";
        if ("NONE".equals(mode) || (seaOnly && !Trip.SHIP_REPAIR_KIT.equals(category))
            || (Trip.CANNON.equals(category) && flag("raidSelection"))) {
            continue;
        }
        if (Trip.SHIP_REPAIR_KIT.equals(category)) {
            // Repair kits are the ship's food - recommended only for a
            // sea mob that can actually damage YOUR keel (Andrew,
            // 2026-08-31: ">0 damage"). A dragon keel at a hammerhead
            // carries nothing.
            String keel = String.valueOf(state.pn().get("shipKeel"));
            if (keelMaxHit(lensed.name, keel) <= 0) continue;
        }
        if (Trip.ANTIVENOM.equals(category) && mobs.stream().noneMatch(Trip::inflictsVenom)
            || Trip.ANTIPOISON.equals(category) && mobs.stream().noneMatch(Trip::inflictsPoison)
            || Trip.CANNON.equals(category) && mobs.stream().anyMatch(Trip::noCannon)) {
            continue;
        }
        // A boss's own teleport (ISS-01M5RMNK62507Q42KKCJ9A7AEE) fits only a
        // trip with that boss: the pick and the menu come from the options
        // that fit, and a stored choice for another boss falls back to the
        // best fitting one you own. General categories fit every trip.
        // The Praying Mantis: pray, but never restore (ISS-01M601Z57QM43W7SHNHCRMWDCE).
        Rules tr = state.taskRules();
        if (Trip.PRAYER_RESTORE.equals(category) && tr != null && tr.noPrayerRestore) continue;
        List<Option> fit = fitting(category, mobs, unl);
        Option pick = option(category, mode);
        if (pick == null && mode.startsWith("DETECT") || pick != null && !fit.contains(pick)) pick = detectBest(fit, owns, pvpDeathTrip());
        if (pick == null) continue;
        List<Map> options = optionNodes(fit, ob);
        // A kit names every item and gets a cell each (field 2026-09-08:
        // the holy symbol was filter-only); doses share one cell.
        boolean kit = pick.names.length == pick.ids.length && pick.names.length > 1;
        for (int i = 0; i < (kit ? pick.ids.length : 1); i++) {
            int[] doses = kit ? pick.cells != null ? pick.cells[i] : new int[]{pick.ids[i]} : pick.ids;
            int id = pick.ids.length > 0 ? pick.ids[i] : 0;
            // A scroll held only in the master scroll book shows as the book
            // (ISS-01M5VDZXT4W4D5DP468R5R7NSW, Andrew 2026-10-25: "when we know this it should be the
            // master scroll book that is shown as the item").
            boolean book = Trip.BOSS_TELEPORT.equals(category) && inScrollBook.test(id);
            if (book) doses = new int[]{SCROLL_BOOK};
            nodes.add(map("category", category, "name", book ? "Master scroll book (" + pick.name + ")" : kit ? pick.names[i] : pick.name,
                "itemId", book ? SCROLL_BOOK : id,
                "ids", Arrays.stream(doses).boxed().collect(toList()), "options", options, "utility", pick.utility));
        }
    }
    return nodes;
}

// The trip's UTILITY casts for one mob: the fight's own spell (the
// Sire's Shadow Barrage stun), the thrall resurrection at the live
// tier, and Death Charge - each cast's runes tagged with why
// (field report 2026-08-15: 'not seeing any runes' on a trip whose
// gear never autocasts but whose FIGHT casts plenty). Looked up by
// NAME so a phase variant's synthetic id still finds its monster.
List<Map> utilityRunesFor(Map mob) {
    List<Map> out = new ArrayList<>();
    Object name = mob.get("name");
    Monster stats = monster(m -> m.name.equals(name));
    String fs = spellFor(stats);
    if (fs != null) addUtilityRunes(out, fs, fs + " (fight mechanic)");
    // The slayer item the kill needs - listed even when not owned
    // (Andrew 2026-10-22: "show them as necessary even when the player
    // doesn't own those items").
    IntPredicate owns = ownedCheck;
    out.addAll(carriedPicks(stats, owns == null ? id -> false : owns));
    // The loot containers you own that this monster's drops warrant
    // (Andrew 2026-10-22: "killerwatts have a predominant herb drop table").
    out.addAll(LootContainers.picks(stats, owns, flag("inWilderness")));
    // The Arceuus offerings in place of the sanctifier and the bonecrusher
    // (ISS-01M5VJAHRWNHFRPPNK3J6B63SZ, Andrew 2026-10-26: "being able to replace ash sanctifier with
    // demonic offering and bonecrusher with sinister offering").
    offering(out, stats, "ashes", "Ash sanctifier", "DEMONIC_OFFERING", 84, "Demonic Offering");
    offering(out, stats, "bones", "Bonecrusher", "SINISTER_OFFERING", 92, "Sinister Offering");
    boolean sm = stats != null && nav(stats.name);
    boolean lc = arceuusBlocked(stats) || raidBookElsewhere();
    if (!sm && membersFlag("thralls") && !lc) {
        String tier = thrallTier(mag);
        if (tier != null) {
            addUtilityRunes(out, "Resurrect " + tier + " Ghost", tier + " thrall (per resurrection)");
            // The book the thrall is cast from (mrapw 2026-10-18: the
            // kit had the runes but not the book; any weapon casts it).
            out.add(map("id", BOOK_OF_THE_DEAD, "name", "Book of the Dead", "qty", 1,
                "why", tier + text("thrall.cast")));
        }
    }
    int dc = intParam("deathCharge");
    boolean f2pl = state.f2pLocked();
    if (!f2pl && !lc && dc > 0 && DefenceFloors.deathChargeWorks(stats)) addUtilityRunes(out, "Death Charge", "Death Charge (per cast)");
    // Ward of Arceuus where the drain is demonic (ISS-01M5VCXYGF51P5NJCDNC1QJZD1, Andrew 2026-10-25:
    // "ward of arceuss and the spectral spirit shield ... by default").
    if (!sm && !lc && arceuus.test(73) && ward(stats)) addUtilityRunes(out, "Ward of Arceuus", text("ward.arceuus"));
    if (flag("spellbookSwap")) {
        // Supplies only (field ask 2026-08-22): the trip carries the
        // runes to keep Vengeance up. Vengeance does return damage,
        // but modelling that is its own problem - this is purely
        // "bring more runes".
        addUtilityRunes(out, "Vengeance", "Vengeance (per cast)");
        // The SWAP is only needed when something else wants another
        // book. Vengeance alone - no thralls, no Death Charge, no
        // fight book - is a perfectly good setup and must not drag
        // swap runes along (field ask 2026-08-22).
        String fb = bookFor(stats);
        boolean elsewhere = fb != null && !fb.isEmpty() && !"lunar".equalsIgnoreCase(fb);
        elsewhere |= !sm && !lc && membersFlag("thralls");
        elsewhere |= !f2pl && !lc && dc > 0;
        if (elsewhere) addUtilityRunes(out, "Spellbook Swap", "Spellbook Swap (per swap)");
    }
    return combineRunes() ? combineCombos(out) : out;
}

static void addUtilityRunes(List<Map> out, String spell, String why) {
    List<Map> runes = costFor(spell, null, null);
    if (runes == null) return;
    for (Map rune : runes) {
        rune.put("why", why);
        out.add(rune);
    }
}

// Attach per-mob profile state (pinned spell/spec, note, the pins,
// the trio lists, the utility casts) to each mob node so renderers
// can show and edit it.
void decorateProfiles(Map entry, List<Map> supplies) {
    StoreOps ops = storeOps;
    Object mobsNode = entry.get("mobs");
    if (ops == null || !(mobsNode instanceof List)) return;
    Monster lensed = lmob();
    for (Object node : (List<?>) mobsNode) {
        if (node instanceof Map) {
            Map mob = (Map) node;
            Object id = mob.get("id");
            if (id instanceof Number) {
                int monsterId = ((Number) id).intValue();
                mob.put("pinnedSpell", ops.mobs().pinnedSpell(monsterId));
                mob.put("pinnedSpec", ops.mobs().pinnedSpec(monsterId));
                mob.put("note", ops.mobs().note(monsterId));
                // An ash dropper with no book of its own suggests Arceuus
                // (ISS-01M5TQ977R0MXBMSQ3VBHS29GB, Andrew 2026-10-25: "default to arceuss for
                // the ability to break down the ashes into prayer").
                mob.put("demonicOffering", lensed != null && arceuus.test(84) && LootContainers.drops(lensed, "ashes"));
                mob.put("wardOfArceuus", arceuus.test(73) && ward(lensed));
                Supplier<Map<String, String>> sd = supplyDefaults;
                mob.put("sinisterOffering", sd != null && "SINISTER_OFFERING".equals(sd.get().get("bones"))
                    && arceuus.test(92) && lensed != null && LootContainers.drops(lensed, "bones"));
                mob.put("skipDegradable", ops.skipDegradable(monsterId));
                mob.put("cureMe", cureMe(lensed));
                mob.put("arceuusBlocked", arceuusBlocked(lensed));
                mob.put("antivenom", antivenomMode(lensed));
                mob.put("cureCategory", cureCategory(lensed));
                List<Map> utility = utilityRunesFor(mob);
                mob.put("utilityRunes", utility);
                // The casting kit: divine rune pouch > rune pouch when
                // owned; the Magic cape (t preferred) for the book
                // swap perk - suggestions only when the trip casts.
                // WILDERNESS (field report 2026-08-31 + wiki): an
                // unlocked pouch is LOST on a pvp death, so only the
                // trouver-locked variants are ever recommended there -
                // locked divine, locked regular, or no pouch at all.
                IntPredicate owns = ownedCheck;
                // The pouch is named whenever ownership is known, so an
                // autocast-only trip carries it too (ISS-01M5VC3V5DCEEDGVNMC37VHJ2K: Save
                // setup puts the runes in it); the card offers it only
                // when the trip casts.
                boolean wt = owns != null && pvpDeathTrip();
                int pouch = owns == null ? -1 : wt ? firstOwned(owns, -1, 27509, 24416)
                    : firstOwned(owns, 12791, 27281, 27509, 12791, 24416);
                if (pouch > 0) mob.put("castingPouch", pouch);
                if (!utility.isEmpty() && owns != null) {
                    // Carried-kit fates (Andrew 2026-08-31): the inventory
                    // joins the lost/kept lists - see wildyCarriedFates.
                    if (wt) {
                        Map<String, List<String>> fates = wildyCarriedFates(pouch, owns.test(9763) || owns.test(9762),
                            supplies.stream().map(s -> String.valueOf(s.get("name"))).collect(toList()), !utility.isEmpty());
                        eachCard(List.of(mob), (side, card) -> {
                            Object rn = card.get("risk");
                            for (String fate : new String[]{"kept", "lost"}) {
                                Object list = rn instanceof Map ? ((Map<?, ?>) rn).get(fate) : null;
                                if (list instanceof List) ((List<Object>) list).addAll(fates.get(fate));
                            }
                        });
                    }
                    mob.put("castingCape", firstOwned(owns, -1, 9763, 9762));
                }
                mob.put("mobExclusions", ops.mobExclusions(monsterId));
                // The pins by scope (slot -> label) for the card, and the
                // pin list's rows - one walk fills both.
                Map<String, Map<String, String>> pins = new LinkedHashMap<>();
                List<Map> pr = new ArrayList<>();
                ops.mobs().allPins(monsterId).forEach((scope, slots) -> {
                    Map<String, String> named = new LinkedHashMap<>();
                    slots.forEach((slot, itemId) -> {
                        named.put(Names.lower(slot.name()), itemLabel(itemId));
                        pr.add(map("id", itemId, "name", itemLabel(itemId), "scope", scope, "slot", Names.lower(slot.name())));
                    });
                    pins.put(scope, named);
                });
                mob.put("pins", pins);
                mob.put("mobPins", pr);
                // The worn slayer requirements, for the cells' "needed"
                // note - by id, so a phase variant keeps its own.
                mob.put("requiredGear", requiredIds(monster(m -> m.id == monsterId), data,
                    flag("kourendElite") ? Set.of(KOUREND_ELITE) : Set.of())
                    .values().stream().flatMap(Set::stream).collect(toList()));
                mob.put("mobSims", ops.mobSims(monsterId));
                mob.put("mobFilters", ops.mobFilters(monsterId));
            }
        }
    }
}

volatile Map assumeOptionsCache;

// Static per-style prayer/boost option lists (key + label),
// mirroring the classic pick menus.
Map assumeOptions() {
    Map cached = assumeOptionsCache;
    if (cached != null) return cached;
    Map prayers = new LinkedHashMap<>();
    Map boosts = new LinkedHashMap<>();
    for (Style style : Style.concreteValues()) {
        prayers.put(style.name().toLowerCase(), Arrays.asList( PrayerBonuses.optionsFor(style)));
        List<Map> sb2 = new ArrayList<>();
        for (BoostProfile b : BoostProfile.values()) {
            if (b == BoostProfile.NONE || b == BoostProfile.LIVE_CURRENT) continue;
            if (b.boosts(style == Style.MELEE ? 'a' : style == Style.RANGED ? 'r' : 'm')) sb2.add(map("key", b.name(), "label", b.toString()));
        }
        boosts.put(style.name().toLowerCase(), sb2);
    }
    // Icon facts for the pickers (additive): prayer name -> sprite id,
    // boost label -> potion item id. Renderers draw, never map.
    Map ps = new LinkedHashMap<>();
    Map pi = new LinkedHashMap<>();
    for (Object list : prayers.values()) {
        for (Object o : (List<?>) list) {
            String name = String.valueOf(o);
            ps.put(name, prayerSprite(name));
            String image = prayerImage(name);
            if (image != null) pi.put(name, image);
        }
    }
    Map bi = new LinkedHashMap<>();
    for (Object list : boosts.values()) {
        for (Object option : (List<?>) list) {
            String label = String.valueOf(((Map<?, ?>) option).get("label"));
            bi.put(label, boostItem(label));
        }
    }
    Map ss = new LinkedHashMap<>();
    for (Spell spell : data.spells) ss.put(spell.name, spellSprite(spell.name));
    // Spellbook Swap is 96 Magic (Vengeance 94) - offered when the
    // player can actually reach the level, boosts included.
    Map options = map("prayers", prayers, "boosts", boosts,
        "prayerSprites", ps, "prayerImages", pi,
        "spellbookSwapAvailable", mag + 5 >= 96, "boostItems", bi, "spellSprites", ss);
    assumeOptionsCache = options;
    return options;
}

// The ship node (REQ-SC-2/3/3b/4/7): cannons priced for a NAVAL mob only
// - the params persist for land mobs but are never read, the same veto
// shape as the F2P lock. Post-compute additive like thralls: cannons
// never steer the gear search.
// <p>Cannon 1 is the player's when the station is "cannon" (visible
// ranged level, wiki formula); every other cannon is crew-fired - the
// documented-but-stale Privateering scaling over a Sailing-level base,
// marked estimated while NavalCombat.crewFormulaStale(). A crew below
// the cannon's Privateering gate, or a player below its Ranged gate,
// cannot operate it: that cannon prices at zero and says why. The
// player-fired cannon borrows the worn ranged bonuses of the engine's
// best owned ranged set (weapon/shield/ammo excluded, per the wiki);
// crew cannons price bare.
Map shipNode(List<Monster> mobs, List<Map<Style, Pick>> pm) {
    if (mobs == null || mobs.isEmpty()) return null;
    Map params = state.pn();
    // The LENSED mob decides (REQ-SC-7): a mixed roster prices cannons
    // only while a sea mob is under the lens.
    int lens = intParam("lensIndex");
    Monster lensed = lensOf(mobs);
    if (!nav(lensed.name)) return null;
    int count = intParam("cannonCount");
    String ap = String.valueOf(params.get("cannonAmmo"));
    List<String> ct = new ArrayList<>();
    for (int i = 0; i < count; i++) ct.add(String.valueOf( params.get(i == 0 ? "cannon1Material" : "cannon2Material")));
    boolean detect = "detect".equals(ap);
    String ammo = ap;
    String ab = null;
    Predicate<String> everyone = ball -> ct.stream().allMatch(t -> canFire(t, ball));
    if (!detect && count > 0 && !everyone.test(ap)) {
        // The RESOLUTION downranks, never the pick (field report
        // 2026-08-31: dragon -> rune swap still showed a dragon ball):
        // the effective tier is the pick when every carried cannon can
        // fire it, else the best they can all share - one tier for the
        // whole ship (REQ-SC-2). The pick itself stays put, so
        // upgrading the cannon back restores it.
        ammo = bestSharedBall(ct);
    }
    if (detect) {
        // Best BANKED ball every carried cannon can fire - never a ball
        // the bank does not hold (the 0.4.1 rule, applied to ammo).
        IntPredicate owns = ownedCheck;
        String best = null;
        for (Ball ball : balls()) if (everyone.test(ball.tier) && owns != null && owns.test(ball.itemId)) best = ball.tier;
        if (best == null) {
            String top = bestSharedBall(ct);
            ab = "No cannonballs banked" + (top == null ? "" : " (up to " + top + ")");
            ammo = null;
        } else ammo = best;
    }
    String op1 = String.valueOf(params.get("cannon1Operator"));
    String op2 = String.valueOf(params.get("cannon2Operator"));
    String station = "you".equals(op1) || "you".equals(op2) ? "cannon" : "gear";
    // The wiki rule: the player's worn ranged accuracy and strength join
    // their cannon fire, EXCLUDING the weapon, shield and ammo slots.
    // The manned player still wears armour - the best owned ranged set
    // the engine already computed - so the cannon borrows its bonuses.
    // Crew gear is unknowable and stays at zero.
    int wa = 0;
    int ws = 0;
    int gl = min(max(lens, 0), (pm == null ? 1 : pm.size()) - 1);
    Pick rr = pm == null || pm.size() <= gl || pm.get(gl) == null ? null
        : pm.get(gl).get(Style.RANGED);
    if (rr != null && rr.overallBest != null) {
        Kit worn = rr.overallBest.loadout;
        for (Slot slot : Slot.values()) {
            if (slot == Slot.WEAPON || slot == Slot.SHIELD || slot == Slot.AMMO) continue;
            Gear item = worn.get(slot);
            if (item != null) {
                wa += item.offensive.ranged;
                ws += item.bonuses.rangedStrength;
            }
        }
    }
    Map node = map("station", station, "ammo", ammo, "ammoDetected", detect);
    if (ab != null) node.put("ammoBlocked", ab);
    node.put("wornAccuracy", wa);
    node.put("wornStrength", ws);
    List<Map> cn = new ArrayList<>();
    boolean ac = false;
    double total = 0;
    double[] bm = new double[mobs.size()];
    for (int i = 0; i < count; i++) {
        String tier = ct.get(i);
        Cannon cannon = cannon(tier);
        if (cannon == null) continue;
        String operator = i == 0 ? op1 : op2;
        boolean pf = "you".equals(operator);
        int priv = PageState.crewLevel(operator);
        Map c = map("tier", tier, "itemId", cannon.itemId);
        if (ammo != null) {
            // Shared ammo, clamped to what THIS cannon can fire (a mithril
            // cannon handed dragon balls fires mithril ones).
            c.put("ball", ammo);
        }
        c.put("firedBy", pf ? "player" : "crew");
        // A dry bank blocks every cannon with the detection's reason (no
        // ball, no crew estimate); a loaded one is gated per operator -
        // the player's Ranged, the crew's Privateering.
        String blocked = ammo == null ? ab
            : pf && rangedLevel < cannon.ranged ? "Needs " + cannon.ranged + " Ranged to operate" : null;
        if (!pf && ammo != null) {
            ac = true;
            if (priv < cannon.privateering) blocked = "Crew needs Privateering " + cannon.privateering;
        }
        if (blocked != null) {
            c.put("blocked", blocked);
            c.put("maxHit", 0);
            c.put("dps", 0.0);
            cn.add(c);
            continue;
        }
        Ball ball = ball(ammo);
        int mh;
        if (pf) {
            mh = playerMaxHit( rangedLevel, cannon.strength, ball.strength, ws, false);
        } else {
            int base = playerMaxHit( sailingLevel, cannon.strength, ball.strength, 0, false);
            mh = crewMaxHit(base, priv);
        }
        int level = pf ? rangedLevel : sailingLevel;
        int acc = equipmentAccuracy( cannon.heavyAccuracy, ball.accuracy, pf ? wa : 0);
        // One roll per roster mob (Andrew 2026-09-03: sea rows show
        // player + cannon): the max hit is shared, the accuracy is not.
        for (int m = 0; m < mobs.size(); m++) {
            Monster target = mobs.get(m);
            if (nav(target.name)) bm[m] += dps(mh, hitChance(level, acc, target.defence, target.defensive.get("heavy")));
        }
        double chance = hitChance(level, acc, lensed.defence, lensed.defensive.get("heavy"));
        double dps = dps(mh, chance);
        c.put("maxHit", mh);
        c.put("dps", dps);
        total += dps;
        cn.add(c);
    }
    node.put("cannons", cn);
    node.put("dps", total);
    node.put("byMob", Arrays.stream(bm).boxed().collect(toList()));
    node.put("estimated", ac && crewFormulaStale());
    // Ship damage taken (REQ-SC-15): the mob attacks the BOAT, so the
    // number is per keel from the wiki table (armour pre-applied) and
    // protection prayers do not apply. Always-hit is assumed - ship
    // defence rolls are undocumented - so this reads as a ceiling.
    String keel = String.valueOf(params.get("shipKeel"));
    int km = keelMaxHit(lensed.name, keel);
    if (km >= 0) {
        int speed = max(1, lensed.offence.speedTicks);
        node.put("incoming", map("keel", keel, "maxHit", km, "dtps", km / 2.0 / (speed * 0.6)));
    }
    return node;
}

Map withHistory(Map page) {
    // Every publish, the pending page too: the path link needs only the
    // mob, never its results (ISS-01M5TE7QAZYZQMTPA1JZ0BQN1Z).
    page.put("pathable", pathable(shownMob()));
    page.put("caTasks", caTasks());
    page.put("history", map("canUndo", history.canUndo(), "canRedo", history.canRedo(),
        "undoLabel", history.peekUndoDescription(), "redoLabel", history.peekRedoDescription()));
    Supplier<Map> supplier = counts;
    if (supplier != null) page.put("counts", supplier.get());
    return page;
}
}

package com.ll.model;

import java.util.Map;
import java.util.function.Consumer;

// The in-process page store between the CommandEngine and the
// renderer: holds the latest published page and notifies the
// listeners the plugin wires at startup. (The 2026-08 merge-back
// retired the PluginMessage seam this class once broadcast over -
// the renderer lives in this plugin now.)
public class CompanionLink {
volatile Map lastPage;
volatile Runnable pageListener;
volatile Consumer<Boolean> statusListener;

public void setPageListener(Runnable pageListener) { this.pageListener = pageListener; }

public void setStatusListener(Consumer<Boolean> statusListener) { this.statusListener = statusListener; }

// Compute-in-flight signal - drives the renderer's waiting state.
public void publishStatus(boolean computing) {
    Consumer<Boolean> listener = statusListener;
    if (listener != null) listener.accept(computing);
}

// Publish an assembled page (the CommandEngine builds them).
public void publishPage(Map page) {
    // Identical pages do not republish (perf, 2026-08-15: post-boss
    // silent refreshes usually land the SAME answer - the deep
    // equals is pennies next to the render it prevents).
    if (page != null && page.equals(lastPage)) return;
    lastPage = page;
    Runnable listener = pageListener;
    if (listener != null) listener.run();
}

// The latest published page - the hosted view renders it.
public Map lastPage() { return lastPage; }
}

package com.ll.model;

import static java.lang.Math.*;
import com.google.gson.*;
import com.ll.engine.*;
import com.ll.data.*;
import java.util.*;
import com.ll.data.NavalCombat.Cannon;

// Core-owned page state for the Companion seam (ADR-0008: Core owns
// ALL state, including view parameters, so every renderer - the bare
// UI, the Companion, undo history - sees the same world). v1 holds
// one active entry: the selected mob and the full compute parameter
// set. The old Swing panel still keeps its own ResultEntry during the
// transition; the two reconcile when the panel leaves for the
// Companion.
// <p>The params live in ONE map seeded from {@link #DEFAULTS} (the slim,
// 2026-10-23: 35 fields and a 40-arm switch said the same thing three
// times over). Booleans, ints and strings are set by the type of their
// default; the arms of {@link #setParam} cover the few with rules of
// their own.
public class PageState {
Monster mob;
List<Monster> rmobs;
String rosterName;

// Every page param with its default, in the params node's order, from
// page_params.json (hub token cap) - the int clamps, the view params and
// the keys a select seeds ride the same file. What each one means, where
// it is not obvious:
// <ul>
// <li>f2pWorld - true while the client is on a NON-members world. The
// chip renders from this, not from f2pOnly - otherwise unticking the
// filter hides the control that unticked it and there is no way back.
// <li>pvpWorld - PvP mode: 0 off, 1 PvP world, 2 High Risk (Ragnarrok,
// 2026-10-20: "3 iteming" on PvP worlds). World state like f2pWorld,
// so never in the selection snapshot; pvpWorldHere = the client is on
// one.
// <li>kourendElite - the elite Kourend & Kebos diary is done (varbit
// 7928) - Karuulm needs no boots (ISS-01M5JJ0Z4M988DR0M0ZGJHD139).
// <li>optimizeMode - MAX_DPS / BALANCED / TANKY, every player's since
// 2026-10-22 (ISS-01M5JBYYWHQNTM0CGNYWQBNYX6; no developer-mode gate).
// <li>nerAvailable - Not Enough Runes is enabled - the ladder's "how
// to get it" link.
// <li>ladderSlot - the slot whose ladder strip is open on the Yours
// card ("" = none); ladderPage - the strip's page (0 = the strip, n =
// the nth five further steps up), reset when another slot opens.
// <li>reqOpen - the "+ Requirement" editor is open; a new search
// closes it (Andrew 2026-10-27).
// <li>cannonCount, cannon1/2Material, cannonAmmo, shipKeel,
// cannon1/2Operator - ship combat (REQ-SC-2/3/3b). Post-compute
// additive like thralls - none of these enter the optimizer request,
// so none ride computeArgs. They persist across lens changes; the
// ENGINE only reads them for a naval mob (REQ-SC-7's veto, same shape
// as the F2P lock). "detect" ammo resolves to the best BANKED ball
// every carried cannon can fire (the boost idiom, Andrew 2026-08-31);
// a tier name pins it. An operator is "you", or "crew1".."crew4" for
// a crewmate of that Privateering (REQ-SC-9). At most one cannon is
// yours - picking "you" on one flips the other back to crew. Picking
// a material auto-RAISES a crew operator to the minimum Privateering
// that can man it (Andrew: "automatically assume you are going to
// pick a crew member at minimum that can man the cannon") and never
// lowers an explicit pick.
// <li>raidSelection - true while the selection is a RAID group (ToB
// included - the boost heuristic missed it): raids are never a
// slayer-task context. Set by the selects, never by a command.
// <li>riskCapped - whether a cap is actually in force; never inferred
// from the gp value, which collides with the engine's no-cap sentinel.
// <li>spellbookSwap - bringing Spellbook Swap + Vengeance on the trip.
// Supplies only - the DPS Vengeance returns is deliberately not
// modelled.
// <li>antifireMode - 0 = shield required, 1 = regular antifire, 2 =
// super antifire - the classic tri-state; Detect resolves it at
// selection time.
// <li>sunfireRunes - assumed for a fire spell (seeded from ownership
// at each selection; the card plate overrides).
// <li>multiView, multiStack - the Multi card (Andrew 2026-10-19): the
// switch computes the multi tools; the stack is a view scale on their
// per-target numbers.
// <li>viewingBis, selectedTab, thralls, lensIndex - view state,
// core-owned like everything else (ADR-0008), but a change here
// republishes without recomputing (see CommandEngine).
// </ul>
static final Map DEFAULTS = new LinkedHashMap<>();
// Set by the engine (the selects, the risk cap), never by a command.
static final Set<String> DERIVED = Set.of("raidSelection", "riskCapped", "myLevels");
static final String[] SIM_KEYS = {"simAttack", "simStrength", "simDefence", "simRanged", "simMagic", "simPrayer", "simHitpoints"};

// Your live levels for the page ("a/s/d/r/m/p/h"): what the stat sim's
// boxes and the report show where nothing is simmed.
synchronized void setMyLevels(String levels) { params.put("myLevels", levels == null ? "" : levels); }
// Int params with a range: {min, max}.
static final Map<String, int[]> CLAMPS = new HashMap<>();
// The params a select seeds (antifire, tab, view side, on-task,
// wilderness, bench, and the config seeds) - what undoing it restores:
// undoing a Callisto used to leave its wilderness and risk chips
// sitting on the restored mob (pre-release adversarial pass
// 2026-08-22).
static final List<String> SNAPSHOT_KEYS = new ArrayList<>();
static final Set<String> VIEW_PARAMS = new HashSet<>();

static {
    JsonObject root = Json.objectOrThrow("page_params.json");
    for (var e : root.getAsJsonObject("defaults").entrySet()) {
        JsonPrimitive v = e.getValue().getAsJsonPrimitive();
        DEFAULTS.put(e.getKey(), v.isBoolean() ? v.getAsBoolean() : v.isNumber() ? (Object) v.getAsInt() : v.getAsString());
    }
    // The one default the engine owns (its uncapped sentinel), never the file.
    DEFAULTS.replace("riskBudgetGp", Req.DEFAULT_RISK_BUDGET_GP);
    for (var e : root.getAsJsonObject("clamps").entrySet()) CLAMPS.put(e.getKey(), Json.ints(e.getValue().getAsJsonArray()));
    Json.strings(root, "snapshotKeys", SNAPSHOT_KEYS);
    Json.strings(root, "viewParams", VIEW_PARAMS);
}

Map params = new LinkedHashMap<>(DEFAULTS);
Map<Style, String> boostPicks = new LinkedHashMap<>();
Map<Style, String> prayerPicks = new LinkedHashMap<>();

// Parameters that change what is SHOWN, not what is computed.
public static boolean isViewParam(String param) { return VIEW_PARAMS.contains(param); }

public synchronized void select(Monster mob) {
    params.put("raidSelection", false);
    this.mob = mob;
    rmobs = null;
    rosterName = null;
}

synchronized void selectRoster(List<Monster> mobs, String name, boolean raid) {
    params.put("raidSelection", raid);
    mob = null;
    rmobs = mobs;
    rosterName = name;
}

synchronized Monster mob() { return mob; }

synchronized List<Monster> rmobs() { return rmobs; }

// Selection snapshot for undo: restore() reinstates it exactly -
// the mob or roster, and the params a select seeds (SNAPSHOT_KEYS).
synchronized Object[] selectionSnapshot() {
    Map seeded = new LinkedHashMap<>();
    for (String key : SNAPSHOT_KEYS) seeded.put(key, params.get(key));
    return new Object[]{mob, rmobs, rosterName, seeded};
}

synchronized void restoreSelection(Object[] snapshot) {
    mob = (Monster) snapshot[0];
    rmobs = (List<Monster>) snapshot[1];
    rosterName = (String) snapshot[2];
    params.putAll((Map) snapshot[3]);
}

synchronized boolean hasSelection() { return mob != null || rmobs != null; }

// Apply one named parameter; returns false for an unknown name so
// the engine can refuse loudly instead of silently dropping it.
public synchronized boolean setParam(String param, Object value) {
    Object current = param == null ? null : params.get(param);
    if (current == null || DERIVED.contains(param)) return false;
    switch (param) {
        case "cannon1Material":
        case "cannon2Material": {
            // The material gates its crew: a pick raises the operator.
            String operator = "cannon" + param.charAt(6) + "Operator";
            params.put(param, String.valueOf(value));
            params.put(operator, raiseCrewToGate(str(operator), String.valueOf(value)));
            return true;
        }
        case "cannon1Operator":
        case "cannon2Operator": {
            // At most one cannon is yours: picking "you" on one demotes the other.
            int i = param.charAt(6) - '1';
            String mine = operator(value, str("cannon" + (i + 1) + "Material"));
            params.put(param, mine);
            String other = "cannon" + (2 - i) + "Operator";
            if ("you".equals(mine) && "you".equals(params.get(other))) params.put(other, raiseCrewToGate("crew1", str("cannon" + (2 - i) + "Material")));
            return true;
        }
        case "shipKeel":
            params.put(param, NavalCombat.normalizeKeel(String.valueOf(value)));
            return true;
        case "cannonAmmo":
            params.put(param, String.valueOf(value));
            return true;
        case "optimizeMode":
            params.put(param, "BALANCED".equals(value) || "TANKY".equals(value) ? value : "MAX_DPS");
            return true;
        case "riskBudgetGp": {
            // ONE source of truth for "is there a cap" (field report
            // 2026-08-22): the chip lit up on riskBudgetGp > 0 while
            // the compute asked riskBudgetGp != DEFAULT - and the
            // DEFAULT *is* 75k, the same value the config seeds, so
            // the UI promised a cap the optimizer ignored. A null
            // clears the cap (the gp falls back to the default).
            int cap = asInt(value, Req.DEFAULT_RISK_BUDGET_GP);
            params.put(param, cap);
            params.put("riskCapped", value != null && cap > 0);
            return true;
        }
        case "lensIndex":
            params.put(param, asInt(value, 0));
            // Switching mobs opens on THAT mob's recommended style (the
            // 2026-08-15 rule) - the row click already did this, but
            // arrow-nav kept the old tab, so a magic-only Warden left
            // "magic" stuck on the Obelisk as a tab-only view (community
            // report, issue #15). The row pick re-sets the tab AFTER the
            // lens, so explicit picks still land.
            params.put("selectedTab", "");
            return true;
        default:
            if (current instanceof Boolean) {
                params.put(param, Boolean.TRUE.equals(value));
            } else if (current instanceof String) {
                params.put(param, value instanceof String ? value : "");
            } else {
                int[] clamp = CLAMPS.getOrDefault(param, new int[]{Integer.MIN_VALUE, Integer.MAX_VALUE});
                params.put(param, max(clamp[0], min(clamp[1], asInt(value, defaultInt(param)))));
            }
            return true;
    }
}

// An int param's default - what a non-numeric value falls back to.
static int defaultInt(String param) { return (Integer) DEFAULTS.get(param); }

// Normalize an operator pick; a crew pick is clamped 1-4 and then
// raised to the material's gate.
static String operator(Object value, String material) {
    String v = String.valueOf(value);
    return "you".equals(v) ? "you" : raiseCrewToGate("crew" + max(1, min(4, crewLevel(v))), material);
}

// Crew operators rise to the minimum Privateering the material demands;
// "you" and already-sufficient crew pass through untouched.
static String raiseCrewToGate(String operator, String material) {
    if ("you".equals(operator)) return operator;
    Cannon cannon = NavalCombat.cannon(material);
    int gate = cannon == null ? 1 : cannon.privateering;
    return "crew" + max(crewLevel(operator), gate);
}

// The Privateering of a "crewN" operator; 1 for "you", a bare "crew"
// or anything else.
static int crewLevel(String operator) {
    if (operator != null && operator.startsWith("crew")) {
        try {
            return Integer.parseInt(operator.substring(4));
        } catch (NumberFormatException ignored) {
        }
    }
    return 1;
}

static int asInt(Object value, int fallback) {
    return value instanceof Number ? ((Number) value).intValue() : fallback;
}

boolean flag(String key) { return Boolean.TRUE.equals(params.get(key)); }

int num(String key) { return (Integer) params.get(key); }

String str(String key) { return (String) params.get(key); }

// The params node of the model page - what a renderer needs to
// draw every chip in its current position.
public synchronized Map pn() {
    Map node = new LinkedHashMap<>(params);
    node.put("prayerPicks", lowered(prayerPicks));
    node.put("boostPicks", lowered(boostPicks));
    return node;
}

// A pick map keyed by the style's lower-case name, for the page.
static Map lowered(Map<Style, String> picks) {
    Map out = new LinkedHashMap<>();
    for (var pick : picks.entrySet()) out.put(pick.getKey().name().toLowerCase(), pick.getValue());
    return out;
}

synchronized int toaInvocation() { return num("toaInvocation"); }

// Prayer/boost pick per style: null value = Detect (remove),
// "NONE" = explicitly none, else the option key.
synchronized void setPick(boolean prayer, Style style, String value) {
    Map<Style, String> picks = prayer ? prayerPicks : boostPicks;
    if (value == null) {
        picks.remove(style);
    } else picks.put(style, value);
}

// The picked combat achievement tasks ("161,72"), in pick order.
synchronized List<CombatAchievements.Task> caPicks() {
    List<CombatAchievements.Task> out = new ArrayList<>();
    for (String id : str("caPicks").split(",")) {
        CombatAchievements.Task t = id.isBlank() ? null : CombatAchievements.byId(Integer.parseInt(id.trim()));
        if (t != null) out.add(t);
    }
    return out;
}

// Every picked task's rules on the page's mobs, ANDed; null when none is picked.
synchronized Rules taskRules() {
    Rules all = null;
    List<Monster> on = rmobs != null ? rmobs : mob != null ? List.of(mob) : List.of();
    for (CombatAchievements.Task t : caPicks()) all = all == null ? t.rulesFor(on) : all.and(t.rulesFor(on));
    return all;
}

// The F2P lock: the param, or a picked free-to-play task (ISS-01M60HTYZT9DTZKDSFAGRNNK53).
synchronized boolean f2pLocked() {
    Rules tasks = taskRules();
    return flag("f2pOnly") || tasks != null && tasks.f2p;
}

// The compute settings, one object per compute (see CommandEngine).
public synchronized ComputeParams computeParams() {
    // Kept-slots mirror the classic riskCap() gate: a risk cap only
    // binds in the wilderness or on a PvP world, and Protect Item
    // keeps a 4th slot - none on High Risk. The wilderness flag itself
    // stays out of it: a PvP world earns no wilderness weapon buff.
    int pvp = num("pvpWorld");
    int kept = PvpRisk.ks(flag("inWilderness") ? max(1, pvp) : pvp, flag("protectItem"));
    // The F2P lock vetoes members mechanics WITHOUT clearing them: the
    // params keep their values (undo history stays coherent, and
    // unticking F2P brings the old setup straight back) - they just
    // stop steering the math while the lock is on (field ask
    // 2026-08-27: D charge / thralls / task have no meaning on F2P).
    boolean f2p = f2pLocked();
    var p = new ComputeParams();
    p.f2pOnly = f2p;
    p.onSlayerTask = !f2p && flag("onTask");
    p.inWilderness = flag("inWilderness");
    p.spellbookLock = str("spellbookLock");
    // -1 = no tradeables limit (the engine's uncapped sentinel).
    p.maxTr = flag("riskCapped") && kept >= 0 ? kept : -1;
    p.riskBudgetGp = num("riskBudgetGp");
    p.antifirePotion = num("antifireMode") == 2;
    p.afire = num("antifireMode");
    // A combat achievement task's rules plus the player's own requirements
    // (ISS-01M5XC7XYMMEN3Q4QC6CGZFVPK).
    Rules taskRules = taskRules();
    List<Rules.Rule> extra = Rules.parse(str("requirements"));
    p.setRules = taskRules != null ? taskRules.plus(extra) : extra.isEmpty() ? null : Rules.of(extra, Set.of(), null);
    p.sunfireRunes = flag("sunfireRunes");
    p.multiView = flag("multiView");
    p.multiStack = num("multiStack");
    p.deathCharge = f2p ? 0 : num("deathCharge");
    p.specWeapon = flag("specWeapon");
    p.boostPicks = new LinkedHashMap<>(boostPicks);
    p.prayerPicks = new LinkedHashMap<>(prayerPicks);
    // A task's prayer and spellbook terms ride the existing picks: no
    // prayer on any style, the one book as the lock.
    if (taskRules != null && taskRules.spellbook != null) p.spellbookLock = taskRules.spellbook;
    p.upgradeBudgetGp = num("upgradeBudgetGp");
    p.maxSwaps = num("maxSwaps");
    // Every player's chosen mode since 2026-10-22 (Andrew: "Release to
    // everyone"; ISS-01M5JBYYWHQNTM0CGNYWQBNYX6) - no developer-mode gate.
    p.optimizeMode = str("optimizeMode");
    p.kourendElite = flag("kourendElite");
    p.gods = GwdProtection.chips(str("requirements"));
    int[] sims = new int[SIM_KEYS.length];
    boolean simmed = false;
    for (int i = 0; i < sims.length; i++) {
        sims[i] = num(SIM_KEYS[i]);
        simmed |= sims[i] > 0;
    }
    p.simLevels = simmed ? sims : null;
    p.simMaxCape = flag("simMaxCape");
    return p;
}
}

package com.ll.model;

import com.ll.data.*;
import com.ll.engine.*;
import java.util.*;
import java.util.function.*;
import com.ll.engine.Incoming.*;
import com.ll.optimizer.Service.*;
import com.ll.engine.PvpRisk.Assessment;
import static com.ll.data.AssumeIcons.*;
import static java.lang.String.*;
import static com.ll.engine.MultiTool.*;

// The generic render-model of ADR-0008: everything a UI needs to draw,
// as JSON-safe maps (the Companion loads in its OWN classloader - no
// shared classes cross the seam, only this structure). Renderers - the
// Companion's rich panel, Core's bare text surface, any future UI -
// consume this and never re-derive game logic.
// <p>v1 is the vertical slice straight off the optimizer's results:
// per-mob per-style cards for both sides, spec, incoming, bench.
// Entry parameter state, chips, and the pre-resolved display strings
// join field-by-field as the panel port peels them out of Swing
// (docs/COMPANION_CONTRACT.md tracks the full shape).
public class RenderModel {
// Contract version stamped on every page; additive evolution only.
static final int VERSION = 1;


// A node from key/value pairs, in argument order (the JSON stays
// canonical: every builder below lists its keys in the contract's order).
static Map map(Object... kv) { return Json.map(kv); }

// The side a card shows: the game-wide best, or the first owned set
// (null for none, or for no result).
static Dps shown(Pick result, boolean bis) {
    return result == null ? null : bis ? result.overallBest
        : result.owned == null || result.owned.isEmpty() ? null : result.owned.get(0);
}

static Map page(List<Map> entries) {
    return map("v", VERSION, "entries", entries);
}

// One result entry: its mobs and, per mob, the per-style cards.
// Single-mob pages are the one-mob case of the same shape.
public static Map entry(List<Monster> mobs, List<Map<Style, Pick>> pm) {
    return entry(mobs, pm, -1, null, Set.of(), null);
}

// Per-build provenance lookup: an item's storage NAME when a fetch
// trip is needed (the classic source dots), "" when at hand.
// riskKeptSlots >= 0 adds a wilderness risk node per card; ownership +
// simmed ids flag every gear cell for the classic border language
// (gold owned-BiS / green assumed / grey).
static final ThreadLocal<IntFunction<String>> LOCATION = new ThreadLocal<>();

public static Map entry(List<Monster> mobs,
    List<Map<Style, Pick>> pm, int rks, IntPredicate owned, Set<Integer> simmed,
    IntFunction<String> lo) {
    LOCATION.set(lo);
    try {
        return buildEntry(mobs, pm, rks, owned, simmed);
    } finally {
        LOCATION.remove();
    }
}

static Map buildEntry(List<Monster> mobs,
    List<Map<Style, Pick>> pm, int rks, IntPredicate owned, Set<Integer> simmed) {
    List<Object> mn = new ArrayList<>();
    for (int i = 0; i < mobs.size(); i++) {
        Map node = mob(mobs.get(i));
        MOB.set(i);
        HP.set(mobs.get(i).hitpoints);
        MOB_STATS.set(mobs.get(i));
        try {
            node.put("styles", styles(pm.get(i), rks, owned, simmed));
            Map multi = multi(pm.get(i), rks, owned, simmed);
            if (multi != null) node.put("multi", multi);
        } finally {
            MOB.remove();
            HP.remove();
            MOB_STATS.remove();
        }
        mn.add(node);
    }
    Map entry = map("mobs", mn);
    if (mobs.size() > 1) {
        Map trip = trip(mobs, pm, false);
        if (trip != null) entry.put("tripKillTime", trip);
        trip = trip(mobs, pm, true);
        if (trip != null) entry.put("bisTripKillTime", trip);
    }
    return entry;
}

// The roster index of the mob whose card is being built: a group
// ladder reads that mob's own numbers (ISS-01M5PE4TZXTGJAQA1YXNRKPEDW);
// and its hitpoints, for the card's kill time.
static final ThreadLocal<Integer> MOB = new ThreadLocal<>();
static final ThreadLocal<Integer> HP = new ThreadLocal<>();
static final ThreadLocal<Monster> MOB_STATS = new ThreadLocal<>();

// The trip's kill time (Andrew 2026-10-29: "TTK for moons of peril,
// barrows should be the combined kill time of all 3 bosses"): each
// member's table in the set its row recommends, convolved; the member
// that never dies named. Null with fewer than two members answered.
static Map trip(List<Monster> mobs, List<Map<Style, Pick>> pm, boolean bis) {
    List<Kill> times = new ArrayList<>();
    List<Object> members = new ArrayList<>();
    String never = null;
    double low = 0, high = 0;
    for (int i : tripMembers(mobs)) {
        Pick r = bestOf(pm.get(i), bis);
        if (r == null) continue;
        var o = BossIncomingOverrides.of(mobs.get(i));
        Kill k = killTime(r, shown(r, bis), mobs.get(i).hitpoints, bis).stretched(o.uptime).delayed(o.downtime);
        times.add(k);
        Map member = killNode(k, 0, mobs.get(i));
        member.put("name", mobs.get(i).label());
        members.add(member);
        Result in = bis ? r.gameIncoming : r.incoming;
        if (in != null && !Double.isInfinite(k.p95)) {
            low += in.tot * k.p05;
            high += in.tot * k.p95;
        }
        if (never == null && Double.isInfinite(k.p50)) never = mobs.get(i).label();
    }
    if (times.size() < 2) return null;
    Map node = killNode(Kill.sum(times), 0, null);
    node.put("members", members);
    node.put("damageLow", low);
    node.put("damageHigh", high);
    if (never != null) node.put("never", never);
    return node;
}

// The members the trip kills: each monster once, its first listed version
// (Andrew 2026-10-30: the Titans' near and out-of-reach versions clear
// one hp bar, "anything with duplicated mobs"), and no add marked
// "trip": false.
static List<Integer> tripMembers(List<Monster> mobs) {
    List<Integer> out = new ArrayList<>();
    Set<String> seen = new HashSet<>();
    for (int i = 0; i < mobs.size(); i++) if (!mobs.get(i).hasAttribute("no_trip") && seen.add(mobs.get(i).name)) out.add(i);
    return out;
}

// The set a member's row recommends: its kit-backed style with the most
// net DPS plus spec, or null when no style answers.
static Pick bestOf(Map<Style, Pick> results, boolean bis) {
    Pick best = null;
    double bd = -1;
    for (Pick r : results.values()) {
        Dps shown = r == null ? null : shown(r, bis);
        if (shown == null || !(bis ? r.gkb : r.okb)) continue;
        double d = shown.net + (bis ? r.gsda : r.sda);
        if (d > bd) {
            bd = d;
            best = r;
        }
    }
    return best;
}

static double healOf(Pick r, boolean bis) {
    Result incoming = bis ? r.gameIncoming : r.incoming;
    return incoming == null ? 0 : incoming.healDps;
}

// The set's kill-time table vs this mob: the card's hit model, the
// boss's heal off the set and the sustained spec (Kill).
static Kill killTime(Pick r, Dps shown, int hp, boolean bis) {
    double[] dist = bis ? r.gameHitDist : r.hd;
    double spec = bis ? r.gsda : r.sda;
    Kill k = dist != null ? Kill.table(hp, dist, shown.attackSpeed * 0.6, shown.dps, healOf(r, bis), spec, false)
        : Kill.table(hp, shown.accuracy, shown.maxHit, shown.attackSpeed, shown.dps, healOf(r, bis), spec);
    // The boss's own downtime stretches the kill (its special phases) or
    // adds to it (Hespori's flower rounds).
    Monster mob = MOB_STATS.get();
    if (mob == null) return k;
    var o = BossIncomingOverrides.of(mob);
    return k.stretched(o.uptime).delayed(o.downtime);
}

static Map killNode(Kill k, double heal, Monster mob) {
    Map node = map("p05", k.p05, "p50", k.p50, "p95", k.p95, "perfect", k.perfect, "approximate", k.approximate, "healDps", heal, "uptime", k.uptime);
    var o = BossIncomingOverrides.of(mob);
    if (o.downtime > 0) node.putAll(map("downtime", o.downtime, "downtimeNote", o.downtimeNote));
    return node;
}

static Map mob(Monster mob) {
    return map("id", mob.id, "profileId", mob.profileId(), "name", mob.name,
        "version", mob.version, "label", mob.label(), "hp", mob.hitpoints,
        "level", mob.combatLevel, "invocationScaled", MonsterMechanics.toaScaled(mob),
        "breathesFire", DragonfireRules.breathesFire(mob), "wilderness", WildernessMonsters.isWilderness(mob),
        "naval", NavalCombat.nav(mob.name), "raid", RaidBoosts.raidKey(mob),
        "taskOnly", SlayerLockedMonsters.isTaskOnly(mob), "fightBook", MonsterSpellbooks.bookFor(mob),
        "fightBookReason", MonsterSpellbooks.reasonFor(mob), "slayerMonster", mob.slayerMonster,
        "multiAble", MultiMobs.isMultiAble(mob), "multiLocations", MultiMobs.locations(mob),
        "wildernessExclusive", WildernessMonsters.isExclusive(mob));
}

static Map styles(Map<Style, Pick> results,
    int rks, IntPredicate owned, Set<Integer> simmed) {
    Map styles = new LinkedHashMap<>();
    for (Style style : Style.concreteValues()) {
        Pick result = results == null ? null : results.get(style);
        if (result == null) continue;
        styles.put(style.name().toLowerCase(), styleNode(style, result, rks, owned, simmed));
    }
    return styles;
}

// The Multi card rows as style nodes keyed by tool, unscaled (the
// engine's decoration applies the stack); null without the switch.
static Map multi(Map<Style, Pick> results,
    int rks, IntPredicate owned, Set<Integer> simmed) {
    Map<String, Pick> tools = null;
    for (Pick r : results == null ? List.<Pick>of() : results.values()) if (r != null && r.multiTools != null) tools = r.multiTools;
    if (tools == null) return null;
    Map out = new LinkedHashMap<>();
    for (MultiTool tool : MultiTool.values()) {
        Pick r = tools.get(tool.key);
        if (r != null) {
            Map node = styleNode(tool.style, r, rks, owned, simmed);
            node.put("multiKind", tool.kind);
            // The two ranged tools wear their own item icon on the strip
            // (Andrew 2026-10-19); the barrage keeps the magic sprite.
            node.put("styleItem", tool == CHINS ? CHIN_IDS[0] : tool == VENATOR ? VENATOR_BOW
                : tool == HALLOWFELL ? HALLOWFELL_SWORD : 0);
            out.put(tool.key, node);
        }
    }
    return out;
}

static Map styleNode(Style style, Pick result,
    int rks, IntPredicate owned, Set<Integer> simmed) {
    Dps os = shown(result, false);
    // Tab facts after the sides: the sprite and each side's SHOWN dps
    // (set + spec) so a renderer can label the strip without re-deriving.
    return map("yours", card(result, false, rks, owned, simmed), "bis", card(result, true, rks, owned, simmed),
        "boostLabel", result.boostLabel, "bisBoostLabel", result.gbl,
        "assume", assumeNode(result.boostLabel), "bisAssume", assumeNode(result.gbl), "styleSprite", styleSprite(style),
        "tabDps", os == null ? 0 : os.dps + result.sda,
        "bisTabDps", result.overallBest == null ? 0 : result.overallBest.dps + result.gsda);
}

// A slot ladder for the card (ISS-01M5GE9EJSX6YWCKMSYEWKZ132): each rung
// with its change in the mode's own terms and a signed gain (positive =
// better under the mode) that sizes the strip's bars; base = the worn
// item's own value in the same terms.
public static Map ladderNode(Ladder ladder) { return ladderNode(ladder, MOB.get()); }

// The ladder for mob `mob` of a roster (null = a solo card): a group
// ladder shows that mob's own base and changes and names the group
// figure beside them (Andrew 2026-10-24: "3.97 but in the card it is
// showing 5.54 which is a confusing mismatch").
public static Map ladderNode(Ladder ladder, Integer mob) {
    boolean own = ladder.basePerMob != null && mob != null && mob < ladder.basePerMob.length;
    double base = own ? ladder.basePerMob[mob] : ladder.bdps;
    Map node = map("base", ladder.mode == OptimizeMode.TANKY
        ? format("%.2f taken/s", ladder.baseDtps) : format("%.2f DPS", base));
    if (own) node.put("groupBase", format("group %.2f DPS", ladder.bdps));
    // Balanced weighs both, so it shows both (Andrew 2026-10-22: "show
    // in the ladder view both the dps gain and the dtps change").
    if (ladder.mode == OptimizeMode.BALANCED) node.put("base2", format("%.2f taken/s", ladder.baseDtps));
    Integer at = own ? mob : null;
    node.putAll(map("group", ladder.group, "up", rungs(ladder, ladder.up, at), "down", rungs(ladder, ladder.down, at)));
    // The steps past the strip, for its "more" pages (ISS-01M5QD7PNMCMNRZD92RPRMHWRP).
    if (!ladder.upMore.isEmpty()) node.put("upMore", rungs(ladder, ladder.upMore, at));
    if (!ladder.downMore.isEmpty()) node.put("downMore", rungs(ladder, ladder.downMore, at));
    if (ladder.all != null) {
        // Every option the strip could show, best first (the "All weapons" list).
        List<Object> all = new ArrayList<>();
        for (Step rung : ladder.all) {
            double dps = at != null && rung.pm != null ? rung.pm[at] : rung.dps;
            all.add(map("id", rung.item.id, "name", rung.item.name, "owned", rung.owned,
                "dps", dps, "delta", format("%+.2f DPS", dps - base)));
        }
        node.put("all", all);
    }
    if (ladder.powered != null || ladder.autocast != null) {
        // The magic weapon slot's two strips (ISS-01M5PKSQBAP823XNC13QBW8830):
        // powered staves and autocast staves, each a ladder of its own.
        Map kinds = new LinkedHashMap<>();
        if (ladder.powered != null) kinds.put("powered", ladderNode(ladder.powered, mob));
        if (ladder.autocast != null) kinds.put("autocast", ladderNode(ladder.autocast, mob));
        node.put("kinds", kinds);
    }
    return node;
}

// The rung's improvement over the worn item under the ladder's mode.
static double ladderGain(Ladder ladder, Step rung) {
    switch (ladder.mode) {
        case TANKY:
            return ladder.baseDtps - rung.dtps;
        case BALANCED:
            double base = ladder.bdps <= 0 ? 0 : ladder.baseDtps / ladder.bdps;
            double ratio = rung.dps <= 0 ? base : rung.dtps / rung.dps;
            return base - ratio;
        default:
            return rung.dps - ladder.bdps;
    }
}

static List<Object> rungs(Ladder ladder, List<Step> rungs, Integer mob) {
    List<Object> out = new ArrayList<>();
    for (Step rung : rungs) {
        // A group step reads this mob's own change; the group's ranks it.
        boolean own = mob != null && rung.pm != null && mob < rung.pm.length;
        double dps = own ? rung.pm[mob] : rung.dps;
        double base = own ? ladder.basePerMob[mob] : ladder.bdps;
        Map node = map("id", rung.item.id, "name", rung.item.name,
            "owned", rung.owned, "price", rung.item.getPriceOrZero(),
            "delta", own ? format("%+.2f DPS", dps - base) : ladderDelta(ladder, rung));
        if (own) node.put("groupDelta", format("group %+.2f DPS", rung.dps - ladder.bdps));
        if (ladder.mode == OptimizeMode.BALANCED) node.put("delta2", format("%+.2f taken/s", rung.dtps - ladder.baseDtps));
        node.put("gain", ladderGain(ladder, rung));
        if (ladder.spec) node.put("spec", true);
        // Same result as the worn item - ranked by its better stats.
        node.put("same", Math.abs(dps - base) <= 1e-9 && Math.abs(rung.dtps - ladder.baseDtps) <= 1e-9);
        if (rung.with != null || rung.offhand != null) {
            node.put("with", rung.with == null ? rung.offhand.name : rung.offhand == null ? rung.with.name
                : rung.offhand.name + " and " + rung.with.name);
        }
        out.add(node);
    }
    return out;
}

// "+0.12 DPS" (Max DPS and Balanced, whose damage taken rides as
// delta2), "-0.30 taken/s" (Tanky).
static String ladderDelta(Ladder ladder, Step rung) {
    switch (ladder.mode) {
        case TANKY:
            return format("%+.2f taken/s", rung.dtps - ladder.baseDtps);
        default:
            return format("%+.2f DPS", rung.dps - ladder.bdps);
    }
}

// One side's card: the shown set and everything rendered around it.
static Map card(Pick result, boolean bis, int rks, IntPredicate owned, Set<Integer> simmed) {
    Dps shown = shown(result, bis);
    if (shown == null) return null;
    Map card = map("dps", shown.dps, "maxHit", shown.maxHit, "accuracy", shown.accuracy);
    // The blowpipe's loaded dart rides the attackType STRING
    // ("ranged rapid - dragon dart") - split it into facts: a clean
    // style line + an internalAmmo entry for the column.
    String attackType = shown.attackType;
    if (attackType != null && attackType.contains(" - ")) {
        int dash = attackType.indexOf(" - ");
        String dt = attackType.substring(dash + 3);
        Integer di = BlowpipeDarts.baseIdForTierName(dt);
        if (di != null) {
            card.put("internalAmmo", map("id", di, "name", Names.cap(dt) + " (loaded)"));
            attackType = attackType.substring(0, dash);
        }
    }
    card.putAll(map("attackType", attackType, "spell", shown.getSpellName(),
        "purchaseCost", shown.purchaseCost, "antifireAssumed", shown.antifireAssumed,
        "counted", new ArrayList<>(shown.countedBonuses)));
    Map gear = new LinkedHashMap<>();
    Dps bs = result.overallBest;
    for (Slot slot : Slot.values()) {
        Gear item = shown.loadout.get(slot);
        if (item != null) {
            Map node = item(item);
            if (owned != null) {
                // The classic border language: gold = owned AND best-
                // available (exact or stat-equivalent analog); green =
                // gear the answer ASSUMES (simmed, or unowned on the
                // Yours side); everything else stays quiet grey.
                boolean owns = owned.test(item.id);
                boolean isSimmed = !owns && simmed.contains(item.id);
                Gear bi = bis || bs == null ? null : bs.loadout.get(slot);
                node.putAll(map("owned", owns, "assumed", isSimmed || (!bis && !owns),
                    "bisMatch", owns && bi != null && !result.beaten.contains(slot)
                        && (bi.id == item.id || statEquivalent(bi, item))));
            }
            IntFunction<String> lo = LOCATION.get();
            if (lo != null) {
                // Only FETCH-TRIP storages carry a dot (the classic
                // rule: at-hand gear stays unmarked).
                String where = lo.apply(item.id);
                if (where != null && !where.isEmpty()) node.put("source", where);
            }
            Ladder ladder = bis ? null : result.ladder.get(slot);
            if (ladder != null) node.put("ladder", ladderNode(ladder));
            gear.put(slot.name().toLowerCase(), node);
        }
    }
    card.putAll(map("gear", gear, "quiverAmmo", item(shown.loadout.quiverAmmo),
        "spec", spec(result, bis), "incoming", incoming(bis ? result.gameIncoming : result.incoming)));
    // How long this set takes to kill (ISS-01M6415DTE84ZZ45C4YD3MZRBJ).
    Integer hp = HP.get();
    if (hp != null) card.put("killTime", killNode(killTime(result, shown, hp, bis), healOf(result, bis), MOB_STATS.get()));
    // The defensive mode's trade belongs to the Yours side only (BiS
    // stays the pure-DPS ceiling).
    ModeTrade trade = bis ? null : result.modeTrade;
    if (trade != null) {
        card.put("modeTrade", map("mode", trade.mode.name(), "dpsLossPct", trade.dpsLossPct,
            "dmgCutPct", trade.dmgCutPct, "reason", trade.reason));
    }
    // Carried GWD protection: which gods each bench item soothes, for
    // the Inventory row's "wear through the dungeon" tooltip.
    Map protection = new LinkedHashMap<>();
    for (Gear item : bis ? result.gameProtection : result.protection) protection.put(String.valueOf(item.id), join(", ", GwdProtection.godsOf(item)));
    // A swap picked by kind says why it rides (Hespori's fast ranged weapon).
    Map swapNotes = new LinkedHashMap<>();
    (bis ? result.gameSwapNotes : result.swapNotes).forEach((id, why) -> swapNotes.put(String.valueOf(id), why));
    Gear rw = shown.loadout.getWeapon();
    Gear rs = shown.loadout.get(Slot.SHIELD);
    Stats bonuses = shown.loadout.bonuses;
    card.putAll(map("bench", items(bis ? result.gameBench : result.bench), "protection", protection, "swapNotes", swapNotes,
        "runes", SpellRunes.costFor(shown.getSpellName(), rw == null ? null : rw.lname,
            rs == null ? null : rs.lname), "kitBacked", bis ? result.gkb : result.okb,
        "stats", map("offensive", statBlock(shown.loadout.offensive),
            "defensive", statBlock(shown.loadout.defensive),
            "strength", bonuses.strength, "rangedStrength", bonuses.rangedStrength,
            "magicDamage", bonuses.magicDamage, "prayer", bonuses.prayer)));
    if (rks >= 0) {
        Assessment risk = PvpRisk.assess( shown.loadout, bis ? result.gameSpecWeapon : result.specWeapon, rks);
        card.put("risk", map("riskGp", risk.riskGp, "kept", labels(risk.kept), "lost", labels(risk.lost)));
        // Per-cell fate (the classic risk dots): kept / dropped.
        for (Object sn : gear.values()) {
            if (!(sn instanceof Map)) continue;
            Map node = (Map) sn;
            int id = ((Number) node.get("id")).intValue();
            for (Gear k : risk.kept) if (k.id == id) node.put("fate", "kept");
            for (Gear l : risk.lost) {
                if (l.id == id) {
                    node.put("fate", "lost");
                    node.put("fateGp", risk.valueOf(l));
                }
            }
        }
    }
    return card;
}

// The items' labels, for the risk node's kept/lost lists.
static List<Object> labels(List<Gear> items) {
    List<Object> out = new ArrayList<>();
    for (Gear item : items) out.add(item.label());
    return out;
}

// Analogs count as best-available (any god's d'hide coif).
static boolean statEquivalent(Gear a, Gear b) {
    return a.slot == b.slot && a.speed == b.speed && a.twoh == b.twoh
        && a.category.equals(b.category) && sameBlock(a.offensive, b.offensive)
        && sameBlock(a.defensive, b.defensive) && sameBlock(a.bonuses, b.bonuses);
}

static boolean sameBlock(Stats a, Stats b) { return Arrays.equals(values(a), values(b)); }

// Every stat of the block, in one array to compare.
static int[] values(Stats b) {
    return new int[]{b.stab, b.slash, b.crush, b.magic, b.ranged,
        b.strength, b.rangedStrength, b.magicDamage, b.prayer};
}

// Facts for the header assume icons: the label "Piety + Divine
// super combat" resolves to a prayer sprite id and a boost potion
// item id (renderers draw, never map).
static Map assumeNode(String boostLabel) {
    if (boostLabel == null || boostLabel.isEmpty()) {
        // "None + none" must still be a node: the assume icons ARE the
        // pickers, and a null here erased both - picking None removed
        // the only control that could undo it (field report 2026-08-31,
        // Not on Hand). The sentinel sprites render from -1: the prayer
        // cell falls back to the prayer-book wings, the boost cell to
        // the muted dash, and both stay clickable.
        return map("text", "No prayer or boost", "prayerSprite", -1, "boostItem", -1, "boostSupplied", false);
    }
    int plus = boostLabel.indexOf(" + ");
    String pp = plus > 0 ? boostLabel.substring(0, plus) : boostLabel;
    String bp = plus > 0 ? boostLabel.substring(plus + 3) : null;
    // boostSupplied: the raid hands these out (CoX overloads, ToA salts) -
    // assumed, never packed (Andrew 2026-09-02: potions are supplies to bring).
    return map("text", boostLabel, "prayerSprite", prayerSprite(pp), "prayerImage", prayerImage(pp),
        "boostItem", bp == null ? -1 : boostItem(bp), "boostSupplied", bp != null
            && (bp.equals(BoostProfile.OVERLOAD.toString()) || bp.equals(BoostProfile.OVERLOAD_PLUS.toString())
            || bp.equals(BoostProfile.SMELLING_SALTS.toString())));
}

static Map statBlock(Stats block) {
    return map("stab", block.stab, "slash", block.slash, "crush", block.crush,
        "magic", block.magic, "ranged", block.ranged);
}

static Map spec(Pick result, boolean bis) {
    Gear weapon = bis ? result.gameSpecWeapon : result.specWeapon;
    if (weapon == null) return null;
    Map wn = item(weapon);
    // The spec cell's swaps strip (ISS-01M5HCS725N7XVVBC7CMK6Y43A).
    if (!bis && result.specLadder != null && wn != null) wn.put("ladder", ladderNode(result.specLadder));
    return map("weapon", wn, "dpsAdded", bis ? result.gsda : result.sda,
        "expectedDamage", bis ? result.gameSpecExpectedDamage : result.specExpectedDamage);
}

static Map incoming(Result incoming) {
    if (incoming == null) return null;
    List<Object> threats = new ArrayList<>();
    for (StyleThreat threat : incoming.threats) {
        threats.add(map("style", threat.style, "dps", threat.dps, "maxHit", threat.maxHit,
            "modeled", threat.modeled, "blocked", threat.blocked, "prayerFactor", threat.prayerFactor));
    }
    return map("dps", incoming.tot, "unprayedDps", incoming.unprayedDps,
        "protectSprite", incoming.protectPrayer == null ? -1 : prayerSprite(String.valueOf(incoming.protectPrayer)),
        "protectPrayer", incoming.protectPrayer, "fullyModeled", incoming.fullyModeled,
        "coverage", incoming.coverage, "unmodeled", new ArrayList<>(incoming.unmodeled),
        "overrideNote", incoming.overrideNote, "threats", threats);
}

static List<Object> items(List<Gear> items) {
    List<Object> nodes = new ArrayList<>();
    if (items != null) for (Gear item : items) nodes.add(item(item));
    return nodes;
}

static Map item(Gear item) {
    if (item == null) return null;
    Map node = map("id", item.id, "name", item.label());
    if (Degradable.matches(item.lname)) node.put("degrades", true);
    node.put("price", item.getPriceOrZero());
    return node;
}
}

package com.ll.optimizer;

import com.ll.data.Json;
import com.google.gson.JsonObject;
import com.ll.engine.*;
import java.util.*;
import static com.ll.engine.BoostProfile.*;

// The best stat boost assumed per style, given what the player actually owns.
// <p>Field report 2026-08-24 (a fresh ironman): the card claimed "Assumes:
// Ranging potion" for an account with no ranging potion in the bank. The old
// rule was "tradeable potions are ALWAYS assumed - cheap consumables, like
// prayers you just bring them", which holds for a main with a GE but is simply
// false for an ironman, and contradicts the panel's own "detect best in bank"
// setting. EVERY boost now gates on ownership and the ladder falls through to
// NONE.
// <p>Raid-scoped boosts (overloads, smelling salts) remain deliberately
// un-assumed. Ids verified against net.runelite.api.ItemID 2026-08-25; the
// divine arrays below match its DIVINE_* constants exactly.
public class BoostSelector {
// All dose variants - owning any counts (GE-verified ids 2026-07-21).
// Base (non-divine) potions - these used to be assumed unconditionally.
// Bastion and battlemage carry the SAME offensive boost as the ranging /
// magic potions plus a super-defence half, so owning one means you bring
// it - they rank above the plain family, divine or not. Their own divine
// variants share those numbers exactly, so both id sets map to the one
// profile rather than inventing a duplicate constant.

// Every dose of each boost, by BoostProfile name (boost_items.json).
static final Map<String, int[]> IDS = new HashMap<>();

static {
    JsonObject root = Json.objectOrThrow("boost_items.json");
    for (String key : root.keySet()) {
        if (!key.startsWith("_")) {
            List<Integer> ids = new ArrayList<>();
            Json.ints(root, key, ids);
            IDS.put(key, ids.stream().mapToInt(Integer::intValue).toArray());
        }
    }
}

static int[] ids(String profile) { return IDS.get(profile); }


// The best boost in the GAME per style - the BiS ceiling assumption.
// F2P mode: members consumables do not exist on a free world - the
// only boosts are the attack/strength potion pair (audit A3.5).
public static BoostProfile ceilingFor(Style style, boolean f2p) {
    if (f2p) return style == Style.MELEE ? F2P_COMBAT : NONE;
    switch (style) {
        // Divine variants hold the boost at ceiling for the whole fight
        // - same numbers, better assumption (field ask 2026-07-21).
        case MELEE: return DIVINE_SUPER_COMBAT;
        case RANGED: return DIVINE_RANGING;
        case MAGIC: return SATURATED_HEART;
        default: return NONE;
    }
}

// Each style's ladder, best first (the divine and bastion/battlemage
// families outrank the plain potions; the hearts lead magic).
static final Map<Style, String[]> LADDERS = new EnumMap<>(Style.class);

static {
    JsonObject lads = Json.objectOrThrow("boost_items.json").getAsJsonObject("_ladders");
    for (String style : lads.keySet()) {
        List<String> names = new ArrayList<>();
        Json.strings(lads, style, names);
        LADDERS.put(Style.valueOf(style), names.toArray(new String[0]));
    }
}

// The best boost you can actually assume per style, given what you own.
// Risk-capped wilderness searches never assume a heart (field spec
// 2026-07-18): both hearts are tradeable and worth far more than any
// sane risk cap, so the assumption falls back to the magic potion.
public static BoostProfile bestFor(Style style, Owned owned, boolean f2p, boolean noHearts) {
    if (f2p) return style == Style.MELEE ? F2P_COMBAT : NONE;
    // Each ladder walks best -> worst and ends at NONE: an unowned boost is
    // never assumed, so a low-level account sees the numbers it can
    // actually reach today.
    for (String name : LADDERS.getOrDefault(style, new String[0])) {
        // Any dose counts; the super attack + strength pair needs one of
        // each (field report 2026-10-29: no super combats left).
        boolean has = "SUPER_ATTACK_STRENGTH".equals(name) ? ownsAny(owned, ids("SUPER_ATTACK")) && ownsAny(owned, ids("SUPER_STRENGTH"))
            : ownsAny(owned, ids(name));
        if (!(noHearts && name.endsWith("_HEART")) && has) return BoostProfile.valueOf(name);
    }
    return NONE;
}

// The highest magic level this player can REACH: their live boosted
// level, or their base plus the best magic boost they actually own -
// never a potion they don't have, and never MAXED as a stand-in for
// unknown levels (the old Death Charge seed did both).
public static int reachableMagic(Levels real, Levels live, Owned owned) {
    if (real == null) return live == null ? 0 : live.magic;
    int reachable = live == null ? real.magic : live.magic;
    if (owned != null) {
        BoostProfile best = bestFor(Style.MAGIC, owned, false, false);
        reachable = Math.max(reachable, best.apply(real, live).magic);
    }
    return Math.max(reachable, real.magic);
}

static boolean ownsAny(Owned owned, int[] ids) {
    for (int id : ids) if (owned.owns(id)) return true;
    return false;
}
}

package com.ll.optimizer;

