// The compute animation: painted frames in render/moods/<key>.txt, one file per
// pool, a token-free resource read when that boss computes (scripts/art/hires.py).
// '--' separates frames, '==' moods. A search with no art of its own plays the
// plugin's theme, Halloween in season. The timer runs ONLY while computing and
// dies on unmount (the mascot-era lesson: a hidden component's timer still burns
// the EDT).
class AsciiLoader extends JComponent {
static final String MOODS = "/com/ll/render/moods/";
static final int COLS = 43, ROWS = 24, CELL_W = 5, CELL_H = 10, CELL_BASE = 8;
// The bundled face, not Java's logical Monospaced: on Windows that draws ASCII in
// one font and borrows blocks and shades from another at other widths (Andrew
// 2026-10-15: the flask's rows slid sideways).
static final Font CELL_FONT = loadFont("DejaVuSansMono.ttf").deriveFont(9f);
// The last resort when a resource is missing: fail soft, never a crash.
static final List<String> PLAIN = List.of("Computing...");

static Font loadFont(String resource) {
    try (InputStream in = AsciiLoader.class.getResourceAsStream(resource)) {
        return Font.createFont(Font.TRUETYPE_FONT, in);
    } catch (Exception e) { return new Font(Font.MONOSPACED, Font.PLAIN, 12); }
}

String key;

// The pool key for the pending selection, or null for land.
void setKey(String key) { this.key = key; }

Timer timer = new Timer(140, e -> advance());
List<String> frames = PLAIN;
int tick;
String cells = "";

AsciiLoader() {
    setOpaque(false);
    setFocusable(false);
    setForeground(ResultCards.ACCENT);
}

// The boss's pool, or null when it has none.
static List<List<String>> pool(String key) {
    if (key == null) return null;
    InputStream in = AsciiLoader.class.getResourceAsStream(MOODS + key + ".txt");
    return in == null ? null : load(in);
}

// A frame's runs: <font color=#rrggbb> sets the ink, any other tag is skipped.
static void paintCells(Graphics2D g, String frame) {
    g.setFont(CELL_FONT);
    g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
    char[] text = frame.toCharArray();
    int x = 0, y = CELL_BASE;
    for (int i = 0; i < text.length; i++) {
        char c = text[i];
        if (c == '<') {
            if (text[i + 1] == 'f') g.setColor(new Color(Integer.parseInt(frame.substring(i + 13, i + 19), 16)));
            i = frame.indexOf('>', i);
        } else if (c == '\n') {
            x = 0;
            y += CELL_H;
        } else {
            if (c != ' ') g.drawChars(text, i, 1, x, y);
            x += CELL_W;
        }
    }
}

public Dimension getPreferredSize() {
    // A pixel over: the face's right-edge bar draws past its cell, and clipped there the rim's right side nearly vanished.
    return new Dimension(COLS * CELL_W + 1, ROWS * CELL_H + 1);
}

protected void paintComponent(Graphics g) {
    g.setColor(getForeground());
    paintCells((Graphics2D) g, cells);
}

// The key the current frames were picked for (a sentinel while idle).
String playingKey = "-";

void setRunning(boolean running) {
    // A search started while the last one still animates re-picks from
    // the NEW selection's pool (field report 2026-09-02: an interrupted
    // search kept the first search's animation).
    boolean repick = running && !Objects.equals(key, playingKey);
    if (running && (!timer.isRunning() || repick)) {
        List<List<String>> pool = pool(key);
        if (pool == null) pool = pool(seasonal(LocalDate.now()));
        frames = pool == null || pool.isEmpty() ? PLAIN : pool.get(ThreadLocalRandom.current().nextInt(pool.size()));
        playingKey = key;
        tick = 0;
        advance();
        timer.start();
    } else if (!running) {
        timer.stop();
        playingKey = "-";
    }
}

public void removeNotify() {
    timer.stop();
    super.removeNotify();
}

// The land pool for a date: Halloween from Oct 15 to Oct 31, every year
// (ISS-01M5PR1FRK0XT2PHQ7HJD0D1FZ, Andrew 2026-10-24: "a halloween themed
// loading screen that can override the main loadout lab guy from 10/15-10/31
// (yearly)"), the other holidays by holidays.tsv (scripts/art/holidays.py), the
// flask otherwise. A boss's own art outranks the season.
static String seasonal(LocalDate today) {
    String iso = today.toString();
    try (BufferedReader r = new BufferedReader(new InputStreamReader(AsciiLoader.class.getResourceAsStream("holidays.tsv"), StandardCharsets.UTF_8))) {
        String line;
        while ((line = r.readLine()) != null) {
            String[] row = line.split("\t");
            // A short row has no year and repeats every year.
            String day = row[0].length() == 5 ? iso.substring(5) : iso;
            if (day.compareTo(row[0]) >= 0 && day.compareTo(row[1]) <= 0) return row[2];
        }
    } catch (Exception e) {
        // no table: the flask
    }
    return "flask";
}

void advance() {
    cells = frames.get(tick++ % frames.size());
    repaint();
}

// Package for the parse test. Frame separators are EXACTLY "--": art may
// legitimately start a line with dashes.
static List<List<String>> load(InputStream in) {
    List<List<String>> moods = new ArrayList<>();
    List<String> mood = new ArrayList<>();
    var frame = new StringBuilder();
    try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
        String line;
        while ((line = reader.readLine()) != null) {
            boolean next = line.startsWith("==");
            if (next || line.equals("--")) {
                if (frame.length() > 0) mood.add(frame.toString());
                frame.setLength(0);
                if (next && !mood.isEmpty()) {
                    moods.add(mood);
                    mood = new ArrayList<>();
                }
                continue;
            }
            if (frame.length() > 0) frame.append('\n');
            frame.append(line);
        }
    } catch (Exception e) {
        // keep what was read; an empty pool falls back to the plain line
    }
    if (frame.length() > 0) mood.add(frame.toString());
    if (!mood.isEmpty()) moods.add(mood);
    return moods;
}
}

package com.ll.render;

import com.ll.data.Json;
import java.util.*;
import static com.ll.render.Model.*;

// The bank-tag layout for a card (ported from the classic panel's
// buildBankLayout): the equipment cross in cols 0-2 of the 8-wide bank
// grid (spec weapon in the empty cell left of the legs), the carried
// inventory 4-wide in cols 4-7. Consumable/supply strips join when
// those nodes reach the model. Returns {ids, layout} ready for the
// bank-filter seam.
class BankLayout {

// ids + positions for the shown card; null when the card is empty.
// Everything the Supplies and Inventory rows draw, as stacks for the
// filter (Andrew 2026-09-02: "not seeing all of the supplies in the
// filter view"): the trip's runes, the pouch and casting cape when it
// casts, the assumed potion unless the raid supplies it, every dose of
// each supply pick, and the mob's own "~" filter list.
static List<Map> tripStacks(Map mob, Map cardAssume,
    List<Map> supplies, List<Map> castRunes, List<Map> utilityRunes) {
    LinkedHashSet<Integer> ids = new LinkedHashSet<>();
    for (List<Map> runes : List.of(castRunes, utilityRunes)) for (Map rune : runes) ids.add(id(rune, "id"));
    boolean casts = !ids.isEmpty();
    for (String key : new String[]{"castingPouch", "castingCape"}) {
        int id = id(mob, key);
        if (id > 0 && casts) ids.add(id);
    }
    int boost = cardAssume == null || flag(cardAssume, "boostSupplied") ? 0 : id(cardAssume, "boostItem");
    if (boost > 0) ids.add(boost);
    for (Map supply : supplies) {
        Object all = supply.get("ids");
        if (all instanceof List && !((List<?>) all).isEmpty()) {
            for (Object o : (List<?>) all) ids.add(((Number) o).intValue());
        } else ids.add(id(supply, "itemId"));
    }
    for (Map item : list(mob, "mobFilters")) ids.add(id(item, "id"));
    List<Map> out = new ArrayList<>();
    for (int id : ids) out.add(Map.of("id", id));
    return out;
}

// extraStacks: rune stacks (autocast + the trip's utility casts)
// that join the carried block, so Filter bank shows them too.
static Map build(Map card, List<Map> extraStacks) {
    Map gear = map(card, "gear");
    if (gear == null) return null;
    Map<Integer, Integer> place = new LinkedHashMap<>();
    var ids = new LinkedHashSet<Integer>();
    // The card's silhouette (ResultCards.CROSS), rows of 3: the spec
    // weapon fills the cell left of the legs, the quiver corner and the
    // blank corners stay empty here.
    for (int i = 0; i < ResultCards.CROSS.length; i++) {
        String slot = ResultCards.CROSS[i];
        int pos = (i / 3) * 8 + (i % 3);
        Map item = "#spec".equals(slot) ? map(map(card, "spec"), "weapon")
            : slot == null || slot.startsWith("#") ? null : map(gear, slot);
        if (item != null) {
            int id = id(item, "id");
            place.put(pos, id);
            ids.add(id);
        }
    }
    var carried = new LinkedHashSet<Integer>();
    Map quiver = map(card, "quiverAmmo");
    if (quiver != null) carried.add(id(quiver, "id"));
    for (List<Map> stacks : List.of(list(card, "bench"), list(card, "runes"), extraStacks)) for (Map item : stacks) carried.add(id(item, "id"));
    carried.removeAll(ids);
    int k = 0;
    for (int id : carried) {
        place.put((k / 4) * 8 + 4 + (k % 4), id);
        ids.add(id);
        k++;
    }
    int maxPos = 0;
    for (int pos : place.keySet()) maxPos = Math.max(maxPos, pos);
    int[] layout = new int[maxPos + 1];
    Arrays.fill(layout, -1);
    for (var entry : place.entrySet()) layout[entry.getKey()] = entry.getValue();
    return Json.map("ids", new ArrayList<>(ids), "layout", layout);
}
}

package com.ll.render;

import java.util.Map;

// Routes a contract command {name, args} to the CommandEngine -
// directly in-plugin today; over PluginMessage if the renderer ever
// lifts out into the parked Companion plugin (ADR-0008 Path C).
public interface CommandSink {
void send(String name, Map args);

// A command with no arguments.
default void send(String name) { send(name, Map.of()); }

// The page-param write every chip and picker sends.
default void set(String param, Object value) { send("set-param", Map.of("param", param, "value", value)); }
}

package com.ll.render;

import static java.lang.Math.*;

// The classic gp field vocabulary (ported from the panel's
// parsedBudgetGp): k/m/b suffixes, "max" or "-" = 2b, empty or
// unparseable = 0, clamped to [0, 2b].
public class Gp {

public static int parse(String text) {
    String raw = text == null ? "" : text.trim().toLowerCase();
    if (raw.isEmpty()) return 0;
    if (raw.equals("-") || raw.equals("max")) return 2_000_000_000;
    double multiplier = 1;
    if (raw.endsWith("k") || raw.endsWith("m") || raw.endsWith("b")) {
        multiplier = raw.endsWith("k") ? 1_000 : raw.endsWith("m") ? 1_000_000 : 1_000_000_000;
        raw = raw.substring(0, raw.length() - 1);
    }
    try {
        double value = Double.parseDouble(raw) * multiplier;
        return (int) max(0, min(value, 2_000_000_000));
    } catch (NumberFormatException ex) { return 0; }
}

// The compact display form: rounded, never the raw integer -
// "25m", "7.9m", "480k". For chips and stat lines.
static String formatShort(int gp) {
    if (gp <= 0) return "";
    if (gp >= 10_000_000) return round(gp / 1_000_000.0) + "m";
    if (gp >= 1_000_000) return String.format("%.1fm", gp / 1_000_000.0).replace(".0m", "m");
    if (gp >= 10_000) return round(gp / 1_000.0) + "k";
    if (gp >= 1_000) return String.format("%.1fk", gp / 1_000.0).replace(".0k", "k");
    return String.valueOf(gp);
}

static String format(int gp) {
    if (gp <= 0) return "";
    if (gp >= 1_000_000 && gp % 1_000_000 == 0) return gp / 1_000_000 + "m";
    if (gp >= 1_000 && gp % 1_000 == 0) return gp / 1_000 + "k";
    return String.valueOf(gp);
}
}

