public class LoadoutLabPluginTest {
	/**
	 * Hub plugins loaded alongside when their jar (and its dependency
	 * jars) sit in dev-plugins/ (gitignored): lets cross-plugin
	 * integrations (PluginMessage) be exercised end-to-end locally, e.g.
	 * against a patched Dude Where's My Stuff before its upstream PR
	 * ships. Remember: a hub-installed copy of the same plugin conflicts
	 * with the sideloaded one - disable the hub copy while testing.
	 */
	private static final String[] COMPANION_PLUGINS = {
		"dev.thource.runelite.dudewheresmystuff.DudeWheresMyStuffPlugin",
		"com.loadoutlabui.LoadoutLabUiPlugin",
		// Inventory Setups with add-setup (fork branch plugin-message-add-setup, ISS-01M5V8P2430MQ61C5QKHHRQR6Z).
		"inventorysetups.InventorySetupsPlugin",
	};

	public static void main(String[] args) throws Exception {
		List<Class<? extends Plugin>> plugins = new ArrayList<>();
		plugins.add(LoadoutLabPlugin.class);
		for (String className : COMPANION_PLUGINS) {
			try {
				@SuppressWarnings("unchecked")
				Class<? extends Plugin> plugin = (Class<? extends Plugin>) Class.forName(className);
				plugins.add(plugin);
				System.out.println("dev client: loading companion plugin " + className);
			} catch (ClassNotFoundException e) {
				// jar not in dev-plugins/ - run without it
			}
		}
		@SuppressWarnings("unchecked")
		Class<? extends Plugin>[] arr = plugins.toArray(new Class[0]);
		ExternalPluginManager.loadBuiltin(arr);
		RuneLite.main(args);
	}
}

package com.ll;
import java.util.regex.Pattern;
import java.util.regex.Matcher;
import java.nio.charset.StandardCharsets;
import java.io.InputStream;


/** The build-stamped plugin version (processResources writes
 * version.properties; VersionStampTest pins it to the hub manifest).
 * Test-side since 0.7.2: nothing in main reads it (the report went).
 */
public class PluginVersion {
    /** Bumped with every release (VersionStampTest pins it to build.gradle):
     * hub builds ship the resource unexpanded, so this is what players see. */
    public static final String FALLBACK = "0.8.4";
    public static final String VERSION = load();

    public static String stamp(String properties) {
        Matcher m = Pattern.compile("version=(\\S+)").matcher(properties);
        return m.find() && !m.group(1).contains("${") ? m.group(1) : FALLBACK;
    }


    static String load() {
        try (InputStream in = PluginVersion.class.getResourceAsStream( "/com/ll/version.properties")) {
            return stamp(new String(in.readAllBytes(), StandardCharsets.UTF_8));
        } catch (Exception ex) { return "unknown"; }
    }
}

