package com.ll.data;

import com.ll.engine.DemonbaneVulnerability;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The Fractured Archive's data after the post-launch fixes (ISS-01M5JBYYKPE7192Z24NTR432M8,
 * Andrew 2026-10-22: "gearscore just did a big update on TFA can we make
 * sure our data is as accurate as theirs"). Values from the live wiki and
 * Jagex's launch-day news; ids from the gameval constants.
 */
class TfaDataTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static Monster byId(int id) {
		return data.getMonsters().stream().filter(m -> m.getId() == id).findFirst()
			.orElseThrow(() -> new AssertionError("no monster row " + id));
	}

	// The cdn gives both Archive Guardian versions the wiki's one id (16659).
	private static Monster byVersion(String name, String version) {
		return data.getMonsters().stream().filter(m -> name.equals(m.getName()) && version.equals(m.getVersion())).findFirst()
			.orElseThrow(() -> new AssertionError("no monster row " + name + " " + version));
	}

	@Test
	@DisplayName("the wiki's fixes since 20 Oct: Nex crush 35, Bork crush 10 and flat armour 11 (the wiki's 8-14 base), Moia weak to air, Xarth's bonuses")
	void statFixes() {
		assertEquals(35, byId(11278).getDefensive().get("crush"), "Nex (Jagex 2026-10-20)");
		Monster bork = byId(16640);
		assertEquals(10, bork.getDefensive().get("crush"));
		assertEquals(11, bork.getDefensive().getFlatArmour());
		Monster moia = byId(16667);
		assertEquals("air", moia.getWeaknessElement());
		assertEquals(80, moia.getWeaknessSeverity());
		Monster xarth = byId(16684);
		assertEquals(150, xarth.getOffence().getAttackBonus());
		assertEquals(225, xarth.getOffence().getStrengthBonus());
		assertEquals(1601, byId(16677).getCombatLevel(), "Ocellus phase 3");
	}

	@Test
	@DisplayName("the Archive Guardian has a real grounded row beside the flying one (the wiki's one id, 16659)")
	void groundedGuardian() {
		Monster grounded = byVersion("Archive Guardian", "Grounded");
		assertEquals("Archive Guardian", grounded.getName());
		assertEquals("Grounded", grounded.getVersion());
		assertEquals(90, grounded.getDefensive().get("slash"));
		assertEquals(50, grounded.getDefensive().get("light"));
		assertEquals(115, grounded.getDefensive().get("standard"));
		assertEquals("fire", grounded.getWeaknessElement());
		assertEquals(40, grounded.getWeaknessSeverity());
		Monster flying = byVersion("Archive Guardian", "Flying");
		assertEquals(16659, flying.getId());
		assertEquals(80, flying.getWeaknessSeverity());
	}

	@Test
	@DisplayName("drains stop at 60% of base Defence on the six capped bosses (Jagex hotfix); The Blade drains to 0")
	void defenceFloors() {
		int[][] floors = {{16659, 156}, {16652, 78}, {16640, 180}, {16667, 117}, {16684, 102}, {16673, 129}, {16677, 150}};
		for (int[] f : floors) {
			assertEquals(f[1], DefenceFloors.floorFor(byId(f[0])), "floor for " + f[0]);
		}
		assertEquals(156, DefenceFloors.floorFor(byVersion("Archive Guardian", "Grounded")));
		assertEquals(0, DefenceFloors.floorFor(byId(16675)), "Ocellus phase 2 (The Blade) has no cap");
		assertEquals(0, DefenceFloors.floorFor(byId(16665)), "Dreadnoth has no cap");
	}

	@Test
	@DisplayName("demonbane: Xarth and Ocellus take 80% of it, Dreadnoth 25%")
	void demonbane() {
		assertEquals(80, DemonbaneVulnerability.percentFor(byId(16684)));
		assertEquals(80, DemonbaneVulnerability.percentFor(byId(16673)), "Ocellus phase 1");
		assertEquals(80, DemonbaneVulnerability.percentFor(byId(16677)));
		assertEquals(25, DemonbaneVulnerability.percentFor(byId(16665)));
	}

	@Test
	@DisplayName("the Dagon'hai trio and the adds have rows: Elder, Monks, jelly, binder, void rift and augmenter, Xarth's corpses")
	void newRows() {
		// Same-stat spawns fold into one row (the corpus rule, as for the
		// Tormented Demons): the Elder is 16643, the two Monks one row - the
		// cdn's order decides which id it keeps.
		assertEquals(640, byId(16643).getHitpoints(), "Dagon'hai Elder");
		assertEquals(640, data.searchMonsters("dagon'hai monk", 1).get(0).getHitpoints(), "Dagon'hai Monk");
		for (int id : new int[]{16666, 16670, 16678, 16680, 16687, 16688}) {
			assertTrue(byId(id).getHitpoints() > 0, "row " + id);
		}
		assertEquals("Doused", byId(16688).getVersion());
	}
}

package com.ll.data;

import com.ll.engine.CandidateMode;
import com.ll.engine.Style;
import com.ll.engine.LoadoutOptimizer;
import com.ll.engine.Req;
import com.ll.engine.Owned;
import com.ll.engine.Levels;
import com.ll.engine.PrayerBonuses;
import com.ll.engine.TestRequests;
import java.util.Set;
import java.util.stream.Collectors;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The Fractured Archive (released 2026-10-20) lands in one pass: the
 * encounters with published stats as a raid group, the rewards as gear
 * rows (scripts/wiki_intake.py, ids from runelite-api 1.13.3 gameval).
 */
class TfaIntakeTest {
	private static Tables data;
	private static MonsterGroups.MonsterGroup tfa;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		tfa = MonsterGroups.load(data).stream()
			.filter(g -> g.getName().equals("The Fractured Archive"))
			.findFirst().orElseThrow();
	}

	private static Monster guardian() {
		return tfa.getMobs().stream().filter(m -> m.getName().equals("Archive Guardian")).findFirst().orElseThrow();
	}

	@Test
	@DisplayName("the raid group lists the encounters that have stats: the Guardian and Xarth in two phases, the Dagon'hai trio, Ocellus in three")
	void groupRoster() {
		assertTrue(tfa.isRaid());
		// The two Monks share one stat block, so the corpus folds them into one row.
		assertEquals(14, tfa.getMobs().size());
		Set<String> names = tfa.getMobs().stream().map(Monster::getName).collect(Collectors.toSet());
		for (String name : new String[]{"Archive Guardian", "Ezekiel", "Bork", "The Smorks",
			"Dreadnoth the Jellied", "Moia", "Xarth", "Ocellus", "Dagon'hai Elder", "Dagon'hai Monk"}) {
			assertTrue(names.contains(name), name);
		}
		assertEquals(3, tfa.getMobs().stream().filter(m -> m.getName().equals("Ocellus")).count());
	}

	@Test
	@DisplayName("the Archive Guardian reads 550 hitpoints and an 80% fire weakness")
	void guardianStats() {
		Monster guardian = guardian();
		assertEquals(550, guardian.getHitpoints());
		assertEquals("fire", guardian.getWeaknessElement());
		assertEquals(80, guardian.getWeaknessSeverity());
	}

	@Test
	@DisplayName("every style computes a set against the Guardian")
	void everyStyleComputes() {
		for (Style style : Style.values()) {
			Req request = TestRequests.of(guardian(), style, Levels.MAXED,
				PrayerBonuses.bestAvailable(Levels.MAXED), null, 0, CandidateMode.ALL_STANDARD,
				true, false, Owned.EMPTY, 1);
			assertFalse(new LoadoutOptimizer().optimize(data, request).isEmpty(), style.name());
		}
	}

	@Test
	@DisplayName("the tradeable rewards are priced so the game-best pool admits them; a charged weapon is priced as the uncharged twin you buy")
	void rewardsArePricedAndTradeableByVersion() {
		for (int id : new int[]{34681, 34719, 34717, 34727, 34684, 34702}) {
			Gear item = data.getGear(id);
			assertTrue(item.isTradeable(), item.getName());
			assertNotNull(item.getEstimatedPrice(), item.getName() + " needs a price for ALL_STANDARD");
		}
		// Charged versions only (ISS-01M5QQV2TGQ5X730T0JJ75S1RD): the uncharged
		// twin is a variant, and the charged one carries its price and trades.
		assertTrue(data.isVariant(34717), "Obligator (uncharged) stands behind the charged one");
		assertTrue(data.getGear(34715).isTradeable(), "Obligator (charged) is bought as the uncharged one");
		assertEquals(data.getGear(34717).getEstimatedPrice(), data.getGear(34715).getEstimatedPrice(), "at its price");
		assertTrue(data.getGear(34725).isTradeable(), "Zorya's tome (charged) the same way");
		Gear xbow = data.getGear(34681);
		Req request = TestRequests.of(guardian(), Style.RANGED, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), null, 0, CandidateMode.ALL_STANDARD,
			true, false, Owned.EMPTY, 1);
		java.util.Map<Slot, Integer> pin = new java.util.EnumMap<>(Slot.class);
		pin.put(Slot.WEAPON, xbow.getId());
		assertFalse(new LoadoutOptimizer().optimize(data, request.withPinnedItems(pin)).isEmpty(),
			"the crossbows find their bolts without a pinned ammo slot");
	}

	@Test
	@DisplayName("the rewards are gear rows: the Obligator a crush two-hander, the tome a powered staff, the crossbows and bolts, the Rondache")
	void rewardsInTheCorpus() {
		Gear obligator = data.getGear(34715);
		assertNotNull(obligator);
		assertEquals("Obligator", obligator.getName());
		assertTrue(obligator.isTwoh());
		assertEquals(120, obligator.getOffensive().getCrush());
		Gear tome = data.getGear(34725);
		assertNotNull(tome);
		assertTrue(tome.isPoweredStaff(), "Zorya's tome is a powered staff");
		assertTrue(tome.isTwoh());
		assertNotNull(data.getGear(34681), "Ascension crossbows");
		assertNotNull(data.getGear(34719), "Rondache");
		for (int bolts : new int[]{34684, 34690, 34696, 34702, 34708}) {
			assertEquals(Slot.AMMO, data.getGear(bolts).getSlot(), "bolts " + bolts);
		}
	}
}

package com.ll.data;

import com.ll.engine.CandidateMode;
import com.ll.engine.Style;
import com.ll.engine.Dps;
import com.ll.engine.Kit;
import com.ll.engine.LoadoutOptimizer;
import com.ll.engine.MonsterMechanics;
import com.ll.engine.Req;
import com.ll.engine.Owned;
import com.ll.engine.Levels;
import com.ll.engine.PrayerBonuses;
import com.ll.engine.TestRequests;
import java.util.EnumMap;
import java.util.List;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Andrew, client test 2026-10-20: "all of my bis recommendations for TFA
 * are melee". The published defences favour crush nearly everywhere, but
 * two phases cannot be meleed (wiki, read 2026-10-20): the Archive
 * Guardian flies until its shield breaks (ranged, magic or a halberd),
 * and Xarth's first phase is fought from behind the pillars. The Guardian
 * is also immune to Ancient Magicks.
 */
class TfaStipulationsTest {
	private static Tables data;
	private static List<Monster> tfa;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		tfa = MonsterGroups.load(data).stream()
			.filter(g -> g.getName().equals("The Fractured Archive"))
			.findFirst().orElseThrow().getMobs();
	}

	private static Monster member(String label) {
		return tfa.stream().filter(m -> label.equals(m.getVersion()))
			.findFirst().orElseThrow(() -> new AssertionError("no member " + label));
	}

	private static List<Dps> best(Monster mob, Style style) {
		Req request = TestRequests.of(mob, style, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), null, 0, CandidateMode.ALL_STANDARD,
			true, false, Owned.EMPTY, 3);
		return new LoadoutOptimizer().optimize(data, request);
	}

	@Test
	@DisplayName("the roster carries the Guardian's two phases, Xarth's two phases and the Dagon'hai Elder and Monk: fourteen rows")
	void fourteenRows() {
		// The Dagon'hai joined 2026-10-22 (ISS-01M5JBYYKPE7192Z24NTR432M8).
		assertEquals(14, tfa.size());
	}

	@Test
	@DisplayName("the shielded Guardian flies: a melee set must be a halberd")
	void shieldFlies() {
		Monster shield = member("Shield (flying)");
		assertTrue(shield.hasAttribute("flying"));
		for (Dps r : best(shield, Style.MELEE)) {
			assertEquals("Polearm", r.getLoadout().getWeapon().getCategory(), r.getLoadout().getWeapon().getName());
		}
	}

	@Test
	@DisplayName("the grounded Guardian takes any melee weapon")
	void groundedTakesMelee() {
		Monster grounded = member("Grounded");
		assertFalse(grounded.hasAttribute("flying"));
		List<Dps> melee = best(grounded, Style.MELEE);
		assertFalse(melee.isEmpty());
		assertNotEquals("Polearm", melee.get(0).getLoadout().getWeapon().getCategory());
	}

	@Test
	@DisplayName("Xarth's first phase has no melee card; his second does")
	void xarthPhases() {
		assertTrue(com.ll.engine.Immunity.styleImmune(member("P1 (from the pillars)"), Style.MELEE));
		assertFalse(com.ll.engine.Immunity.styleImmune(member("P2"), Style.MELEE));
		assertFalse(best(member("P2"), Style.MELEE).isEmpty());
	}

	@Test
	@DisplayName("the Guardian takes no Ancient Magicks in either phase")
	void guardianShrugsOffAncients() {
		Spell barrage = data.getSpells().stream().filter(s -> s.getName().equals("Ice Barrage")).findFirst().orElseThrow();
		Spell surge = data.getSpells().stream().filter(s -> s.getName().equals("Fire Surge")).findFirst().orElseThrow();
		EnumMap<Slot, Gear> worn = new EnumMap<>(Slot.class);
		worn.put(Slot.WEAPON, data.getGear(21006));
		Kit kodai = new Kit(worn);
		for (String phase : new String[]{"Shield (flying)", "Grounded"}) {
			Monster guardian = member(phase);
			assertTrue(MonsterMechanics.isImmune(guardian, Style.MAGIC, kodai, barrage), phase);
			assertFalse(MonsterMechanics.isImmune(guardian, Style.MAGIC, kodai, surge), phase);
		}
	}

	@Test
	@DisplayName("Ocellus is a demon in phases 1 and 3 only - the wiki leaves phase 2's attributes blank")
	void ocellusDemonPhases() {
		for (Monster m : tfa) {
			if (m.getName().equals("Ocellus")) {
				assertEquals(!"Phase 2".equals(m.getVersion()), m.hasAttribute("demon"), m.getVersion());
			}
		}
	}

	@Test
	@DisplayName("Ocellus's third phase reads its own 5,250 hitpoints")
	void ocellusThree() {
		assertEquals(5250, tfa.stream().filter(m -> "Phase 3".equals(m.getVersion()) && m.getName().equals("Ocellus"))
			.findFirst().orElseThrow().getHitpoints());
	}
}

package com.ll.data;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;

/**
 * The trip-supply tier tables (field direction 2026-07-20): persistent
 * food/fast-food/prayer/surge/anti-venom defaults with a "Detect best"
 * that picks the best owned tier, and anti-venom gated on the wiki's
 * venom-inflictor list.
 */
public class TripSuppliesTest {
	@Test
	public void everyCategoryLoadsWithBestFirstOrdering() {
		// Spot-check the verified tier heads (wiki 2026-07-20): moonlight
		// antelope 26 hp leads food, karambwan leads fast food, super
		// restore leads prayer, extended anti-venom+ leads anti-venom.
		Assert.assertEquals("MOONLIGHT_ANTELOPE", Trip.options(Trip.FOOD).get(0).key);
		Assert.assertEquals("KARAMBWAN", Trip.options(Trip.FAST_FOOD).get(0).key);
		Assert.assertEquals("SUPER_RESTORE", Trip.options(Trip.PRAYER_RESTORE).get(0).key);
		Assert.assertEquals("SURGE_POTION", Trip.options(Trip.SURGE).get(0).key);
		Assert.assertEquals("MAX_CAPE", Trip.options(Trip.SPELLBOOK_CAPE).get(0).key);
		Assert.assertEquals("EXTENDED_ANTIVENOM", Trip.options(Trip.ANTIVENOM).get(0).key);
	}

	@Test
	public void detectBestPicksTheBestOwnedTierAcrossAnyDose() {
		// Owning only a 1-dose prayer potion (id 143) must still detect
		// PRAYER_POTION - the filter and detection cover every dose.
		Set<Integer> owned = new HashSet<>();
		owned.add(143);
		Trip.Option pick = Trip.detectBest(Trip.PRAYER_RESTORE, owned::contains);
		Assert.assertNotNull(pick);
		Assert.assertEquals("PRAYER_POTION", pick.key);

		// Adding a super restore (3-dose, 3026) upgrades the pick.
		owned.add(3026);
		Assert.assertEquals("SUPER_RESTORE",
			Trip.detectBest(Trip.PRAYER_RESTORE, owned::contains).key);
	}

	/** Andrew 2026-09-01: "wildy food / supplies should prefer blighted
	 * options". Blighted variants are wilderness-only (wiki), so a trip
	 * there takes a banked one over any tradeable tier, and a land trip
	 * never picks one (ids objtypes-verified 2026-09-02). */
	@Test
	public void blightedSuppliesWinInTheWildernessAndNeverOnLand() {
		Set<Integer> bank = new HashSet<>(List.of(29143, 24592, 3024, 24598, 3144, 24595));
		Assert.assertEquals("BLIGHTED_ANGLERFISH",
			Trip.detectBest(Trip.options(Trip.FOOD), bank::contains, true).key);
		Assert.assertEquals("BLIGHTED_SUPER_RESTORE",
			Trip.detectBest(Trip.options(Trip.PRAYER_RESTORE), bank::contains, true).key);
		Assert.assertEquals("BLIGHTED_KARAMBWAN",
			Trip.detectBest(Trip.options(Trip.FAST_FOOD), bank::contains, true).key);
		// Land: the best tradeable tier, blighted ignored even when owned.
		Assert.assertEquals("MOONLIGHT_ANTELOPE",
			Trip.detectBest(Trip.options(Trip.FOOD), bank::contains, false).key);
		Set<Integer> onlyBlighted = Set.of(24592);
		Assert.assertNull("blighted cannot be eaten outside the wilderness",
			Trip.detectBest(Trip.options(Trip.FOOD), onlyBlighted::contains, false));
		// Wilderness without a blighted stack falls through to the tiers.
		Set<Integer> sharks = Set.of(385);
		Assert.assertEquals("SHARK",
			Trip.detectBest(Trip.options(Trip.FOOD), sharks::contains, true).key);
		// The two-arg detect is the land rule.
		Assert.assertNull(Trip.detectBest(Trip.FOOD, onlyBlighted::contains));
	}

	@Test
	public void detectBestReturnsNullWhenNothingIsOwned() {
		Assert.assertNull(Trip.detectBest(Trip.FOOD, id -> false));
	}

	@Test
	public void prayerRegenerationIsNeverAutoDetected() {
		// Its over-time mechanism must not win a detect - explicitly
		// selectable only (detect:false in the resource).
		Set<Integer> owned = new HashSet<>();
		owned.add(30125); // Prayer regeneration potion(4)
		Assert.assertNull(Trip.detectBest(Trip.PRAYER_RESTORE, owned::contains));
		Assert.assertNotNull(Trip.option(Trip.PRAYER_RESTORE, "PRAYER_REGENERATION"));
	}

	/** Field report 2026-10-31 (an ironman, Discord): "please give us moonlight
	 * moth mixes as an option". Wiki: 22 prayer points a dose, two doses, no
	 * Herblore - the prayer potion for irons, weaker per dose than one. */
	@Test
	public void moonlightMothMixIsAPrayerRestoreBelowThePrayerPotion() {
		Trip.Option mix = Trip.option(Trip.PRAYER_RESTORE, "MOONLIGHT_MOTH_MIX");
		Assert.assertNotNull("the mix is a prayer restore option", mix);
		Assert.assertEquals("Moonlight moth mix", mix.name);
		Assert.assertArrayEquals("two-dose leads the cell, one-dose rides the filter", new int[]{29195, 29213}, mix.ids);
		Assert.assertTrue("a real restore, so Detect best may pick it", mix.detect);
		List<String> keys = new java.util.ArrayList<>();
		for (Trip.Option o : Trip.options(Trip.PRAYER_RESTORE)) keys.add(o.key);
		Assert.assertTrue("after the prayer potion", keys.indexOf("PRAYER_POTION") < keys.indexOf("MOONLIGHT_MOTH_MIX"));
		Assert.assertTrue("before prayer regeneration", keys.indexOf("MOONLIGHT_MOTH_MIX") < keys.indexOf("PRAYER_REGENERATION"));
		// An iron with only mixes banked detects them; a prayer potion in the bank still wins.
		Assert.assertEquals("MOONLIGHT_MOTH_MIX", Trip.detectBest(Trip.PRAYER_RESTORE, id -> id == 29213).key);
		Assert.assertEquals("PRAYER_POTION", Trip.detectBest(Trip.PRAYER_RESTORE, id -> id == 29213 || id == 143).key);
	}

	@Test
	public void spellbookCapeDetectPrefersTheMaxCape() {
		Set<Integer> owned = new HashSet<>();
		owned.add(9763); // Magic cape(t)
		Assert.assertEquals("MAGIC_CAPE",
			Trip.detectBest(Trip.SPELLBOOK_CAPE, owned::contains).key);
		owned.add(13280); // Max cape
		Assert.assertEquals("MAX_CAPE",
			Trip.detectBest(Trip.SPELLBOOK_CAPE, owned::contains).key);
	}

	@Test
	public void onlyTheSpellbookCapesAreUtilityPlacement() {
		// Utility = fight-relevant gear that is neither worn nor carried:
		// the bank layout's third strip. Consumables stay inventory-placed.
		for (Trip.Option o : Trip.options(Trip.SPELLBOOK_CAPE)) {
			Assert.assertTrue(o.key + " should be utility", o.utility);
		}
		for (String category : new String[]{Trip.FOOD, Trip.FAST_FOOD,
			Trip.PRAYER_RESTORE, Trip.SURGE, Trip.ANTIVENOM}) {
			for (Trip.Option o : Trip.options(category)) {
				Assert.assertFalse(o.key + " should not be utility", o.utility);
			}
		}
	}

	@Test
	public void theCannonIsAnExplicitFiveCellKit() {
		// miko (Discord 2026-10-17) wanted the cannon in every setup; AKAddons:
		// "an easy option to include it in inventory" - no dps modelled, so
		// Detect best never picks it; chosen, it is one cell per part.
		List<Trip.Option> cannon = Trip.options(Trip.CANNON);
		Assert.assertEquals(1, cannon.size());
		Assert.assertEquals("DWARF_MULTICANNON", cannon.get(0).key);
		Assert.assertArrayEquals(new int[]{6, 8, 10, 12, 2}, cannon.get(0).ids);
		Assert.assertEquals(5, cannon.get(0).names.length);
		Assert.assertFalse(cannon.get(0).detect);
		Assert.assertNull(Trip.detectBest(Trip.CANNON, id -> true));
		// Each cell carries its variants too (Andrew 2026-10-18: the ornamented
		// parts and granite cannonballs must light up in the filter).
		Assert.assertEquals(5, cannon.get(0).cells.length);
		Assert.assertArrayEquals(new int[]{6, 26520}, cannon.get(0).cells[0]);
		Assert.assertArrayEquals(new int[]{2, 21728}, cannon.get(0).cells[4]);
		Assert.assertEquals("Cannon", Trip.label(Trip.CANNON));
		Assert.assertEquals("Food", Trip.label(Trip.FOOD));
		Assert.assertNull("repair kits never show in the chip menu",
			Trip.label(Trip.SHIP_REPAIR_KIT));
	}

	@Test
	public void unknownAndModeKeysResolveToNoOption() {
		Assert.assertNull(Trip.option(Trip.FOOD, "DETECT_BEST"));
		Assert.assertNull(Trip.option(Trip.FOOD, "NONE"));
		Assert.assertNull(Trip.option(Trip.FOOD, "NO_SUCH"));
	}

	@Test
	public void venomInflictorsMatchByNameIncludingVariants() {
		Assert.assertTrue(Trip.inflictsVenom(named("Zulrah")));
		Assert.assertTrue(Trip.inflictsVenom(named("Araxxor")));
		Assert.assertTrue(Trip.inflictsVenom(named("Dreadborn Araxyte")));
		Assert.assertTrue(Trip.inflictsVenom(named("Vorkath")));
		Assert.assertFalse(Trip.inflictsVenom(named("General Graardor")));
