import com.ll.optimizer.BoostSelector;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * F2P mode used to assume members consumables and prayers (2026-07 player
 * audit A3.5): Super combat / Ranging potion / Saturated heart labels on
 * F2P cards, and game-best prayers of Piety/Rigour/Augury that do not
 * exist on a free world. F2P assumptions now cap at the real F2P book
 * (everything through Mystic Might) and F2P potions (attack + strength).
 * Also locks A2.12: sub-31 prayer tiers are NAMED, not silently applied.
 */
class F2pAssumptionsTest {
	@Test
	@DisplayName("the F2P prayer ceiling is the 1.15 tier, by name")
	void f2pPrayerCeiling() {
		PrayerBonuses f2p = PrayerBonuses.bestAvailable(Levels.MAXED, Prayers.F2P);
		assertEquals("Incredible Reflexes + Ultimate Strength", f2p.nameFor(Style.MELEE));
		assertEquals("Eagle Eye", f2p.nameFor(Style.RANGED));
		assertEquals("Mystic Might", f2p.nameFor(Style.MAGIC));
	}

	@Test
	@DisplayName("F2P boosts: attack+strength potions for melee, nothing for ranged/magic")
	void f2pBoosts() {
		assertEquals(BoostProfile.F2P_COMBAT, BoostSelector.bestFor(Style.MELEE, Owned.EMPTY, true, false));
		assertEquals(BoostProfile.NONE, BoostSelector.bestFor(Style.RANGED, Owned.EMPTY, true, false));
		assertEquals(BoostProfile.NONE, BoostSelector.bestFor(Style.MAGIC, Owned.EMPTY, true, false));
		assertEquals(BoostProfile.F2P_COMBAT, BoostSelector.ceilingFor(Style.MELEE, true));
		// Members with an EMPTY bank now assume nothing either (2026-08-25):
		// this line used to expect SUPER_COMBAT, which was the same defect the
		// ironman field report caught. The F2P assertions above are unaffected -
		// F2P_COMBAT is a mode ceiling, not an owned item.
		assertEquals(BoostProfile.NONE, BoostSelector.bestFor(Style.MELEE, Owned.EMPTY, false, false));
	}

	@Test
	@DisplayName("attack/strength potions boost +3 plus 10% of the level")
	void f2pCombatPotionMath() {
		Levels boosted = BoostProfile.F2P_COMBAT.apply(Levels.MAXED, null);
		assertEquals(99 + 3 + 9, boosted.getAttack());
		assertEquals(99 + 3 + 9, boosted.getStrength());
		assertEquals(99, boosted.getRanged(), "no F2P ranged boost exists");
		assertEquals(99, boosted.getMagic(), "no F2P magic boost exists");
	}

	@Test
	@DisplayName("sub-31 prayer tiers are named in the assumes label (audit A2.12)")
	void lowTierPrayersAreNamed() {
		Levels low = new Levels(99, 99, 99, 99, 99, 16, 99);
		PrayerBonuses prayers = PrayerBonuses.bestAvailable(low, Prayers.ALL);
		assertEquals("Improved Reflexes + Superhuman Strength", prayers.nameFor(Style.MELEE));
		assertEquals("Sharp Eye", prayers.nameFor(Style.RANGED));
		assertEquals("Mystic Will", prayers.nameFor(Style.MAGIC));

		Levels mid = new Levels(99, 99, 99, 99, 99, 27, 99);
		PrayerBonuses midPrayers = PrayerBonuses.bestAvailable(mid, Prayers.ALL);
		assertEquals("Hawk Eye", midPrayers.nameFor(Style.RANGED));
		assertEquals("Mystic Lore", midPrayers.nameFor(Style.MAGIC));
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * TRIPLEKILLTRENT (YouTube 2026-10-18): "its telling me salad blade is
 * better than my fang at toa". The harness showed why: inside the Tombs
 * the fang's hit chance ran 17-24% under the official calc while the
 * sulphur blades matched exactly. Wiki (Osmumten's fang): outside ToA the
 * fang rerolls a failed accuracy check against a reduced defence roll;
 * inside the Tombs it simply rolls accuracy twice, so the hit chance is
 * 1 - (1 - p)^2. The constants below are the official calculator's own
 * numbers for these exact vectors (fang-baba-i300, fang-warden3-i300:
 * maxed levels, Piety, invocation 300, the fang alone).
 */
class FangToaTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static Dps fangAt(String monster, String version, int invocation) {
		Monster mob = version.isEmpty() ? data.searchMonsters(monster, 1).get(0)
			: data.getMonsters().stream()
				.filter(m -> m.getName().equalsIgnoreCase(monster) && m.getVersion().equalsIgnoreCase(version))
				.findFirst().orElseThrow(AssertionError::new);
		mob = MonsterMechanics.atToaInvocation(mob, invocation);
		Gear fang = data.getGearItems().stream()
			.filter(g -> g.getLname().equals("osmumten's fang") && g.isStandardGear())
			.findFirst().orElseThrow(AssertionError::new);
		EnumMap<Slot, Gear> gear = new EnumMap<>(Slot.class);
		gear.put(Slot.WEAPON, fang);
		Req request = new Req(mob, Style.MELEE, Levels.MAXED,
			// The official vectors were taken under Piety (2026-10-18); ALL
			// assumes Zeal since the Fractured Archive (2026-10-20).
			PrayerBonuses.bestAvailable(Levels.MAXED, new Prayers(true, true, true, true, true)),
			null, 0, CandidateMode.ALL_STANDARD, true, false,
			Owned.EMPTY, RequirementProfile.MAXED, 1);
		Dps result = new Calc().calculate(request, new Kit(gear));
		assertNotNull(result);
		return result;
	}

	@Test
	@DisplayName("inside the Tombs the fang rolls accuracy twice - the official calc's hit chances")
	void fangRollsTwiceInsideToa() {
		assertEquals(0.624, fangAt("Ba-Ba", "", 300).getAccuracy(), 0.006, "Ba-Ba at invocation 300");
		assertEquals(0.441, fangAt("Elidinis' Warden", "Enraged", 300).getAccuracy(), 0.006,
			"the Enraged Warden at invocation 300");
	}

	@Test
	@DisplayName("outside the Tombs the fang keeps its reroll formula - vector fang-goblin stays exact")
	void fangRerollOutsideToa() {
		Dps goblin = fangAt("Goblin", "", 0);
		assertEquals(RollMath.fangAccuracy(goblin.getAr(), goblin.getDr()),
			goblin.getAccuracy(), 1e-9);
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.EnumMap;
import org.junit.Assert;
import org.junit.Test;

/**
 * Flat armour applies PER HITSPLAT (official calc: a hit-distribution
 * transformer on accurate hits). Blue Moon's -5 rewards multi-hit
 * weapons twice (wiki: "weapons which deal damage via multiple
 * hitsplats are particularly effective here" - field report
 * 2026-08-10: "double hits on blue moon is good"); Eclipse Moon's +6
 * punishes them twice. The old order split the macuahuitl's max AFTER
 * armour, crediting the -5 only once.
 */
public class FlatArmourPerHitTest {
	private static Tables data;

	private static Tables data() {
		if (data == null) {
			data = new DataService().load();
		}
		return data;
	}

	private static Gear byName(String lname) {
		return data().getGearItems().stream()
			.filter(g -> g.getLname().equals(lname) && g.isStandardGear())
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing: " + lname));
	}

	private static Dps macuahuitlVs(String monster) {
		Monster mob = data().searchMonsters(monster, 1).get(0);
		Req request = TestRequests.of(mob, Style.MELEE,
			Levels.MAXED, PrayerBonuses.bestAvailable(Levels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, Owned.EMPTY, 1);
		EnumMap<Slot, Gear> gear = new EnumMap<>(Slot.class);
		gear.put(Slot.WEAPON, byName("dual macuahuitl"));
		Dps result = new Calc().calculate(request, new Kit(gear));
		Assert.assertNotNull(result);
		return result;
	}

	@Test
	public void blueMoonCreditsTheMinusFiveOnBothHitsplats() {
		Dps result = macuahuitlVs("blue moon");
		// Each hitsplat carries its own +5, applied AFTER the accurate-
		// zero rule (a landed 0 counts as 1) - repinned 2026-08-21 from
		// the old bound-shift model, which dropped that bump and ran
		// 0.5% low; the harness vector macuahuitl-bluemoon is now exact.
		int rawMax = result.getMaxHit() - 5;
		int firstRaw = rawMax / 2;
		int secondRaw = rawMax - firstRaw;
		double acc = result.getAccuracy();
		double perHitExpected = RollMath.expectedHitWithFlatArmour(acc, 0, firstRaw, -5)
			+ acc * RollMath.expectedHitWithFlatArmour(acc, 0, secondRaw, -5);
		Assert.assertEquals("each hitsplat carries its own +5",
			perHitExpected, result.getEh(), 1e-9);
	}

	@Test
	public void eclipseMoonChargesTheArmourOnBothHitsplats() {
		Monster mob = data().searchMonsters("eclipse moon", 1).get(0);
		int armour = mob.getDefensive().getFlatArmour();
		Assert.assertTrue("eclipse forms carry positive flat armour", armour > 0);
		Dps result = macuahuitlVs("eclipse moon");
		int rawMax = result.getMaxHit() + armour;
		int firstRaw = rawMax / 2;
		int secondRaw = rawMax - firstRaw;
		double acc = result.getAccuracy();
		// Per-roll clamp, NOT a bound shift (official-calc verified
		// 2026-08-21: the shifted model overpriced Eclipse ~16% - the
		// noxhalberd-eclipsemoon harness vector now matches to 0.00%).
		double perHitExpected = RollMath.expectedHitWithFlatArmour(acc, 0, firstRaw, armour)
			+ acc * RollMath.expectedHitWithFlatArmour(acc, 0, secondRaw, armour);
		Assert.assertEquals("each hitsplat pays the armour on every roll",
			perHitExpected, result.getEh(), 1e-9);
	}
}

