package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field report (Andrew, 2026-10-26): "the plugin is completely disregarding
 * keris partisan on kephri". Two keris effects the official calc models
 * (PlayerVsNPCCalc.ts) were missing: every keris has a 1/51 chance of a
 * triple hit against kalphites, and inside the Tombs the keris partisan of
 * the sun rolls accuracy x5/4 while the target is below 25% hitpoints.
 */
class KerisProcTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static Monster mob(String name, String version) {
		return data.getMonsters().stream()
			.filter(m -> m.getName().equalsIgnoreCase(name) && (version.isEmpty() || m.getVersion().equalsIgnoreCase(version)))
			.findFirst().orElseThrow(AssertionError::new);
	}

	private static Dps wielding(String weapon, Monster mob) {
		Gear item = data.getGearItems().stream()
			.filter(g -> g.getLname().equals(weapon) && g.isStandardGear())
			.findFirst().orElseThrow(AssertionError::new);
		EnumMap<Slot, Gear> gear = new EnumMap<>(Slot.class);
		gear.put(Slot.WEAPON, item);
		Req request = new Req(mob, Style.MELEE, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED, new Prayers(true, true, true, true, true)),
			null, 0, CandidateMode.ALL_STANDARD, true, false,
			Owned.EMPTY, RequirementProfile.MAXED, 1);
		Dps result = new Calc().calculate(request, new Kit(gear));
		assertNotNull(result);
		return result;
	}

	private static double plain(Dps r) {
		return RollMath.eh(r.getAccuracy(), 0, r.getMaxHit());
	}

	@Test
	@DisplayName("a keris triples one hit in 51 against a kalphite - the expected hit is 53/51 of a plain one")
	void kerisTriplesAgainstKalphites() {
		Dps kephri = wielding("keris partisan", mob("Kephri", "Shielded"));
		assertEquals(plain(kephri) * 53 / 51, kephri.getEh(), 1e-9);
		Dps queen = wielding("keris partisan", mob("Kalphite Queen", ""));
		assertEquals(plain(queen) * 53 / 51, queen.getEh(), 1e-9);
	}

	@Test
	@DisplayName("no triple hit against a mob that is not a kalphite")
	void noTripleOffKalphites() {
		Dps goblin = wielding("keris partisan", mob("Goblin", ""));
		assertEquals(plain(goblin), goblin.getEh(), 1e-9);
	}

	@Test
	@DisplayName("the sun keris inside the Tombs: the last quarter of the hitpoints at x5/4 accuracy, and the triple hit")
	void sunKerisInsideToa() {
		Dps r = wielding("keris partisan of the sun", mob("Kephri", "Shielded"));
		double boosted = RollMath.eh(RollMath.normalAccuracy(r.getAr() * 5 / 4, r.getDr()),
			0, r.getMaxHit());
		double timed = 1 / (0.75 / plain(r) + 0.25 / boosted);
		assertTrue(boosted > plain(r), "the boost raises the hit chance");
		assertEquals(timed * 53 / 51, r.getEh(), 1e-9);
	}

	@Test
	@DisplayName("the sun keris outside the Tombs has no accuracy boost")
	void sunKerisOutsideToa() {
		Dps goblin = wielding("keris partisan of the sun", mob("Goblin", ""));
		assertEquals(plain(goblin), goblin.getEh(), 1e-9);
	}
}

package com.ll.engine;

import java.util.List;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Kill time (ISS-01M6415DTE84ZZ45C4YD3MZRBJ, Andrew 2026-10-29: "make the
 * time to kill as low as possible"; "P50 is what is displayed, the other
 * stuff is shown when hovered"; "it should be the statistical P90"; "90% of
 * runs fall between"): the expected time, and the table behind the card's
 * P05, median, P95 and Perfect.
 */
class KillTimeTest {
	@Test
	@DisplayName("the expected kill time is hp over net DPS: the heal comes off, the sustained spec goes on, nothing left reads never")
	void expected() {
		assertEquals(100, Kill.of(500, 5, 0, 0), 1e-9);
		assertEquals(125, Kill.of(500, 5, 1, 0), 1e-9);
		assertEquals(100, Kill.of(500, 4, 1, 2), 1e-9);
		assertTrue(Double.isInfinite(Kill.of(500, 1, 1, 0)));
		assertTrue(Double.isInfinite(Kill.of(500, 0, 0, 0)));
	}

	@Test
	@DisplayName("Perfect is every attack at its max and no heal: 500 hp, max 40, 4 ticks = 13 attacks = 31.2 s")
	void perfect() {
		Kill t = Kill.table(500, 0.7, 40, 4, 0.7 * 20 / 2.4, 0, 0);
		assertEquals(31.2, t.perfect, 1e-9);
		assertFalse(t.approximate);
	}

	@Test
	@DisplayName("the median sits within 3% of hp over net DPS on a uniform 0.7-accuracy case, P05 <= P50 <= P95 with P95 the slower end, and a heal stretches all three")
	void percentiles() {
		double dps = 0.7 * 20 / 2.4;
		Kill t = Kill.table(500, 0.7, 40, 4, dps, 0, 0);
		double expected = 500 / dps;
		assertEquals(expected, t.p50, expected * 0.03);
		assertTrue(t.p05 <= t.p50 && t.p50 <= t.p95, t.p05 + " " + t.p50 + " " + t.p95);
		assertTrue(t.p05 < t.p95, "a real band");
		assertTrue(t.perfect < t.p05, "nobody beats perfect");
		Kill healed = Kill.table(500, 0.7, 40, 4, dps, 1.5, 0);
		assertTrue(healed.p05 > t.p05 && healed.p50 > t.p50 && healed.p95 > t.p95);
		assertEquals(500 / (dps - 1.5), healed.p50, 500 / (dps - 1.5) * 0.03);
		assertEquals(t.perfect, healed.perfect, 1e-9, "Perfect never lets the boss heal");
	}

	@Test
	@DisplayName("the percentiles are statistical: 5% and 95% of the table's kill mass lie at or before them")
	void statistical() {
		Kill t = Kill.table(500, 0.7, 40, 4, 0.7 * 20 / 2.4, 0, 0);
		double before05 = 0, before95 = 0, at05 = 0, at95 = 0;
		for (int tick = 0; tick < t.pmf.length; tick++) {
			double s = tick * Kill.TICK;
			if (s < t.p05) before05 += t.pmf[tick];
			if (s <= t.p05) at05 += t.pmf[tick];
			if (s < t.p95) before95 += t.pmf[tick];
			if (s <= t.p95) at95 += t.pmf[tick];
		}
		assertTrue(before05 < 0.05 && at05 >= 0.05, before05 + " " + at05);
		assertTrue(before95 < 0.95 && at95 >= 0.95, before95 + " " + at95);
	}

	@Test
	@DisplayName("a set that cannot outpace the heal reads never on every percentile, Perfect still finite")
	void never() {
		Kill t = Kill.table(500, 0.7, 40, 4, 1, 2, 0);
		assertTrue(Double.isInfinite(t.p50) && Double.isInfinite(t.p05) && Double.isInfinite(t.p95));
		assertEquals(31.2, t.perfect, 1e-9);
	}

	@Test
	@DisplayName("without a distribution, a hit model that is not one uniform roll is scaled to its mean and flagged approximate")
	void approximate() {
		double uniform = 0.7 * 20 / 2.4;
		Kill exact = Kill.table(500, 0.7, 40, 4, uniform, 0, 0);
		Kill scythe = Kill.table(500, 0.7, 40, 4, uniform * 1.6, 0, 0);
		assertTrue(scythe.approximate);
		assertFalse(exact.approximate);
		assertEquals(500 / (uniform * 1.6), scythe.p50, 500 / (uniform * 1.6) * 0.03);
	}

	@Test
	@DisplayName("with the set's own distribution the table is exact: a scythe's three rolls kill in a tighter band than one paced uniform roll of the same mean, Perfect at the three maxes")
	void distribution() {
		double[] one = Dist.armoured(0.7, 0, 40, 0);
		double[] scythe = Dist.plus(Dist.plus(one, Dist.armoured(0.7, 0, 20, 0)), Dist.armoured(0.7, 0, 10, 0));
		double dps = Dist.mean(scythe) / 3.0;
		Kill exact = Kill.table(500, scythe, 3.0, dps, 0, 0, false);
		Kill paced = Kill.table(500, 0.7, 40, 5, dps, 0, 0);
		assertFalse(exact.approximate);
		assertTrue(paced.approximate);
		// The median lands on an attack boundary (3 s apart) and a kill
		// overshoots the hp by part of a hit, so it sits within one attack
		// above the mean.
		assertTrue(exact.p50 >= 500 / dps - 1e-9 && exact.p50 <= 500 / dps + 3.0, exact.p50 + " vs " + 500 / dps);
		assertEquals(Math.ceil(500 / 70.0) * 3.0, exact.perfect, 1e-9);
		assertTrue(exact.p95 - exact.p05 < paced.p95 - paced.p05, exact.p05 + ".." + exact.p95 + " vs " + paced.p05 + ".." + paced.p95);
	}

	@Test
	@DisplayName("a fixed delay adds to every percentile and Perfect, a trip of delayed members carries it, and no delay is the same table")
	void delayed() {
		double dps = 0.7 * 20 / 2.4;
		Kill a = Kill.table(500, 0.7, 40, 4, dps, 0, 0);
		Kill late = a.delayed(6);
		assertEquals(a.p05 + 6, late.p05, 1e-9);
		assertEquals(a.p50 + 6, late.p50, 1e-9);
		assertEquals(a.p95 + 6, late.p95, 1e-9);
		assertEquals(a.perfect + 6, late.perfect, 1e-9);
		assertEquals(a.uptime, late.uptime, 1e-9);
		assertSame(a, a.delayed(0));
		Kill b = Kill.table(300, 0.7, 40, 4, dps, 0, 0);
		Kill trip = Kill.sum(List.of(late, b.delayed(18)));
		Kill plain = Kill.sum(List.of(a, b));
		assertEquals(plain.perfect + 24, trip.perfect, 1e-9);
		assertEquals(plain.p50 + 24, trip.p50, 0.61);
	}

	@Test
	@DisplayName("a boss hittable half the fight takes twice as long on every percentile and on Perfect, a trip of such members stretches with them, and a full-uptime boss is untouched")
	void stretched() {
		double dps = 0.7 * 20 / 2.4;
		Kill a = Kill.table(500, 0.7, 40, 4, dps, 0, 0);
		Kill half = a.stretched(0.5);
		assertEquals(0.5, half.uptime, 1e-9);
		assertEquals(a.p05 * 2, half.p05, 1e-9);
		assertEquals(a.p50 * 2, half.p50, 1e-9);
		assertEquals(a.p95 * 2, half.p95, 1e-9);
		assertEquals(a.perfect * 2, half.perfect, 1e-9);
		assertSame(a, a.stretched(1));
		Kill trip = Kill.sum(List.of(half, Kill.table(300, 0.7, 40, 4, dps, 0, 0).stretched(0.5)));
		Kill plain = Kill.sum(List.of(a, Kill.table(300, 0.7, 40, 4, dps, 0, 0)));
		assertEquals(plain.perfect * 2, trip.perfect, 1e-9);
		assertEquals(plain.p50 * 2, trip.p50, plain.p50 * 0.05);
	}

	@Test
	@DisplayName("a trip is the members' tables convolved: median near the sum of their means, Perfect the sum of theirs, never when one member never dies")
	void trip() {
		double dps = 0.7 * 20 / 2.4;
		Kill a = Kill.table(500, 0.7, 40, 4, dps, 0, 0);
		Kill b = Kill.table(300, 0.7, 40, 4, dps, 0, 0);
		Kill c = Kill.table(400, 0.7, 40, 4, dps, 0, 0);
		Kill trip = Kill.sum(List.of(a, b, c));
		double mean = 1200 / dps;
		assertEquals(mean, trip.p50, mean * 0.03);
		assertEquals(a.perfect + b.perfect + c.perfect, trip.perfect, 1e-9);
		assertTrue(trip.p05 >= a.p05 + b.p05 + c.p05, "the sum's P05 is above the sum of P05s");
		assertTrue(trip.p95 <= a.p95 + b.p95 + c.p95, "and its P95 below the sum of P95s");
		Kill never = Kill.sum(List.of(a, Kill.table(500, 0.7, 40, 4, 1, 2, 0)));
		assertTrue(Double.isInfinite(never.p50));
	}
}

