		Assert.assertEquals("proselyte carries no strength",
			0, proselyte.getBonuses().getStrength());
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1);
		owned.put(29045, 1);
		owned.put(9678, 1);
		Req request = TestRequests.of(
			monster, Style.MELEE, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false, new Owned(owned, true), 10);

