import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Pinned items: user preference wins the slot (bracelet of slaughter
 * class - value the model cannot price), the optimizer builds the best
 * set AROUND the pin. Optimizer-level by mandate: these run the real
 * search, the same path the panel renders.
 */
class PinTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static Req ranged(CandidateMode mode, Owned owned) {
		return new Req(
			data.searchMonsters("goblin", 1).get(0), Style.RANGED,
			Levels.MAXED, PrayerBonuses.bestAvailable(Levels.MAXED), null, 0,
			mode, true, false, owned, RequirementProfile.MAXED, 1);
	}

	@Test
	@DisplayName("a pinned bracelet of slaughter holds the hands slot against better dps gloves")
	void pinnedSlaughterBraceletWins() {
		Owned owned = new Owned(
			Map.of(861, 1, 21326, 100, 7462, 1, 21183, 1), true);
		List<Dps> results = new LoadoutOptimizer().optimize(data,
			ranged(CandidateMode.OWNED_ONLY, owned)
				.withPinnedItems(Map.of(Slot.HANDS, 21183)));
		assertFalse(results.isEmpty());
		Gear hands = results.get(0).getLoadout().get(Slot.HANDS);
		assertNotNull(hands);
		assertEquals("bracelet of slaughter", hands.getLname(),
			"got: " + hands.getLname());
	}

	@Test
	@DisplayName("an UNOWNED pin still rides in owned-only mode - 'I am bringing this'")
	void unownedPinAppears() {
		Owned owned = new Owned(Map.of(861, 1, 21326, 100), true);
		List<Dps> results = new LoadoutOptimizer().optimize(data,
			ranged(CandidateMode.OWNED_ONLY, owned)
				.withPinnedItems(Map.of(Slot.HANDS, 21183)));
		assertFalse(results.isEmpty());
		Gear hands = results.get(0).getLoadout().get(Slot.HANDS);
		assertNotNull(hands);
		assertEquals("bracelet of slaughter", hands.getLname());
	}

	@Test
	@DisplayName("a pinned salve rides a low-risk set - the never-risk veto yields to the pin")
	void pinnedSalveSurvivesLowRisk() {
		MonsterStatsHolder rev = new MonsterStatsHolder();
		rev.monster = data.searchMonsters("revenant demon", 1).get(0);
		Gear salve = null;
		for (Gear item : data.getGearItems()) {
			if (item.getLname().equals("salve amulet(ei)")) {
				salve = item;
			}
		}
		assertNotNull(salve);

		Req constrained = new Req(
			rev.monster, Style.RANGED, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, Owned.EMPTY,
			RequirementProfile.MAXED, 1)
			.withMaxTr(3).withRiskBudgetGp(25_000)
			.withPinnedItems(Map.of(Slot.NECK, salve.getId()));

		List<Dps> results = new LoadoutOptimizer().optimize(data, constrained);
		assertFalse(results.isEmpty());
		Gear neck = results.get(0).getLoadout().get(Slot.NECK);
		assertNotNull(neck);
		assertEquals("salve amulet(ei)", neck.getLname(),
			"the pin must override the rebuild veto and the cap, got: " + neck.getLname());
	}

	@Test
	@DisplayName("a pinned weapon locks the weapon line")
	void pinnedWeaponForced() {
		List<Dps> results = new LoadoutOptimizer().optimize(data,
			ranged(CandidateMode.ALL_STANDARD, Owned.EMPTY)
				.withPinnedItems(Map.of(Slot.WEAPON, 861)));
		assertFalse(results.isEmpty());
		Gear weapon = results.get(0).getLoadout().get(Slot.WEAPON);
		assertEquals("magic shortbow", weapon.getLname(),
			"got: " + weapon.getLname());
	}

	private static final class MonsterStatsHolder {
		com.ll.data.Monster monster;
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.data.Spell;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

/**
 * A pinned spell must only ride weapons that can actually cast it
 * (field report 2026-08-09: Blood Barrage pinned on Thermy, but the
 * recommended weapon was a Trident - a powered staff that can only
 * fire its own built-in). The auto-spell path already enforces
 * autocast legality per weapon; the fixed-spell path skipped it.
 */
public class PinnedSpellLegalityTest {
	private static Tables data;

	private static Tables data() {
		if (data == null) {
			data = new DataService().load();
		}
		return data;
	}

	private static Spell spell(String name) {
		return data().getSpells().stream()
			.filter(s -> s.getName().equalsIgnoreCase(name))
			.findFirst().orElseThrow(AssertionError::new);
	}

	private static void own(Map<Integer, Integer> owned, String lname) {
		Gear item = data().getGearItems().stream()
			.filter(g -> g.getLname().equals(lname) && g.isStandardGear())
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing: " + lname));
		owned.put(item.getId(), 1);
	}

	private static Req ownedMagicRequest(Monster mob, Map<Integer, Integer> owned) {
		return new Req(
			mob, Style.MAGIC, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false,
			new Owned(owned, true), RequirementProfile.MAXED, 1);
	}

	@Test
	public void aPinnedBarrageNeverRidesAPoweredStaff() {
		Monster thermy = data().searchMonsters("thermonuclear smoke devil", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		own(owned, "trident of the seas");
		own(owned, "ancient staff");

		List<Dps> results = new LoadoutOptimizer().optimize(data(),
			ownedMagicRequest(thermy, owned).withSpell(spell("Blood Barrage")));
		Assert.assertFalse("an ancient staff is owned - the pin must field it", results.isEmpty());
		String weapon = results.get(0).getLoadout().get(Slot.WEAPON).labelLower();
		Assert.assertFalse("a powered staff cannot cast a pinned spell: " + weapon,
			weapon.contains("trident"));
		Assert.assertTrue("the ancient-capable staff carries the pin: " + weapon,
			weapon.contains("ancient staff"));
	}

	@Test
	public void noAutocastCapableWeaponMeansNoResultNotAnIllegalPair() {
		Monster thermy = data().searchMonsters("thermonuclear smoke devil", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		own(owned, "trident of the seas");
		// Harmonised autocasts the standard book only - it must not
		// carry an ancient pin either.
		own(owned, "harmonised nightmare staff");

		List<Dps> results = new LoadoutOptimizer().optimize(data(),
			ownedMagicRequest(thermy, owned).withSpell(spell("Blood Barrage")));
		Assert.assertTrue("no owned weapon can autocast the pin - honest empty beats an illegal pair",
			results.isEmpty());
	}

	@Test
	public void aStandardPinStillPricesNormally() {
		Monster thermy = data().searchMonsters("thermonuclear smoke devil", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		own(owned, "kodai wand");

		List<Dps> results = new LoadoutOptimizer().optimize(data(),
			ownedMagicRequest(thermy, owned).withSpell(spell("Fire Surge")));
		Assert.assertFalse(results.isEmpty());
		Assert.assertTrue(results.get(0).getMaxHit() > 0);
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Poison tiers stat-tie but are not equal in game (field request: always
 * recommend dragon dagger p++ over plain). Optimizer-level: the real
 * search must pick the p++ when tiers tie.
 */
class PoisonTierTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	@Test
	@DisplayName("poison tiers parse from corpus versions, unpoisoned included")
	void tiersParse() {
		int[] tiers = new int[4];
		for (Gear item : data.getGearItems()) {
			if (item.getLname().equals("dragon dagger")) {
				tiers[item.poisonTier()]++;
			}
		}
		assertArrayEquals(new int[]{1, 1, 1, 1}, tiers,
			"expected exactly one dagger per tier 0..3");
	}

	@Test
	@DisplayName("owning every dagger tier, the search recommends the p++")
	void ownedDaggersPickThePlusPlus() {
		// 1215 unpoisoned, 1231 p, 5680 p+, 5698 p++.
		Owned owned = new Owned(
			Map.of(1215, 1, 1231, 1, 5680, 1, 5698, 1), true);
		Req request = new Req(
			data.searchMonsters("goblin", 1).get(0), Style.MELEE,
			Levels.MAXED, PrayerBonuses.bestAvailable(Levels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false, owned, RequirementProfile.MAXED, 1);

		List<Dps> results = new LoadoutOptimizer().optimize(data, request);
		assertFalse(results.isEmpty());
		Gear weapon = results.get(0).getLoadout().get(Slot.WEAPON);
		assertEquals("dragon dagger", weapon.getLname());
		assertEquals(3, weapon.poisonTier(),
			"expected the p++ tier, got version: " + weapon.getVer());
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Monster;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static com.ll.engine.Style.*;
import static org.junit.jupiter.api.Assertions.*;

/**
 * The style's prayer raises Defence in the damage-taken model
 * (ISS-01M6415DFFW34P8QY468GA74KY, Andrew 2026-10-29: "Tabs + defence fix").
 * The offensive prayers run beside the overheads in game; the factors are
 * osrs-dps-calc's Prayer.ts (factorDefence, factorDefenceMagic) and the
 * wiki's Zeal page.
 */
class PrayerDefenceTest {
	private static void levels(Style style, String prayer, int defence, int magic) {
		assertArrayEquals(new int[]{defence, magic}, PrayerBonuses.defending(style, prayer, 99, 99), style + " " + prayer);
	}

	private static Req request(Monster mob, Style style) {
		return new Req(mob, style, Levels.MAXED, PrayerBonuses.bestAvailable(Levels.MAXED),
			null, 0, CandidateMode.ALL_STANDARD, false, false, Owned.EMPTY, RequirementProfile.MAXED, 10);
	}

	@Test
	@DisplayName("each prayer raises Defence and Magic by its own factor, floored; no prayer leaves both alone")
	void factors() {
		levels(MELEE, "Zeal", 123, 99);
		levels(MELEE, "Piety", 123, 99);
		levels(MELEE, "Chivalry", 118, 99);
		levels(MELEE, "Ultimate Strength + Incredible Reflexes", 99, 99);
		levels(RANGED, "Rigour", 123, 99);
		levels(RANGED, "Deadeye", 103, 99);
		levels(RANGED, "Eagle Eye", 99, 99);
		levels(MAGIC, "Augury", 123, 123);
		levels(MAGIC, "Mystic Vigour", 103, 116);
		levels(MAGIC, "Mystic Might", 99, 113);
		levels(MAGIC, "Mystic Lore", 99, 108);
		levels(MAGIC, "Mystic Will", 99, 103);
		levels(MELEE, "", 99, 99);
		levels(MELEE, null, 99, 99);
		levels(MELEE, "Not a prayer", 99, 99);
		assertArrayEquals(new int[]{50, 1}, PrayerBonuses.defending(MAGIC, "Augury", 40, 1), "low levels floor too");
	}

	@Test
	@DisplayName("the defense-weighted beam builds its constants at the levels the request's prayer gives")
	void beamUsesThePrayer() {
		Monster moon = new DataService().load().searchMonsters("blood moon", 1).get(0);
		Req melee = request(moon, MELEE);
		assertEquals("Zeal", melee.prayers.nameFor(MELEE), "maxed with every unlock");
		assertEquals(123, Incoming.Prepared.of(melee).defenceLevel, "Zeal: +25% Defence");
		assertEquals(99, Incoming.Prepared.of(melee.withPrayers(PrayerBonuses.NONE)).defenceLevel, "prayerless");
		Incoming.Prepared magic = Incoming.Prepared.of(request(moon, MAGIC));
		assertEquals(123, magic.defenceLevel, "Augury: +25% Defence");
		assertEquals(Incoming.magicEffectiveLevel(123, 123), magic.magicEffective, "and +25% Magic");
	}
}

package com.ll.engine;

import org.junit.Assert;
import org.junit.Test;

/**
 * The assume-chip prayer picker (field direction 2026-07-21: "I don't use
 * Piety against every mob"): named tiers per style whose factors mirror
 * bestAvailable's cascade exactly.
 */
public class PrayerPickTest {
	@Test
	public void picksReplaceOnlyTheChosenStylesFactors() {
		PrayerBonuses best = PrayerBonuses.bestAvailable(Levels.MAXED);
		PrayerBonuses chivalry = PrayerBonuses.forPick(Style.MELEE, "Chivalry", best);
		Assert.assertEquals(1.15, chivalry.getMeleeAccuracy(), 1e-9);
		Assert.assertEquals(1.18, chivalry.getMeleeStrength(), 1e-9);
		Assert.assertEquals("Chivalry", chivalry.nameFor(Style.MELEE));
		Assert.assertEquals("the other styles keep the fallback",
			best.getRangedAccuracy(), chivalry.getRangedAccuracy(), 1e-9);

		PrayerBonuses eagle = PrayerBonuses.forPick(Style.RANGED, "Eagle Eye", best);
		Assert.assertEquals(1.15, eagle.getRangedAccuracy(), 1e-9);
		Assert.assertEquals(1.15, eagle.getRangedStrength(), 1e-9);

		PrayerBonuses might = PrayerBonuses.forPick(Style.MAGIC, "Mystic Might", best);
		Assert.assertEquals(1.15, might.getMagicAccuracy(), 1e-9);
		Assert.assertEquals(2.0, might.getMagicDamagePercent(), 1e-9);

		// The lower melee combo tiers (field ask 2026-07-21): 1.10/1.10
		// and 1.05/1.05, mirroring bestAvailable's cascade exactly.
		PrayerBonuses mid = PrayerBonuses.forPick(Style.MELEE,
			"Superhuman Strength + Improved Reflexes", best);
		Assert.assertEquals(1.10, mid.getMeleeAccuracy(), 1e-9);
		Assert.assertEquals(1.10, mid.getMeleeStrength(), 1e-9);
		PrayerBonuses low = PrayerBonuses.forPick(Style.MELEE,
			"Burst of Strength + Clarity of Thought", best);
		Assert.assertEquals(1.05, low.getMeleeAccuracy(), 1e-9);
		Assert.assertEquals(1.05, low.getMeleeStrength(), 1e-9);

		// The lower ranged/magic tiers (field ask 2026-07-21 part 2),
		// mirroring the cascade: Hawk/Sharp Eye, Mystic Lore/Will.
		Assert.assertEquals(1.10, PrayerBonuses.forPick(Style.RANGED,
			"Hawk Eye", best).getRangedAccuracy(), 1e-9);
		Assert.assertEquals(1.05, PrayerBonuses.forPick(Style.RANGED,
			"Sharp Eye", best).getRangedStrength(), 1e-9);
		PrayerBonuses lore = PrayerBonuses.forPick(Style.MAGIC, "Mystic Lore", best);
		Assert.assertEquals(1.10, lore.getMagicAccuracy(), 1e-9);
		Assert.assertEquals(1.0, lore.getMagicDamagePercent(), 1e-9);
		PrayerBonuses will = PrayerBonuses.forPick(Style.MAGIC, "Mystic Will", best);
		Assert.assertEquals(1.05, will.getMagicAccuracy(), 1e-9);
		Assert.assertEquals(0.0, will.getMagicDamagePercent(), 1e-9);
	}

	@Test
	public void unknownPicksFallBackToDetect() {
		PrayerBonuses best = PrayerBonuses.bestAvailable(Levels.MAXED);
		Assert.assertSame(best, PrayerBonuses.forPick(Style.MELEE, "Retribution", best));
	}

	@Test
	public void everyStyleOffersItsNamedTiers() {
		Assert.assertEquals("Zeal", PrayerBonuses.optionsFor(Style.MELEE)[0]);
		Assert.assertEquals("Rigour", PrayerBonuses.optionsFor(Style.RANGED)[0]);
		Assert.assertEquals("Augury", PrayerBonuses.optionsFor(Style.MAGIC)[0]);
	}

	@Test
	public void boostMembershipDrivesTheStyleMenus() {
		Assert.assertTrue(BoostProfile.SMELLING_SALTS.boosts('a'));
		Assert.assertTrue(BoostProfile.SMELLING_SALTS.boosts('m'));
		Assert.assertTrue(BoostProfile.SUPER_COMBAT.boosts('a'));
		Assert.assertFalse(BoostProfile.SUPER_COMBAT.boosts('r'));
		Assert.assertTrue(BoostProfile.RANGING.boosts('r'));
		Assert.assertFalse(BoostProfile.RANGING.boosts('m'));
	}
}

package com.ll.engine;

import org.junit.Assert;
import org.junit.Test;

public class PrayerUnlocksTest {
	@Test
	public void lockedPrayersFallBackToTheBestUnlockedTier() {
		Levels maxed = Levels.MAXED;

		// No King's Ransom: no Piety - falls to Ultimate Strength tier.
		PrayerBonuses noKr = PrayerBonuses.bestAvailable(maxed,
			new Prayers(false, true, true, true, true));
		Assert.assertEquals(1.15, noKr.getMeleeAccuracy(), 1e-9);
		Assert.assertEquals(1.15, noKr.getMeleeStrength(), 1e-9);

		// No Rigour scroll but Deadeye unlocked: 18/18.
		PrayerBonuses noRigour = PrayerBonuses.bestAvailable(maxed,
			new Prayers(true, false, true, true, true));
		Assert.assertEquals(1.18, noRigour.getRangedAccuracy(), 1e-9);
		Assert.assertEquals(1.18, noRigour.getRangedStrength(), 1e-9);

		// Neither Rigour nor Deadeye: Eagle Eye tier.
		PrayerBonuses eagleEye = PrayerBonuses.bestAvailable(maxed,
			new Prayers(true, false, true, false, true));
		Assert.assertEquals(1.15, eagleEye.getRangedAccuracy(), 1e-9);

		// No Augury but Mystic Vigour: 1.18 accuracy, 3% damage.
		PrayerBonuses noAugury = PrayerBonuses.bestAvailable(maxed,
			new Prayers(true, true, false, true, true));
		Assert.assertEquals(1.18, noAugury.getMagicAccuracy(), 1e-9);
		Assert.assertEquals(3.0, noAugury.getMagicDamagePercent(), 1e-9);

		// Everything unlocked: Augury WINS over Mystic Vigour, it never
		// stacks with it - all magic prayers share one prayer group, so
		// only one can be active (the wiki calc engine happily stacks
		// illegal combos; the game does not).
		PrayerBonuses all = PrayerBonuses.bestAvailable(maxed, Prayers.ALL);
		// Zeal since 2026-10-20 (the Fractured Archive): ALL unl it.
		Assert.assertEquals(1.25, all.getMeleeAccuracy(), 1e-9);
		Assert.assertEquals(1.25, all.getMagicAccuracy(), 1e-9);
		Assert.assertEquals(4.0, all.getMagicDamagePercent(), 1e-9);
		Assert.assertEquals("Augury", all.nameFor(Style.MAGIC));
	}
}

package com.ll.engine;

import com.ll.data.SpellRunes;
import java.util.HashMap;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field report 2026-08-27 (Not on Hand's F2P test account): the plugin
 * recommended Death Charge - members, Magic 90, A Kingdom Divided, a
 * blood + death + soul rune per cast - and autocast spells whose runes the
 * bank does not hold.
 *
 * <p>The gate checks only the premium combat runes (blood, soul, death,
 * wrath). Elemental and mind/chaos-class runes are deliberately ungated -
 * any shop sells them, and requiring every air rune in the bank would be
 * noise, not honesty.
 */
class PremiumRuneGateTest {
	private static final int BLOOD = 565;
	private static final int DEATH = 560;
	private static final int SOUL = 566;
	private static final int WRATH = 21880;

	private static Owned bank(int... ids) {
		Map<Integer, Integer> owned = new HashMap<>();
		for (int id : ids) {
			owned.put(id, 1000);
		}
		return new Owned(owned, true);
	}

	@Test
	@DisplayName("a runeless bank blocks blood, death, soul and wrath spells")
	void runelessBankBlocksPremiumSpells() {
		Owned empty = bank();
		assertFalse(SpellRunes.premiumRunesOwned("Fire Wave", empty), "Fire Wave costs a blood rune");
		assertFalse(SpellRunes.premiumRunesOwned("Ice Barrage", empty), "Ice Barrage costs blood + death");
		assertFalse(SpellRunes.premiumRunesOwned("Fire Surge", empty), "Fire Surge costs a wrath rune");
		assertFalse(SpellRunes.premiumRunesOwned("Death Charge", empty), "Death Charge costs blood + death + soul");
	}

	@Test
	@DisplayName("cheap-rune spells always pass - shops sell their runes")
	void cheapSpellsAlwaysPass() {
		Owned empty = bank();
		assertTrue(SpellRunes.premiumRunesOwned("Fire Strike", empty));
		assertTrue(SpellRunes.premiumRunesOwned("Fire Bolt", empty));
	}

	@Test
	@DisplayName("owning exactly the needed premium runes unlocks the spell")
	void owningTheRunesUnlocks() {
		assertTrue(SpellRunes.premiumRunesOwned("Fire Wave", bank(BLOOD)));
		assertFalse(SpellRunes.premiumRunesOwned("Ice Barrage", bank(BLOOD)),
			"Ice Barrage also needs death runes");
		assertTrue(SpellRunes.premiumRunesOwned("Ice Barrage", bank(BLOOD, DEATH)));
		assertTrue(SpellRunes.premiumRunesOwned("Fire Surge", bank(WRATH)));
		assertTrue(SpellRunes.premiumRunesOwned("Death Charge", bank(BLOOD, DEATH, SOUL)));
	}

	@Test
	@DisplayName("unknown spells and a null bank fail open")
	void failsOpen() {
		assertTrue(SpellRunes.premiumRunesOwned("Some Future Spell", bank()));
		assertTrue(SpellRunes.premiumRunesOwned("Fire Wave", null));
		assertTrue(SpellRunes.premiumRunesOwned(null, bank()));
	}
}

package com.ll.engine;

import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Stats;
import java.util.HashMap;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class PvpRiskTest {
	/** The retired risksRebuild() overloads: the friction-only case
	 * of risksUnprotected(), i.e. no protect-only flags. They had no
	 * production callers, so they live here as delegates instead. */
	private static boolean risksRebuild(Kit loadout, Gear cspec, int ks) {
		return risksRebuild(loadout, cspec, ks, java.util.Collections.emptySet());
	}

	private static boolean risksRebuild(Kit loadout, Gear cspec, int ks,
		java.util.Set<Integer> pinnedIds) {
		return PvpRisk.risksUnprotected(loadout, cspec, ks, pinnedIds,
			java.util.Collections.emptySet());
	}

	private static Gear item(int id, Slot slot, boolean tradeable, int price) {
		return new Gear(id, "Item" + id, "", slot, "", 0, false, true,
			tradeable, true, price, Stats.ZERO, Stats.ZERO, Stats.ZERO, null);
	}

	private static final Stats SOME_DEFENCE =
		new Stats(0, 0, 0, 0, 0, 0, 0, 0, 2);

	private static Gear untradeable(int id, String name, Slot slot, Stats bonuses) {
		return new Gear(id, name, "", slot, "", 0, false, true,
			false, true, null, Stats.ZERO, Stats.ZERO, bonuses, null);
	}

	private static Kit worn(Gear... items) {
		Map<Slot, Gear> gear = new HashMap<>();
		for (Gear g : items) {
			gear.put(g.getSlot(), g);
		}
		return new Kit(gear);
	}

	@Test
	public void tradeablesBeyondTheKeptSlotsAreTheRisk() {
		Kit loadout = worn(
			item(1, Slot.WEAPON, true, 100),
			item(2, Slot.BODY, true, 80),
			item(3, Slot.LEGS, true, 60),
			item(4, Slot.HEAD, true, 40),
			item(5, Slot.FEET, true, 20));
		PvpRisk.Assessment three = PvpRisk.assess(loadout, null, 3);
		Assert.assertEquals(60, three.riskGp);
		Assert.assertEquals(3, three.kept.size());
		Assert.assertEquals(2, three.lost.size());
		Assert.assertEquals(20, PvpRisk.assess(loadout, null, 4).riskGp);
	}

	@Test
	public void avariceSkullsTheWearerSoDefaultProtectionVanishes() {
		// The amulet of avarice keeps the wearer permanently skulled:
		// keep-3 becomes keep-0, keep-4 (Protect Item) becomes keep-1.
		Gear avarice = new Gear(9, "Amulet of avarice", "", Slot.NECK, "", 0,
			false, true, true, true, 500_000, Stats.ZERO, Stats.ZERO, Stats.ZERO, null);
		Kit loadout = worn(
			item(1, Slot.WEAPON, true, 100),
			item(2, Slot.BODY, true, 80),
			avarice);

		PvpRisk.Assessment skulled = PvpRisk.assess(loadout, null, 3);
		Assert.assertEquals(0, skulled.kept.size());
		Assert.assertEquals(100 + 80 + 500_000, skulled.riskGp);

		PvpRisk.Assessment protect = PvpRisk.assess(loadout, null, 4);
		Assert.assertEquals(1, protect.kept.size());
		Assert.assertEquals("the amulet itself is the most valuable piece",
			9, protect.kept.get(0).getId());
	}

	@Test
	public void costFreeBreakersChargeTheirRebuildFriction() {
		// Salve amulet(ei): gp cost 0 (free tomb re-obtain, imbue points
		// refunded) but the death still costs the rebuild errand - the
		// curated 150k friction charges into the risk total and the risk
		// cap, so it can never ride into a low-risk set as "safe".
		Kit loadout = worn(
			item(1, Slot.WEAPON, true, 100),
			untradeable(2, "salve amulet(ei)", Slot.NECK, SOME_DEFENCE));
		PvpRisk.Assessment fates = PvpRisk.assess(loadout, null, 3);
		Assert.assertEquals(1, fates.untradeableCharges.size());
		Assert.assertEquals(2, fates.untradeableCharges.get(0).item.getId());
		Assert.assertEquals(150_000, fates.untradeableCharges.get(0).costGp);
		Assert.assertEquals(150_000, fates.riskGp);
	}

	@Test
	public void risksRebuildFlagsUnprotectedFrictionItemsOnly() {
		// Salve: unprotectable in the model - always a risked rebuild.
		Kit salve = worn(
			item(1, Slot.WEAPON, true, 100),
			untradeable(2, "salve amulet(ei)", Slot.NECK, SOME_DEFENCE));
		Assert.assertTrue(risksRebuild(salve, null, 3));

		// Warrior ring (i) with cheap tradeables: it ranks into the kept
		// slots - protected, so no risked rebuild.
		Kit protectedRing = worn(
			item(1, Slot.WEAPON, true, 100),
			untradeable(3, "warrior ring (i)", Slot.RING, SOME_DEFENCE));
		Assert.assertFalse(risksRebuild(protectedRing, null, 3));

		// The same ring displaced from the kept slots by pricier gear IS
		// a risked rebuild.
		Kit displacedRing = worn(
			item(1, Slot.WEAPON, true, 100_000_000),
			item(2, Slot.BODY, true, 50_000_000),
			item(4, Slot.LEGS, true, 20_000_000),
			untradeable(3, "warrior ring (i)", Slot.RING, SOME_DEFENCE));
		Assert.assertTrue(risksRebuild(displacedRing, null, 3));

		// No friction anywhere: cheap early exit, never flagged.
		Kit plain = worn(item(1, Slot.WEAPON, true, 100));
		Assert.assertFalse(risksRebuild(plain, null, 3));
	}

	@Test
	public void imbuedConvertsCarryTheirReimbueFrictionInThePool() {
		// Warrior ring (i): the killer gets the 60k base ring and the
		// victim owes a re-imbue visit - loss price is 60k + 50k friction.
		Kit loadout = worn(
			untradeable(3, "warrior ring (i)", Slot.RING, SOME_DEFENCE));
		PvpRisk.Assessment fates = PvpRisk.assess(loadout, null, 0);
		Assert.assertEquals(110_000, fates.riskGp);
		Assert.assertEquals(110_000, fates.valueOf(
			loadout.get(Slot.RING)));
	}

	@Test
	public void untradeablesAreKeptOutsideTheSlotRanking() {
		Kit loadout = worn(
			item(1, Slot.WEAPON, true, 100),
			item(2, Slot.BODY, false, 999_999),
			item(3, Slot.LEGS, false, 999_999));
		PvpRisk.Assessment risk = PvpRisk.assess(loadout, null, 3);
		Assert.assertEquals(0, risk.riskGp);
		Assert.assertEquals(1, risk.kept.size());
	}

	@Test
	public void theCarriedSpecWeaponCompetesForKeptSlotsAndCanDisplaceCheaperGear() {
		Kit loadout = worn(
			item(1, Slot.WEAPON, true, 100),
			item(2, Slot.BODY, true, 80),
			item(3, Slot.LEGS, true, 60));
		// Without the spec weapon: everything kept.
		Assert.assertEquals(0, PvpRisk.assess(loadout, null, 3).riskGp);
		// A pricey carried spec weapon takes a kept slot; the 60 is lost.
		Gear spec = item(9, Slot.WEAPON, true, 500);
		PvpRisk.Assessment risk = PvpRisk.assess(loadout, spec, 3);
		Assert.assertEquals(60, risk.riskGp);
		Assert.assertEquals("Item9", risk.kept.get(0).getName());
	}

	@Test
	public void aTrouverClassUntradeableAddsTheFlat500kManglFeeToTheRisk() {
		Kit loadout = worn(
