package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.data.Spell;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Quest-boss engine fixes (ISS-01M5RVDTMR5XG16HM6G2JTF7FF, Andrew 2026-10-24:
 * "do the engine bugs"), each against the reference calculator or the wiki.
 */
class QuestBossEngineTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static Monster mob(String name) {
		return data.searchMonsters(name, 5).stream().filter(m -> m.getName().equalsIgnoreCase(name)).findFirst()
			.orElseThrow(() -> new AssertionError("corpus is missing " + name));
	}

	private static Req request(Monster mob, Style style) {
		return new Req(mob, style, Levels.MAXED, PrayerBonuses.bestAvailable(Levels.MAXED),
			null, 0, CandidateMode.ALL_STANDARD, true, false, Owned.EMPTY, RequirementProfile.MAXED, 1);
	}

	private static List<Dps> best(String name, Style style) {
		return new LoadoutOptimizer().optimize(data, request(mob(name), style));
	}

	private static String spellElement(Dps result) {
		Spell spell = data.getSpells().stream().filter(s -> s.getName().equals(result.getSpellName()))
			.findFirst().orElse(null);
		return spell == null ? "none" : spell.getElement();
	}

	private static String ammo(Dps result) {
		Gear ammo = result.getLoadout().get(Slot.AMMO);
		return ammo == null ? "" : ammo.getLname();
	}

	@Test
	@DisplayName("the Fragment of Seren takes at most 24 a hit in every style")
	void serenCap() {
		for (Style style : Style.concreteValues()) {
			Dps set = best("fragment of seren", style).get(0);
			assertTrue(set.getMaxHit() <= 24, style + " max " + set.getMaxHit());
		}
	}

	@Test
	@DisplayName("Fareed: magic casts a water spell, ranged fires arrows, and Tumeken's shadow cannot hurt him")
	void fareed() {
		assertEquals("water", spellElement(best("fareed", Style.MAGIC).get(0)));
		assertTrue(ammo(best("fareed", Style.RANGED).get(0)).contains("arrow"));
		Map<Slot, Gear> gear = new EnumMap<>(Slot.class);
		gear.put(Slot.WEAPON, data.getGearItems().stream().filter(g -> g.getLname().equals("tumeken's shadow"))
			.findFirst().get());
		assertNull(new Calc().calculate(request(mob("fareed"), Style.MAGIC), new Kit(gear)));
	}

	@Test
	@DisplayName("Kamil: the magic set casts a fire spell")
	void kamil() {
		assertEquals("fire", spellElement(best("kamil", Style.MAGIC).get(0)));
	}

	@Test
	@DisplayName("the Fire Warrior of Lesarkus has no melee or magic set; ranged fires ice arrows")
	void fireWarrior() {
		assertTrue(best("fire warrior of lesarkus", Style.MELEE).isEmpty());
		assertTrue(best("fire warrior of lesarkus", Style.MAGIC).isEmpty());
		assertEquals("ice arrows", ammo(best("fire warrior of lesarkus", Style.RANGED).get(0)));
	}

	@Test
	@DisplayName("zogres and Slash Bash: the ranged set wields the comp ogre bow with brutal arrows")
	void zogres() {
		for (String name : List.of("zogre", "slash bash")) {
			Dps set = best(name, Style.RANGED).get(0);
			assertEquals("comp ogre bow", set.getLoadout().getWeapon().getLname(), name);
			assertTrue(ammo(set).contains("brutal"), name + " ammo " + ammo(set));
		}
	}

	@Test
	@DisplayName("Slagilith: the melee set wields a pickaxe")
	void slagilith() {
		assertEquals("Pickaxe", best("slagilith", Style.MELEE).get(0).getLoadout().getWeapon().getCategory());
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.GearRequirements;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.data.RequiredGear;
import java.util.List;
import java.util.Set;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Quest-gate data fixes from the quest-boss audit (ISS-01M5RRTHQ3F1FCCJA30HQKMJ5R,
 * Andrew 2026-10-24: "Start with the zero-token data fixes (d'hide bodies,
 * dwarven helmet, light ballista, Dorgeshuun weapons, ice gloves for Flambeed
 * and Fareed)"). Every rule was checked against the item's OSRS Wiki page.
 */
class QuestGateDataTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	/** The row by name: the base item first, else a cosmetic variant (the
	 * trimmed bodies and crested shields are variants of their base). */
	private static Gear item(String name) {
		return data.getGearItems().stream()
			.filter(g -> g.getLname().equals(name))
			.min(java.util.Comparator.comparing(g -> data.isVariant(g.getId())))
			.orElseThrow(() -> new AssertionError("corpus is missing " + name));
	}

	private static RequirementProfile quests(String... done) {
		return new RequirementProfile(RequirementProfile.MAXED.getLevels(), Set.of(done));
	}

	@Test
	@DisplayName("without Dragon Slayer I the blue, red, black and Zamorak d'hide bodies are wearable; the green and gilded ones are not")
	void dhideBodies() {
		for (String name : List.of("blue d'hide body", "red d'hide body", "black d'hide body", "black d'hide body (t)",
			"zamorak d'hide body")) {
			assertTrue(quests().canEquip(item(name).getRequirements()), name + " needs no quest");
		}
		for (String name : List.of("green d'hide body", "green d'hide body (g)", "gilded d'hide body")) {
			assertFalse(quests().canEquip(item(name).getRequirements()), name + " still needs Dragon Slayer I");
			assertTrue(quests("DRAGON_SLAYER_I").canEquip(item(name).getRequirements()), name + " with the quest");
		}
	}

	@Test
	@DisplayName("the dwarven helmet needs Grim Tales, not Between a Rock...")
	void dwarvenHelmet() {
		GearRequirements helmet = item("dwarven helmet").getRequirements();
		assertEquals(Set.of("GRIM_TALES"), helmet.getQuests());
		assertFalse(quests("BETWEEN_A_ROCK").canEquip(helmet));
		assertTrue(quests("GRIM_TALES").canEquip(helmet));
	}

	@Test
	@DisplayName("the light ballista needs no quest; the heavy ballista still needs Monkey Madness II")
	void ballistas() {
		assertTrue(item("light ballista").getRequirements().getQuests().isEmpty());
		assertEquals(Set.of("MONKEY_MADNESS_II"), item("heavy ballista").getRequirements().getQuests());
	}

	@Test
	@DisplayName("the Dorgeshuun crossbow needs no quest; the Dorgeshuun-crest rune kiteshield still needs The Lost Tribe")
	void dorgeshuun() {
		assertTrue(item("dorgeshuun crossbow").getRequirements().getQuests().isEmpty());
		assertEquals(Set.of("THE_LOST_TRIBE"), item("rune kiteshield (dorgeshuun)").getRequirements().getQuests());
	}

	@Test
	@DisplayName("against Flambeed and Fareed the hands slot is ice gloves or smiths gloves (i), and the best melee set wears one")
	void iceGloves() {
		Set<Integer> gloves = Set.of(item("ice gloves").getId(), item("smiths gloves (i)").getId());
		for (String boss : List.of("flambeed", "fareed")) {
			Monster mob = data.searchMonsters(boss, 1).get(0);
			RequiredGear.Rule rule = RequiredGear.rulesFor(mob).stream().filter(r -> r.slot == Slot.HANDS)
				.findFirst().orElseThrow(() -> new AssertionError(boss + " has no hands rule"));
			assertEquals(gloves, rule.ids(data), boss + " names both gloves");
			Req request = new Req(mob, Style.MELEE, Levels.MAXED,
				PrayerBonuses.bestAvailable(Levels.MAXED), null, 0, CandidateMode.ALL_STANDARD, true, false,
				Owned.EMPTY, RequirementProfile.MAXED, 1);
			List<Dps> best = new LoadoutOptimizer().optimize(data, request);
			assertFalse(best.isEmpty(), boss + " has a melee set");
			Gear hands = best.get(0).getLoadout().get(Slot.HANDS);
			assertTrue(hands != null && gloves.contains(hands.getId()),
				boss + "'s melee set wears " + (hands == null ? "nothing" : hands.getName()));
		}
	}
}

