package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.MonsterGroups;
import com.ll.data.Monster;
import java.util.EnumMap;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/**
 * Royal Titans phase model (field report 2026-08-10: "even the noxious
 * halberd can't reach them in phase 1"; wiki-verified): the group
 * carries synthetic "(Out of reach)" forms per titan - melee-immune,
 * with the wiki's hidden +500% (6x) ranged accuracy that lasts while
 * they are out of melee distance. The near-phase base rows keep all
 * three styles; the roster kit must therefore seat a ranged answer.
 */
public class RoyalTitansTest {
	private static Tables data;

	private static Tables data() {
		if (data == null) {
			data = new DataService().load();
		}
		return data;
	}

	private static Monster farTitan(String name) {
		for (MonsterGroups.MonsterGroup group : MonsterGroups.load(data())) {
			if (!"Royal Titans".equals(group.getName())) {
				continue;
			}
			for (Monster mob : group.getMobs()) {
				if (mob.getName().toLowerCase().contains(name)
					&& mob.label().contains("Out of reach")) {
					return mob;
				}
			}
		}
		throw new AssertionError("no out-of-reach form for " + name);
	}

	@Test
	public void farFormsAreMeleeImmuneNearFormsAreNot() {
		Monster far = farTitan("branda");
		Assert.assertTrue(com.ll.engine.Immunity.styleImmune(far, Style.MELEE));
		Assert.assertFalse(com.ll.engine.Immunity.styleImmune(far, Style.RANGED));
		Monster near = data().searchMonsters("branda the fire queen", 1).get(0);
		Assert.assertFalse("the near-phase base row keeps melee",
			com.ll.engine.Immunity.styleImmune(near, Style.MELEE));
		Assert.assertTrue(com.ll.engine.Immunity.styleImmune(farTitan("eldric"), Style.MELEE));
	}

	@Test
	public void outOfReachGrantsSixTimesRangedAccuracyOnly() {
		Monster near = data().searchMonsters("branda the fire queen", 1).get(0);
		Monster far = farTitan("branda");
		EnumMap<Slot, Gear> gear = new EnumMap<>(Slot.class);
		for (Gear g : data().getGearItems()) {
			if (g.getLname().equals("twisted bow") && g.isStandardGear()) {
				gear.put(Slot.WEAPON, g);
			}
			if (g.getLname().equals("dragon arrow") && g.isStandardGear()) {
				gear.put(Slot.AMMO, g);
			}
		}
		Kit loadout = new Kit(gear);
		Dps atNear = calc(near, loadout);
		Dps atFar = calc(far, loadout);
		Assert.assertEquals("the multiplier is accuracy-only",
			atNear.getMaxHit(), atFar.getMaxHit());
		Assert.assertEquals("attack roll is exactly 6x while out of reach",
			atNear.getAr() * 6, atFar.getAr());
		Assert.assertTrue("6x must bite against +700 ranged defence",
			atFar.getAccuracy() > atNear.getAccuracy() * 2);
	}

	private static Dps calc(Monster mob, Kit loadout) {
		Req request = TestRequests.of(mob, Style.RANGED,
			Levels.MAXED, PrayerBonuses.bestAvailable(Levels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, Owned.EMPTY, 1);
		Dps result = new Calc().calculate(request, loadout);
		Assert.assertNotNull(result);
		return result;
	}

	@Test
	public void theGroupCarriesSixForms() {
		for (MonsterGroups.MonsterGroup group : MonsterGroups.load(data())) {
			if ("Royal Titans".equals(group.getName())) {
				Assert.assertEquals(6, group.getMobs().size());
				List<Monster> mobs = group.getMobs();
				long far = mobs.stream().filter(m -> m.label().contains("Out of reach")).count();
				Assert.assertEquals(2, far);
				return;
			}
		}
		throw new AssertionError("Royal Titans group missing");
	}
}

package com.ll.engine;

import com.ll.data.*;
import com.ll.optimizer.Service;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * A rule that names items finds its set (ISS-01M67DW3T4FRYM42ENDM6HAXGG, Andrew
 * 2026-10-30: "LL: find a set when a rule names items the score cut drops").
 * These search as the plugin does, with everything owned so Yours may reach anything.
 */
class RuleNamedItemsTest {
    private static final String HIDE = "has:hueycoatl hide";
    private static final List<Style> STYLES = List.of(Style.MELEE, Style.RANGED, Style.MAGIC);
    private static Tables data;
    private static Owned everything;

    @BeforeAll
    static void load() {
        data = new DataService().load();
        Map<Integer, Integer> bank = new HashMap<>();
        for (Slot slot : Slot.values()) for (Gear g : data.getGearItems(slot)) bank.put(g.id, 1);
        everything = new Owned(bank, true);
    }

    private static Monster mob(String name) {
        return data.searchMonsters(name, 1).get(0);
    }

    private static Rules rule(String stat, String op, double value) {
        return Rules.of(List.of(new Rules.Rule(stat, op, value)), Set.of(), null);
    }

    private static Req request(Monster mob, Style style) {
        return new Req(mob, style, Levels.MAXED, PrayerBonuses.bestAvailable(Levels.MAXED, Prayers.ALL),
            null, 0, CandidateMode.ALL_STANDARD, true, false, Owned.EMPTY, RequirementProfile.MAXED, 3);
    }

    private static void hasASet(Monster mob, Rules rules, boolean superAntifire, List<Style> styles) throws Exception {
        ComputeParams p = new ComputeParams();
        p.setRules = rules;
        p.antifirePotion = superAntifire;
        Service service = new Service(data);
        Map<Style, Service.Pick> results;
        try {
            var done = new CompletableFuture<Map<Style, Service.Pick>>();
            service.bestPerStyle(mob, Levels.MAXED, Levels.MAXED, Prayers.ALL, RequirementProfile.MAXED, everything, 1, p,
                Collections.emptyMap(), Collections.emptySet(), Collections.emptyMap(), null, 0, Collections.<Integer>emptySet(), done::complete);
            results = done.get(5, TimeUnit.MINUTES);
        } finally {
            service.shutdown();
        }
        for (Style style : styles) {
            String label = mob.getName() + " " + style + " " + rules.getRules();
            Service.Pick result = results.get(style);
            assertNotNull(result, label);
            assertNotNull(result.overallBest, label + ": a best set");
            assertTrue(rules.holds(result.overallBest.getLoadout()), label + ": the best set holds, wears " + worn(result.overallBest));
            assertFalse(result.owned.isEmpty(), label + ": a set of yours");
            assertTrue(rules.holds(result.owned.get(0).getLoadout()), label + ": your set holds, wears " + worn(result.owned.get(0)));
        }
    }

    private static List<String> worn(Dps result) {
        List<String> names = new ArrayList<>();
        for (Gear item : result.getLoadout().getGear().values()) names.add(item.name);
        return names;
    }

    @Test
    @DisplayName("I'm your son: two Hueycoatl pieces on every style, gear that scores nothing for melee or magic")
    void hueycoatlHide() throws Exception {
        Monster hueycoatl = mob("the hueycoatl");
        hasASet(hueycoatl, CombatAchievements.byId(575).rulesFor(List.of(hueycoatl)), false, STYLES);
    }

    @Test
    @DisplayName("Antifire Protection with super antifire on: the anti-dragon shield still reaches the set")
    void antiDragonShield() throws Exception {
        Monster kbd = mob("king black dragon");
        hasASet(kbd, CombatAchievements.byId(166).rulesFor(List.of(kbd)), true, STYLES);
    }

    @Test
    @DisplayName("a salve amulet task keeps its amulet on every style")
    void salveAmulet() throws Exception {
        Monster bloat = mob("pestilent bloat");
        hasASet(bloat, CombatAchievements.byId(387).rulesFor(List.of(bloat)), false, STYLES);
    }

    @Test
    @DisplayName("the Lightbearer swap leaves a ring the rule asked for")
    void lightbearerKeepsTheRule() throws Exception {
        hasASet(mob("general graardor"), rule("has:berserker ring", ">=", 1), false, List.of(Style.MELEE));
    }

    @Test
    @DisplayName("the beam: Hueycoatl pieces on melee keep the 11.4 dps set, which falls to 10.6 without the reserve")
    void beamReserve() {
        Monster hueycoatl = mob("the hueycoatl");
        Req req = request(hueycoatl, Style.MELEE).withSetRules(CombatAchievements.byId(575).rulesFor(List.of(hueycoatl)));
        double dps = new LoadoutOptimizer().optimize(data, req).get(0).dps;
        assertTrue(dps > 11.2, "dps " + dps);
    }

    @Test
    @DisplayName("the pool: a rule's 3 best items join their slot, no weapon joins, and an at-most rule or a plain stat rule brings nothing")
    void thePool() {
        LoadoutOptimizer optimizer = new LoadoutOptimizer();
        Req free = request(mob("the hueycoatl"), Style.MELEE);
        Req hide = free.withSetRules(rule(HIDE, ">=", 2));
        for (Slot slot : List.of(Slot.HEAD, Slot.BODY, Slot.LEGS, Slot.HANDS)) {
            List<Gear> base = optimizer.candidates(data, free, slot, LoadoutOptimizer.SLOT_LIMIT, null);
            List<Gear> added = new ArrayList<>(optimizer.candidates(data, hide, slot, LoadoutOptimizer.SLOT_LIMIT, null));
            assertTrue(added.containsAll(base), slot + " keeps its pool");
            added.removeAll(base);
            assertFalse(added.isEmpty(), slot + " gains hide");
            assertTrue(added.size() <= 3, slot + " gains " + added);
            for (Gear item : added) assertEquals(1, Rules.of(item, HIDE), item.name);
            assertEquals(base, optimizer.candidates(data, free.withSetRules(rule(HIDE, "<", 1)), slot, LoadoutOptimizer.SLOT_LIMIT, null), slot + " under an at-most rule");
            assertEquals(base, optimizer.candidates(data, free.withSetRules(rule("prayer", ">=", 12)), slot, LoadoutOptimizer.SLOT_LIMIT, null), slot + " under a stat rule");
        }
        assertEquals(optimizer.candidates(data, free, Slot.WEAPON, LoadoutOptimizer.WEAPON_LIMIT, null),
            optimizer.candidates(data, hide, Slot.WEAPON, LoadoutOptimizer.WEAPON_LIMIT, null), "no weapon line joins");
    }

    @Test
    @DisplayName("two rules in one slot each keep their own items in the pool")
    void eachRuleInThePool() {
        LoadoutOptimizer optimizer = new LoadoutOptimizer();
        String other = "has:black d'hide";
        Rules both = rule(HIDE, ">=", 1).plus(List.of(new Rules.Rule(other, ">=", 1)));
        Req req = request(mob("the hueycoatl"), Style.MELEE).withSetRules(both);
        List<Gear> pool = optimizer.candidates(data, req, Slot.BODY, LoadoutOptimizer.SLOT_LIMIT, null);
        for (String stat : List.of(HIDE, other)) assertTrue(pool.stream().anyMatch(g -> Rules.of(g, stat) > 0), stat);
    }

    private static Gear firstOf(Slot slot, String stat) {
        return data.getGearItems(slot).stream().filter(g -> Rules.of(g, stat) > 0).findFirst().get();
    }

    @Test
    @DisplayName("namedProgress: a met rule counts the same however far past it, ranks above any unmet count, and plain or at-most rules count nothing")
    void namedProgress() {
        var two = new EnumMap<Slot, Gear>(Slot.class);
        two.put(Slot.BODY, firstOf(Slot.BODY, HIDE));
        two.put(Slot.LEGS, firstOf(Slot.LEGS, HIDE));
        Kit worn = Kit.adopting(two);
        assertEquals(12, rule(HIDE, ">=", 1).namedProgress(worn));
        assertEquals(12, rule(HIDE, ">=", 2).namedProgress(worn));
        assertEquals(12, rule(HIDE, ">", 0).namedProgress(worn));
        assertEquals(2, rule(HIDE, ">=", 3).namedProgress(worn));
        assertEquals(0, rule(HIDE, "<=", 1).namedProgress(worn));
        assertEquals(0, rule("prayer", ">=", 1).namedProgress(worn));
    }
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.List;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Salarin the twisted (wiki): "can only be damaged by Strike spells,
 * ring of recoil damage, and dynamite(p)" - a flat 9-12 by highest
 * strike unlocked, unaffected by gear. The one mob where optimizing
 * equipment is meaningless, which the answer must SAY rather than
 * pretend otherwise.
 */
class SalarinTest {
	private static Tables data;
	private static Monster salarin;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		salarin = data.searchMonsters("salarin", 1).get(0);
		assertEquals(304, salarin.getId());
	}

	private static Req req(Style style) {
		return TestRequests.of(salarin, style, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, Owned.EMPTY, 1);
	}

	@Test
	@DisplayName("melee and ranged never land")
	void meleeAndRangedAreImmune() {
		assertTrue(new LoadoutOptimizer().optimize(data, req(Style.MELEE)).isEmpty());
		assertTrue(new LoadoutOptimizer().optimize(data, req(Style.RANGED)).isEmpty());
	}

	@Test
	@DisplayName("the magic answer is a Strike at a flat 12, plus the elemental amulet's 2")
	void magicIsAFlatStrike() {
		List<Dps> out = new LoadoutOptimizer().optimize(data, req(Style.MAGIC));
		assertFalse(out.isEmpty(), "strikes must survive the elemental prune");
		Dps best = out.get(0);
		assertNotNull(best.getSpellName());
		assertTrue(best.getSpellName().endsWith("Strike"),
			"picked: " + best.getSpellName());
		// Wiki: "The sole exception is the Elemental amulet, which increases
		// the player's max hit by 2." The ceiling wears it since the pool
		// stopped merging it into the amulet of magic (2026-09-27); before,
		// this read a flat 12 only because the amulet never reached the beam.
		assertEquals("elemental amulet",
			best.getLoadout().get(com.ll.data.Slot.NECK).getLname());
		assertEquals(14, best.getMaxHit(), "flat 12 at maxed magic, +2 from the amulet");
		assertEquals(14.0, best.getEh(), 1e-9, "guaranteed, no roll");
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The salve amulet family's tiers, wiki-verified (2026-07 player audit
 * A2.1/A2.2): melee/ranged - base and (i) at 16.67%, (e) and (ei) at 20%;
 * magic - (i) 15% accuracy AND damage, (ei) 20% accuracy AND damage. The
 * original engine matched "salve amulet (e)" (with a space), so the
 * spaceless "Salve amulet(ei)" fell into the 16.67% bucket, and the magic
 * DAMAGE path had no salve branch at all.
 */
class SalveTest {
	private static Tables data;
	private static Monster ankou;   // undead, magic-attackable

	@BeforeAll
	static void load() {
		data = new DataService().load();
		ankou = data.searchMonsters("ankou", 1).get(0);
		assertTrue(ankou.hasAttribute("undead"), "test premise: ankou is undead");
	}

	private static Gear byName(String lname) {
		for (Gear item : data.getGearItems()) {
			if (item.getLname().equals(lname)) {
				return item;
			}
		}
		throw new AssertionError("corpus is missing: " + lname);
	}

	private static Req request(Style style) {
		return new Req(ankou, style, Levels.MAXED,
			PrayerBonuses.NONE, null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			Owned.EMPTY, RequirementProfile.MAXED, 1);
	}

	private static Dps calc(Style style, Gear weapon, Gear neck) {
		EnumMap<Slot, Gear> gear = new EnumMap<>(Slot.class);
		gear.put(Slot.WEAPON, weapon);
		if (neck != null) {
			gear.put(neck.getSlot(), neck);
		}
		return new Calc().calculate(request(style), new Kit(gear));
	}

	@Test
	@DisplayName("melee: salve(ei) sits in the 20% tier with salve (e), above (i) and base")
	void meleeTiers() {
		Gear whip = byName("abyssal whip");
		double ei = calc(Style.MELEE, whip, byName("salve amulet(ei)")).getDps();
		double e = calc(Style.MELEE, whip, byName("salve amulet (e)")).getDps();
		double i = calc(Style.MELEE, whip, byName("salve amulet(i)")).getDps();
		double base = calc(Style.MELEE, whip, byName("salve amulet")).getDps();

		assertEquals(e, ei, 1e-9, "(ei) must match (e)'s 20% melee tier");
		assertEquals(base, i, 1e-9, "(i) shares the base 16.67% melee tier");
		assertTrue(ei > i, "20% tier must beat 16.67% tier");
	}

	@Test
	@DisplayName("magic: salve(ei) raises the MAX HIT 20% and (i) 15% against undead")
	void magicDamageTiers() {
		Gear sang = byName("sanguinesti staff");
		int bare = calc(Style.MAGIC, sang, null).getMaxHit();
		int ei = calc(Style.MAGIC, sang, byName("salve amulet(ei)")).getMaxHit();
		int i = calc(Style.MAGIC, sang, byName("salve amulet(i)")).getMaxHit();

		assertEquals(multiply(bare, 6, 5), ei, "(ei) magic damage is +20%");
		assertEquals(multiply(bare, 23, 20), i, "(i) magic damage is +15%");
	}

	@Test
	@DisplayName("salves do nothing against the living")
	void noEffectOnNonUndead() {
		Monster goblin = data.searchMonsters("goblin", 1).get(0);
		assertFalse(goblin.hasAttribute("undead"));
		Req req = new Req(goblin, Style.MELEE,
			Levels.MAXED, PrayerBonuses.NONE, null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			Owned.EMPTY, RequirementProfile.MAXED, 1);
		Gear whip = byName("abyssal whip");

		EnumMap<Slot, Gear> bare = new EnumMap<>(Slot.class);
		bare.put(Slot.WEAPON, whip);
		EnumMap<Slot, Gear> salved = new EnumMap<>(bare);
		Gear ei = byName("salve amulet(ei)");
		salved.put(ei.getSlot(), ei);

		assertEquals(new Calc().calculate(req, new Kit(bare)).getDps(),
			new Calc().calculate(req, new Kit(salved)).getDps(), 1e-9);
	}

	private static int multiply(int value, int numerator, int denominator) {
		return value * numerator / denominator;
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Boat combat's first rule (wiki; Andrew's catch 2026-08-31 - "are you sure
 * you can use a noxious halberd on boat?"): melee cannot attack at sea. A
 * sea monster is melee-immune through the same mechanism Zulrah uses, so no
 * melee card is ever produced for one.
 */
class SeaMeleeTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	@Test
	@DisplayName("every roster sea monster rejects melee; land mobs are untouched")
	void seaMonstersRejectMelee() {
		Kit bare = new Kit(new EnumMap<>(com.ll.data.Slot.class));
		for (String name : com.ll.data.NavalCombat.NAVAL) {
			Monster mob = data.searchMonsters(name, 1).get(0);
			assertTrue(MonsterMechanics.isImmune(mob, Style.MELEE, bare, null),
				name + " must reject melee at sea");
			assertFalse(MonsterMechanics.isImmune(mob, Style.RANGED, bare, null),
				name + " must still take ranged");
		}
		Monster graardor = data.searchMonsters("general graardor", 1).get(0);
		assertFalse(MonsterMechanics.isImmune(graardor, Style.MELEE, bare, null));
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Game-update audit 2026-10-06 (The Blood Moon Rises, 30 June 2026).
 * Wiki, Arrows: seeking arrows "have +20 ranged accuracy more than their
 * normal counterpart and a minimum hit of 3" - a landed 0, 1 or 2 becomes
 * 3. The official calc clamps every accurate hitsplat to 3. */
class SeekingArrowsTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static Dps shoot(String bow, String ammo) {
		Monster mob = data.searchMonsters("goblin", 1).get(0);
		Req request = TestRequests.of(mob, Style.RANGED, Levels.MAXED,
			PrayerBonuses.NONE, null, 0, CandidateMode.ALL_STANDARD, true, false, Owned.EMPTY, 1);
		EnumMap<Slot, Gear> gear = new EnumMap<>(Slot.class);
		for (String name : new String[]{bow, ammo}) {
			Gear item = data.getGearItems().stream()
				.filter(g -> g.getLname().equals(name) && g.isStandardGear())
				.findFirst().orElseThrow(() -> new AssertionError("corpus is missing: " + name));
			gear.put(item.getSlot(), item);
		}
		return new Calc().calculate(request, new Kit(gear));
	}

	@Test
	@DisplayName("a landed seeking arrow deals at least 3: the 0, 1 and 2 rolls lift to 3")
	void minimumHitOfThree() {
		Dps seeking = shoot("magic shortbow", "seeking rune arrow");
		Dps plain = shoot("magic shortbow", "rune arrow");
		assertEquals(plain.getMaxHit(), seeking.getMaxHit(), "same max hit");
		assertTrue(seeking.getAccuracy() > plain.getAccuracy(), "+20 ranged accuracy");
		double acc = seeking.getAccuracy();
		int max = seeking.getMaxHit();
		// The plain expectation already counts a landed 0 as 1, so the
		// three low rolls lift by 2, 2 and 1 (official vector: 0.0%).
		double expected = RollMath.expectedHitWithFlatArmour(acc, 0, max, 0) + acc * 5.0 / (max + 1);
		assertEquals(expected, seeking.getEh(), 1e-9, "three rolls lifted to 3");
	}

	@Test
	@DisplayName("seeking arrows in the ammo slot of a blowpipe count for nothing")
	void onlyWhenTheWeaponFiresThem() {
		Dps pipe = shoot("toxic blowpipe", "seeking rune arrow");
		double acc = pipe.getAccuracy();
		assertEquals(RollMath.expectedHitWithFlatArmour(acc, 0, pipe.getMaxHit(), 0),
			pipe.getEh(), 1e-9);
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The "cost to own" line prices the gap between your bank and the set on
 * screen. It leans entirely on the search accumulating budgetCost per slot
 * - the item's price when you do not own it, zero when you do - so these
 * pin that behaviour down rather than the formatting.
 */
class SetCostTest {
	private static Tables data;
	private static Monster target;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		target = data.searchMonsters("abyssal demon", 1).get(0);
	}

	private static Dps best(Owned owned, CandidateMode mode) {
		Req request = TestRequests.of(target,
			Style.MELEE, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), null, 0,
			mode, true, false, owned, 1);
		List<Dps> out = new LoadoutOptimizer().optimize(data, request);
		assertFalse(out.isEmpty(), "optimizer returned nothing");
		return out.get(0);
	}

	@Test
	@DisplayName("a game-best set owned by nobody prices its whole self")
	void gameBestPricesTheGap() {
		Dps r = best(Owned.EMPTY, CandidateMode.ALL_STANDARD);
		assertTrue(r.getPurchaseCost() > 0,
			"the BiS set must carry the gp cost of the pieces you lack - "
				+ "the 'cost to own' line renders from exactly this");
	}

	@Test
	@DisplayName("owning the pieces drives the cost to zero")
	void owningThemCostsNothing() {
		// Own precisely what the game-best search picked, then re-run: every
		// slot now returns budgetCost 0, so the line is suppressed.
		Dps bis = best(Owned.EMPTY, CandidateMode.ALL_STANDARD);
		Map<Integer, Integer> owned = new HashMap<>();
		bis.getLoadout().getGear().values().stream()
			.filter(java.util.Objects::nonNull)
			.forEach(g -> owned.put(g.getId(), 1));

		Dps again = best(new Owned(owned, true), CandidateMode.ALL_STANDARD);
		assertEquals(0, again.getPurchaseCost(),
			"a set you already own must price at zero, so the line stays off");
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.List;
import java.util.Set;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Stage 1 of the combat achievement chips (ISS-01M5XA7NVZYGVR3EVTM05XHXKP):
 * rules over the worn set's totals, item bans and a weapon allow-list bind
 * the optimizer. Andrew, 2026-10-26: "give me a set with at least 12 prayer,
 * or at least 100 range def, etc."
 */
class SetRulesTest {
    private static Tables data;

    @BeforeAll
    static void load() {
        data = new DataService().load();
    }

    private static Monster mob(String name) {
        return data.getMonsters().stream().filter(m -> m.getName().equalsIgnoreCase(name))
            .findFirst().orElseThrow(AssertionError::new);
    }

    private static List<Dps> best(String monster, Style style, Rules rules) {
        Req request = new Req(mob(monster), style, Levels.MAXED,
            PrayerBonuses.bestAvailable(Levels.MAXED, new Prayers(true, true, true, true, true)),
            null, 0, CandidateMode.ALL_STANDARD, true, false, Owned.EMPTY, RequirementProfile.MAXED, 5)
            .withSetRules(rules);
        return new LoadoutOptimizer().optimize(data, request);
    }

    private static double total(Dps r, String stat) {
        return Rules.total(r.getLoadout(), stat);
    }

    private static String worn(Dps r) {
        StringBuilder s = new StringBuilder();
        for (Gear g : r.getLoadout().getGear().values()) s.append(g.getLname()).append(", ");
        return s.toString();
    }

    @Test
    @DisplayName("a weight ceiling binds: under 20kg at the Shellbane gryphon, where the unrestricted melee set weighs more")
    void weightRuleBinds() {
        // Featherweight Fighter's 40kg does not bind on maxed gear (the best melee set weighs ~29kg), so a
        // 20kg ceiling proves the rule: the unrestricted set breaks it, the ruled one keeps it.
        Dps free = best("Shellbane gryphon", Style.MELEE, null).get(0);
        assertTrue(total(free, "weight") >= 20, "the rule must bind: " + total(free, "weight") + " " + worn(free));
        List<Dps> light = best("Shellbane gryphon", Style.MELEE,
            Rules.of(List.of(new Rules.Rule("weight", "<", 20)), Set.of(), null));
        assertFalse(light.isEmpty());
        for (Dps r : light) assertTrue(total(r, "weight") < 20, worn(r));
    }

    @Test
    @DisplayName("at least 12 prayer and at least 100 ranged defence hold on every result")
    void floorsHold() {
        for (Dps r : best("Vorkath", Style.RANGED,
            Rules.of(List.of(new Rules.Rule("prayer", ">=", 12), new Rules.Rule("def_ranged", ">=", 100)), Set.of(), null))) {
            assertTrue(total(r, "prayer") >= 12, worn(r));
            assertTrue(total(r, "def_ranged") >= 100, worn(r));
        }
    }

    @Test
    @DisplayName("Prayer Smasher: only the Verac's flail as a weapon, and no recoil items")
    void weaponAllowListAndBans() {
        List<Dps> results = best("Kalphite Queen", Style.MELEE, Rules.of(List.of(),
            Set.of("ring of recoil", "ring of suffering", "ring of suffering (i)", "echo boots"), Set.of("verac's flail")));
        assertFalse(results.isEmpty());
        for (Dps r : results) {
            String worn = worn(r);
            assertTrue(r.getLoadout().getWeapon().getLname().startsWith("verac's flail"), worn);
            assertFalse(worn.contains("recoil") || worn.contains("suffering") || worn.contains("echo boots"), worn);
        }
    }

    @Test
    @DisplayName("a rule no set can meet gives no results")
    void impossibleRule() {
        assertTrue(best("Vorkath", Style.RANGED,
            Rules.of(List.of(new Rules.Rule("prayer", ">=", 500)), Set.of(), null)).isEmpty());
    }

    @Test
    @DisplayName("no rules leaves the best set as it was")
    void noRulesNoChange() {
        assertEquals(worn(best("Vorkath", Style.RANGED, null).get(0)),
            worn(best("Vorkath", Style.RANGED, Rules.of(List.of(), Set.of(), null)).get(0)));
    }
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Andrew, 2026-09-17: "lizardman shamans need to have the level 5 shayzien
 * armor to protect from their poison (when outside of cox)". Wiki: a full
 * tier-5 set negates the acid attack. */
class ShamanShayzienTest {
	@Test
	@DisplayName("outside CoX the owned melee set wears all five tier-5 Shayzien pieces over better-statted armour; a missing piece frees only its slot")
	void fullSetRequired() {
		Tables data = new DataService().load();
		Monster temple = data.searchMonsters("Lizardman shaman", 5).stream()
			.filter(m -> "Lizardman Temple".equals(m.getVersion())).findFirst().orElseThrow();
		Map<Integer, Integer> owned = new HashMap<>();
		for (int id : new int[]{4151, 10828, 4131, 11832, 11834, 7462, 13379, 13381, 13380, 13377, 13378}) {
			owned.put(id, 1); // whip, helm of neitiznot, rune boots, bandos chest + tassets, barrows gloves, Shayzien (5) x5
		}
		Req request = TestRequests.of(temple, Style.MELEE, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), null, 0, CandidateMode.OWNED_ONLY, true, false,
			new Owned(owned, true), 1);
		List<Dps> results = new LoadoutOptimizer().optimize(data, request);
		assertFalse(results.isEmpty(), "a usable set exists");
		Kit worn = results.get(0).getLoadout();
		for (Slot slot : new Slot[]{Slot.HEAD, Slot.BODY, Slot.LEGS, Slot.HANDS, Slot.FEET}) {
			Gear piece = worn.get(slot);
			assertTrue(piece != null && piece.getLname().startsWith("shayzien"), slot + ": " + piece);
		}
		owned.remove(13378); // lose the boots: the set is incomplete
		List<Dps> without = new LoadoutOptimizer().optimize(data,
			TestRequests.of(temple, Style.MELEE, Levels.MAXED, PrayerBonuses.bestAvailable(Levels.MAXED),
				null, 0, CandidateMode.OWNED_ONLY, true, false, new Owned(owned, true), 1));
		// A missing piece never empties the card (the required-gear rule since
		// 2026-08-08: an unowned protection falls back to the unconstrained
		// hunt and the note explains the gap); the four owned pieces stay.
		assertFalse(without.isEmpty(), "a missing piece never empties the card");
		Kit partial = without.get(0).getLoadout();
		assertEquals("rune boots", partial.get(Slot.FEET).getLname());
		assertTrue(partial.get(Slot.HEAD).getLname().startsWith("shayzien"));
	}
}

package com.ll.engine;

import com.ll.data.NavalCombat;
import java.util.List;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Ship-cannon formulas, pinned against hand-computed values from the wiki's
 * documented formula (Boat combat / Cannons, 2026-08-31):
 * floor((level * (cannonStr + ballStr + wornStr + 64) + 320) / 640).
 */
class ShipCannonTest {
	@Test
	@DisplayName("player max hit matches the wiki formula at hand-computed points")
	void playerMaxHitPins() {
		// 99 ranged, dragon cannon (32) + dragon ball (270), nothing worn:
		// (99 * 366 + 320) / 640 = 57.11 -> 57.
		assertEquals(57, ShipCannon.playerMaxHit(99, 32, 270, 0, false));
		// Perildance bitter: +1 flat.
		assertEquals(58, ShipCannon.playerMaxHit(99, 32, 270, 0, true));
		// Worn ranged strength joins the strength term: +30 worn ->
		// (99 * 396 + 320) / 640 = 61.75 -> 61.
		assertEquals(61, ShipCannon.playerMaxHit(99, 32, 270, 30, false));
		// A fresh account on a bronze/bronze setup cannot hit:
		// (1 * 115 + 320) / 640 = 0.68 -> 0.
		assertEquals(0, ShipCannon.playerMaxHit(1, 8, 43, 0, false));
		// Mid levels: 50 ranged, steel/steel, +20 worn ->
		// (50 * 170 + 320) / 640 = 13.78 -> 13.
		assertEquals(13, ShipCannon.playerMaxHit(50, 12, 74, 20, false));
	}

	@Test
	@DisplayName("crew scaling is the documented (priv + 13) / 20 - and flagged stale")
	void crewScalingPins() {
		assertEquals(48, ShipCannon.crewMaxHit(57, 4)); // 57 * 17/20 = 48.45
		assertEquals(39, ShipCannon.crewMaxHit(57, 1)); // 57 * 14/20 = 39.9
		assertEquals(0, ShipCannon.crewMaxHit(0, 4));
		// The wiki flags this formula out-of-date; the data carries the flag
		// so the UI marks crew numbers as estimates. If the flag is ever
		// cleared, the corrected formula must land WITH that change.
		assertTrue(NavalCombat.crewFormulaStale(),
			"crewFormulaStale cleared - did the corrected formula land here?");
	}

	@Test
	@DisplayName("cannon DPS averages the uniform roll over the 7-tick cycle")
	void dpsShape() {
		// Max 57 at guaranteed hits: 28.5 damage per 4.2s cycle.
		assertEquals(57 / 2.0 / 4.2, ShipCannon.dps(57, 1.0), 1e-9);
		// Halved hit chance halves it; zero chance is zero.
		assertEquals(57 / 4.0 / 4.2, ShipCannon.dps(57, 0.5), 1e-9);
		assertEquals(0.0, ShipCannon.dps(57, 0.0), 1e-9);
	}

	@Test
	@DisplayName("a cannon fires balls at or below its tier - granite rides above mithril")
	void ballTierClamps() {
		assertTrue(NavalCombat.canFire("dragon", "dragon"));
		assertTrue(NavalCombat.canFire("dragon", "bronze"));
		assertFalse(NavalCombat.canFire("bronze", "iron"));
		// Granite sits between mithril and adamant in the firing order: a
		// mithril cannon cannot fire it, an adamant cannon can.
		assertFalse(NavalCombat.canFire("mithril", "granite"));
		assertTrue(NavalCombat.canFire("adamant", "granite"));
	}

	@Test
	@DisplayName("shared ammo caps at the LOWER cannon's tier (REQ-SC-2)")
	void sharedAmmoCap() {
		assertEquals("mithril", NavalCombat.bestSharedBall(List.of("dragon", "mithril")));
		assertEquals("dragon", NavalCombat.bestSharedBall(List.of("dragon", "dragon")));
		assertEquals("bronze", NavalCombat.bestSharedBall(List.of("bronze")));
		assertNull(NavalCombat.bestSharedBall(List.of()));
	}

	@Test
	@DisplayName("the data tables carry the wiki's current numbers")
	void dataPins() {
		// Dragon ball at the post-2026-03-18 +270, never the launch +174.
		assertEquals(270, NavalCombat.ball("dragon").strength);
		assertEquals(31916, NavalCombat.ball("dragon").itemId);
		// Steel ball is the classic Cannonball, item 2.
		assertEquals(2, NavalCombat.ball("steel").itemId);
		// Rune and dragon cannons demand Privateering 4 of their crew.
		assertEquals(4, NavalCombat.cannon("rune").privateering);
		assertEquals(4, NavalCombat.cannon("dragon").privateering);
		// Seven cannons, eight balls, uniform 7-tick rate.
		assertEquals(7, NavalCombat.cannons().size());
		assertEquals(8, NavalCombat.balls().size());
		assertEquals(7, NavalCombat.ATTACK_TICKS);
	}
}

