		// 35% since the Summer Sweep-Up gear changes (wiki, 7 August 2026).
		Assert.assertEquals(35, burningClaws.getEnergyCost());
	}

	@Test
	public void ornateGraniteMaulSpecCostsFiftyWhileThePlainMaulCostsSixty() {
		SpecialAttack ornate = SpecialAttack.match(byName("Granite maul (ornate handle)"), Style.MELEE);
		SpecialAttack plain = SpecialAttack.match(byName("Granite maul"), Style.MELEE);
		Assert.assertNotNull(ornate);
		Assert.assertNotNull(plain);
		Assert.assertEquals(SpecialAttack.Kind.EXTRA_ATTACK, ornate.getKind());
		Assert.assertEquals(SpecialAttack.Kind.EXTRA_ATTACK, plain.getKind());
		Assert.assertEquals(50, ornate.getEnergyCost());
		Assert.assertEquals(60, plain.getEnergyCost());
	}

	@Test
	public void accursedSceptreSpecBoostsDamageByHalf() {
		Gear sceptre = byName("Accursed sceptre");
		SpecialAttack spec = SpecialAttack.match(sceptre, Style.MAGIC);
		Assert.assertNotNull(spec);
		// Rolls (2, 0) with the 1.5x accuracy boost give attack roll 3:
		// hit chance 1 - 2/8 = 0.75 exactly; damage rolls 0..(1.5 * 40).
		Assert.assertEquals(0.75 * ((int) (40 * 1.5)) / 2.0,
			spec.expectedDamage(fabricated(sceptre, 40, 2L, 0L), null, Levels.MAXED), 1e-9);
	}

	@Test
	public void volatileSpellMaxMatchesTheWikiAnchorsAtEightyFourAndNinetyNineMagic() {
		Gear staff = byName("Volatile nightmare staff");
		SpecialAttack spec = SpecialAttack.match(staff, Style.MAGIC);
		Assert.assertNotNull(spec);
		Dps sureHit = fabricated(staff, 30, 1_000_000_000L, 1L);
		// Level 84: spell max min(floor(58*84/99) + 1, 58) = 50; the staff's
		// 15% magic damage takes it to 57. Expected = mean = 28.5.
		Levels magic84 = new Levels(99, 99, 99, 99, 84, 99, 99);
		Assert.assertEquals(57 / 2.0, spec.expectedDamage(sureHit, null, magic84), 1e-4);
		// Level 99: spell max caps at 58; 15% gear takes it to 66. Mean 33.
		Assert.assertEquals(66 / 2.0, spec.expectedDamage(sureHit, null, Levels.MAXED), 1e-4);
		// A boosted 98 already hits the 58 cap.
		Levels magic98 = new Levels(99, 99, 99, 99, 98, 99, 99);
		Assert.assertEquals(66 / 2.0, spec.expectedDamage(sureHit, null, magic98), 1e-4);
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.data.Spell;
import java.util.EnumMap;
import java.util.List;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Lever 5 (ISS-01M62X98ZMFKDE48JJ7KFT1FQ4, Andrew 2026-10-28: "and go ahead
 * and execute lever 5"): a calculator cuts each rule list to the rules its
 * monster's gate allows, once per monster. The active-mask half measured no
 * faster and was dropped. Lever 6 (ISS-01M6320S1ZYTC9H74X8Y1Y2P09): a spell's
 * attack label and amulet marker are built once, not per magic trial.
 */
class SpeedPass2SeamsTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static Gear weapon(String lname, String ver) {
		return data.getGearItems(Slot.WEAPON).stream()
			.filter(g -> g.lname.equals(lname) && (ver == null || ver.equals(g.ver)))
			.findFirst().get();
	}

	private static Kit wielding(Gear item) {
		EnumMap<Slot, Gear> gear = new EnumMap<>(Slot.class);
		gear.put(Slot.WEAPON, item);
		return new Kit(gear);
	}

	@Test
	@DisplayName("one calculator re-cuts its rule lists when the monster changes: a lance on a dragon, then Graardor, then the dragon")
	void ruleCutFollowsTheMonster() {
		Monster dragon = data.searchMonsters("vorkath", 1).get(0);
		Monster graardor = data.searchMonsters("general graardor", 1).get(0);
		Kit lance = wielding(weapon("dragon hunter lance", null));
		Calc shared = new Calc();
		for (Monster mob : List.of(dragon, graardor, dragon)) {
			Req request = new Req(mob, Style.MELEE, Levels.MAXED,
				PrayerBonuses.NONE, null, 0, CandidateMode.ALL_STANDARD, false, false, Owned.EMPTY,
				RequirementProfile.MAXED, 10);
			Dps fresh = new Calc().calculate(request, lance);
			Dps reused = shared.calculate(request, lance);
			assertEquals(fresh.dps, reused.dps, 1e-12, mob.name + ": the reused calculator matches a fresh one");
			assertEquals(mob == dragon, reused.countedBonuses.toString().contains("dragon hunter lance"),
				mob.name + ": the lance's dragon rule applies only on the dragon");
		}
	}

	@Test
	@DisplayName("one calculator meeting a hundred monsters in turn answers each exactly as a fresh one does")
	void ruleCutsAcrossManyMonsters() {
		Kit lance = wielding(weapon("dragon hunter lance", null));
		Calc shared = new Calc();
		int met = 0;
		for (Monster mob : data.monsters) {
			if (met == 100) break;
			Req request = new Req(mob, Style.MELEE, Levels.MAXED,
				PrayerBonuses.NONE, null, 0, CandidateMode.ALL_STANDARD, false, false, Owned.EMPTY,
				RequirementProfile.MAXED, 10);
			Dps fresh = new Calc().calculate(request, lance);
			Dps reused = shared.calculate(request, lance);
			if (fresh == null) {
				assertNull(reused, mob.name);
				continue;
			}
			met++;
			assertEquals(fresh.dps, reused.dps, 1e-12, mob.name);
		}
		assertEquals(100, met);
	}

	@Test
	@DisplayName("a spell carries its attack label and amulet marker, built once, and a magic result uses them")
	void spellStringsBuiltOnce() {
		Spell surge = new Spell("Fire Surge", 24, 95, "standard", "fire");
		assertEquals("magic: Fire Surge", surge.attack);
		assertEquals("amulet of fire", surge.amulet);
		Spell bare = new Spell(null, 0, 1, null, null);
		assertEquals("magic: ", bare.attack, "a nameless spell");
		assertEquals("amulet of ", bare.amulet, "an elementless spell");
		Spell spell = data.spells.stream().filter(s -> s.name.equals("Fire Surge")).findFirst().get();
		Monster mob = data.searchMonsters("general graardor", 1).get(0);
		Kit staff = wielding(weapon("staff of fire", null));
		Req request = new Req(mob, Style.MAGIC, Levels.MAXED,
			PrayerBonuses.NONE, spell, 0, CandidateMode.ALL_STANDARD, false, false, Owned.EMPTY,
			RequirementProfile.MAXED, 10);
		Dps result = new Calc().calculate(request, staff);
		assertSame(spell.attack, result.attackType, "the label is the spell's own string, not a fresh one");
	}

	@Test
	@DisplayName("an inactive Bow of Faerdhinen is worn but never active, asked twice each way")
	void inactiveBowIsWornNotActive() {
		Kit bow = wielding(weapon("bow of faerdhinen", "inactive"));
		for (int ask = 0; ask < 2; ask++) {
			assertTrue(bow.wears("bow of faerdhinen", false), "worn");
			assertFalse(bow.wears("bow of faerdhinen", true), "not active");
		}
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.data.SpellRunes;
import com.ll.data.Spell;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Wiring net for the premium-rune spell gate: PremiumRuneGateTest proves the
 * predicate, this proves the optimizer's pool actually consults it - on the
 * OWNED side only, and before the mob whitelists so a nibbler lock cannot
 * resurrect a spell the bank cannot pay for.
 */
class SpellRuneWiringTest {
	private static Tables data;
	private static Monster zulrah;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		zulrah = data.searchMonsters("zulrah", 1).get(0);
	}

	private static Req request(CandidateMode mode, Owned owned) {
		return new Req(
			zulrah, Style.MAGIC, Levels.MAXED,
			PrayerBonuses.NONE, null, 0,
			mode, true, false,
			owned, RequirementProfile.MAXED, 1);
	}

	@Test
	@DisplayName("a runeless bank's own spell pool holds no premium-rune spell")
	void ownedPoolDropsPremiumSpells() {
		List<Spell> pool = LoadoutOptimizer.spellsFor(data,
			request(CandidateMode.OWNED_ONLY, Owned.EMPTY));
		assertFalse(pool.isEmpty(), "the pool should still hold shop-rune spells");
		for (Spell spell : pool) {
			assertTrue(SpellRunes.premiumRunesOwned(spell.getName(), Owned.EMPTY),
				spell.getName() + " needs premium runes the bank does not hold");
		}
	}

	@Test
	@DisplayName("owning the runes restores the barrage-class spells")
	void owningRunesRestoresThePool() {
		Map<Integer, Integer> runes = new HashMap<>();
		runes.put(565, 1000); // blood
		runes.put(560, 1000); // death
		runes.put(566, 1000); // soul
		runes.put(21880, 1000); // wrath
		List<Spell> pool = LoadoutOptimizer.spellsFor(data,
			request(CandidateMode.OWNED_ONLY, new Owned(runes, true)));
		boolean premium = false;
		for (Spell spell : pool) {
			premium |= !SpellRunes.premiumRunesOwned(spell.getName(), Owned.EMPTY);
		}
		assertTrue(premium, "with the runes banked, premium spells should be back");
	}

	@Test
	@DisplayName("the ceiling keeps every spell - it prices the game, not the bank")
	void ceilingIsUngated() {
		List<Spell> pool = LoadoutOptimizer.spellsFor(data,
			request(CandidateMode.ALL_STANDARD, Owned.EMPTY));
		boolean premium = false;
		for (Spell spell : pool) {
			premium |= !SpellRunes.premiumRunesOwned(spell.getName(), Owned.EMPTY);
		}
		assertTrue(premium, "the BiS side must not be rune-gated");
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class SpellbookLockTest {
	private static Tables data;

	private static Tables data() {
		if (data == null) {
			data = new DataService().load();
		}
		return data;
	}

	@Test
	public void lockRestrictsAutoSpellToTheChosenBook() {
		Monster td = data().searchMonsters("tormented demon", 1).get(0);
		Req base = new Req(
			td, Style.MAGIC, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			Owned.EMPTY, RequirementProfile.MAXED, 1);

		// Unlocked vs demons: arceuus demonbane or a powered staff wins.
		Dps any = new LoadoutOptimizer().optimize(data(), base).get(0);
		Assert.assertTrue(any.getSpellName() == null
			|| any.getSpellName().contains("Demonbane"));

		// Locked to standard: no arceuus spell may appear.
		Dps standard = new LoadoutOptimizer().optimize(data(),
			base.withSpellbookLock("standard")).get(0);
		if (standard.getSpellName() != null) {
			Assert.assertEquals("standard", bookOf(standard.getSpellName()));
		}

		// Locked to ancient: the pick is an ancient spell or a powered staff.
		Dps ancient = new LoadoutOptimizer().optimize(data(),
			base.withSpellbookLock("ancient")).get(0);
		if (ancient.getSpellName() != null) {
			Assert.assertEquals("ancient", bookOf(ancient.getSpellName()));
		}
	}

	@Test
	public void purgingStaffAutocastsAncientsAndNoSpellMeansNoResult() {
		Monster graardor = data().searchMonsters("general graardor", 1).get(0);
		java.util.Map<Integer, Integer> owned = new java.util.HashMap<>();
		data().getGearItems().stream().filter(g -> g.getName().equalsIgnoreCase("Purging staff"))
			.findFirst().ifPresent(g -> owned.put(g.getId(), 1));
		// Premium runes: the rune-ownership gate (0.4.1) would otherwise
		// drop the blood/death spells and shift the arithmetic this test
		// pins - rune poverty has its own net (SpellRuneWiringTest).
		owned.put(565, 1000);   // blood
		owned.put(560, 1000);   // death
		owned.put(566, 1000);   // soul
		owned.put(21880, 1000); // wrath
		Req ancientLock = new Req(
			graardor, Style.MAGIC, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false,
			new Owned(owned, true), RequirementProfile.MAXED, 1)
			.withSpellbookLock("ancient");
		List<Dps> results = new LoadoutOptimizer().optimize(data(), ancientLock);
		// The purging staff CAN autocast ancients - a real barrage result,
		// never a spell-less max-0 garbage row (the field 0.04-dps report).
		Assert.assertFalse(results.isEmpty());
		Assert.assertNotNull(results.get(0).getSpellName());
		Assert.assertTrue(results.get(0).getMaxHit() > 0);
	}

	private static String bookOf(String spellName) {
		return data().getSpells().stream()
			.filter(s -> s.getName().equals(spellName))
			.findFirst().orElseThrow(AssertionError::new).getSpellbook();
	}

	@Test
	public void eyeOfAyakEvaluatesAsAPoweredStaffInTheOptimizer() {
		// The optimizer once had its own powered-staff list missing the
		// eye of ayak, sending it down the autocast path. A powered staff
		// result carries no spell name.
		com.ll.data.Tables data = new com.ll.data.DataService().load();
		com.ll.data.Monster zulrah = data.searchMonsters("zulrah", 1).get(0);
		java.util.Map<Integer, Integer> owned = java.util.Map.of(31113, 1); // eye of ayak (charged)
		Req req = TestRequests.of(zulrah, Style.MAGIC,
			Levels.MAXED, PrayerBonuses.bestAvailable(Levels.MAXED, Prayers.ALL),
			null, 0, CandidateMode.OWNED_ONLY, true, false,
			new com.ll.engine.Owned(data.canonicalizeOwned(owned), true), 1);
		java.util.List<Dps> out = new LoadoutOptimizer().optimize(data, req);
		org.junit.Assert.assertFalse(out.isEmpty());
		org.junit.Assert.assertEquals("Eye of Ayak", out.get(0).getLoadout().getWeapon().getName());
		org.junit.Assert.assertNull("powered staff results carry no spell name",
			out.get(0).getSpellName());
		org.junit.Assert.assertTrue(out.get(0).getDps() > 0);
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Tables;
import net.runelite.api.Skill;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.EnumMap;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Stat simulation (ISS-01M5QY13K6YHTYDW1CCYD30CSY, Andrew 2026-10-24: "you
 * should be able to sim as any stat, defaulted to your current ones. lower
 * or higher should work too"; "max cape should automatically unlock the
 * fire/inferno, mage/ rage cape combo versions").
 */
class StatSimTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static Gear item(String name) {
		return data.getGearItems().stream()
			.filter(g -> g.getLname().equals(name) && g.isStandardGear() && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing " + name));
	}

	private static RequirementProfile profile(int attack) {
		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		levels.put(Skill.ATTACK, attack);
		levels.put(Skill.STRENGTH, 70);
		levels.put(Skill.DEFENCE, 70);
		levels.put(Skill.RANGED, 80);
		levels.put(Skill.MAGIC, 85);
		levels.put(Skill.PRAYER, 60);
		levels.put(Skill.HITPOINTS, 80);
		return new RequirementProfile(levels, Set.of());
	}

	@Test
	@DisplayName("a sim of 99 Attack over 70/70/70/80/85/60/80 keeps the other six; zero means your own")
	void aSimReplacesOnlyTheLevelsItNames() {
		Levels mine = new Levels(70, 70, 70, 80, 85, 60, 80);
		Levels simmed = mine.overridden(new int[]{99, 0, 0, 0, 0, 0, 0});
		assertEquals(99, simmed.getAttack());
		assertEquals(70, simmed.getStrength());
		assertEquals(80, simmed.getHitpoints());
		assertEquals(mine.toString(), mine.overridden(null).toString(), "no sim: your own levels");
		assertEquals(50, mine.overridden(new int[]{0, 0, 0, 0, 0, 0, 50}).getHitpoints(), "lower works too");
	}

	@Test
	@DisplayName("the requirement profile follows the sim: 60 Attack cannot wear the fang, simmed to 99 it can, back to 60 it cannot")
	void gearFollowsTheSim() {
		Gear fang = item("osmumten's fang");
		RequirementProfile sixty = profile(60);
		assertFalse(sixty.canEquip(fang.getRequirements()));
		Levels ninetyNine = Levels.from(sixty).overridden(new int[]{99, 0, 0, 0, 0, 0, 0});
		assertTrue(sixty.withLevels(ninetyNine).canEquip(fang.getRequirements()), "99 Attack admits the fang");
		assertFalse(sixty.withLevels(ninetyNine).withLevels(Levels.from(sixty)).canEquip(fang.getRequirements()), "and 60 drops it again");
		assertEquals(85, sixty.withLevels(ninetyNine).getLevels().get(Skill.MAGIC), "the other skills ride along unchanged");
	}

	@Test
	@DisplayName("max cape sims: with a fire cape owned the max cape and the fire max cape; with nothing, the max cape alone; an imbued Zamorak cape brings its imbued max cape")
	void maxCapeCombos() {
		int fireCape = item("fire cape").getId();
		int imbuedZamorak = item("imbued zamorak cape").getId();
		Set<String> withFire = names(MaxCapeSims.ids(data, id -> id == fireCape));
		assertEquals(Set.of("max cape", "fire max cape"), withFire);
		assertEquals(Set.of("max cape"), names(MaxCapeSims.ids(data, id -> false)));
		assertTrue(names(MaxCapeSims.ids(data, id -> id == imbuedZamorak)).contains("imbued zamorak max cape"));
	}

	private static Set<String> names(Set<Integer> ids) {
		return ids.stream().map(id -> data.getGear(id).getLname()).collect(Collectors.toSet());
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.data.Spell;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Kendyy (Discord 2026-10-19): "same goes for if you are using sunfire
 * runes or not". Wiki (Sunfire rune, read 2026-10-19): any successful
 * hit with an offensive fire spell deals a minimum of 10% of the max
 * hit. The official calc takes trunc(maxHit / 10) after the magic
 * damage pool and the elemental weakness and BEFORE the tome step, so
 * a charged tome of fire lifts the max hit without lifting the floor.
 */
class SunfireTest {
	private static Tables data;
	private static Monster araxxor;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		araxxor = data.searchMonsters("araxxor", 1).get(0);
		assertEquals("Araxxor", araxxor.getName());
		assertEquals("fire", araxxor.getWeaknessElement(), "the fixture needs a fire-weak target");
	}

	private static Spell spell(String name) {
		return data.getSpells().stream().filter(s -> s.getName().equalsIgnoreCase(name))
			.findFirst().orElseThrow(AssertionError::new);
	}

	private static Gear item(String lname, String ver) {
		return data.getGearItems().stream()
			.filter(g -> g.getLname().equals(lname)
				&& (ver == null ? g.isStandardGear() : g.getVer().equals(ver)))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing: " + lname));
	}

	/** A magic-damage set, so the fixture's max hits sit where the tenth
	 * is worth testing: Fire Wave reads 37 pre-tome and 40 with the tome
	 * (floors 3 and 4) - a bare wand gave 39 and 42, the same floor. */
	private static final String[] MAGIC_SET = {"kodai wand", "occult necklace",
		"tormented bracelet", "ancestral hat", "ancestral robe top", "ancestral robe bottom"};

	private static Dps cast(Spell spell, boolean sunfire, boolean fireTome) {
		EnumMap<Slot, Gear> gear = new EnumMap<>(Slot.class);
		for (String name : MAGIC_SET) {
			Gear piece = item(name, null);
			gear.put(piece.getSlot(), piece);
		}
		if (fireTome) {
			gear.put(Slot.SHIELD, item("tome of fire", "charged"));
		}
		Req request = new Req(
			araxxor, Style.MAGIC, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), spell, 0,
			CandidateMode.ALL_STANDARD, true, false,
			Owned.EMPTY, RequirementProfile.MAXED, 1).withSunfireRunes(sunfire);
		Dps result = new Calc().calculate(request, new Kit(gear));
		assertNotNull(result);
		return result;
	}

	@Test
	@DisplayName("sunfire runes give Fire Surge a minimum hit of a tenth of its max, priced uniform over [min, max]")
	void sunfireRunesRaiseTheFloor() {
		Dps plain = cast(spell("Fire Surge"), false, false);
		Dps sunfire = cast(spell("Fire Surge"), true, false);
		assertEquals(plain.getMaxHit(), sunfire.getMaxHit(), "the max hit is untouched");
		assertEquals(plain.getAccuracy(), sunfire.getAccuracy(), 1e-12, "accuracy is untouched");
		int min = sunfire.getMaxHit() / 10;
		assertTrue(min >= 1, "the fixture's max hit must be at least 10 for a floor to exist");
		assertEquals(sunfire.getAccuracy() * (min + sunfire.getMaxHit()) / 2.0,
			sunfire.getEh(), 1e-9, "a landed hit is uniform over [min, max]");
		assertTrue(sunfire.getDps() > plain.getDps(), "the floor raises the dps");
	}

	@Test
	@DisplayName("the floor is a tenth of the pre-tome max: a charged tome of fire lifts the max, not the minimum")
	void floorIsTakenBeforeTheTome() {
		Dps bare = cast(spell("Fire Wave"), true, false);
		Dps tome = cast(spell("Fire Wave"), true, true);
		assertTrue(tome.getMaxHit() > bare.getMaxHit(), "the charged fire tome adds damage");
		int floor = bare.getMaxHit() / 10;
		assertNotEquals(tome.getMaxHit() / 10, floor,
			"fixture guard: the post-tome tenth must differ or the ordering is untested");
		assertEquals(tome.getAccuracy() * (floor + tome.getMaxHit()) / 2.0,
			tome.getEh(), 1e-9, "the minimum is still the pre-tome tenth");
	}

	@Test
	@DisplayName("the flag does nothing to a water spell")
	void waterSpellsIgnoreTheFlag() {
		Dps plain = cast(spell("Water Surge"), false, false);
		Dps flagged = cast(spell("Water Surge"), true, false);
		assertEquals(plain.getDps(), flagged.getDps(), 1e-12);
		assertEquals(plain.getEh(), flagged.getEh(), 1e-12);
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.EnumMap;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * miko (Discord 2026-10-17) wanted the Expeditious bracelet in every
 * setup; Andrew made it a slayer-task option. The overlay turns the
 * preference into hands pins the optimizer already honours.
 */
class TaskBraceletTest {
	private static final Tables DATA = new DataService().load();
	private static final Monster DEMON = DATA.searchMonsters("abyssal demon", 1).get(0);
	private static final Monster ORCA = DATA.searchMonsters("orca", 1).get(0);

	private static final int EXPEDITIOUS = 21177;
	private static final int BARROWS_GLOVES = 7462;

	private static Map<Style, Map<Slot, Integer>> meleeHandsPinned() {
		EnumMap<Style, Map<Slot, Integer>> pins = new EnumMap<>(Style.class);
		EnumMap<Slot, Integer> melee = new EnumMap<>(Slot.class);
		melee.put(Slot.HANDS, BARROWS_GLOVES);
		pins.put(Style.MELEE, melee);
		return pins;
	}

	@Test
	@DisplayName("on task: every concrete style's hands slot is pinned to the bracelet")
	void onTaskPinsEveryStyle() {
		Map<Style, Map<Slot, Integer>> out =
			TaskBracelet.overlay(Map.of(), DEMON, true, TaskBracelet.EXPEDITIOUS_BRACELET);
		for (Style style : Style.concreteValues()) {
			assertEquals(EXPEDITIOUS, out.get(style).get(Slot.HANDS), style.name());
		}
	}

	@Test
	@DisplayName("the mob's own hands pin wins on its style; the others still get the bracelet")
	void mobPinWins() {
		Map<Style, Map<Slot, Integer>> in = meleeHandsPinned();
		Map<Style, Map<Slot, Integer>> out =
			TaskBracelet.overlay(in, DEMON, true, TaskBracelet.BRACELET_OF_SLAUGHTER);
		assertEquals(BARROWS_GLOVES, out.get(Style.MELEE).get(Slot.HANDS));
		assertEquals(21183, out.get(Style.RANGED).get(Slot.HANDS));
		assertEquals(21183, out.get(Style.MAGIC).get(Slot.HANDS));
		assertNull(in.get(Style.RANGED), "the input map must not be mutated");
	}

	@Test
	@DisplayName("a monster that is never a slayer task gets no bracelet, task param or not (Orca, 2026-10-18)")
	void nonSlayerMonsterIsUntouched() {
		Map<Style, Map<Slot, Integer>> in = meleeHandsPinned();
		assertFalse(ORCA.isSlayerMonster(), "the fixture needs a non-slayer monster");
		assertSame(in, TaskBracelet.overlay(in, ORCA, true, TaskBracelet.EXPEDITIOUS_BRACELET));
		assertSame(in, TaskBracelet.overlay(in, null, true, TaskBracelet.EXPEDITIOUS_BRACELET));
	}

	@Test
	@DisplayName("off task, or with None chosen, the pins pass through untouched")
	void offTaskOrNoneIsIdentity() {
		Map<Style, Map<Slot, Integer>> in = meleeHandsPinned();
		assertSame(in, TaskBracelet.overlay(in, DEMON, false, TaskBracelet.EXPEDITIOUS_BRACELET));
		assertSame(in, TaskBracelet.overlay(in, DEMON, true, TaskBracelet.NONE));
		assertSame(in, TaskBracelet.overlay(in, DEMON, true, null));
	}
}

package com.ll.engine;

import com.ll.data.Monster;
import com.ll.data.Spell;

/**
 * Test-only factory for the requirement-profile-less request shape. This
 * used to be an 11-arg convenience constructor on Req whose
 * only job was to supply {@link RequirementProfile#MAXED}, but no main-source
 * caller ever used it (Service always passes a profile explicitly),
 * so it lived on only for the tests while counting against the Plugin Hub's
 * main-source token cap. Moved here, where test sources are free.
 */
public final class TestRequests {
	private TestRequests() {
	}

	/** A request with the requirement profile defaulted to MAXED. */
	public static Req of(
		Monster monster,
		Style style,
		Levels levels,
		PrayerBonuses prayers,
		Spell spell,
		int budget,
		CandidateMode candidateMode,
		boolean includeUntradeables,
		boolean onSlayerTask,
		Owned oi,
		int resultLimit) {
		return new Req(
			monster,
			style,
			levels,
			prayers,
			spell,
			budget,
			candidateMode,
			includeUntradeables,
			onSlayerTask,
			oi,
			RequirementProfile.MAXED,
			resultLimit);
	}
}

package com.ll.engine;

import com.ll.data.DataService;
