import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Vampyre maths at parity with the official calculator's engine
 * (ISS-01M5RM2A7FFR9XWKATPX877TDD; osrs-dps-calc 89c3e25b PlayerVsNPCCalc
 * vampyre accuracy, damage, tier-2 transforms and immunity; PR #671). Each
 * vampyre is compared with its own twin minus the vampyre attribute, so the
 * expected numbers come from the same set's plain max hit and roll.
 */
class VampyreParityTest {
	private static final int SENTINEL = 9756;
	/** Any loaded juvinate: the loader folds combat-identical versions. */
	private static final int JUVINATE = -2;
	private static final int FERAL = 3237;
	private static final int EFARITAY = 21140;
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static Monster monster(int id) {
		return data.getMonsters().stream()
			.filter(m -> id == JUVINATE ? m.getLname().equals("vampyre juvinate") && m.hasAttribute("vampyre2")
				: m.getId() == id)
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing monster " + id));
	}

	/** The same monster without its vampyre tier: the plain baseline. */
	private static Monster plain(int id) {
		Monster m = monster(id);
		return m.withoutAttributes(-m.getId(), m.getVersion(), List.of("vampyre1", "vampyre2", "vampyre3"));
	}

	private static Gear named(String name) {
		return data.getGearItems().stream()
			.filter(g -> g.getLname().equals(name) && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing " + name));
	}

	private static Kit wearing(Object... items) {
		Map<Slot, Gear> gear = new EnumMap<>(Slot.class);
		for (Object item : items) {
			Gear g = item instanceof Integer ? data.getGear((Integer) item) : named((String) item);
			gear.put(g.getSlot(), g);
		}
		return new Kit(gear);
	}

	private static Dps calc(Monster monster, Style style, Levels levels, PrayerBonuses prayers,
		Spell spell, Kit loadout) {
		Req request = new Req(monster, style, levels, prayers, spell, 0,
			CandidateMode.ALL_STANDARD, true, false, Owned.EMPTY, RequirementProfile.MAXED, 1);
		return new Calc().calculate(request, loadout);
	}

	private static Dps melee(Monster monster, Kit loadout) {
		return calc(monster, Style.MELEE, Levels.MAXED, PrayerBonuses.bestAvailable(Levels.MAXED),
			null, loadout);
	}

	/** Expected damage per attack of one uniform hit 0..max at this
	 * accuracy, each roll mapped through the transform. */
	private static double expected(double accuracy, int max, IntUnaryOperator perHit) {
		double sum = 0;
		for (int d = 0; d <= max; d++) {
			sum += perHit.applyAsInt(d);
		}
		return accuracy * sum / (max + 1);
	}

	@Test
	@DisplayName("the reference's own sentinel case: blisterwood stakes max 26, and 28 with Efaritay's aid")
	void referenceStakeCase() {
		Levels levels = new Levels(99, 99, 99, 112, 99, 99, 99);
		PrayerBonuses deadeye = PrayerBonuses.forPick(Style.RANGED, "Deadeye", PrayerBonuses.bestAvailable(levels));
		Object[] set = {11664, 22109, 19547, 33716, 13072, 13073, 8842, 19933};
		Dps without = calc(monster(SENTINEL), Style.RANGED, levels, deadeye, null, wearing(set));
		Object[] withRing = java.util.Arrays.copyOf(set, set.length + 1);
		withRing[set.length] = EFARITAY;
		Dps with = calc(monster(SENTINEL), Style.RANGED, levels, deadeye, null, wearing(withRing));
		assertNotNull(without, "the stake hurts a tier-3 vampyre");
		assertEquals(26, without.getMaxHit());
		assertEquals(28, with.getMaxHit());
	}

	@Test
	@DisplayName("the hallowed flail vs a sentinel: roll x1.25, then x23/20 with Efaritay's aid; max x1.25, the ring's x1.1 first")
	void hallowedFlailVsSentinel() {
		Dps base = melee(plain(SENTINEL), wearing("hallowed flail"));
		Dps bane = melee(monster(SENTINEL), wearing("hallowed flail"));
		Dps ring = melee(monster(SENTINEL), wearing("hallowed flail", EFARITAY));
		int max = base.getMaxHit();
		long roll = base.getAr();
		assertEquals(max * 125 / 100, bane.getMaxHit());
		assertEquals(roll * 125 / 100, bane.getAr());
		assertEquals((max * 11 / 10) * 125 / 100, ring.getMaxHit());
		assertEquals((roll * 125 / 100) * 23 / 20, ring.getAr());
	}

	@Test
	@DisplayName("the blisterwood flail and sickle get +5% accuracy and their own damage; the Ivandis flail damage only")
	void flailAndSickleBonuses() {
		for (Object[] row : new Object[][]{{"blisterwood flail", 105, 125}, {"blisterwood sickle", 105, 115},
			{"ivandis flail", 100, 120}}) {
			String name = (String) row[0];
			Dps base = melee(plain(SENTINEL), wearing(name));
			Dps bane = melee(monster(SENTINEL), wearing(name));
			assertEquals(base.getAr() * (int) row[1] / 100, bane.getAr(), name + " roll");
			assertEquals(base.getMaxHit() * (int) row[2] / 100, bane.getMaxHit(), name + " max");
		}
	}

	@Test
	@DisplayName("a juvinate: a whip is immune, Efaritay's aid halves every hit (the raised accurate 0 too)")
	void tierTwoRegularWeapon() {
		assertNull(melee(monster(JUVINATE), wearing("abyssal whip")), "regular weapons cannot hurt tier 2");
		Dps base = melee(plain(JUVINATE), wearing("abyssal whip"));
		Dps ring = melee(monster(JUVINATE), wearing("abyssal whip", EFARITAY));
		assertNotNull(ring);
		assertEquals(base.getMaxHit() / 2, ring.getMaxHit());
		double perAttack = expected(ring.getAccuracy(), base.getMaxHit(), d -> Math.max(1, d) / 2);
		assertEquals(perAttack / (ring.getAttackSpeed() * 0.6), ring.getDps(), 1e-9);
	}

	@Test
	@DisplayName("a juvinate: silver weapons cap at 10 (halved with the ring), the Ivandis flail x1.2 then capped, the sunspear x1.5 uncapped")
	void tierTwoSilverAndBane() {
		int silverlight = melee(plain(JUVINATE), wearing("silverlight")).getMaxHit();
		assertEquals(Math.min(silverlight, 10), melee(monster(JUVINATE), wearing("silverlight")).getMaxHit());
		assertEquals(silverlight / 2, melee(monster(JUVINATE), wearing("silverlight", EFARITAY)).getMaxHit());
		int ivandis = melee(plain(JUVINATE), wearing("ivandis flail")).getMaxHit();
		assertEquals(Math.min(ivandis * 6 / 5, 10), melee(monster(JUVINATE), wearing("ivandis flail")).getMaxHit());
		int sunspear = melee(plain(JUVINATE), wearing("sunspear")).getMaxHit();
		assertEquals(sunspear * 150 / 100, melee(monster(JUVINATE), wearing("sunspear")).getMaxHit());
		assertEquals(Math.min(melee(plain(JUVINATE), wearing("blisterwood sickle (e)")).getMaxHit(), 10),
			melee(monster(JUVINATE), wearing("blisterwood sickle (e)")).getMaxHit(), "the (e) sickle is tier-2 silver");
		assertNull(melee(monster(SENTINEL), wearing("blisterwood sickle (e)")), "and no tier-3 weapon");
	}

	@Test
	@DisplayName("a juvinate: silver bolts let a crossbow through, capped at 10; other bolts are immune; magic needs the ring")
	void tierTwoRangedAndMagic() {
		PrayerBonuses best = PrayerBonuses.bestAvailable(Levels.MAXED);
		int bolts = calc(plain(JUVINATE), Style.RANGED, Levels.MAXED, best, null,
			wearing("rune crossbow", 9145)).getMaxHit();
		assertEquals(Math.min(bolts, 10), calc(monster(JUVINATE), Style.RANGED, Levels.MAXED, best, null,
			wearing("rune crossbow", 9145)).getMaxHit());
		assertNull(calc(monster(JUVINATE), Style.RANGED, Levels.MAXED, best, null,
			wearing("rune crossbow", "adamant bolts")));
		Spell bolt = data.getSpells().stream().filter(s -> s.getName().equals("Fire Bolt")).findFirst().get();
		assertNull(calc(monster(JUVINATE), Style.MAGIC, Levels.MAXED, best, bolt, wearing("staff of fire")));
		int spell = calc(plain(JUVINATE), Style.MAGIC, Levels.MAXED, best, bolt, wearing("staff of fire")).getMaxHit();
		assertEquals(spell / 2, calc(monster(JUVINATE), Style.MAGIC, Levels.MAXED, best, bolt,
			wearing("staff of fire", EFARITAY)).getMaxHit());
	}

	@Test
	@DisplayName("a tier-1 vampyre: silverlight x1.1 (x1.1 again and +15% accuracy with the ring); a whip unchanged, ring or not")
	void tierOne() {
		Dps base = melee(plain(FERAL), wearing("silverlight"));
		assertEquals(base.getMaxHit() * 11 / 10, melee(monster(FERAL), wearing("silverlight")).getMaxHit());
		Dps ring = melee(monster(FERAL), wearing("silverlight", EFARITAY));
		assertEquals((base.getMaxHit() * 11 / 10) * 11 / 10, ring.getMaxHit());
		assertEquals(base.getAr() * 23 / 20, ring.getAr());
		int whip = melee(plain(FERAL), wearing("abyssal whip")).getMaxHit();
		assertEquals(whip, melee(monster(FERAL), wearing("abyssal whip")).getMaxHit());
		assertEquals(whip, melee(monster(FERAL), wearing("abyssal whip", EFARITAY)).getMaxHit());
	}

	@Test
	@DisplayName("the optimizer pairs an owned whip with an owned Efaritay's aid vs a juvinate, and finds nothing without the ring")
	void optimizerFindsTheRing() {
		Owned both = new Owned(Map.of(4151, 1, EFARITAY, 1), true);
		Req request = new Req(monster(JUVINATE), Style.MELEE, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), null, 0, CandidateMode.OWNED_ONLY, true, false, both,
			RequirementProfile.MAXED, 5);
		List<Dps> sets = new LoadoutOptimizer().optimize(data, request);
		assertFalse(sets.isEmpty(), "the ring makes the whip work");
		Gear ring = sets.get(0).getLoadout().get(Slot.RING);
		assertNotNull(ring, "the set wears a ring");
		assertEquals("Efaritay's aid", ring.getName());
		assertEquals("Abyssal whip", sets.get(0).getLoadout().getWeapon().getName());
		Req whipOnly = new Req(monster(JUVINATE), Style.MELEE, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), null, 0, CandidateMode.OWNED_ONLY, true, false,
			new Owned(Map.of(4151, 1), true), RequirementProfile.MAXED, 5);
		assertTrue(new LoadoutOptimizer().optimize(data, whipOnly).isEmpty(), "and nothing works without it");
	}

	@Test
	@DisplayName("Efaritay's aid stays in the ring pool vs a vampyre")
	void ringPoolKeepsEfaritay() {
		Req request = new Req(monster(SENTINEL), Style.MELEE, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), null, 0, CandidateMode.ALL_STANDARD, true, false,
			Owned.EMPTY, RequirementProfile.MAXED, 1);
		assertTrue(new LoadoutOptimizer().preparePools(data, request).slotCandidates.get(Slot.RING).stream()
			.anyMatch(g -> g != null && g.getId() == EFARITAY));
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class VampyreRulesTest {
	private static Tables data;

	private static Tables data() {
		if (data == null) {
			data = new DataService().load();
		}
		return data;
	}

	private static Monster monster(String query) {
		return data().searchMonsters(query, 1).get(0);
	}

	private static Gear byName(String name) {
		return data().getGearItems().stream()
			.filter(g -> g.getName().equalsIgnoreCase(name))
			.findFirst()
			.orElseThrow(() -> new AssertionError("missing item: " + name));
	}

	@Test
	public void regularWeaponsCannotDamageVyrewatchSentinels() {
		Monster sentinel = monster("vyrewatch sentinel");
		Assert.assertTrue(sentinel.hasAttribute("vampyre3"));
		Assert.assertFalse(VampyreRules.canDamage(sentinel, Style.MELEE, byName("Abyssal whip")));
		Assert.assertTrue(VampyreRules.canDamage(sentinel, Style.MELEE, byName("Blisterwood flail")));
		Assert.assertTrue(VampyreRules.canDamage(sentinel, Style.MELEE, byName("Ivandis flail")));
	}

	@Test
	public void optimizerNeverSuggestsNonVyreWeaponsAgainstSentinels() {
		Monster sentinel = monster("vyrewatch sentinel");
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1); // abyssal whip - must NOT be suggested
		Req request = new Req(
			sentinel,
			Style.MELEE,
			Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED),
			null,
			0,
			CandidateMode.OWNED_ONLY,
			true,
			false,
			new Owned(owned, true),
			RequirementProfile.MAXED,
			5);
		Assert.assertTrue("a whip cannot hit a tier-3 vampyre",
			new LoadoutOptimizer().optimize(data(), request).isEmpty());
	}

	@Test
	public void gameBestAgainstSentinelsUsesAVyreWeapon() {
		Monster sentinel = monster("vyrewatch sentinel");
		Req request = new Req(
			sentinel,
			Style.MELEE,
			Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED),
			null,
			0,
			CandidateMode.ALL_STANDARD,
			true,
			false,
			Owned.EMPTY,
			RequirementProfile.MAXED,
			1);
		List<Dps> results = new LoadoutOptimizer().optimize(data(), request);
		Assert.assertFalse(results.isEmpty());
		String weapon = results.get(0).getLoadout().getWeapon().getName().toLowerCase();
		Assert.assertTrue("expected a vyre-baneful weapon, got: " + weapon,
			VampyreRules.canDamage(sentinel, Style.MELEE, results.get(0).getLoadout().getWeapon()));
	}

	@Test
	public void tormentedDemonRangedBisUsesRealStatGearDespiteGuaranteedHits() {
		// Vs guaranteed-hit monsters all accuracy gear ties on DPS; the
		// attack-roll tie-break must still pick the strongest gear, and the
		// Avernic treads combos (wrongly non-standard upstream) must be in.
		Monster td = data().searchMonsters("tormented demon", 1).get(0);
		Req request = new Req(
			td, Style.RANGED, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			Owned.EMPTY, RequirementProfile.MAXED, 1);
		Dps best = new LoadoutOptimizer().optimize(data(), request).get(0);
		Gear feet = best.getLoadout().get(com.ll.data.Slot.FEET);
		Gear hands = best.getLoadout().get(com.ll.data.Slot.HANDS);
		Assert.assertNotNull(feet);
		Assert.assertTrue("expected avernic treads, got " + feet.getName(),
			feet.getName().toLowerCase().startsWith("avernic treads"));
		Assert.assertNotNull(hands);
		Assert.assertEquals("Zaryte vambraces", hands.getName());
	}

	/** The 2026-07-05 rule halved non-silver weapons vs tier 2; the
	 * official calc makes them immune unless Efaritay's aid is worn
	 * (ISS-01M5RM2A7FFR9XWKATPX877TDD - VampyreParityTest pins the maths). */
	@Test
	public void juvinatesNeedSilverAVampyrebaneWeaponOrEfaritaysAid() {
		Monster juvinate = monster("vampyre juvinate");
		Assert.assertTrue(juvinate.hasAttribute("vampyre2"));
		Assert.assertTrue(VampyreRules.immune(juvinate, Style.MELEE, wearing("Abyssal whip")));
		Assert.assertFalse(VampyreRules.immune(juvinate, Style.MELEE, wearing("Abyssal whip", "Efaritay's aid")));
		Assert.assertFalse(VampyreRules.immune(juvinate, Style.MELEE, wearing("Blisterwood flail")));
		Assert.assertFalse(VampyreRules.immune(juvinate, Style.MELEE, wearing("Silverlight")));
		// Tier 1 and normal monsters: anything lands.
		Assert.assertFalse(VampyreRules.immune(monster("feral vampyre"), Style.MELEE, wearing("Abyssal whip")));
		Assert.assertFalse(VampyreRules.immune(monster("goblin"), Style.MELEE, wearing("Abyssal whip")));
	}

	private static Kit wearing(String... names) {
		Map<com.ll.data.Slot, Gear> gear = new java.util.EnumMap<>(com.ll.data.Slot.class);
		for (String name : names) {
			Gear item = byName(name);
			gear.put(item.getSlot(), item);
		}
		return new Kit(gear);
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Vanstrom Klause in Sins of the Father (ISS-01M5RGMT70PG86MWHPF28DBJ3V,
 * raw on Discord 2026-10-24: "it tells me no usable melee set but I was
 * expecting it to tell me to use my blisterwood flail as the quest needs
 * you to defeat him with it"). The wiki files the flails and the rod of
 * Ivandis as one-handed staves that fight in melee (Bash/Pound/Focus,
 * crush); "no spells are capable of dealing damage to vampyres", and the
 * reference calculator makes a tier-3 vampyre immune to anything but a
 * melee flail/sickle/sunspear or a thrown blisterwood stake.
 */
class VanstromFlailTest {
	private static final int VANSTROM_SOTF = 9567;
	private static final int BLISTERWOOD_FLAIL = 24699;
	private static final int STAFF_OF_FIRE = 1387;
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static Monster vanstrom() {
		return data.searchMonsters("vanstrom klause", 10).stream()
			.filter(m -> m.getId() == VANSTROM_SOTF).findFirst()
			.orElseThrow(() -> new AssertionError("corpus is missing Vanstrom Klause (Sins of the Father)"));
	}

	private static Gear named(String name) {
		return data.getGearItems().stream()
			.filter(g -> g.getLname().equals(name) && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing " + name));
	}

	/** An ironman mid-quest: 70s in combat, Sins of the Father not finished. */
	private static Req request(Style style, CandidateMode mode, Map<Integer, Integer> owned) {
		Levels levels = new Levels(70, 70, 70, 70, 70, 52, 70);
		RequirementProfile profile = new RequirementProfile(Map.of(Skill.ATTACK, 70, Skill.STRENGTH, 70,
			Skill.DEFENCE, 70, Skill.RANGED, 70, Skill.MAGIC, 70, Skill.PRAYER, 52, Skill.HITPOINTS, 70), Set.of());
		return new Req(vanstrom(), style, levels, PrayerBonuses.bestAvailable(levels), null, 0,
			mode, true, false, new Owned(owned, true), profile, 5);
	}

	@Test
	@DisplayName("the blisterwood flail, the Ivandis flail and the rod of Ivandis fight in melee; a plain staff still does not")
	void vampyreStavesAreMeleeWeapons() {
		for (String name : List.of("blisterwood flail", "ivandis flail", "rod of ivandis")) {
			assertTrue(named(name).isWeaponFor(Style.MELEE), name + " fights in melee");
		}
		assertTrue(named("blisterwood flail").isWeaponFor(Style.MAGIC), "and the flail still autocasts");
		assertFalse(named("staff of fire").isWeaponFor(Style.MELEE), "an ordinary staff stays out of melee");
	}

	@Test
	@DisplayName("an ironman owning the blisterwood flail gets a melee set for Vanstrom (Sins of the Father) that wields it")
	void ironmanMeleeSetWieldsTheFlail() {
		List<Dps> melee = new LoadoutOptimizer().optimize(data,
			request(Style.MELEE, CandidateMode.OWNED_ONLY, Map.of(BLISTERWOOD_FLAIL, 1)));
		assertFalse(melee.isEmpty(), "a melee set exists");
		assertEquals("Blisterwood flail", melee.get(0).getLoadout().getWeapon().getName());
		assertTrue(melee.get(0).getDps() > 0);
	}

	@Test
	@DisplayName("no spell damages a tier-3 vampyre: magic has no set vs Vanstrom, owned flail or best in slot")
	void magicCannotHurtVanstrom() {
		assertTrue(new LoadoutOptimizer().optimize(data, request(Style.MAGIC, CandidateMode.OWNED_ONLY,
			Map.of(BLISTERWOOD_FLAIL, 1, STAFF_OF_FIRE, 1))).isEmpty(), "the flail cannot autocast past the immunity");
		assertTrue(new LoadoutOptimizer().optimize(data, request(Style.MAGIC, CandidateMode.ALL_STANDARD,
			Map.of())).isEmpty(), "nor can any staff in the game");
		Monster vanstrom = vanstrom();
		assertFalse(VampyreRules.canDamage(vanstrom, Style.MAGIC, named("blisterwood flail")));
		assertTrue(VampyreRules.canDamage(vanstrom, Style.MELEE, named("blisterwood flail")));
		assertTrue(VampyreRules.canDamage(vanstrom, Style.RANGED, named("blisterwood stake")));
		assertFalse(VampyreRules.canDamage(vanstrom, Style.MELEE, named("abyssal whip")));
	}
}

package com.ll.engine;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Wiki (Venator bow, read 2026-10-19): in a multi area the arrow bounces
 * up to twice; each bounce rolls its own accuracy with a max hit of
 * two-thirds of the first, floored. Accuracy cancels, so the chain is
 * worth 1 + 2 x E(floor(2m/3)) / E(m) single hits.
 */
class VenatorFactorTest {
	@Test
	@DisplayName("a 30 max hit chains to about 2.34 single hits: 20-max bounces at the same accuracy")
	void thirtyMax() {
		double e30 = 30 / 2.0 + 1.0 / 31;
		double e20 = 20 / 2.0 + 1.0 / 21;
		assertEquals(1 + 2 * e20 / e30, RollMath.venatorFactor(30), 1e-12);
		assertEquals(2.337, RollMath.venatorFactor(30), 0.001);
	}

	@Test
	@DisplayName("the bounce max floors (31 -> 20) and a zero max hit chains nothing")
	void flooringAndZero() {
		double e31 = 31 / 2.0 + 1.0 / 32;
		double e20 = 20 / 2.0 + 1.0 / 21;
		assertEquals(1 + 2 * e20 / e31, RollMath.venatorFactor(31), 1e-12);
		assertEquals(1.0, RollMath.venatorFactor(0), 1e-12);
	}

	@Test
	@DisplayName("the tool factors: area tools scale with the stack up to nine, the chain needs a second target")
	void toolFactors() {
		assertEquals(3, MultiTool.factor("area", 3, 30), 1e-12);
		assertEquals(9, MultiTool.factor("area", 12, 30), 1e-12);
		assertEquals(1, MultiTool.factor("area", 1, 30), 1e-12);
		assertEquals(1, MultiTool.factor("chain", 1, 30), 1e-12);
		assertEquals(RollMath.venatorFactor(30), MultiTool.factor("chain", 5, 30), 1e-12);
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Void's set value lives entirely in the DPS model - the pieces carry
 * ~zero raw stats, so without pool seeding the zero-score prune dropped
 * the helm/gloves and a stocked bank's top-N cut dropped the top/robe:
 * the set could never assemble for a well-geared account (field question
 * 2026-07-17). These tests pin the seeding and the set math, including
 * the previously missing elite magic void damage.
 */
class VoidSetTest {
	private static Tables data;
	private static Monster ankou;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		ankou = data.searchMonsters("ankou", 1).get(0);
	}

	private static Gear byId(int id) {
		Gear item = data.getGear(id);
		assertNotNull(item, "corpus is missing item " + id);
		return item;
	}

	private static Req request(Style style) {
		return new Req(ankou, style, Levels.MAXED,
			PrayerBonuses.NONE, null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			Owned.EMPTY, RequirementProfile.MAXED, 1);
	}

	@Test
	@DisplayName("every void piece is seeded into its style's candidate pool")
	void voidPiecesScoreIntoThePool() {
		// The shared pieces enter every style's pool; each helm only its own.
		int[] shared = {8839, 8840, 8842, 13072, 13073}; // top, robe, gloves, elite top, elite robe
		for (Style style : new Style[]{Style.MELEE, Style.RANGED, Style.MAGIC}) {
			for (int id : shared) {
				assertTrue(LoadoutOptimizer.candidateScore(request(style), byId(id), false) > 0,
					"piece " + id + " must be seeded for " + style);
			}
		}
		assertTrue(LoadoutOptimizer.candidateScore(request(Style.RANGED), byId(11664), false) > 0,
			"ranger helm seeds the ranged pool");
		assertTrue(LoadoutOptimizer.candidateScore(request(Style.MAGIC), byId(11663), false) > 0,
			"mage helm seeds the magic pool");
		assertTrue(LoadoutOptimizer.candidateScore(request(Style.MELEE), byId(11665), false) > 0,
			"melee helm seeds the melee pool");
		// The off-style helm stays unseeded (zero score - pruned).
		assertEquals(0.0, LoadoutOptimizer.candidateScore(request(Style.MELEE), byId(11664), false),
			1e-9, "ranger helm has no business in the melee pool");
	}

	@Test
	@DisplayName("elite magic void grants +2.5% magic damage on top of the 45% accuracy")
	void eliteMagicVoidDamage() {
		Dps regular = calcMagic(8839, 8840); // regular top + robe
		Dps elite = calcMagic(13072, 13073); // elite top + robe
		assertTrue(regular.getMaxHit() > 0);
		assertEquals((int) Math.floor(regular.getMaxHit() * 1.025), elite.getMaxHit(),
			"elite = floor(regular x 1.025)");
	}

	private Dps calcMagic(int topId, int robeId) {
		com.ll.data.Spell surge = data.getSpells().stream()
			.filter(sp -> sp.getName().equalsIgnoreCase("Fire Surge"))
			.findFirst().orElseThrow(() -> new AssertionError("no Fire Surge"));
		EnumMap<Slot, Gear> gear = new EnumMap<>(Slot.class);
		gear.put(Slot.WEAPON, byName("kodai wand"));
		gear.put(Slot.HEAD, byId(11663));
		gear.put(Slot.BODY, byId(topId));
		gear.put(Slot.LEGS, byId(robeId));
		gear.put(Slot.HANDS, byId(8842));
		return new Calc().calculate(
			request(Style.MAGIC).withSpell(surge), new Kit(gear));
	}

	private static Gear byName(String lname) {
		for (Gear item : data.getGearItems()) {
			if (item.getLname().equals(lname)) {
				return item;
			}
		}
		throw new AssertionError("corpus is missing: " + lname);
	}
}

