import static org.junit.jupiter.api.Assertions.*;

/**
 * Andrew, 2026-10-26: "superantifire and no shield reuqires protection from
 * magic to prevent the full damage of magical attacks". The wiki's Vorkath
 * dragonfire table (failed roll): unprotected 80, shield 20, PfM 30, antifire
 * 70, super antifire 60, shield + antifire 10, shield + super 0, PfM +
 * antifire 20, PfM + super 10.
 */
class VorkathDragonfireTest {
	private static Tables data;
	private static Monster vorkath;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		vorkath = data.getMonsters().stream().filter(m -> m.getName().equals("Vorkath"))
			.findFirst().orElseThrow(AssertionError::new);
	}

	private static Kit wearing(String shield) {
		EnumMap<Slot, Gear> gear = new EnumMap<>(Slot.class);
		if (shield != null) {
			gear.put(Slot.SHIELD, data.getGearItems().stream()
				.filter(g -> g.getLname().equals(shield) && g.isStandardGear())
				.findFirst().orElseThrow(AssertionError::new));
		}
		return new Kit(gear);
	}

	private static Incoming.StyleThreat dragonfire(Incoming.Result result) {
		return result.threats.stream().filter(t -> t.style.toLowerCase().contains("dragonfire"))
			.findFirst().orElseThrow(() -> new AssertionError("no dragonfire row"));
	}

	@Test
	@DisplayName("super antifire without a shield prays Magic: the dragonfire's 60 comes down to 10")
	void superAntifireNoShieldPraysMagic() {
		Incoming.Result r = Incoming.calculate(vorkath, wearing(null), 99, 99, 2);
		assertEquals("Protect from Magic", r.protectPrayer);
		Incoming.StyleThreat fire = dragonfire(r);
		assertEquals(60, fire.maxHit);
		assertTrue(fire.blocked);
		assertEquals(10.0 / 60, fire.prayerFactor, 1e-9);
	}

	@Test
	@DisplayName("super antifire with an anti-dragon shield: no dragonfire damage, Protect from Missiles")
	void superAntifireWithShield() {
		Incoming.Result r = Incoming.calculate(vorkath, wearing("anti-dragon shield"), 99, 99, 2);
		assertEquals(0, dragonfire(r).maxHit);
		assertEquals("Protect from Missiles", r.protectPrayer);
	}

	@Test
	@DisplayName("antifire with a shield: 10 under either prayer, Protect from Missiles")
	void antifireWithShield() {
		Incoming.Result r = Incoming.calculate(vorkath, wearing("anti-dragon shield"), 99, 99, 1);
		Incoming.StyleThreat fire = dragonfire(r);
		assertEquals(10, fire.maxHit);
		assertFalse(fire.blocked);
		assertEquals("Protect from Missiles", r.protectPrayer);
	}

	@Test
	@DisplayName("a shield and no potion: the dragonfire hits up to 20")
	void shieldOnly() {
		assertEquals(20, dragonfire(Incoming.calculate(vorkath, wearing("anti-dragon shield"), 99, 99, 0)).maxHit);
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The Wardens' ejected core (ToA P2, wiki-verified 2026-08-06): "Players
 * will always deal their max hit when using melee against the Warden's
 * core" - no accuracy roll, no damage roll. The certainty is the whole
 * reason the phase is a spec dump (field report 2026-08-06: "ToA is
 * missing the crucial heart phase with the DDS spec").
 */
class WardenCoreTest {
	private static Tables data;
	private static Monster core;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		core = data.searchMonsters("tumeken's warden", 8).stream()
			.filter(m -> m.getVersion().startsWith("Core-ejected"))
			.findFirst().orElseThrow();
		assertTrue(MonsterMechanics.isWardenCore(core), "test premise: the core row");
		assertEquals(1, core.getSize(), "the ejected core is a 1x1 target - the"
			+ " Warden-frame size 5 handed the chally sweep a phantom second hit"
			+ " (field report 2026-08-06)");
	}

	private static Gear byName(String lname) {
		for (Gear item : data.getGearItems()) {
			if (item.getLname().equals(lname)) {
				return item;
			}
		}
		throw new AssertionError("corpus is missing: " + lname);
	}

	private static Kit wielding(String lname) {
		EnumMap<Slot, Gear> gear = new EnumMap<>(Slot.class);
		gear.put(Slot.WEAPON, byName(lname));
		return new Kit(gear);
	}

	private static Req req(Monster monster) {
		return TestRequests.of(monster,
			Style.MELEE, Levels.MAXED, PrayerBonuses.NONE, null, 0,
			CandidateMode.ALL_STANDARD, true, false, Owned.EMPTY, 1);
	}

	@Test
	@DisplayName("melee at the core always deals its max: accuracy 1, expectation = max")
	void meleeAlwaysMaxes() {
		Dps whip = new Calc().calculate(req(core), wielding("abyssal whip"));
		assertNotNull(whip);
		assertEquals(1.0, whip.getAccuracy(), 1e-9, "no accuracy roll at the core");
		assertEquals(whip.getMaxHit(), whip.getEh(), 1e-9,
			"no damage roll either - every hit is the max");
		assertEquals(whip.getMaxHit() / (whip.getAttackSpeed() * 0.6),
			whip.getDps(), 1e-9);
		assertTrue(whip.getCountedBonuses().stream().anyMatch(b -> b.contains("core")),
			"the certainty must be a COUNTED assumption, visible in the assurance line");
	}

	@Test
	@DisplayName("the DDS spec prices as both boosted hits at max - the classic dump")
	void ddsSpecIsTwoMaxHits() {
		Dps base = new Calc().calculate(req(core), wielding("dragon dagger"));
		assertNotNull(base);
		SpecialAttack spec = SpecialAttack.match(byName("dragon dagger"));
		assertNotNull(spec, "the corpus must carry the DDS spec");
		double expected = spec.expectedDamage(base, core, Levels.MAXED);
		assertEquals(2.0 * (int) (base.getMaxHit() * 1.15), expected, 1e-9,
			"two independent hits, both at their boosted max, both landing");
	}

	@Test
	@DisplayName("the always-max rule stays at the core - a goblin still rolls normally")
	void ruleIsScopedToTheCore() {
		Monster goblin = data.searchMonsters("goblin", 1).get(0);
		Dps base = new Calc().calculate(req(goblin), wielding("dragon dagger"));
		assertNotNull(base);
		SpecialAttack spec = SpecialAttack.match(byName("dragon dagger"));
		double expected = spec.expectedDamage(base, goblin, Levels.MAXED);
		assertTrue(expected < 2.0 * (int) (base.getMaxHit() * 1.15),
			"away from the core the rolls are real again");
	}

}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * The Whisperer's damage taken under standard play + leak
 * (ISS-01M5PBSZBBBAS9Y46X04MVMHZB, Andrew 2026-10-24: "i'd love the standard
 * play + leak"): the coloured volleys are prayed on cue and leak a tenth, the
 * melee binds land through prayer, tentacles / Screech / Soul Siphon stay
 * dodged, and the card's max hit is one hit (42), never the pair (84).
 */
class WhispererIncomingTest {
	@Test
	@DisplayName("the Whisperer prays on cue: the leaked projectiles and the melee binds are the damage, the specials stay dodged, the max hit reads 42")
	void standardPlayPlusLeak() {
		Tables data = new DataService().load();
		// The loader drops the "Post-quest" label: the 900-hp row is the bare fight.
		Monster whisperer = data.searchMonsters("the whisperer", 10).stream()
			.filter(m -> m.getName().equals("The Whisperer") && m.getHitpoints() == 900).findFirst()
			.orElseThrow(() -> new AssertionError("no 900-hp Whisperer in the corpus"));
		Incoming.Result result = Incoming.calculate(whisperer, new Kit(Map.of()), 99, 99, 0);

		assertEquals(Incoming.CURATED, result.coverage);
		assertNotNull(result.protectPrayer);
		assertTrue(result.protectPrayer.endsWith("on cue"), result.protectPrayer);
		assertTrue(result.tot > 0 && result.tot < result.unprayedDps,
			result.tot + " prayed vs " + result.unprayedDps + " unprayed");

		boolean volley = false, bind = false, tentacles = false;
		double counted = 0;
		for (Incoming.StyleThreat threat : result.threats) {
			if (threat.style.startsWith("ranged volley")) {
				volley = true;
				assertTrue(threat.style.contains("on cue"), threat.style);
				assertEquals(0.1, threat.prayerFactor, 1e-9, "a tenth of the volley lands");
				assertEquals(40, threat.maxHit);
			}
			if (threat.style.startsWith("melee (x2)")) {
				bind = true;
				assertEquals(42, threat.maxHit, "one hit of the pair, not 84");
				assertTrue(threat.prayerFactor > 0.1 && threat.prayerFactor < 1, "the second hit pierces: " + threat.prayerFactor);
			}
			if (threat.style.startsWith("shadow tentacles")) {
				tentacles = true;
				assertTrue(threat.style.contains("avoidable"), threat.style);
			}
			if (threat.modeled && !threat.style.contains("avoidable")) {
				counted += threat.dps * threat.share * threat.prayerFactor;
			}
		}
		assertTrue(volley && bind && tentacles, "volley " + volley + " bind " + bind + " tentacles " + tentacles);
		assertEquals(result.tot, counted, 1e-6, "the total is exactly the counted rows");
	}
}

package com.ll.engine;

