import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.EnumMap;
import org.junit.Assert;
import org.junit.Test;

/**
 * Zorya's tome special (wiki, 2026-10-20): a cast at +150% accuracy and
 * +60% damage; if it lands, the next three casts carry the same buff and
 * fire every two ticks. The energy cost is unpublished: 50% assumed (the
 * Gatekeeper's Cane proposal's cost; the blog changed the buff, not it).
 */
public class ZoryaSpecTest {
	@Test
	public void aLandedSpecBuysThreeBuffedCastsAndTheirTime() {
		Tables data = new DataService().load();
		Gear tome = data.getGear(34725);
		SpecialAttack spec = SpecialAttack.match(tome, Style.MAGIC);
		Assert.assertNotNull(spec);
		Assert.assertEquals(SpecialAttack.Kind.BUFFED_FOLLOWUPS, spec.getKind());
		Assert.assertEquals(50, spec.getEnergyCost());
		Monster goblin = data.searchMonsters("goblin", 1).get(0);
		Req request = new Req(goblin, Style.MAGIC, Levels.MAXED,
			PrayerBonuses.NONE, null, 0, CandidateMode.ALL_STANDARD, false, false, Owned.EMPTY,
			RequirementProfile.MAXED, 10);
		EnumMap<Slot, Gear> worn = new EnumMap<>(Slot.class);
		worn.put(Slot.WEAPON, tome);
		Dps base = new Calc().calculate(request, new Kit(worn));
		double h = RollMath.normalAccuracy((long) (base.getAr() * 2.5), base.getDr());
		double hit = h * (int) (base.getMaxHit() * 1.6) / 2.0;
		Assert.assertEquals(hit * (1 + 3 * h), spec.expectedDamage(base, goblin, Levels.MAXED), 1e-9);
		Assert.assertEquals(6 * h, spec.extraTicks(base), 1e-9);
		Assert.assertEquals(0, SpecialAttack.match(data.getGear(11802), Style.MELEE).extraTicks(base), 1e-9);
	}
}

package com.ll.engine;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.EnumMap;
import org.junit.Assert;
import org.junit.Test;

/**
 * Zorya's tome (the Fractured Archive, 2026-10-20; wiki): a two-handed
 * powered staff, 3-tick, base max hit 18 (flat, like the crystal staff),
 * 15% magic damage of its own.
 */
public class ZoryaTomeTest {
	@Test
	public void threeTicksFromABaseOfEighteen() {
		Tables data = new DataService().load();
		Gear tome = data.getGear(34725);
		Assert.assertNotNull(tome);
		Assert.assertTrue(tome.isPoweredStaff());
		Monster goblin = data.searchMonsters("goblin", 1).get(0);
		Req request = new Req(goblin, Style.MAGIC, Levels.MAXED,
			PrayerBonuses.NONE, null, 0, CandidateMode.ALL_STANDARD, false, false, Owned.EMPTY,
			RequirementProfile.MAXED, 10);
		EnumMap<Slot, Gear> gear = new EnumMap<>(Slot.class);
		gear.put(Slot.WEAPON, tome);
		Dps result = new Calc().calculate(request, new Kit(gear));
		Assert.assertEquals(3, result.getAttackSpeed());
		// floor(18 * 1.15): the base with the tome's own 15%.
		Assert.assertEquals(20, result.getMaxHit());
	}
}

package com.ll.model;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * "Detect best in bank" for cannonballs (Andrew 2026-08-31), under the
 * 0.4.1 ownership rule: the resolved ball is the best BANKED tier every
 * carried cannon can fire, and a bank with no cannonballs prices every
 * cannon at zero with the reason - never an assumed ball.
 */
class AmmoDetectTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static final class CaptureLink extends CompanionLink {
		Map<String, Object> published;

		@Override
		public void publishPage(Map page) {
			published = page;
		}
	}

	private static Map<String, Object> shipWith(Set<Integer> bank,
		Map<String, Object> shipParams) {
		PageState state = new PageState();
		for (Map.Entry<String, Object> e : shipParams.entrySet()) {
			state.setParam(e.getKey(), e.getValue());
		}
		CaptureLink link = new CaptureLink();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			link);
		engine.setRangedLevel(99);
		engine.setOwnedCheck(bank::contains);
		Monster shark = data.searchMonsters("hammerhead shark", 1).get(0);
		engine.execute("select", Map.of("id", shark.getId()));
		engine.onResults(shark, Map.of());
		try {
			javax.swing.SwingUtilities.invokeAndWait(() -> {
			});
		} catch (Exception ex) {
			throw new AssertionError(ex);
		}
		Map<?, ?> entry = (Map<?, ?>) ((List<?>) link.published.get("entries")).get(0);
		@SuppressWarnings("unchecked")
		Map<String, Object> ship = (Map<String, Object>) entry.get("ship");
		return ship;
	}

	@Test
	@DisplayName("detect resolves to the best banked ball every cannon can fire")
	void detectResolvesFromTheBank() {
		// Bank holds mithril (31910) and rune (31914) balls; a dragon +
		// mithril pair can share at most mithril - rune is banked but the
		// mithril cannon cannot fire it.
		Map<String, Object> ship = shipWith(Set.of(31910, 31914),
			Map.of("cannonCount", 2, "cannon1Material", "dragon",
				"cannon2Material", "mithril"));
		assertEquals("mithril", ship.get("ammo"));
		assertEquals(Boolean.TRUE, ship.get("ammoDetected"));
		assertNull(ship.get("ammoBlocked"));
	}

	@Test
	@DisplayName("a dry bank fires nothing - the reason rides the node")
	void dryBankBlocks() {
		Map<String, Object> ship = shipWith(Set.of(),
			Map.of("cannonCount", 1, "cannon1Material", "dragon",
				"cannon1Operator", "you"));
		assertEquals("No cannonballs banked (up to dragon)", ship.get("ammoBlocked"));
		Map<?, ?> c1 = (Map<?, ?>) ((List<?>) ship.get("cannons")).get(0);
		assertEquals(0, c1.get("maxHit"));
		assertEquals(0.0, (Double) ship.get("dps"), 1e-9);
	}

	@Test
	@DisplayName("an explicit tier pick bypasses detection entirely")
	void explicitPickBypasses() {
		Map<String, Object> ship = shipWith(Set.of(),
			Map.of("cannonCount", 1, "cannon1Material", "dragon",
				"cannonAmmo", "dragon", "cannon1Operator", "you"));
		assertEquals("dragon", ship.get("ammo"));
		assertEquals(Boolean.FALSE, ship.get("ammoDetected"));
		Map<?, ?> c1 = (Map<?, ?>) ((List<?>) ship.get("cannons")).get(0);
		assertEquals(57, c1.get("maxHit"), "the explicit pick prices even with a dry bank");
	}

	@Test
	@DisplayName("ship params persist per character through the scoped store")
	void shipParamsPersist() {
		PageState state = new PageState();
		CaptureLink link = new CaptureLink();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			link);
		java.util.Map<String, String> saved = new java.util.HashMap<>();
		engine.setStoreOps(new TestStoreOps() {
			@Override
			public void setSupplyDefault(String category, String choice) {
				saved.put(category, choice);
			}
		});
		engine.execute("set-param", Map.of("param", "cannon1Material", "value", "dragon"));
		engine.execute("set-param", Map.of("param", "cannon1Operator", "value", "you"));
		assertEquals("dragon", saved.get("ship.cannon1Material"));
		assertEquals("you", saved.get("ship.cannon1Operator"));
		// The SETTLED value persists, clamps applied: crew2 on a dragon
		// cannon stores as the auto-raised crew4.
		engine.execute("set-param", Map.of("param", "cannon1Operator", "value", "crew2"));
		assertEquals("crew4", saved.get("ship.cannon1Operator"));
	}

	@Test
	@DisplayName("ship damage taken rides the node per keel - even with no cannons")
	void shipIncomingPerKeel() {
		// Hammerhead: keel row 7,6,5,4,3,1,0,0; speed 4 ticks (2.4s).
		Map<String, Object> ship = shipWith(Set.of(),
			Map.of("cannonCount", 0, "shipKeel", "none"));
		assertNotNull(ship, "a sea lens carries the ship node for DTPS alone");
		Map<?, ?> in = (Map<?, ?>) ship.get("incoming");
		assertEquals("none", in.get("keel"));
		assertEquals(7, in.get("maxHit"));
		assertEquals(7 / 2.0 / 2.4, (Double) in.get("dtps"), 1e-9);

		Map<?, ?> rune = (Map<?, ?>) shipWith(Set.of(),
			Map.of("cannonCount", 0, "shipKeel", "rune")).get("incoming");
		assertEquals(0, rune.get("maxHit"),
			"a rune keel cannot be hit by a hammerhead (wiki table)");
		assertEquals(0.0, (Double) rune.get("dtps"), 1e-9);
	}

	@Test
	@DisplayName("an explicit pick downranks at resolution and springs back")
	void explicitPickDownranksAtResolution() {
		// Dragon pick on a rune cannon resolves to rune...
		Map<String, Object> ship = shipWith(Set.of(),
			Map.of("cannonCount", 1, "cannon1Material", "rune",
				"cannonAmmo", "dragon", "cannon1Operator", "you"));
		assertEquals("rune", ship.get("ammo"));
		// ...and the pick itself never mutated: back on a dragon cannon the
		// dragon ball returns.
		ship = shipWith(Set.of(),
			Map.of("cannonCount", 1, "cannon1Material", "dragon",
				"cannonAmmo", "dragon", "cannon1Operator", "you"));
		assertEquals("dragon", ship.get("ammo"));
	}

	@Test
	@DisplayName("thralls cannot be cast on a boat - they add nothing at sea")
	void thrallsVetoedAtSea() {
		PageState state = new PageState();
		state.setParam("thralls", true);
		CaptureLink link = new CaptureLink();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			link);
		engine.setMag(99);
		Monster shark = data.searchMonsters("hammerhead shark", 1).get(0);
		engine.execute("select", Map.of("id", shark.getId()));
		engine.onResults(shark, Map.of());
		try {
			javax.swing.SwingUtilities.invokeAndWait(() -> {
			});
		} catch (Exception ex) {
			throw new AssertionError(ex);
		}
		Map<?, ?> entry = (Map<?, ?>) ((List<?>) link.published.get("entries")).get(0);
		assertNull(entry.get("thralls"),
			"thrall resurrections cannot be cast on a boat (confirmed 2026-08-31)");

		// The land path keeps its fold.
		Monster graardor = data.searchMonsters("general graardor", 1).get(0);
		engine.execute("select", Map.of("id", graardor.getId()));
		engine.onResults(graardor, Map.of());
		try {
			javax.swing.SwingUtilities.invokeAndWait(() -> {
			});
		} catch (Exception ex) {
			throw new AssertionError(ex);
		}
		entry = (Map<?, ?>) ((List<?>) link.published.get("entries")).get(0);
		assertNotNull(entry.get("thralls"), "the land fold must survive the veto");
	}

	/** Andrew 2026-09-02: "i don't think you need actual food supplies for
	 * boat combat mobs just ship repair" - a sea-only trip carries repair
	 * kits only; food and the rest stay on land trips. */
	@Test
	@DisplayName("a sea-only trip carries repair kits, never food")
	void seaTripsCarryRepairKitsOnly() {
		PageState state = new PageState();
		state.setParam("shipKeel", "none");
		CaptureLink link = new CaptureLink();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			link);
		engine.setStoreOps(new TestStoreOps());
		engine.setOwnedCheck(id -> id == 31982 || id == 13441); // a kit and anglerfish banked
		engine.setSupplyDefaults(() -> Map.of(
			com.ll.data.Trip.SHIP_REPAIR_KIT, "DETECT_BEST",
			com.ll.data.Trip.FOOD, "DETECT_BEST"));
		Monster shark = data.searchMonsters("hammerhead shark", 1).get(0);
		engine.execute("select", Map.of("id", shark.getId()));
		engine.onResults(shark, Map.of());
		try {
			javax.swing.SwingUtilities.invokeAndWait(() -> {
			});
		} catch (Exception ex) {
			throw new AssertionError(ex);
		}
		Map<?, ?> entry = (Map<?, ?>) ((List<?>) link.published.get("entries")).get(0);
		java.util.List<Object> categories = new java.util.ArrayList<>();
		for (Object node : (List<?>) entry.get("supplies")) {
			categories.add(((Map<?, ?>) node).get("category"));
		}
		assertEquals(List.of("shipRepairKit"), categories,
			"at sea the boat takes the hits - repair kits, no food");
	}

	@Test
	@DisplayName("repair kits recommend only when the mob can damage YOUR keel")
	void repairKitsFollowTheKeel() {
		java.util.function.BiFunction<String, String, Boolean> kitShown = (mobName, keel) -> {
			PageState state = new PageState();
			state.setParam("shipKeel", keel);
			CaptureLink link = new CaptureLink();
			CommandEngine engine = new CommandEngine(data, state,
				(mob, p, onDone) -> {
				},
				link);
			engine.setStoreOps(new TestStoreOps());
			engine.setOwnedCheck(id -> id == 31982); // a rosewood kit banked
			engine.setSupplyDefaults(() -> Map.of(
				com.ll.data.Trip.SHIP_REPAIR_KIT, "DETECT_BEST"));
			Monster mob = data.searchMonsters(mobName, 1).get(0);
			engine.execute("select", Map.of("id", mob.getId()));
			engine.onResults(mob, Map.of());
			try {
				javax.swing.SwingUtilities.invokeAndWait(() -> {
				});
			} catch (Exception ex) {
				throw new AssertionError(ex);
			}
			Map<?, ?> entry = (Map<?, ?>) ((List<?>) link.published.get("entries")).get(0);
			for (Object node : (List<?>) entry.get("supplies")) {
				if ("shipRepairKit".equals(((Map<?, ?>) node).get("category"))) {
					return true;
				}
			}
			return false;
		};
		// A hammerhead dents a keel-less boat (max 7): kits recommended.
		assertTrue(kitShown.apply("hammerhead shark", "none"));
		// The same shark cannot touch a dragon keel (max 0): no kits.
		assertFalse(kitShown.apply("hammerhead shark", "dragon"),
			"a mob doing 0 damage to your keel needs no repair kits");
		// Land mobs never see the category.
		assertFalse(kitShown.apply("general graardor", "none"));
	}
}

package com.ll.model;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Andrew (client test 2026-10-19): Drakes suggested Water Surge while
 * thralls and Death Charge were on - an invalid state, since both are
 * cast from Arceuus and a standard autocast needs the standard book.
 * The rule he picked: the card stands down. A card whose autocast is on
 * another book carries an arceuusStandDown reason; the render shows its
 * number without the thrall fold and says why. Melee and ranged cards,
 * powered staves and Arceuus spells are untouched.
 */
class ArceuusStandDownTest {
	private static final Map<String, Object> BOOKS = Map.of(
		"Water Surge", "standard", "Ice Barrage", "ancient", "Dark Demonbane", "arceuus");

	private static Map<String, Object> card(String spell) {
		Map<String, Object> card = new LinkedHashMap<>();
		card.put("spell", spell);
		card.put("dps", 9.56);
		return card;
	}

	private static List<Object> page(String yoursSpell, String bisSpell) {
		Map<String, Object> magic = new LinkedHashMap<>();
		magic.put("yours", card(yoursSpell));
		magic.put("bis", card(bisSpell));
		Map<String, Object> melee = new LinkedHashMap<>();
		melee.put("yours", card(null));
		Map<String, Object> styles = new LinkedHashMap<>();
		styles.put("melee", melee);
		styles.put("magic", magic);
		Map<String, Object> mob = new LinkedHashMap<>();
		mob.put("styles", styles);
		List<Object> mobs = new ArrayList<>();
		mobs.add(mob);
		return mobs;
	}

	@SuppressWarnings("unchecked")
	private static String reason(List<Object> mobs, String style, String side) {
		Map<String, Object> styles = (Map<String, Object>) ((Map<?, ?>) mobs.get(0)).get("styles");
		Map<String, Object> card = (Map<String, Object>) ((Map<?, ?>) styles.get(style)).get(side);
		return (String) card.get("arceuusStandDown");
	}

	@Test
	@DisplayName("a standard or Ancients autocast stands thralls and Death Charge down, with the book named")
	void otherBooksStandDown() {
		List<Object> mobs = page("Water Surge", "Ice Barrage");
		CommandEngine.arceuusStandDown(mobs, BOOKS, true);
		assertEquals("Water Surge autocasts from the standard book", reason(mobs, "magic", "yours"));
		assertEquals("Ice Barrage autocasts from the ancient book", reason(mobs, "magic", "bis"));
		assertNull(reason(mobs, "melee", "yours"), "a melee card has no autocast");
	}

	@Test
	@DisplayName("an Arceuus spell, a powered staff and an unknown spell keep the fold")
	void arceuusAndStavesKeepIt() {
		List<Object> mobs = page("Dark Demonbane", null);
		CommandEngine.arceuusStandDown(mobs, BOOKS, true);
		assertNull(reason(mobs, "magic", "yours"));
		assertNull(reason(mobs, "magic", "bis"));
		List<Object> unknown = page("Mystery Bolt", null);
		CommandEngine.arceuusStandDown(unknown, BOOKS, true);
		assertNull(reason(unknown, "magic", "yours"), "no book on record, nothing to contradict");
	}

	@Test
	@DisplayName("with neither thralls nor Death Charge on, no card is marked")
	void nothingWantedNothingMarked() {
		List<Object> mobs = page("Water Surge", "Water Surge");
		CommandEngine.arceuusStandDown(mobs, BOOKS, false);
		assertNull(reason(mobs, "magic", "yours"));
		assertNull(reason(mobs, "magic", "bis"));
	}
}

package com.ll.model;

import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field report 2026-08-31 (Not on Hand): "If i click and remove the prayer
 * shown, when I try to add it back there is no longer an option to do so."
 *
 * <p>The assume icons ARE the pickers. An empty assume label used to return
 * a null node, which erased both icons - picking None removed the only
 * control that could undo it. The empty state is now a real node with
 * sentinel values (-1), which the render side draws as the prayer-book
 * wings and the muted dash, both still clickable.
 */
class AssumeSentinelTest {
	@Test
	@DisplayName("an empty assume label yields sentinel pickers, never null")
	void emptyLabelKeepsThePickers() {
		for (String label : new String[]{null, ""}) {
			Map<String, Object> node = RenderModel.assumeNode(label);
			assertNotNull(node, "a null node erases the pickers (label=" + label + ")");
			assertEquals(-1, node.get("prayerSprite"), "sentinel prayer sprite");
			assertEquals(-1, node.get("boostItem"), "sentinel boost item");
			assertEquals("No prayer or boost", node.get("text"));
		}
	}

	@Test
	@DisplayName("real labels still resolve their icons")
	void realLabelsUnchanged() {
		Map<String, Object> node = RenderModel.assumeNode("Piety + Super combat");
		assertNotNull(node);
		assertTrue((int) node.get("prayerSprite") > 0, "Piety resolves a sprite");
		assertTrue((int) node.get("boostItem") > 0, "Super combat resolves an item");
	}

	/** Andrew 2026-09-02: the boost potion is a supply to bring - unless
	 * the raid hands it out (CoX overloads, ToA salts). */
	@Test
	@DisplayName("a raid-supplied boost is flagged so the supplies row does not pack it")
	void raidSuppliedBoostsAreFlagged() {
		Map<String, Object> potion = RenderModel.assumeNode("Rigour + Divine ranging potion");
		assertEquals(23733, potion.get("boostItem"));
		assertEquals(false, potion.get("boostSupplied"));
		assertEquals(true, RenderModel.assumeNode("Piety + Overload (+)").get("boostSupplied"));
		assertEquals(true, RenderModel.assumeNode("Piety + Smelling salts").get("boostSupplied"));
		assertEquals(false, RenderModel.assumeNode("Augury + Saturated heart").get("boostSupplied"));
	}
}

package com.ll.model;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/** Field report 2026-11-01: "Is there a way to clear the bank selection
 * when not in use?" Andrew: "it should be clear when there is no active
 * search". The Filter bank and Show in bank toggles live on the card, so
 * every road to the empty page used to leave the bank filtered. */
class BankToolsClearTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	/** Records every bank call: null means "clear". */
	private static final class BankOps extends TestStoreOps {
		final List<Set<Integer>> filters = new ArrayList<>();
		final List<Set<Integer>> shows = new ArrayList<>();

		@Override
		public void filterBank(Set<Integer> itemIds, int[] layout) {
			filters.add(itemIds);
		}

		@Override
		public void showInBank(Set<Integer> itemIds) {
			shows.add(itemIds);
		}

		Set<Integer> lastFilter() {
			return filters.isEmpty() ? Set.of(-1) : filters.get(filters.size() - 1);
		}

		Set<Integer> lastShow() {
			return shows.isEmpty() ? Set.of(-1) : shows.get(shows.size() - 1);
		}
	}

	private static final class CaptureLink extends CompanionLink {
		Map<String, Object> page;

		@Override
		public void publishPage(Map page) {
			this.page = page;
		}

		@Override
		public Map<String, Object> lastPage() {
			return page;
		}
	}

	private static void flush() {
		try {
			javax.swing.SwingUtilities.invokeAndWait(() -> {
			});
		} catch (Exception ex) {
			throw new AssertionError(ex);
		}
	}

	private BankOps ops;
	private CaptureLink link;
	private CommandEngine engine;

	/** A searched mob with both bank tools switched on from its card. */
	private Monster searchedWithBankToolsOn() {
		PageState state = new PageState();
		link = new CaptureLink();
		engine = new CommandEngine(data, state, (mob, p, onDone) -> {
		}, link);
		ops = new BankOps();
		engine.setStoreOps(ops);
		Monster cerberus = data.searchMonsters("cerberus", 1).get(0);
		assertTrue(engine.execute("select", Map.of("id", cerberus.getId())));
		engine.onResults(cerberus, Map.of());
		flush();
		assertTrue(engine.execute("bank-filter", Map.of("ids", List.of(11802, 13239), "layout", Arrays.asList(11802, -1, 13239))));
		assertTrue(engine.execute("bank-show", Map.of("ids", List.of(11802))));
		assertEquals(Set.of(11802, 13239), ops.lastFilter(), "the filter went on");
		assertEquals(Set.of(11802), ops.lastShow(), "the highlight went on");
		return cerberus;
	}

	private void assertBankToolsCleared(String road) {
		flush();
		assertTrue(((List<?>) link.page.get("entries")).isEmpty(), road + ": the idle page");
		assertNull(ops.lastFilter(), road + ": the bank filter is cleared");
		assertNull(ops.lastShow(), road + ": the bank highlight is cleared");
	}

