		return cannonIds(raid ? "Tombs of Amascut" : null, "abyssal demon");
	}

	/** group: a curated group to select (null = the single mob). */
	private List<Integer> cannonIds(String group, String mobQuery) {
		cannonCells.clear();
		PageState state = new PageState();
		CaptureLink link = new CaptureLink();
		CommandEngine engine = new CommandEngine(data, state,
			(m, p, onDone) -> {
			},
			link);
		engine.setStoreOps(new TestStoreOps());
		engine.setOwnedCheck(id -> true);
		engine.setSupplyDefaults(() -> Map.of(Trip.CANNON, "DWARF_MULTICANNON"));
		if (group != null) {
			// A real group select: the group data flags a raid, the engine
			// sets the param - the same path RaidSelectionTest proves.
			engine.execute("select", Map.of("query", group));
			List<Monster> mobs = state.rmobs();
			List<Map<com.ll.engine.Style, com.ll.optimizer.Service.Pick>> empty =
				new ArrayList<>();
			for (int i = 0; i < mobs.size(); i++) {
				empty.add(Map.of());
			}
			engine.onRosterResults(mobs, empty);
		} else {
			Monster mob = data.searchMonsters(mobQuery, 1).get(0);
			engine.execute("select", Map.of("id", mob.getId()));
			engine.onResults(mob, Map.of());
		}
		try {
			javax.swing.SwingUtilities.invokeAndWait(() -> {
			});
		} catch (Exception ex) {
			throw new AssertionError(ex);
		}
		Map<?, ?> entry = (Map<?, ?>) ((List<?>) link.published.get("entries")).get(0);
		List<Integer> ids = new ArrayList<>();
		for (Object node : (List<?>) entry.get("supplies")) {
			Map<?, ?> supply = (Map<?, ?>) node;
			if (Trip.CANNON.equals(supply.get("category"))) {
				ids.add(((Number) supply.get("itemId")).intValue());
				List<Integer> cell = new ArrayList<>();
				for (Object o : (List<?>) supply.get("ids")) {
					cell.add(((Number) o).intValue());
				}
				cannonCells.add(cell);
			}
		}
		return ids;
	}

	@Test
	@DisplayName("chosen, the cannon is five supply cells in part order")
	void cannonIsFiveCells() {
		assertEquals(List.of(6, 8, 10, 12, 2), cannonIds(false));
	}

	@Test
	@DisplayName("each cell lights up its variants in the filter: the ornamented part, granite balls")
	void cellsCarryVariants() {
		cannonIds(false);
		assertEquals(List.of(6, 26520), cannonCells.get(0), "base and the (or) base");
		assertEquals(List.of(2, 21728), cannonCells.get(4), "cannonballs and granite cannonballs");
	}

	@Test
	@DisplayName("no cannon where it cannot be set up or does nothing: Barrows, Vorkath, a cannon-immune gorilla")
	void prohibitedOrImmuneSkipsTheCannon() {
		// Andrew, client test 2026-10-20: "it's suggesting dwarf multicannon
		// for barrows even though it's not allowed on that boss".
		assertTrue(cannonIds(null, "dharok the wretched").isEmpty(), "a Barrows brother");
		assertTrue(cannonIds("Barrows", null).isEmpty(), "the Barrows roster");
		assertTrue(cannonIds(null, "vorkath").isEmpty(), "Ungael is a prohibited area");
		assertTrue(cannonIds(null, "demonic gorilla").isEmpty(), "cannon-immune (wiki)");
		// Exact names only: the wiki's immune "Black demon (The Scar)" page
		// must not take the cannon from every black demon.
		assertEquals(List.of(6, 8, 10, 12, 2), cannonIds(null, "black demon"));
	}

	@Test
	@DisplayName("a raid selection never carries the cannon")
	void raidsSkipTheCannon() {
		assertTrue(cannonIds(true).isEmpty());
	}
}

package com.ll.model;

import com.ll.data.DataService;
import com.ll.data.Tables;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Andrew, 2026-09-18: "for each of the exclude/sim/item filters can you
 * have a reset all in list option". One command, one recompute, one undo
 * step that puts every entry back. */
class ClearMobListTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	/** Store ops with a real per-mob exclusion list. */
	private static final class ListOps extends TestStoreOps {
		final List<Map> exclusions = new ArrayList<>();

		@Override
		public List<Map> mobExclusions(int monsterId) {
			return new ArrayList<>(exclusions);
		}

		@Override
		public void removeMobExclusion(int monsterId, String scope, int itemId) {
			exclusions.removeIf(e -> ((Number) e.get("id")).intValue() == itemId && scope.equals(e.get("scope")));
		}

		@Override
		public void excludeForMob(int monsterId, String scope, int itemId) {
			exclusions.add(Map.of("id", itemId, "name", "item " + itemId, "scope", scope));
		}
	}

	@Test
	@DisplayName("clear-mob-list empties the mob's exclusions in one recompute and undo restores every entry")
	void clearAndUndo() {
		java.util.concurrent.atomic.AtomicInteger computes = new java.util.concurrent.atomic.AtomicInteger();
		CommandEngine engine = new CommandEngine(data, new PageState(),
			(mob, p, onDone) -> computes.incrementAndGet(), new CompanionLink());
		ListOps ops = new ListOps();
		ops.exclusions.add(Map.of("id", 4151, "name", "Abyssal whip", "scope", "ALL"));
		ops.exclusions.add(Map.of("id", 11802, "name", "Armadyl godsword", "scope", "MELEE"));
		engine.setStoreOps(ops);
		assertTrue(engine.execute("select", Map.of("query", "goblin")));
		int before = computes.get();

		assertTrue(engine.execute("clear-mob-list", Map.of("kind", "mobExclusions")));
		assertTrue(ops.exclusions.isEmpty(), "both entries gone");
		assertEquals(before + 1, computes.get(), "one recompute for the whole clear");

		assertTrue(engine.execute("undo", Map.of()));
		assertEquals(2, ops.exclusions.size(), "undo puts every entry back");
		assertTrue(ops.exclusions.stream().anyMatch(e -> "MELEE".equals(e.get("scope"))), "with its scope");
	}
}

