package com.ll.model;

import com.ll.data.DataService;
import com.ll.data.Tables;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * The strip's "more" control sends set-param ladderPage; the param must be
 * declared or the state refuses it and the click does nothing (Andrew
 * 2026-10-24: "more steps up is not working for me" -
 * ISS-01M5QJMTBRNAWX5WT7NRJD8JWC).
 */
class LadderPageParamTest {
	private static final class Link extends CompanionLink {
		private Map<String, Object> last;

		@Override
		public void publishPage(Map page) {
			last = page;
		}

		@Override
		public Map<String, Object> lastPage() {
			return last;
		}
	}

	@Test
	@DisplayName("set-param ladderPage is accepted as a view param (no recompute) and opening another slot resets it to 0")
	void ladderPageIsADeclaredViewParam() {
		Tables data = new DataService().load();
		AtomicInteger computes = new AtomicInteger();
		PageState state = new PageState();
		CommandEngine engine = new CommandEngine(data, state, (mob, p, onDone) -> computes.incrementAndGet(), new Link());
		assertTrue(engine.execute("select", Map.of("query", "abyssal demon")));
		int before = computes.get();

		assertTrue(engine.execute("set-param", Map.of("param", "ladderPage", "value", 2)), "the page turns");
		assertEquals(2, ((Number) state.pn().get("ladderPage")).intValue());
		assertEquals(before, computes.get(), "a view param never recomputes");

		assertTrue(engine.execute("set-param", Map.of("param", "ladderSlot", "value", "weapon")));
		assertEquals(0, ((Number) state.pn().get("ladderPage")).intValue(), "a fresh slot opens on its first page");
		assertEquals(before, computes.get());
	}

	@Test
	@DisplayName("a new search closes the strip and resets its page (Andrew 2026-10-24: \"whenver a new search is done the ladder view should be reset\")")
	void aNewSearchClosesTheStrip() {
		Tables data = new DataService().load();
		PageState state = new PageState();
		CommandEngine engine = new CommandEngine(data, state, (mob, p, onDone) -> {
		}, new Link());
		assertTrue(engine.execute("select", Map.of("query", "abyssal demon")));
		assertTrue(engine.execute("set-param", Map.of("param", "ladderSlot", "value", "weapon")));
		assertTrue(engine.execute("set-param", Map.of("param", "ladderPage", "value", 2)));

		assertTrue(engine.execute("select", Map.of("query", "zulrah")));
		assertEquals("", state.pn().get("ladderSlot"), "no strip until a slot is clicked");
		assertEquals(0, ((Number) state.pn().get("ladderPage")).intValue(), "page one");

		assertTrue(engine.execute("set-param", Map.of("param", "ladderSlot", "value", "weapon")));
		assertTrue(engine.execute("set-param", Map.of("param", "ladderPage", "value", 1)));
		assertTrue(engine.execute("select", Map.of("query", "tombs of amascut")), "a group search resets it too");
		assertEquals("", state.pn().get("ladderSlot"));
		assertEquals(0, ((Number) state.pn().get("ladderPage")).intValue());
	}
}

package com.ll.model;

import com.ll.data.DataService;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Picking a ladder rung sims it and wears it (ISS-01M5GNMHHCD8M56JD4GAZBFV7Y,
 * Andrew 2026-10-21: "Sim + pin for this mob") - one undo step that puts
 * everything back.
 */
class LadderTryTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	/** Records every sim/pin call; starts with an optional ALL-scope pin. */
	private static final class RecordingOps extends TestStoreOps {
		final List<String> calls = new ArrayList<>();
		final Map<Slot, Integer> pins = new EnumMap<>(Slot.class);
		int spec;

		@Override
		public int pinnedSpec(int monsterId) {
			return spec;
		}

		@Override
		public void setPinnedSpec(int monsterId, int itemId) {
			calls.add("spec " + itemId);
		}

		@Override
		public Map<String, Map<Slot, Integer>> allPins(int monsterId) {
			return Map.of("ALL", new EnumMap<>(pins.isEmpty() ? new EnumMap<>(Slot.class) : pins));
		}

		@Override
		public void pin(int monsterId, String scope, Slot slot, int itemId) {
			calls.add("pin " + slot.name().toLowerCase() + " " + itemId);
		}

		@Override
		public void unpin(int monsterId, String scope, Slot slot) {
			calls.add("unpin " + slot.name().toLowerCase());
		}

		@Override
		public void simForMob(int monsterId, int itemId) {
			calls.add("sim " + itemId);
		}

		@Override
		public void removeMobSim(int monsterId, int itemId) {
			calls.add("unsim " + itemId);
		}
	}

	private static CommandEngine engine(RecordingOps ops, boolean owned) {
		PageState state = new PageState();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			new CompanionLink());
		engine.setStoreOps(ops);
		engine.setOwnedCheck(id -> owned);
		Monster mob = data.searchMonsters("abyssal demon", 1).get(0);
		assertTrue(engine.execute("select", Map.of("id", mob.getId())));
		return engine;
	}

	private static Map<String, Object> tentacle() {
		return Map.of("slot", "weapon", "itemId", 12006, "label", "Abyssal tentacle");
	}

	@Test
	@DisplayName("an unowned rung is simmed and pinned in one step; undo takes both back")
	void simAndWear() {
		RecordingOps ops = new RecordingOps();
		CommandEngine engine = engine(ops, false);
		assertTrue(engine.execute("ladder-try", tentacle()));
		assertEquals(List.of("sim 12006", "pin weapon 12006"), ops.calls);
		ops.calls.clear();
		assertTrue(engine.execute("undo", Map.of()));
		assertEquals(List.of("unsim 12006", "unpin weapon"), ops.calls);
	}

	@Test
	@DisplayName("an owned rung is only pinned, and undo restores the slot's earlier pin")
	void ownedRestoresPreviousPin() {
		RecordingOps ops = new RecordingOps();
		ops.pins.put(Slot.WEAPON, 4151);
		CommandEngine engine = engine(ops, true);
		assertTrue(engine.execute("ladder-try", tentacle()));
		assertEquals(List.of("pin weapon 12006"), ops.calls, "no sim for an item you own");
		ops.calls.clear();
		assertTrue(engine.execute("undo", Map.of()));
		assertEquals(List.of("pin weapon 4151"), ops.calls, "the whip pin comes back");
	}

	@Test
	@DisplayName("trying a spec step sims it and makes it this mob's spec; undo restores the earlier spec")
	void specStep() {
		RecordingOps ops = new RecordingOps();
		ops.spec = 13652;
		CommandEngine engine = engine(ops, false);
		assertTrue(engine.execute("ladder-try", Map.of("slot", "spec", "itemId", 11802, "label", "Armadyl godsword")));
		assertEquals(List.of("sim 11802", "spec 11802"), ops.calls);
		ops.calls.clear();
		assertTrue(engine.execute("undo", Map.of()));
		assertEquals(List.of("unsim 11802", "spec 13652"), ops.calls, "the claws come back as the spec");
	}
}

package com.ll.model;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.MonsterGroups;
import com.ll.data.Monster;
import com.ll.engine.Style;
import com.ll.engine.Req;
import com.ll.optimizer.Service;
import com.ll.optimizer.ServiceCalls;
import com.ll.profile.FixtureBank;
import com.ll.profile.PlayerProfile;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

/**
 * Model-snapshot golden (ADR-0008): the serialized render-model for a
 * scenario matrix, canonical-JSON per line. Byte-identical output is
 * the contract the Companion renders against - this locks the seam the
 * way golden/rosterGolden lock the engine, and the captured lines
 * double as the Companion repo's renderer fixtures.
 *
 *   ./gradlew -q modelGolden > model-golden.txt
 */
public final class ModelGolden {
	/** Single mobs chosen for card-shape coverage: tri-style + spec
	 * (Graardor), recoil/venom + magic-led (Zulrah), antifire +
	 * required-gear (Vorkath), incoming-override boss (Muspah). */
	private static final String[] MOBS = {
		"general graardor", "zulrah", "vorkath", "phantom muspah",
	};

	private static final String ROSTER_GROUP = "Dagannoth Kings";
	private static final int ROSTER_BENCH = 3;

	/** A wilderness boss under the kept-on-death cap, so the risk node
	 * (and the "Kept on death:" tooltip built on it) is exercised - the
	 * gap the render baseline measured as uncovered. */
	private static final String WILDERNESS_MOB = "callisto";
	private static final int LOW_RISK_TRADEABLES = 3;

	private ModelGolden() {
	}

	public static void main(String[] args) throws Exception {
		Tables data = new DataService().load();
		PlayerProfile profile = FixtureBank.profile(data);
		for (String name : MOBS) {
			Monster mob = data.searchMonsters(name, 1).get(0);
			System.out.println("##### " + mob.label());
			System.out.println(Json.write(RenderModel.page(List.of(single(data, profile, mob)))));
		}
		Monster wildy = data.searchMonsters(WILDERNESS_MOB, 1).get(0);
		System.out.println("##### " + wildy.label() + " | low-risk");
		System.out.println(Json.write(RenderModel.page(
			List.of(single(data, profile, wildy, LOW_RISK_TRADEABLES)))));

		MonsterGroups.MonsterGroup group = null;
		for (MonsterGroups.MonsterGroup candidate : MonsterGroups.load(data)) {
			if (candidate.getName().equalsIgnoreCase(ROSTER_GROUP)) {
				group = candidate;
			}
		}
		if (group == null) {
			throw new IllegalStateException("group gone: " + ROSTER_GROUP);
		}
		System.out.println("##### " + group.label() + " | bench=" + ROSTER_BENCH);
		System.out.println(Json.write(RenderModel.page(
			List.of(roster(data, profile, group.getMobs(), ROSTER_BENCH)))));
	}

	private static Map<String, Object> single(Tables data, PlayerProfile profile,
		Monster mob) throws Exception {
		return single(data, profile, mob, -1);
	}

	private static Map<String, Object> single(Tables data, PlayerProfile profile,
		Monster mob, int maxTr) throws Exception {
		Service service = new Service(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
			ServiceCalls.bestPerStyle(service, mob,
				profile.realLevels, profile.boostedLevels, profile.prayerUnlocks,
				profile.requirements, profile.oi(), profile.owned.hashCode(),
				false, false, "", new EnumMap<>(Style.class), maxTr,
				Req.DEFAULT_RISK_BUDGET_GP, false, false,
				Collections.emptySet(), 0,
				Collections.emptyMap(), null, 0, Collections.emptySet(),
				r -> {
					out.set(r);
					done.countDown();
				});
			if (!done.await(300, TimeUnit.SECONDS)) {
				throw new IllegalStateException("query timed out: " + mob.label());
			}
			// riskKeptSlots >= 0 is what emits the wilderness risk node
			// (and with it the "Kept on death:" tooltip).
			return RenderModel.entry(List.of(mob), List.of(out.get()),
				maxTr >= 0 ? maxTr : -1, null,
				java.util.Collections.emptySet(), null);
		} finally {
			service.shutdown();
		}
	}

	private static Map<String, Object> roster(Tables data, PlayerProfile profile,
		List<Monster> mobs, int bench) throws Exception {
		Service service = new Service(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Service.RosterResult> out = new AtomicReference<>();
			ServiceCalls.bestPerStyleAcross(service, mobs,
				profile.realLevels, profile.boostedLevels, profile.prayerUnlocks,
				profile.requirements, profile.oi(), profile.owned.hashCode(),
				false, false, "", Collections.emptyMap(), -1,
				Req.DEFAULT_RISK_BUDGET_GP, false, false,
				Collections.emptySet(), 0, bench,
				Collections.emptyMap(), null, Collections.emptySet(),
				roster -> {
					out.set(roster);
					done.countDown();
				});
			if (!done.await(300, TimeUnit.SECONDS)) {
				throw new IllegalStateException("roster query timed out");
			}
			return RenderModel.entry(out.get().mobs, out.get().pm);
		} finally {
			service.shutdown();
		}
	}
}

package com.ll.model;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The contract's transport rules (docs/COMPANION_CONTRACT.md): pages
 * are versioned, serialization is canonical and deterministic, and
 * non-JSON-safe values fail loudly instead of leaking classes across
 * the classloader seam.
 */
class ModelShapeTest {
	@Test
	@DisplayName("every page carries the contract version")
	void pageCarriesVersion() {
		Map<String, Object> page = RenderModel.page(List.of());
		assertEquals(RenderModel.VERSION, page.get("v"));
		assertTrue(Json.write(page).startsWith("{\"v\":" + RenderModel.VERSION));
	}

	@Test
	@DisplayName("canonical JSON is byte-stable and escapes strictly")
	void canonicalAndEscaped() {
		Map<String, Object> node = new LinkedHashMap<>();
		node.put("name", "Rada's \"blessing\"\n4\\");
		node.put("dps", 9.196969696969697d);
		node.put("hp", 240);
		node.put("none", null);
		node.put("flag", true);
		String once = Json.write(node);
		assertEquals(once, Json.write(node), "same input, same bytes");
		assertEquals("{\"name\":\"Rada's \\\"blessing\\\"\\n4\\\\\","
			+ "\"dps\":9.196969696969697,\"hp\":240,\"none\":null,\"flag\":true}", once);
	}

	@Test
	@DisplayName("non-JSON-safe values fail loudly, never cross the seam")
	void unsafeValuesRejected() {
		assertThrows(IllegalArgumentException.class,
			() -> Json.write(Map.of("bad", new Object())));
		assertThrows(IllegalArgumentException.class,
			() -> Json.write(Map.of("bad", Double.NaN)));
	}
}

