		assertTrue(engine.execute("toggle-sim", Map.of("itemId", fang, "label", "Osmumten's fang")));
		assertTrue(engine.execute("pin", Map.of("slot", "weapon", "itemId", fang)));
		assertTrue(engine.execute("toggle-sim", Map.of("itemId", fang, "label", "Osmumten's fang")));
