package com.ll.model;

import com.ll.engine.Req;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * One source of truth for "is a risk cap in force". Field report
 * 2026-08-22 (Artio): the chip lit up on riskBudgetGp > 0 while the
 * compute asked riskBudgetGp != DEFAULT - and DEFAULT is itself 75k,
 * the exact value the config seeds, so the UI promised a cap the
 * optimizer ignored and the report called it "none".
 */
class RiskCapTruthTest {

	private static PageState wilderness() {
		PageState state = new PageState();
		state.setParam("inWilderness", true);
		return state;
	}

	@Test
	@DisplayName("a cap equal to the engine's sentinel still binds")
	void theSentinelValueIsStillARealCap() {
		PageState state = wilderness();
		state.setParam("riskBudgetGp", Req.DEFAULT_RISK_BUDGET_GP);
		assertEquals(Boolean.TRUE, state.pn().get("riskCapped"),
			"75k is a cap the player chose, not the absence of one");
		assertEquals(3, state.computeParams().maxTr,
			"a bound cap limits carried tradeables to 3");
	}

	@Test
	@DisplayName("no cap by default, and clearing it releases the constraint")
	void clearedCapReleasesTheConstraint() {
		PageState fresh = wilderness();
		assertEquals(Boolean.FALSE, fresh.pn().get("riskCapped"));
		assertEquals(-1, fresh.computeParams().maxTr, "unconstrained by default");

		PageState state = wilderness();
		state.setParam("riskBudgetGp", 5_000_000);
		assertEquals(Boolean.TRUE, state.pn().get("riskCapped"));
		state.setParam("riskBudgetGp", null);
		assertEquals(Boolean.FALSE, state.pn().get("riskCapped"),
			"an emptied field means uncapped");
		assertEquals(-1, state.computeParams().maxTr);
	}

	@Test
	@DisplayName("a cap can be typed even when it equals the sentinel")
	void typingTheSentinelValueTakesEffect() {
		// Found by the adversarial pass 2026-08-22: set-param's no-op
		// guard compared only the gp number, and 75k reads identically
		// capped or not - so typing 75k was silently swallowed.
		PageState state = wilderness();
		CommandEngine engine = new CommandEngine(
			new com.ll.data.DataService().load(), state,
			(mob, p, onDone) -> {
			},
			new CompanionLink());
		assertEquals(Boolean.FALSE, state.pn().get("riskCapped"));

		assertTrue(engine.execute("set-param", Map.of(
			"param", "riskBudgetGp", "value", Req.DEFAULT_RISK_BUDGET_GP)));
		assertEquals(Boolean.TRUE, state.pn().get("riskCapped"),
			"typing 75k must bind a real cap");
		assertEquals(3, state.computeParams().maxTr);
	}

	@Test
	@DisplayName("Protect Item keeps a fourth slot under a bound cap")
	void protectItemKeepsAFourthSlot() {
		PageState state = wilderness();
		state.setParam("riskBudgetGp", 1_000_000);
		state.setParam("protectItem", true);
		assertEquals(4, state.computeParams().maxTr);
	}

	@Test
	@DisplayName("a cap outside the wilderness never constrains")
	void tameContentIgnoresTheCap() {
		PageState state = new PageState();
		state.setParam("riskBudgetGp", 1_000_000);
		assertEquals(-1, state.computeParams().maxTr);
	}
}

package com.ll.model;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/** Andrew 2026-09-02: "the ability to reorder monsters in the list for a
 * group search". Order is presentation: the roster list reorders, the
 * lens follows the moved row, undo restores both. */
class RosterReorderTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static final class CaptureLink extends CompanionLink {
		@Override
		public void publishPage(Map page) {
		}
	}

	private static List<String> labels(PageState state) {
		List<String> out = new ArrayList<>();
		for (Monster mob : state.rmobs()) {
			out.add(mob.label());
		}
		return out;
	}

	@Test
	@DisplayName("a roster row moves up or down, the lens follows it, and undo puts it back")
	void moveUpAndDown() {
		PageState state = new PageState();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			new CaptureLink());
		engine.setStoreOps(new TestStoreOps());
		// The full group name: aliases route through monster search, not the group lookup.
		assertTrue(engine.execute("select", Map.of("query", "Tombs of Amascut")));
		assertNotNull(state.rmobs(), "a group select sets a roster");
		List<String> before = labels(state);
		assertTrue(before.size() > 3, "a roster");
		assertTrue(engine.execute("set-param", Map.of("param", "lensIndex", "value", 1)));

		// Row 1 moves up: it swaps with row 0 and the lens follows it.
		assertTrue(engine.execute("move-mob", Map.of("index", 1, "delta", -1)));
		List<String> moved = labels(state);
		assertEquals(before.get(1), moved.get(0));
		assertEquals(before.get(0), moved.get(1));
		assertEquals(0, ((Number) state.pn().get("lensIndex")).intValue());
		assertEquals(before.subList(2, before.size()), moved.subList(2, moved.size()),
			"only the two rows swap");

		// Out of range is a no-op, not a crash.
		assertFalse(engine.execute("move-mob", Map.of("index", 0, "delta", -1)));
		assertFalse(engine.execute("move-mob", Map.of("index", before.size() - 1, "delta", 1)));

		// Undo restores the order and the lens.
		assertTrue(engine.execute("undo", Map.of()));
		assertEquals(before, labels(state));
		assertEquals(1, ((Number) state.pn().get("lensIndex")).intValue());
	}

	@Test
	@DisplayName("moving a row reorders the results it already has - no recompute, and undo does not recompute either")
	void moveDoesNotRecompute() {
		java.util.concurrent.atomic.AtomicInteger searches = new java.util.concurrent.atomic.AtomicInteger();
		PageState state = new PageState();
		CapturePages link = new CapturePages();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> searches.incrementAndGet(),
			link);
		engine.setStoreOps(new TestStoreOps());
		assertTrue(engine.execute("select", Map.of("query", "Tombs of Amascut")));
		List<Monster> mobs = state.rmobs();
		List<Map<com.ll.engine.Style, com.ll.optimizer.Service.Pick>> pm = new ArrayList<>();
		for (int i = 0; i < mobs.size(); i++) {
			pm.add(Map.of());
		}
		engine.onRosterResults(mobs, pm);
		flush();
		int after = searches.get();
		List<String> before = labels(state);

		assertTrue(engine.execute("move-mob", Map.of("index", 1, "delta", -1)));
		flush();
		assertEquals(after, searches.get(), "a reorder is presentation only");
		assertEquals(before.get(1), labels(state).get(0));
		assertEquals(before.get(1), link.firstMobName(), "the page shows the reordered roster without a search");

		assertTrue(engine.execute("undo", Map.of()));
		flush();
		assertEquals(after, searches.get(), "undo of a reorder is presentation only");
		assertEquals(before.get(0), link.firstMobName());
	}

	private static final class CapturePages extends CompanionLink {
		Map<String, Object> page;

		@Override
		public void publishPage(Map page) {
			this.page = page;
		}

		String firstMobName() {
