package com.ll.model;

import com.ll.data.DataService;
import com.ll.data.Tables;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Spellbook Swap + Vengeance as a SUPPLIES option (field ask
 * 2026-08-22): it changes which runes the trip carries and nothing
 * else - the damage Vengeance returns is deliberately unmodelled.
 */
class SpellbookSwapTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static CommandEngine engine(PageState state, CaptureLink link, int magic) {
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			link);
		engine.setMag(magic);
		// utilityRunes ride the page only when stores are wired.
		engine.setStoreOps(new TestStoreOps());
		return engine;
	}

	private static List<Map> runesOf(Map<String, Object> page) {
		List<?> entries = (List<?>) page.get("entries");
		Map<?, ?> entry = (Map<?, ?>) entries.get(0);
		List<?> mobs = (List<?>) entry.get("mobs");
		Object runes = ((Map<?, ?>) mobs.get(0)).get("utilityRunes");
		return runes instanceof List ? (List<Map>) runes
			: java.util.Collections.emptyList();
	}

	private static void flushEdt() {
		try {
			javax.swing.SwingUtilities.invokeAndWait(() -> {
			});
		} catch (Exception ex) {
			throw new AssertionError(ex);
		}
	}

	@Test
	@DisplayName("the option is offered only when 96 Magic is reachable")
	void offeredOnlyWhenReachable() {
		PageState state = new PageState();
		CaptureLink link = new CaptureLink();
		CommandEngine high = engine(state, link, 91);
		high.execute("select", Map.of("query", "abyssal demon"));
		high.onResults(data.searchMonsters("abyssal demon", 1).get(0), Map.of());
		flushEdt();
		assertEquals(Boolean.TRUE,
			((Map<?, ?>) link.published.get("assumeOptions")).get("spellbookSwapAvailable"),
			"91 + a boost reaches 96");

		PageState low = new PageState();
		CaptureLink lowLink = new CaptureLink();
		CommandEngine weak = engine(low, lowLink, 80);
		weak.execute("select", Map.of("query", "abyssal demon"));
		weak.onResults(data.searchMonsters("abyssal demon", 1).get(0), Map.of());
		flushEdt();
		assertEquals(Boolean.FALSE,
			((Map<?, ?>) lowLink.published.get("assumeOptions")).get("spellbookSwapAvailable"),
			"80 Magic cannot reach 96");
	}

	@Test
	@DisplayName("switching it on brings the swap and Vengeance runes")
	void bringsTheRunes() {
		PageState state = new PageState();
		CaptureLink link = new CaptureLink();
		CommandEngine engine = engine(state, link, 99);
		assertTrue(engine.execute("select", Map.of("query", "abyssal demon")));
		engine.onResults(data.searchMonsters("abyssal demon", 1).get(0), Map.of());
		flushEdt();
		assertTrue(runesOf(link.published).stream()
			.noneMatch(r -> String.valueOf(r.get("why")).contains("Vengeance")),
			"off by default");

		// Thralls live on Arceuus, so this trip genuinely swaps books.
		assertTrue(engine.execute("set-param", Map.of("param", "thralls", "value", true)));
		assertTrue(engine.execute("set-param",
			Map.of("param", "spellbookSwap", "value", true)));
		flushEdt();
		List<Map> runes = runesOf(link.published);
		assertTrue(runes.stream().anyMatch(r ->
			String.valueOf(r.get("why")).contains("Spellbook Swap")), "swap runes: " + runes);
		assertTrue(runes.stream().anyMatch(r ->
			String.valueOf(r.get("why")).contains("Vengeance")), "vengeance runes: " + runes);
	}

	@Test
	@DisplayName("it never moves a dps number - supplies only")
	void neverTouchesTheAnswer() {
		PageState state = new PageState();
		state.setParam("spellbookSwap", true);
		// A view param: it republishes the held answer, never recomputes.
		assertTrue(PageState.isViewParam("spellbookSwap"));
	}

	@Test
	@DisplayName("Vengeance alone brings no Spellbook Swap runes")
	void vengeanceStandsAlone() {
		// No thralls, no Death Charge, no fight book: nothing else wants
		// another spellbook, so there is nothing to swap into.
		PageState state = new PageState();
		CaptureLink link = new CaptureLink();
		CommandEngine engine = engine(state, link, 99);
		assertTrue(engine.execute("select", Map.of("query", "abyssal demon")));
		engine.onResults(data.searchMonsters("abyssal demon", 1).get(0), Map.of());
		assertTrue(engine.execute("set-param",
			Map.of("param", "spellbookSwap", "value", true)));
		flushEdt();
		List<Map> runes = runesOf(link.published);
		assertTrue(runes.stream().anyMatch(r ->
			String.valueOf(r.get("why")).contains("Vengeance")), "vengeance rides alone");
		assertTrue(runes.stream().noneMatch(r ->
			String.valueOf(r.get("why")).contains("Spellbook Swap")),
			"nothing to swap into: " + runes);

		// Turn thralls on and the swap earns its runes.
		assertTrue(engine.execute("set-param", Map.of("param", "thralls", "value", true)));
		flushEdt();
		assertTrue(runesOf(link.published).stream().anyMatch(r ->
			String.valueOf(r.get("why")).contains("Spellbook Swap")),
			"arceuus summons need the swap");
	}

	@Test
	@DisplayName("combination runes are a panel preference, detected by default")
	void comboRunesPreference() {
		// Field ask 2026-08-22: the choice belongs in the panel, and
		// "detect" means combine when you own combination runes.
		PageState state = new PageState();
		CaptureLink link = new CaptureLink();
		CommandEngine engine = engine(state, link, 99);
		java.util.Map<String, String> defaults = new java.util.HashMap<>();
		engine.setSupplyDefaults(() -> defaults);
		assertTrue(engine.execute("select", Map.of("query", "abyssal demon")));
		engine.onResults(data.searchMonsters("abyssal demon", 1).get(0), Map.of());
		flushEdt();

		List<?> catalog = (List<?>) link.published.get("supplyCatalog");
		assertTrue(catalog.stream().anyMatch(c ->
			"comboRunes".equals(((Map<?, ?>) c).get("category"))),
			"the preference rides the supplies menu: " + catalog);
	}

	private static final class CaptureLink extends CompanionLink {
		Map<String, Object> published;

		@Override
		public void publishPage(Map page) {
			published = page;
		}
	}
}

package com.ll.model;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.engine.ComputeParams;
import com.ll.engine.Levels;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * The stat sim through the engine (ISS-01M5QY13K6YHTYDW1CCYD30CSY): one
 * sim-stats command carries the seven levels and the max cape tick, is one
 * recompute and one undo step; the live levels ride the params node; the
 * report prints the sim while it is on.
 */
class StatSimParamsTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static final class Link extends CompanionLink {
		private Map<String, Object> last;

		@Override
		public void publishPage(Map page) {
			last = page;
		}

		@Override
		public Map<String, Object> lastPage() {
			return last;
		}
	}

	private static Map<String, Object> stats(int attack, int strength, int defence, int ranged, int magic, int prayer,
		int hitpoints, boolean maxCape) {
		return Map.of("attack", attack, "strength", strength, "defence", defence, "ranged", ranged, "magic", magic,
			"prayer", prayer, "hitpoints", hitpoints, "maxCape", maxCape);
	}

	@Test
	@DisplayName("sim-stats with 99 Attack and the max cape: one recompute carrying simLevels 99/0/0/0/0/0/0 and the cape; one undo step takes it back; Mine clears it")
	void simStatsIsOneStep() {
		AtomicInteger computes = new AtomicInteger();
		AtomicReference<ComputeParams> last = new AtomicReference<>();
		PageState state = new PageState();
		CommandEngine engine = new CommandEngine(data, state, (mob, p, onDone) -> {
			computes.incrementAndGet();
			last.set(p);
		}, new Link());
		assertTrue(engine.execute("select", Map.of("query", "abyssal demon")));
		assertEquals(1, computes.get());
		assertNull(last.get().simLevels, "nothing simmed: your own levels");

		assertTrue(engine.execute("sim-stats", stats(99, 0, 0, 0, 0, 0, 0, true)));
		assertEquals(2, computes.get(), "one recompute for the whole row");
		assertArrayEquals(new int[]{99, 0, 0, 0, 0, 0, 0}, last.get().simLevels);
		assertTrue(last.get().simMaxCape);
		assertEquals(99, ((Number) state.pn().get("simAttack")).intValue());

		// Undo restores the page it had, no recompute: the state goes back.
		assertTrue(engine.execute("undo", Map.of()));
		assertEquals(0, ((Number) state.pn().get("simAttack")).intValue(), "undone in one step");
		assertFalse((Boolean) state.pn().get("simMaxCape"));
		assertNull(state.computeParams().simLevels);

		assertTrue(engine.execute("sim-stats", stats(0, 0, 0, 0, 0, 0, 50, false)));
		assertArrayEquals(new int[]{0, 0, 0, 0, 0, 0, 50}, last.get().simLevels, "lower works too");
		assertTrue(engine.execute("sim-stats", stats(0, 0, 0, 0, 0, 0, 0, false)), "Mine");
		assertNull(last.get().simLevels);
	}

	@Test
	@DisplayName("the live levels ride the params node as myLevels")
	void liveLevels() {
		PageState state = new PageState();
		CommandEngine engine = new CommandEngine(data, state, (mob, p, onDone) -> {
		}, new Link());
		engine.setLevels(new Levels(70, 70, 70, 80, 85, 60, 80));
		assertEquals("70/70/70/80/85/60/80", state.pn().get("myLevels"));
	}
}

package com.ll.model;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.data.SpellRunes;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The sunfire assumption on the card (Kendyy, Discord 2026-10-19): a
 * page param seeded from ownership at each selection, toggled from the
 * card's sunfire plate, passed to every compute, re-seeded by Detect.
 */
class SunfireAssumptionTest {
	private static final int SUNFIRE_RUNE = 28929;
	private static final int FIRE_RUNE = 554;
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static CommandEngine engine(AtomicReference<Boolean> seen, boolean ownsSunfire) {
		CommandEngine engine = new CommandEngine(data, new PageState(),
			(mob, p, onDone) -> seen.set(p.sunfireRunes),
			new CompanionLink());
		engine.setStoreOps(new TestStoreOps());
		engine.setOwnedCheck(id -> ownsSunfire && id == SUNFIRE_RUNE);
		return engine;
	}

	@Test
	@DisplayName("selection seeds the sunfire assumption from ownership and passes it to the compute")
	void seededFromOwnership() {
		AtomicReference<Boolean> seen = new AtomicReference<>();
		CommandEngine engine = engine(seen, true);
		Monster araxxor = data.searchMonsters("araxxor", 1).get(0);
		engine.execute("select", Map.of("id", araxxor.getId()));
		assertEquals(Boolean.TRUE, seen.get(), "owned sunfire runes are assumed");

		AtomicReference<Boolean> none = new AtomicReference<>();
		engine(none, false).execute("select", Map.of("id", araxxor.getId()));
		assertEquals(Boolean.FALSE, none.get(), "no sunfire runes, no assumption");
	}

	@Test
	@DisplayName("a simmed sunfire rune counts as owned for the seed (Andrew, client test 2026-10-19)")
	void simmedRuneSeeds() {
		AtomicReference<Boolean> seen = new AtomicReference<>();
		CommandEngine engine = engine(seen, false);
		engine.setCounts(() -> Map.of("simmedItems",
			List.of(Map.of("id", SUNFIRE_RUNE, "name", "Sunfire rune"))));
		Monster araxxor = data.searchMonsters("araxxor", 1).get(0);
		engine.execute("select", Map.of("id", araxxor.getId()));
		assertEquals(Boolean.TRUE, seen.get(), "a sim is 'count this as owned'");
		engine.execute("set-param", Map.of("param", "sunfireRunes", "value", false));
		assertTrue(engine.execute("detect-sunfire", Map.of()));
		assertEquals(Boolean.TRUE, seen.get(), "Detect best sees the sim too");
	}

	@Test
	@DisplayName("the plate's toggle sticks and Detect re-seeds it")
	void toggleAndDetect() {
		AtomicReference<Boolean> seen = new AtomicReference<>();
		CommandEngine engine = engine(seen, true);
		Monster araxxor = data.searchMonsters("araxxor", 1).get(0);
		engine.execute("select", Map.of("id", araxxor.getId()));
		engine.execute("set-param", Map.of("param", "sunfireRunes", "value", false));
		assertEquals(Boolean.FALSE, seen.get(), "the manual pick reaches the compute");
		assertTrue(engine.execute("detect-sunfire", Map.of()));
		assertEquals(Boolean.TRUE, seen.get(), "Detect runs the ownership seed again");
	}

	@Test
	@DisplayName("with the assumption on, the trip runes carry sunfire runes in place of fire runes")
	void tripRunesSwap() {
		List<Map> runes = SpellRunes.costFor("Fire Surge", null, null);
		assertTrue(ids(runes).contains(FIRE_RUNE), "fixture: a bare Fire Surge costs fire runes");
		List<Map> swapped = SpellRunes.withSunfire(runes);
		assertFalse(ids(swapped).contains(FIRE_RUNE));
		assertTrue(ids(swapped).contains(SUNFIRE_RUNE));
		Map<String, Object> sunfire = swapped.stream()
			.filter(r -> ((Number) r.get("id")).intValue() == SUNFIRE_RUNE).findFirst().orElseThrow();
		assertEquals("Sunfire rune", sunfire.get("name"));
		assertEquals(runes.stream().filter(r -> ((Number) r.get("id")).intValue() == FIRE_RUNE)
			.findFirst().orElseThrow().get("qty"), sunfire.get("qty"), "same count per cast");
		List<Map> water = SpellRunes.costFor("Water Surge", null, null);
		assertEquals(ids(water), ids(SpellRunes.withSunfire(water)), "a water spell's runes are untouched");
	}

	private static List<Integer> ids(List<Map> runes) {
		List<Integer> out = new ArrayList<>();
		for (Map<String, Object> r : runes) {
			out.add(((Number) r.get("id")).intValue());
		}
		return out;
	}
}

package com.ll.model;

import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * A do-nothing StoreOps for engine tests - the page decoration that
 * attaches notes, pins and utility runes only runs when stores are
 * wired, so a test without one silently loses those facts.
 *
 * <p>{@code acceptedToggles} caps how many store TOGGLES succeed; past
 * it they refuse, which is how a revert is made to fail on purpose.
 */
class TestStoreOps implements CommandEngine.StoreOps, CommandEngine.MobProfiles {
	public CommandEngine.MobProfiles mobs() {
		return this;
	}

	public java.util.Map<String, java.util.Map<com.ll.data.Slot, Integer>> allPins(int monsterId) {
		return java.util.Map.of();
	}

	private final int acceptedToggles;
	private int toggles;

	TestStoreOps() {
		this(Integer.MAX_VALUE);
	}

	TestStoreOps(int acceptedToggles) {
		this.acceptedToggles = acceptedToggles;
