import static org.junit.jupiter.api.Assertions.*;

/**
 * A group's trip kills each monster once (Andrew 2026-10-30: "royal titans -
 * trip time is the total of all mobs but really it only clears the hp of the
 * titans once"; "the royal titans thing happens to anything with duplicated
 * mobs: toa, cox, tormented demons, demonic gorillas, tfa?, tob"; "Titans
 * only").
 */
class TripDedupeTest {
	private static List<MonsterGroup> groups;

	@BeforeAll
	static void load() {
		Tables data = new DataService().load();
		groups = MonsterGroups.load(data);
	}

	private static MonsterGroup group(String name) {
		return groups.stream().filter(g -> g.getName().equalsIgnoreCase(name)).findFirst().orElseThrow(AssertionError::new);
	}

	@Test
	@DisplayName("the Royal Titans trip counts Branda and Eldric once each, their first version, and leaves the elementals out")
	void royalTitans() {
		List<Monster> mobs = group("Royal Titans").getMobs();
		assertEquals(6, mobs.size());
		assertEquals(List.of(0, 1), RenderModel.tripMembers(mobs));
		assertTrue(mobs.get(4).hasAttribute("no_trip") && mobs.get(5).hasAttribute("no_trip"));
	}

	@Test
	@DisplayName("prayer variants and repeated raid bosses count once: Tormented Demons, Demonic gorillas, Zulrah's forms, the Tombs, the Chambers, the Theatre, the Archive")
	void duplicatesOnce() {
		for (String name : new String[]{"Tormented Demons", "Demonic gorillas", "Zulrah (all forms)", "Tombs of Amascut",
			"Chambers of Xeric", "Theatre of Blood (Entry)", "The Fractured Archive"}) {
			List<Monster> mobs = group(name).getMobs();
			List<Integer> counted = RenderModel.tripMembers(mobs);
			long distinct = mobs.stream().map(m -> m.name).distinct().count();
			assertEquals(distinct, counted.size(), name);
			for (int i : counted) {
				int first = i;
				for (int j = 0; j < i; j++) if (mobs.get(j).name.equals(mobs.get(i).name)) first = j;
				assertEquals(i, first, name + ": the first version counts");
			}
		}
	}
}

package com.ll.model;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Undo integrity, from the pre-release adversarial pass 2026-08-22.
 * The snapshot restore carried only the PAGE, so the results cache
 * kept the pre-undo answer and the next republish drew the wrong
 * mob; and a refused revert consumed history depth the snapshot
 * deques never followed, putting every later restore out of phase.
 */
class UndoIntegrityTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static void flushEdt() {
		try {
			javax.swing.SwingUtilities.invokeAndWait(() -> {
			});
		} catch (Exception ex) {
			throw new AssertionError(ex);
		}
	}

	private static String firstMobLabel(Map<String, Object> page) {
		List<?> entries = (List<?>) page.get("entries");
		if (entries == null || entries.isEmpty()) {
			return null;
		}
		List<?> mobs = (List<?>) ((Map<?, ?>) entries.get(0)).get("mobs");
		return mobs == null || mobs.isEmpty()
			? null : (String) ((Map<?, ?>) mobs.get(0)).get("label");
	}

	@Test
	@DisplayName("after undo, a republish draws the restored mob - not the undone one")
	void undoRestoresTheResultsWithThePage() {
		CaptureLink link = new CaptureLink();
		PageState state = new PageState();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			link);

		assertTrue(engine.execute("select", Map.of("query", "abyssal demon")));
		engine.onResults(data.searchMonsters("abyssal demon", 1).get(0), Map.of());
		flushEdt();
		assertTrue(engine.execute("select", Map.of("query", "zulrah")));
		engine.onResults(data.searchMonsters("zulrah", 1).get(0), Map.of());
		flushEdt();

		assertTrue(engine.execute("undo", Map.of()));
		flushEdt();
		assertTrue(firstMobLabel(link.published).toLowerCase().contains("abyssal"),
			"undo restored the demon page");

		// A pure VIEW param - it republishes from the results cache.
		assertTrue(engine.execute("set-param", Map.of("param", "thralls", "value", true)));
		flushEdt();
		assertTrue(firstMobLabel(link.published).toLowerCase().contains("abyssal"),
			"the republish must draw the RESTORED mob, not the undone one: "
				+ firstMobLabel(link.published));
	}

	@Test
	@DisplayName("a refused revert keeps the snapshot stacks in phase")
	void refusedRevertKeepsPhase() {
		CaptureLink link = new CaptureLink();
		PageState state = new PageState();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			link);
		engine.setStoreOps(new TestStoreOps(1));

		assertTrue(engine.execute("select", Map.of("query", "abyssal demon")));
		engine.onResults(data.searchMonsters("abyssal demon", 1).get(0), Map.of());
		flushEdt();

		// Accepted once, refused on the revert - CommandHistory drops it.
		assertTrue(engine.execute("toggle-exclusion", Map.of("itemId", 4151)));
		assertFalse(engine.execute("undo", Map.of()), "the refused revert reports failure");

		// The next undo must reach the SELECT, clearing the selection.
		assertTrue(engine.execute("undo", Map.of()));
		flushEdt();
		assertNull(state.mob(), "the select was undone");
		assertNull(firstMobLabel(link.published),
			"the page must be the pre-select one, not an orphaned snapshot");
	}

	@Test
	@DisplayName("undoing a select also undoes the params it seeded")
	void undoRestoresSeededParams() {
		CaptureLink link = new CaptureLink();
		PageState state = new PageState();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			link);

		assertTrue(engine.execute("select", Map.of("query", "abyssal demon")));
		assertEquals(Boolean.FALSE, state.pn().get("inWilderness"));

		// A wilderness-exclusive forces the param on at selection.
		assertTrue(engine.execute("select", Map.of("query", "callisto")));
		assertEquals(Boolean.TRUE, state.pn().get("inWilderness"),
			"the exclusive forced the wilderness param");

		assertTrue(engine.execute("undo", Map.of()));
		flushEdt();
		assertEquals(Boolean.FALSE, state.pn().get("inWilderness"),
			"undo must take the seeded params back with the selection");
	}


	private static final class CaptureLink extends CompanionLink {
		Map<String, Object> published;
		private Map<String, Object> last;

		@Override
		public void publishPage(Map page) {
			published = page;
			last = page;
		}

		@Override
		public Map<String, Object> lastPage() {
			return last;
		}
	}
}

package com.ll.model;

import com.google.gson.Gson;
import com.ll.collection.MonsterProfileStore;
import com.ll.data.DataService;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.testsupport.InMemoryConfigManager;
import java.util.Map;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Andrew 2026-10-22, Araxxor: "i got rid of my pin/ownership of obligator
 * and it is still comign in as a result" - he used right-click > Unpin
 * weapon. The engine's commands against the REAL profile store.
 */
class UnpinRoundTripTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	/** The plugin's StoreOps wiring for pins, over a real store. */
	private static TestStoreOps wired(MonsterProfileStore store) {
		return new TestStoreOps() {
			@Override
			public Map<String, Map<Slot, Integer>> allPins(int monsterId) {
				return store.allPins(monsterId);
			}

			@Override
			public void pin(int monsterId, String scope, Slot slot, int itemId) {
				store.pin(monsterId, scope, slot, itemId);
			}

			@Override
			public void unpin(int monsterId, String scope, Slot slot) {
				store.unpin(monsterId, scope, slot);
			}
		};
	}

	@Test
	@DisplayName("Unpin clears the slot in every scope - a style pin cannot outlive it - and one undo puts each back")
	void unpinClearsEveryScope() {
		ConfigManager cfg = InMemoryConfigManager.create();
		MonsterProfileStore store = new MonsterProfileStore(cfg, new Gson());
		store.loadScope("std.1");
		CommandEngine engine = new CommandEngine(data, new PageState(), (mob, p, onDone) -> {
		}, new CompanionLink());
		engine.setStoreOps(wired(store));
		Monster araxxor = data.searchMonsters("araxxor", 1).get(0);
		int mobId = araxxor.getId();
		assertTrue(engine.execute("select", Map.of("id", mobId)));
		store.pin(mobId, MonsterProfileStore.ALL, Slot.WEAPON, 4151);
		store.pin(mobId, "MELEE", Slot.WEAPON, 12006);
		store.pin(mobId, "RANGED", Slot.WEAPON, 12006);
		store.pin(mobId, MonsterProfileStore.ALL, Slot.HEAD, 10828);

		assertTrue(engine.execute("unpin", Map.of("slot", "weapon")));
		assertNull(store.pinsFor(mobId, "MELEE").get(Slot.WEAPON));
		assertNull(store.pinsFor(mobId, "RANGED").get(Slot.WEAPON));
		assertEquals(Integer.valueOf(10828), store.pinsFor(mobId, "MELEE").get(Slot.HEAD), "other slots stay");
		MonsterProfileStore fresh = new MonsterProfileStore(cfg, new Gson());
		fresh.loadScope("std.1");
		assertNull(fresh.pinsFor(mobId, "MELEE").get(Slot.WEAPON), "and it persisted");

		assertTrue(engine.execute("undo", Map.of()), "Unpin is one undo step");
		assertEquals(Integer.valueOf(12006), store.pinsFor(mobId, "MELEE").get(Slot.WEAPON), "the style pin is back");
		assertEquals(Integer.valueOf(12006), store.pinsFor(mobId, "RANGED").get(Slot.WEAPON));
		assertEquals(Integer.valueOf(4151), store.pinsFor(mobId, MonsterProfileStore.ALL).get(Slot.WEAPON), "and the ALL pin");

		assertFalse(engine.execute("unpin", Map.of("slot", "legs")), "nothing pinned there - nothing to undo");
		assertFalse(engine.execute("unpin", Map.of("slot", "no-such-slot")), "a bad slot name refuses");
	}

	private static int obligator() {
		return data.getGearItems().stream()
			.filter(g -> g.getLname().startsWith("obligator") && g.isStandardGear() && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError("no obligator")).getId();
	}

	@Test
	@DisplayName("Unpin weapon on Araxxor removes a pin made by Pin or by trying a swap")
	void unpinRemovesThePin() {
		MonsterProfileStore store = new MonsterProfileStore(InMemoryConfigManager.create(), new Gson());
		store.loadScope("std.1");
		CommandEngine engine = new CommandEngine(data, new PageState(), (mob, p, onDone) -> {
		}, new CompanionLink());
		engine.setStoreOps(wired(store));
		engine.setOwnedCheck(id -> true);
		Monster araxxor = data.searchMonsters("araxxor", 1).get(0);
		assertTrue(engine.execute("select", Map.of("id", araxxor.getId())));

		for (String how : new String[]{"pin", "ladder-try"}) {
			assertTrue(engine.execute(how, Map.of("slot", "weapon", "itemId", obligator(), "label", "Obligator")));
			assertEquals(Integer.valueOf(obligator()), store.pinsFor(araxxor.getId(), "MELEE").get(Slot.WEAPON), how);
			assertTrue(engine.execute("unpin", Map.of("slot", "weapon")));
			assertEquals(Map.of(), store.allPins(araxxor.getId()), "unpinned after " + how);
		}
	}

	@Test
	@DisplayName("on a roster view, pin / try / unpin act on the row the card shows")
	void rosterViewPins() {
		MonsterProfileStore store = new MonsterProfileStore(InMemoryConfigManager.create(), new Gson());
		store.loadScope("std.1");
		PageState state = new PageState();
		CommandEngine engine = new CommandEngine(data, state, (mob, p, onDone) -> {
		}, new CompanionLink());
		engine.setStoreOps(wired(store));
		engine.setOwnedCheck(id -> true);
		Monster araxxor = data.searchMonsters("araxxor", 1).get(0);
		Monster demon = data.searchMonsters("abyssal demon", 1).get(0);
		state.selectRoster(java.util.List.of(araxxor, demon), "Custom roster", false);

		for (String how : new String[]{"pin", "ladder-try"}) {
			assertTrue(engine.execute(how, Map.of("slot", "weapon", "itemId", obligator(), "label", "Obligator")), how);
			assertEquals(Integer.valueOf(obligator()), store.pinsFor(araxxor.getId(), "MELEE").get(Slot.WEAPON), how);
			assertTrue(engine.execute("unpin", Map.of("slot", "weapon")), "unpin after " + how);
			assertEquals(Map.of(), store.allPins(araxxor.getId()), "unpinned after " + how);
		}
	}
}

