		javax.swing.SwingUtilities.invokeAndWait(() -> {
		});
		AtomicReference<Monster> got = new AtomicReference<>();
		engine.setWikiCalcOpener((m, shown, dartId, assumes, onTask, inWilderness) -> got.set(m));
