/** Field report (Andrew, 2026-09-08): simmed chaos gauntlets never beat
 * the tormented bracelet on a Fire Bolt card. The per-slot pool keeps the
 * top ten by raw magic stats and the gauntlets score zero there - their
 * value lives in the DPS model, like the leaf-bladed battleaxe. Same for
 * the element amulets, which tie a crowd of glories at +10. */
class BoltGearPoolTest {
	private static Tables data;
	private static Monster goblin;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		goblin = data.searchMonsters("Goblin", 1).get(0);
	}

	@Test
	@DisplayName("chaos gauntlets reach the beam past ten better-statted gloves and win the Fire Bolt card")
	void gauntlets() throws Exception {
		Map<Integer, Integer> owned = own("staff of fire", "occult necklace", "chaos gauntlets", "tormented bracelet",
			"barrows gloves", "infinity gloves", "dragon gloves", "rune gloves", "lunar gloves", "bloodbark gauntlets",
			"adamant gloves", "swampbark gauntlets", "regen bracelet", "mystic gloves");
		assertEquals(777, slot(owned, "Fire Bolt", Slot.HANDS).getId(), "chaos gauntlets: 16 max hit beats 13");
	}

	@Test
	@DisplayName("an amulet of air reaches the beam past ten +10 necks and wins the Wind Bolt card")
	void elementAmulet() throws Exception {
		Map<Integer, Integer> owned = own("staff of air", "occult necklace", "amulet of air", "amulet of fury",
			"amulet of glory", "amulet of magic", "amulet of magic (t)", "dragonbone necklace", "bonecrusher necklace",
			"3rd age amulet", "amulet of the damned", "amulet of power", "amulet of glory (t)");
		assertEquals(34407, slot(owned, "Wind Bolt", Slot.NECK).getId(), "amulet of air: 14 max hit beats 13");
	}

	private static Map<Integer, Integer> own(String... names) {
		Map<Integer, Integer> owned = new HashMap<>();
		for (String name : names) {
			owned.put(byName(name).getId(), 1);
		}
		return owned;
	}

	private static Gear byName(String lname) {
		for (Gear g : data.getGearItems()) {
			if (g.getLname().equals(lname)) {
				return g;
			}
		}
		throw new AssertionError("missing from the gear data: " + lname);
	}

	private static Gear slot(Map<Integer, Integer> owned, String spellName, Slot slot) throws Exception {
		Spell spell = data.getSpells().stream().filter(s -> s.getName().equals(spellName)).findFirst().orElseThrow();
		Service service = new Service(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
			ServiceCalls.bestPerStyle(service, goblin, Levels.MAXED, Levels.MAXED,
				Prayers.ALL, RequirementProfile.MAXED, new Owned(owned, true), 1, false, false, "",
				Collections.emptySet(), -1, Req.DEFAULT_RISK_BUDGET_GP, false, Collections.emptySet(), 0,
				Collections.emptyMap(), spell, results -> {
					out.set(results);
					done.countDown();
				});
			assertTrue(done.await(120, TimeUnit.SECONDS));
			return out.get().get(Style.MAGIC).owned.get(0).getLoadout().get(slot);
		} finally {
			service.shutdown();
		}
	}
}

package com.ll.optimizer;

import com.ll.engine.BoostProfile;
import com.ll.engine.Style;
import com.ll.engine.Owned;
import com.ll.engine.Levels;
import java.util.HashMap;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Risk-capped wilderness searches never assume a heart (field spec
 * 2026-07-18): both hearts are tradeable and worth far more than any
 * sane risk cap - the magic assumption falls back to the potion.
 */
class BoostSelectorTest {
	@Test
	@DisplayName("a risk-capped wildy search downgrades the heart to a magic potion")
	void noHeartsUnderARiskCap() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(27641, 1); // saturated heart
		owned.put(3040, 1);  // magic potion(4) - the fallback must be OWNED now
		Owned bag = new Owned(owned, true);
		assertEquals(BoostProfile.SATURATED_HEART,
			BoostSelector.bestFor(Style.MAGIC, bag, false, false));
		assertEquals(BoostProfile.MAGIC,
			BoostSelector.bestFor(Style.MAGIC, bag, false, true));
	}

	@Test
	@DisplayName("the BiS ceiling assumes divine potions for melee and ranged")
	void ceilingPrefersDivine() {
		assertEquals(BoostProfile.DIVINE_SUPER_COMBAT,
			BoostSelector.ceilingFor(Style.MELEE, false));
		assertEquals(BoostProfile.DIVINE_RANGING,
			BoostSelector.ceilingFor(Style.RANGED, false));
		assertEquals(BoostProfile.SATURATED_HEART,
			BoostSelector.ceilingFor(Style.MAGIC, false),
			"the heart out-boosts the flat divine magic potion");
	}

	@Test
	@DisplayName("owned divine potions are preferred over the base assumption")
	void ownedDivinePreferred() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(23691, 1); // divine super combat (2) - any dose counts
		owned.put(23733, 1); // divine ranging (4)
		owned.put(23754, 1); // divine magic (1)
		Owned bag = new Owned(owned, true);
		assertEquals(BoostProfile.DIVINE_SUPER_COMBAT,
			BoostSelector.bestFor(Style.MELEE, bag, false, false));
		assertEquals(BoostProfile.DIVINE_RANGING,
			BoostSelector.bestFor(Style.RANGED, bag, false, false));
		assertEquals(BoostProfile.DIVINE_MAGIC,
			BoostSelector.bestFor(Style.MAGIC, bag, false, false));
	}

	@Test
	@DisplayName("an empty bank assumes NO boost - not a potion you do not own")
	void emptyBankAssumesNothing() {
		// RE-PINNED 2026-08-25. This test previously asserted SUPER_COMBAT /
		// RANGING / MAGIC for an EMPTY bank, encoding the old "tradeables are
		// always assumed" rule. Field report from a fresh ironman: the card
		// claimed "Assumes: Ranging potion" with none in the bank and the panel
		// set to detect from bank. The old expectations were the defect.
		Owned empty = new Owned(new HashMap<>(), true);
		assertEquals(BoostProfile.NONE,
			BoostSelector.bestFor(Style.MELEE, empty, false, false));
		assertEquals(BoostProfile.NONE,
			BoostSelector.bestFor(Style.RANGED, empty, false, false));
		assertEquals(BoostProfile.NONE,
			BoostSelector.bestFor(Style.MAGIC, empty, false, false));
	}

	@Test
	@DisplayName("owning the base potion still assumes it")
	void ownedBasePotionsAreAssumed() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(12695, 1);  // super combat potion(4)
		owned.put(2444, 1);   // ranging potion(4)
		owned.put(3040, 1);   // magic potion(4)
		Owned bag = new Owned(owned, true);
		assertEquals(BoostProfile.SUPER_COMBAT,
			BoostSelector.bestFor(Style.MELEE, bag, false, false));
		assertEquals(BoostProfile.RANGING,
			BoostSelector.bestFor(Style.RANGED, bag, false, false));
		assertEquals(BoostProfile.MAGIC,
			BoostSelector.bestFor(Style.MAGIC, bag, false, false));
	}

	@Test
	@DisplayName("bastion outranks ranging, battlemage outranks magic - even divine ones")
	void bastionAndBattlemageOutrankThePlainFamily() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(22461, 1);  // bastion potion(4)
		owned.put(22449, 1);  // battlemage potion(4)
		Owned bag = new Owned(owned, true);
		assertEquals(BoostProfile.BASTION,
			BoostSelector.bestFor(Style.RANGED, bag, false, false));
		assertEquals(BoostProfile.BATTLEMAGE,
			BoostSelector.bestFor(Style.MAGIC, bag, false, false));

		// Same offensive numbers plus a defence half, so bastion/battlemage win
		// even against the DIVINE plain variants (owner call 2026-08-25).
		owned.put(23733, 1);  // divine ranging potion(4)
		owned.put(23745, 1);  // divine magic potion(4)
		Owned both = new Owned(owned, true);
		assertEquals(BoostProfile.BASTION,
			BoostSelector.bestFor(Style.RANGED, both, false, false));
		assertEquals(BoostProfile.BATTLEMAGE,
			BoostSelector.bestFor(Style.MAGIC, both, false, false));
	}

	@Test
	@DisplayName("a divine bastion owner is told to bring the divine one, not the plain")
	void divineBastionAndBattlemage() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(24635, 1);  // divine bastion potion(4)
		owned.put(24623, 1);  // divine battlemage potion(4)
		Owned bag = new Owned(owned, true);
		// Same boost numbers as the plain pair, but the label drives the
		// "what to bring" icon (AssumeIcons) - collapsing them would point a
		// divine-only owner at a potion they do not have, which is the very
		// bug this release fixes.
		assertEquals(BoostProfile.DIVINE_BASTION,
			BoostSelector.bestFor(Style.RANGED, bag, false, false));
		assertEquals(BoostProfile.DIVINE_BATTLEMAGE,
			BoostSelector.bestFor(Style.MAGIC, bag, false, false));
	}

	@Test
	@DisplayName("reachable magic never assumes MAXED or an unowned potion")
	void reachableMagicIsHonest() {
		// Unknown levels -> 0, never 99 (the old fallback seeded Death
		// Charge ON for a fresh login, F2P included: field report 2026-08-27).
		assertEquals(0, BoostSelector.reachableMagic(null, null, null));

		Levels base85 = new Levels(70, 70, 70, 70, 85, 70, 70);
		Owned nothing = new Owned(new HashMap<>(), true);
		assertEquals(85, BoostSelector.reachableMagic(base85, null, nothing),
			"no boost owned - reachable is just the base");

		Map<Integer, Integer> heart = new HashMap<>();
		heart.put(27641, 1); // saturated heart: +4 then +10% -> 85 + 12 = 97
		assertEquals(97, BoostSelector.reachableMagic(base85, null,
			new Owned(heart, true)));

		// A live boost the player already drank counts even if unowned now.
		Levels live91 = new Levels(70, 70, 70, 70, 91, 70, 70);
		assertEquals(91, BoostSelector.reachableMagic(base85, live91, nothing));

		// A live DRAIN never drags reachable below base.
		Levels drained = new Levels(70, 70, 70, 70, 60, 70, 70);
		assertEquals(85, BoostSelector.reachableMagic(base85, drained, nothing));
	}

	@Test
	@DisplayName("an owned heart still beats an owned divine magic potion")
	void heartBeatsDivineMagic() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(27641, 1); // saturated heart
		owned.put(23745, 1); // divine magic (4)
		Owned bag = new Owned(owned, true);
		assertEquals(BoostProfile.SATURATED_HEART,
			BoostSelector.bestFor(Style.MAGIC, bag, false, false));
		assertEquals(BoostProfile.DIVINE_MAGIC,
			BoostSelector.bestFor(Style.MAGIC, bag, false, true),
			"under a risk cap the heart falls to the divine potion when owned");
	}

	@Test
	@DisplayName("with no super combat left, a super attack and a super strength together are the melee rung; one alone assumes nothing; a super combat still wins")
	void superAttackAndStrength() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(145, 1);    // super attack(3)
		owned.put(2440, 1);   // super strength(4)
		Owned pair = new Owned(owned, true);
		assertEquals(BoostProfile.SUPER_ATTACK_STRENGTH, BoostSelector.bestFor(Style.MELEE, pair, false, false));
		assertEquals(BoostProfile.NONE, BoostSelector.bestFor(Style.MELEE, new Owned(Map.of(2436, 1), true), false, false),
			"a super attack alone is no rung");
		owned.put(12699, 1);  // super combat(2)
		assertEquals(BoostProfile.SUPER_COMBAT, BoostSelector.bestFor(Style.MELEE, new Owned(owned, true), false, false));
		Levels boosted = BoostProfile.SUPER_ATTACK_STRENGTH.apply(Levels.MAXED, null);
		assertEquals(118, boosted.attack);
		assertEquals(118, boosted.strength);
		assertEquals(99, boosted.defence, "the pair leaves Defence alone");
	}
}

package com.ll.optimizer;

import com.ll.data.*;
import com.ll.engine.*;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Budget Cutter (ISS-01M674YPVT5GFVSAT2PAK8RXS1, field report 2026-10-28: "the
 * vardorvis budget cutter option in the loadout lab plugin, gives gear that is
 * greater than the maximum 2m"; Andrew 2026-10-30: "1, 2 and 3a"): the Lightbearer
 * obeys the task's rules, a capped price never wraps back to free, and the price
 * rule counts an imbued item or slayer helmet at what it is made from.
 */
class BudgetCutterTest {
    private static Tables data;
    private static Monster vardorvis;
    private static Rules budget;

    @BeforeAll
    static void load() {
        data = new DataService().load();
        vardorvis = data.searchMonsters("vardorvis", 1).get(0);
        budget = CombatAchievements.byId(493).rulesFor(List.of(vardorvis));
    }

    private static List<Gear> rows(String name) {
        List<Gear> found = new ArrayList<>();
        for (Slot slot : Slot.values()) {
            found.addAll(data.getGearItems(slot).stream().filter(g -> g.name.equals(name)).collect(Collectors.toList()));
        }
        assertFalse(found.isEmpty(), name + " is in the data");
        return found;
    }

    private static Gear item(String name) { return rows(name).get(0); }

    private static Gear item(String name, String version) {
        return rows(name).stream().filter(g -> g.version.equals(version)).findFirst()
            .orElseThrow(() -> new AssertionError(name + " " + version));
    }

    private static Kit wearing(Gear... items) {
        EnumMap<Slot, Gear> gear = new EnumMap<>(Slot.class);
        for (Gear g : items) gear.put(g.slot, g);
        return new Kit(gear);
    }

    private static Req request(Monster mob, Style style, Rules rules) {
        Req request = new Req(mob, style, Levels.MAXED, PrayerBonuses.NONE, null, 0,
            CandidateMode.ALL_STANDARD, false, false, Owned.EMPTY, RequirementProfile.MAXED, 10);
        return rules == null ? request : request.withSetRules(rules);
    }

    /** A price cap just under the Lightbearer's, so no market move can make the ring fit. */
    private static Rules tooDearForTheLightbearer() {
        double price = item("Lightbearer").getPriceOrZero();
        assertTrue(price > 0, "the Lightbearer has a price");
        return Rules.of(List.of(new Rules.Rule("price", "<=", price - 1)), Set.of(), null);
    }

    private static String describe(Kit set) {
        return set.getGear().values().stream().map(g -> g.name + " " + (long) Rules.of(g, "price"))
            .collect(Collectors.joining(", ")) + " = " + (long) Rules.total(set, "price");
    }

    // REQ-1

    @Test
    @DisplayName("the Lightbearer comes into a set only when the set still keeps the request's rules")
    void swapObeysTheRules() {
        Kit whip = wearing(item("Abyssal whip"));
        Kit free = Service.lightbearerSwap(data, whip, List.of(request(vardorvis, Style.MELEE, null)), null);
        assertNotNull(free, "no rules: the ring comes in");
        assertEquals("Lightbearer", free.get(Slot.RING).name);
        assertNull(Service.lightbearerSwap(data, whip,
            List.of(request(vardorvis, Style.MELEE, tooDearForTheLightbearer())), null), "over a price rule");
        assertNull(Service.lightbearerSwap(data, whip,
            List.of(request(vardorvis, Style.MELEE, Rules.of(List.of(), Set.of("Lightbearer"), null))), null), "banned by name");
        Rules roomy = Rules.of(List.of(new Rules.Rule("price", "<=", 2_000_000_000d)), Set.of(), null);
        assertNotNull(Service.lightbearerSwap(data, whip, List.of(request(vardorvis, Style.MELEE, roomy)), null),
            "a rule it fits does not keep it out");
    }

    @Test
    @DisplayName("a group's Lightbearer stays out when any one member's rules break it")
    void rosterVariantObeysEveryMember() {
        Kit whip = wearing(item("Abyssal whip"));
        Monster other = data.searchMonsters("general graardor", 1).get(0);
        assertNotNull(Service.lightbearerVariant(data, whip,
            List.of(request(vardorvis, Style.MELEE, null), request(other, Style.MELEE, null)), null));
        assertNull(Service.lightbearerVariant(data, whip,
            List.of(request(vardorvis, Style.MELEE, null), request(other, Style.MELEE, tooDearForTheLightbearer())), null));
    }

    @Test
    @DisplayName("every set Vardorvis shows under Budget Cutter keeps the 2m, best in game and yours, in every style and mode")
    void everyShownSetKeepsTheRule() throws Exception {
        // Yours holds the ring and a spec weapon, so the swap has something to win.
        Map<Integer, Integer> bank = new HashMap<>();
        // Ferocious gloves: the best melee gloves, worth their Hydra leather (field report 2026-10-30, "8M cost").
        for (String name : List.of("Lightbearer", "Dragon claws", "Abyssal whip", "Berserker ring (i)", "Seers ring (i)", "Amulet of glory", "Ferocious gloves", "Barrows gloves")) {
            bank.put(item(name).id, 1);
        }
        Owned owned = new Owned(bank, true);
        Service service = new Service(data);
        try {
            int mine = 0;
            for (String mode : List.of("MAX_DPS", "BALANCED", "TANKY")) {
                ComputeParams p = new ComputeParams();
                p.setRules = budget;
                p.optimizeMode = mode;
                var done = new CompletableFuture<Map<Style, Service.Pick>>();
                service.bestPerStyle(vardorvis, Levels.MAXED, Levels.MAXED, Prayers.ALL, RequirementProfile.MAXED,
                    owned, 1, p, Collections.emptyMap(), Collections.emptySet(), Collections.emptyMap(), null, 0,
                    Collections.<Integer>emptySet(), done::complete);
                Map<Style, Service.Pick> styles = done.get(5, TimeUnit.MINUTES);
                assertEquals(3, styles.size(), mode);
                for (var e : styles.entrySet()) {
                    Kit best = e.getValue().overallBest.getLoadout();
                    assertTrue(budget.holds(best), mode + " " + e.getKey() + " best in game: " + describe(best));
                    for (Dps yours : e.getValue().owned) {
                        mine++;
                        assertTrue(budget.holds(yours.getLoadout()), mode + " " + e.getKey() + " yours: " + describe(yours.getLoadout()));
                        Gear hands = yours.getLoadout().get(Slot.HANDS);
                        assertFalse(hands != null && hands.name.equals("Ferocious gloves"), mode + " " + e.getKey() + " yours wears the 8m gloves: " + describe(yours.getLoadout()));
                    }
                }
            }
            assertTrue(mine > 0, "the owned side was searched too");
        } finally {
            service.shutdown();
        }
    }

    // REQ-2

    @Test
    @DisplayName("a capped price plus anything costs int max, not a wrapped negative the card shows as free")
    void cappedCostStaysCapped() {
        Gear obligator = item("Obligator", "Charged");
        assertEquals(Integer.MAX_VALUE, obligator.getPriceOrZero(), "its 2.4b price caps at load");
        Gear amulet = item("Amulet of fury");
        assertTrue(amulet.getPriceOrZero() > 0);
        Kit set = wearing(obligator, amulet);
        assertEquals(Integer.MAX_VALUE, set.cost);
        assertEquals(Integer.MAX_VALUE, new Calc().calculate(request(vardorvis, Style.MELEE, null), set).purchaseCost);
        assertFalse(budget.holds(set), "the price rule never read it as free");
    }

    @Test
    @DisplayName("Zulrah's forced recoil on a capped set stays at int max too")
    void recoilOnACappedSet() {
        Monster zulrah = data.searchMonsters("zulrah", 1).get(0);
        // The free recoils out, so the priced Ring of recoil is the one that comes in.
        Set<Integer> free = new HashSet<>();
        for (String name : List.of("Ring of suffering (i)", "Ring of suffering", "Echo boots")) {
            for (Gear row : rows(name)) free.add(row.id);
        }
        Req request = request(zulrah, Style.MAGIC, null).withExcludedItems(free);
        Kit set = wearing(item("Trident of the Swamp", "Charged"), item("3rd Age druidic robe top"));
        Dps shown = new Calc().calculate(request, set);
        assertEquals(Integer.MAX_VALUE, shown.purchaseCost, "the robe top's price caps");
        Dps recoiled = new LoadoutOptimizer().ensureRequiredUtility(data, request, shown);
        assertEquals("Ring of recoil", recoiled.getLoadout().get(Slot.RING).name);
        assertTrue(recoiled.getLoadout().get(Slot.RING).getPriceOrZero() > 0, "a priced recoil, or no sum can wrap");
        assertEquals(Integer.MAX_VALUE, recoiled.purchaseCost);
    }

    // REQ-3

    @Test
    @DisplayName("an imbued ring counts as the ring it was made from, in every version")
    void imbuedRingsCountTheirBase() {
        for (String ring : List.of("Berserker ring", "Seers ring", "Archers ring", "Warrior ring", "Ring of the gods")) {
            int base = item(ring).getPriceOrZero();
            assertTrue(base > 0, ring + " has a price");
            List<Gear> imbued = rows(ring + " (i)");
            assertTrue(imbued.size() >= 2, ring + ": the Soul Wars and Emir's Arena rows too");
            for (Gear row : imbued) assertEquals(base, (int) Rules.of(row, "price"), row.name + " " + row.version);
        }
    }

    @Test
    @DisplayName("an imbued item whose base has untradeable rows too still counts the tradeable one")
    void cheapestTradeableBaseCounts() {
        assertEquals(item("Ring of suffering", "Uncharged").getPriceOrZero(), (int) Rules.of(rows("Ring of suffering (i)").get(0), "price"));
    }

    @Test
    @DisplayName("every slayer helmet, plain, imbued or recoloured, and the imbued black mask count as the cheapest black mask")
    void slayerHelmetsCountTheBlackMask() {
        int mask = rows("Black mask").stream().filter(g -> g.tradeable).mapToInt(Gear::getPriceOrZero).min().getAsInt();
        assertTrue(mask > 0);
        for (String name : List.of("Slayer helmet", "Slayer helmet (i)", "Hydra slayer helmet", "Hydra slayer helmet (i)", "Black mask (i)")) {
            for (Gear row : rows(name)) assertEquals(mask, (int) Rules.of(row, "price"), row.name + " " + row.version);
        }
    }

    @Test
    @DisplayName("an untradeable made from tradeables counts them: Ferocious gloves their Hydra leather, a faceguard its helm and jaw, crystal armour its seeds, a blood fury its fury, the Avernic defender the 600k the game values it at")
    void componentTableCounts() {
        double gloves = Rules.of(item("Ferocious gloves"), "price");
        assertTrue(gloves > 2_000_000, "Hydra leather alone breaks Budget Cutter: " + gloves);
        assertNull(item("Ferocious gloves").estimatedPrice, "the market price stays unknown");
        assertFalse(budget.holds(wearing(item("Ferocious gloves"))), "the gloves alone break the rule");
        double helm = Rules.of(item("Crystal helm", "Active"), "price");
        assertTrue(helm > 0);
        assertEquals(3 * helm, Rules.of(item("Crystal body", "Active"), "price"), 1, "a body is three seeds to a helm's one");
        assertEquals(2 * helm, Rules.of(item("Crystal legs", "Active"), "price"), 1);
        // The table is priced at its own refresh; the corpus snapshot may be a few days apart.
        Map<String, Integer> table = Json.read("component_prices.json", new com.google.gson.reflect.TypeToken<Map<String, Integer>>() {}.getType());
        assertEquals(table.get("amulet of blood fury"), (int) Rules.of(item("Amulet of blood fury"), "price"));
        int fury = item("Amulet of fury").getPriceOrZero();
        assertTrue(Math.abs(fury - table.get("amulet of blood fury")) < fury * 0.1, "the table's fury is the corpus's fury, give or take a market week: " + fury + " vs " + table.get("amulet of blood fury"));
        assertEquals(600_000, (int) Rules.of(item("Avernic defender"), "price"));
        double faceguard = Rules.of(item("Neitiznot faceguard"), "price");
        assertTrue(faceguard > item("Helm of Neitiznot").getPriceOrZero(), "the jaw counts on top of the helm: " + faceguard);
    }

    @Test
    @DisplayName("an untradeable with nothing tradeable behind it stays at 0 until the in-game read, and a priced item counts its own price")
    void everythingElseAsBefore() {
        for (String name : List.of("Fire cape", "Barrows gloves", "Crystal bow (i)", "Salve amulet(i)", "Imbued Guthix cape")) {
            assertEquals(0, (int) Rules.of(item(name), "price"), name);
        }
        Gear fury = item("Amulet of fury");
        assertEquals(fury.getPriceOrZero(), (int) Rules.of(fury, "price"));
    }

    // REQ-4

    @Test
    @DisplayName("only the price rule reads it: budgets, risk and the card still see an imbued ring as unpriced")
    void marketPriceUntouched() {
        Gear ring = rows("Berserker ring (i)").get(0);
        assertNull(ring.estimatedPrice);
        assertEquals(0, ring.getPriceOrZero());
        assertEquals(0, wearing(ring).cost);
    }
}

package com.ll.optimizer;

import com.ll.data.DataService;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.engine.*;
import java.util.Collections;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Andrew (client test 2026-10-19): "best should always align with the
 * highest dps option". The Best-in-game side is the ceiling, so it
 * always assumes a super antifire against a fire-breather and never
 * spends its shield slot on protection; Yours keeps the owned-tier
 * detection and the manual pick.
 */
class CeilingAntifireTest {
	@Test
	@DisplayName("the game-best card at Vorkath assumes a super antifire: no protective shield")
	void ceilingAssumesSuperAntifire() throws Exception {
		Tables data = new DataService().load();
		Monster vorkath = data.searchMonsters("vorkath", 1).get(0);
		Service service = new Service(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
			ServiceCalls.bestPerStyle(service, vorkath, Levels.MAXED, Levels.MAXED,
				Prayers.ALL, RequirementProfile.MAXED, new Owned(Map.of(4151, 1), true), 7,
				false, false, "", Collections.emptySet(), -1,
				Req.DEFAULT_RISK_BUDGET_GP, false, Collections.emptySet(), 0,
				results -> { out.set(results); done.countDown(); });
			assertTrue(done.await(120, TimeUnit.SECONDS));
			Service.Pick melee = out.get().get(Style.MELEE);
			assertNotNull(melee);
			assertNotNull(melee.overallBest, "a game-best melee set must exist");
			var shield = melee.overallBest.getLoadout().get(Slot.SHIELD);
			assertNotNull(shield, "the ceiling still wears a shield slot item");
			assertFalse(DragonfireRules.isProtectiveShield(shield),
				"the ceiling spends the slot on dps, not protection: " + shield.getLname());
		} finally {
			service.shutdown();
		}
	}
}

package com.ll.optimizer;

import com.ll.data.DataService;
import com.ll.data.Gear;
