import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Swaps on a group search (ISS-01M5JAGFEJ5QHXE37B37XM8HJJ, Andrew 2026-10-22:
 * "ladder view is disabled for group searches but i think it should be
 * included" - scored by "The whole group").
 */
class GroupSwapsTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static int id(String lname) {
		return data.getGearItems().stream()
			.filter(g -> g.getLname().equals(lname) && g.isStandardGear() && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing " + lname)).getId();
	}

	@Test
	@DisplayName("a group search has swaps: one strip on every member, scored by the group's HP-weighted DPS")
	void groupStrip() throws Exception {
		List<Monster> mobs = List.of(data.searchMonsters("abyssal demon", 1).get(0),
			data.searchMonsters("black demon", 1).get(0));
		Map<Integer, Integer> owned = new HashMap<>();
		for (String name : new String[]{"abyssal whip", "dragon scimitar", "rune scimitar", "fighter torso",
			"dragon defender"}) {
			owned.put(id(name), 1);
		}
		Service service = new Service(data);
		try {
			Service.RosterResult roster = ServiceCalls.runRoster(service, mobs, owned, 0, Map.of());
			Service.Pick first = roster.pm.get(0).get(Style.MELEE);
			Service.Pick second = roster.pm.get(1).get(Style.MELEE);
			Service.Ladder weapon = first.ladder.get(Slot.WEAPON);
			assertNotNull(weapon, "the group's weapon slot has swaps");
			assertTrue(weapon.group, "scored across the group");
			assertSame(weapon, second.ladder.get(Slot.WEAPON), "every member shows the same strip");
			for (Service.Step rung : weapon.up) {
				assertTrue(rung.dps > weapon.bdps, rung.item.getName() + " helps the group");
			}
			for (Service.Step rung : weapon.down) {
				assertTrue(rung.owned && rung.dps < weapon.bdps, rung.item.getName() + " is yours and worse");
			}
			assertFalse(weapon.up.isEmpty());
		} finally {
			service.shutdown();
		}
	}
}

package com.ll.optimizer;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.data.RequiredGear;
import com.ll.engine.*;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Elling (Discord 2026-10-30): "Hespori isnt putting a fast range weapon to
 * kill the sprouts"; AKAddons: "i'll make sure it puts a 2 tick range weapon
 * in" (ISS-01M65N6WS5N2V9TQC0MJ03NKY8). A swap rule may name a kind: the best
 * owned ranged weapon that fires at 2 ticks on rapid rides the inventory.
 */
class HesporiFastSwapTest {
	private static Tables data;
	private static Monster hespori;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		hespori = data.searchMonsters("hespori", 1).get(0);
	}

	private static int id(String name) {
		return data.getGearItems().stream().filter(g -> g.getLname().equals(name) && g.isStandardGear() && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError(name)).getId();
	}

	private static Map<Style, Service.Pick> search(Map<Integer, Integer> owned) throws Exception {
		ComputeParams p = new ComputeParams();
		p.maxSwaps = 2;
		Service service = new Service(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
			service.bestPerStyle(hespori, Levels.MAXED, Levels.MAXED, Prayers.ALL,
				RequirementProfile.MAXED, new Owned(owned, true), 7, p, Collections.emptyMap(),
				Collections.emptySet(), Collections.emptyMap(), null, 0, Collections.<Integer>emptySet(), r -> {
					out.set(r);
					done.countDown();
				});
			assertTrue(done.await(300, TimeUnit.SECONDS));
			return out.get();
		} finally {
			service.shutdown();
		}
	}

	private static boolean fast(Gear g) { return g.speed == 3 && g.isWeaponFor(Style.RANGED); }

	@Test
	@DisplayName("Hespori's swap rule is the fast ranged kind; Cerberus' stays an item")
	void rule() {
		assertEquals("fastRanged", RequiredGear.swaps(hespori).get(0).category);
		assertNull(RequiredGear.swaps(data.searchMonsters("cerberus", 1).get(0)).get(0).category);
	}

	@Test
	@DisplayName("a melee bank with rune knives and adamant darts carries the better of them to Hespori, with the rule's note; the BiS side carries the game's best 2-tick weapon")
	void knivesRide() throws Exception {
		Map<Integer, Integer> owned = new HashMap<>();
		for (String name : new String[]{"abyssal whip", "avernic defender", "bandos chestplate", "bandos tassets", "rune knife", "adamant dart"}) {
			owned.put(id(name), 1);
		}
		Service.Pick melee = search(owned).get(Style.MELEE);
		List<Gear> fastOnes = melee.bench.stream().filter(HesporiFastSwapTest::fast).collect(java.util.stream.Collectors.toList());
		assertEquals(1, fastOnes.size(), "one fast ranged weapon rides: " + melee.bench);
		assertEquals(id("rune knife"), fastOnes.get(0).id, "the knives out-hit the darts");
		assertTrue(melee.swapNotes.get(id("rune knife")).contains("sprouts"), melee.swapNotes.toString());
		assertTrue(melee.gameBench.stream().anyMatch(HesporiFastSwapTest::fast), "BiS carries one too: " + melee.gameBench);
	}

	@Test
	@DisplayName("a bank with no fast ranged weapon carries none")
	void nothingToCarry() throws Exception {
		Map<Integer, Integer> owned = new HashMap<>();
		for (String name : new String[]{"abyssal whip", "avernic defender", "bandos chestplate", "bandos tassets"}) {
			owned.put(id(name), 1);
		}
		Service.Pick melee = search(owned).get(Style.MELEE);
		assertTrue(melee.bench.stream().noneMatch(HesporiFastSwapTest::fast), melee.bench.toString());
	}
}

package com.ll.optimizer;

import com.ll.data.DataService;
