import static org.junit.jupiter.api.Assertions.*;

/**
 * A card's damage taken rolls the boss against the levels its assumed prayer
 * gives (ISS-01M6415DFFW34P8QY468GA74KY, Andrew 2026-10-29: "Tabs + defence
 * fix"): the same prayer the card's dps assumes, the player's pick first.
 */
class IncomingPrayerTest {
	private static final Kit NAKED = new Kit(new EnumMap<>(Slot.class));
	private static Tables data;
	private static Service service;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		service = new Service(data);
	}

	@AfterAll
	static void stop() {
		service.shutdown();
	}

	private static Service.ComputeContext context(Map<Style, String> prayerPicks) {
		ComputeParams p = new ComputeParams();
		p.prayerPicks = prayerPicks;
		return service.buildContext(Levels.MAXED, Levels.MAXED, Prayers.ALL, RequirementProfile.MAXED,
			Owned.EMPTY, 1, p, Collections.emptyMap(), Collections.emptySet(), Collections.emptyMap(),
			Collections.emptyMap(), Collections.emptyMap(), Collections.<Integer>emptySet());
	}

	@Test
	@DisplayName("Blood Moon's damage taken on a melee card is the calculator's at Defence 123 under Zeal, 118 under a Chivalry pick, 99 prayerless")
	void meleeCards() {
		Monster moon = data.searchMonsters("blood moon", 1).get(0);
		double zeal = Service.inc(moon, NAKED, context(Map.of()), Style.MELEE).tot;
		double chivalry = Service.inc(moon, NAKED,
			context(Map.of(Style.MELEE, "Chivalry")), Style.MELEE).tot;
		double none = Service.inc(moon, NAKED,
			context(Map.of(Style.MELEE, "NONE")), Style.MELEE).tot;
		assertEquals(Incoming.calculate(moon, NAKED, 123, 99, 0).tot, zeal, 1e-12);
		assertEquals(Incoming.calculate(moon, NAKED, 118, 99, 0).tot, chivalry, 1e-12);
		assertEquals(Incoming.calculate(moon, NAKED, 99, 99, 0).tot, none, 1e-12);
		assertTrue(zeal < chivalry && chivalry < none, zeal + " < " + chivalry + " < " + none);
	}

	@Test
	@DisplayName("a mage's spells on a magic card roll against Augury's Magic and Defence: 99 and 99 read 123 and 123")
	void auguryCard() {
		Monster mage = new Monster(1, "Test mage", "", 300, 255, 1, 1, 200, 0,
			MonsterDefences.ZERO, new MonsterOffence(1, 1, 1, 200, 0, 0, 0, 0, 0, 0, 4, List.of("Magic")),
			Collections.emptyList(), false, "", 0);
		// Unprayed: Protect from Magic blocks a lone magic style outright.
		double augury = Service.inc(mage, NAKED, context(Map.of()), Style.MAGIC).unprayedDps;
		assertEquals(Incoming.calculate(mage, NAKED, 123, 123, 0).unprayedDps, augury, 1e-12);
		assertTrue(augury < Incoming.calculate(mage, NAKED, 99, 99, 0).unprayedDps);
	}
}

package com.ll.optimizer;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.engine.Style;
import com.ll.engine.MonsterMechanics;
import com.ll.engine.Owned;
import com.ll.engine.Levels;
import com.ll.engine.Prayers;
import com.ll.engine.RequirementProfile;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Assert;
import org.junit.Test;

/**
 * The single-mob cache key must carry the ToA invocation level (found
 * by a token-diet agent 2026-08-09: optimizeKey had it, baseKeyFor did
 * not - so flipping the Invocation chip on a Warden card served the
 * PREVIOUS level's cached results). The defence scaling
 * (x(250+invo)/250) guarantees the two levels' numbers must differ.
 */
public class InvocationCacheKeyTest {
	private static Map<Style, Service.Pick> best(
		Service service, Monster monster) throws Exception {
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Map<Style, Service.Pick>> out =
			new AtomicReference<>();
		ServiceCalls.bestPerStyle(service, monster,
			Levels.MAXED, Levels.MAXED, Prayers.ALL,
			RequirementProfile.MAXED, Owned.EMPTY, 1,
			false, false, "", new EnumMap<>(Style.class), -1,
			com.ll.engine.Req.DEFAULT_RISK_BUDGET_GP,
			false, false, Collections.emptySet(), 0,
			Collections.emptyMap(), null, Collections.emptySet(),
			r -> { out.set(r); done.countDown(); });
		Assert.assertTrue("compute timed out", done.await(120, TimeUnit.SECONDS));
		return out.get();
	}

	@Test
	public void flippingTheInvocationLevelNeverServesStaleResults() throws Exception {
		Tables data = new DataService().load();
		Monster warden = data.searchMonsters("tumeken's warden", 6).stream()
			.filter(m -> MonsterMechanics.toaScaled(m))
			.findFirst().orElseThrow();
		Service service = new Service(data);
		try {
			double atZero = best(service, MonsterMechanics.atToaInvocation(warden, 0))
				.get(Style.RANGED).overallBest.getDps();
			double at300 = best(service, MonsterMechanics.atToaInvocation(warden, 300))
				.get(Style.RANGED).overallBest.getDps();
			Assert.assertNotEquals("invocation 300 must not serve the cached"
					+ " invocation-0 numbers (defence x2.2 has to move the dps)",
				atZero, at300, 1e-9);
			Assert.assertTrue("higher invocation means lower dps",
				at300 < atZero);
		} finally {
			service.shutdown();
		}
	}
}

package com.ll.optimizer;

