/**
 * A style's shared kit is weighed by the mobs that USE the style
 * (ISS-01M5PKSQBAP823XNC13QBW8830, Andrew 2026-10-24: "when i pin my trident
 * of the seas in that spot, i get 4.6 dps so for some reason it is missing
 * trident of the seas in this calculation"). The Warden's Core is meleed; its
 * earth weakness must not hand the MAGIC kit to the Purging staff's Earth
 * Surge when the trident is better on the mob that actually gets maged.
 */
class KitWeightsByStyleUseTest {
	private static Tables data;
	private static Service service;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		service = new Service(data);
	}

	@AfterAll
	static void stop() {
		service.shutdown();
	}

	private static Monster member(MonsterGroups.MonsterGroup group, String name, String label) {
		return group.getMobs().stream()
			.filter(m -> m.getName().equals(name) && m.label().contains(label)).findFirst()
			.orElseThrow(() -> new AssertionError("no " + name + " " + label));
	}

	@Test
	@DisplayName("Akkha (Magic only) and the Warden's Core: the Core is meleed, so the magic kit wears the trident for Akkha, not the Purging staff the Core's earth weakness would pick")
	void magicKitFollowsTheMagedMob() throws Exception {
		MonsterGroups.MonsterGroup toa = MonsterGroups.load(data).stream()
			.filter(g -> g.getName().equals("Tombs of Amascut")).findFirst().orElseThrow();
		Monster akkha = member(toa, "Akkha", "Magic only");
		Monster core = member(toa, "Tumeken's Warden", "Core");
		Map<Integer, Integer> owned = new HashMap<>();
		for (String name : new String[]{"trident of the seas", "purging staff", "ancestral hat", "ancestral robe top",
			"ancestral robe bottom", "occult necklace", "tormented bracelet", "eternal boots", "imbued zamorak cape",
			"magus ring", "rada's blessing 4", "noxious halberd", "torva full helm", "torva platebody", "torva platelegs",
			"amulet of torture", "ferocious gloves", "primordial boots", "infernal cape", "ultor ring"}) {
			int id = data.getGearItems().stream()
				.filter(g -> g.getLname().equals(name) && g.isStandardGear() && !data.isVariant(g.getId()))
				.findFirst().orElseThrow(() -> new AssertionError("corpus is missing " + name)).getId();
			owned.put(id, 1);
		}
		for (int rune : new int[]{554, 555, 556, 557, 560, 565, 566, 21880}) {
			owned.put(rune, 10000);
		}
		ComputeParams p = new ComputeParams();
		p.thralls = true; // Andrew's raid setting: the trident keeps the group on Arceuus with thralls
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Service.RosterResult> out = new AtomicReference<>();
		service.bestPerStyleAcross(List.of(akkha, core), Levels.MAXED, Levels.MAXED, Prayers.ALL,
			RequirementProfile.MAXED, new Owned(owned, true), owned.hashCode(), p, Map.of(), Set.of(), Map.of(), Map.of(),
			Map.of(), Map.of(), Map.of(), Set.of(), roster -> {
				out.set(roster);
				done.countDown();
			});
		assertTrue(done.await(180, TimeUnit.SECONDS), "roster compute timed out");
		Service.RosterResult roster = out.get();

		Service.Pick coreMelee = roster.pm.get(1).get(Style.MELEE);
		Service.Pick coreMagic = roster.pm.get(1).get(Style.MAGIC);
		assertNotNull(coreMelee);
		assertTrue(coreMelee.owned.get(0).getDps() > coreMagic.owned.get(0).getDps(),
			"the Core is a melee fight: " + coreMelee.owned.get(0).getDps() + " vs magic " + coreMagic.owned.get(0).getDps());

		Dps akkhaMagic = roster.pm.get(0).get(Style.MAGIC).owned.get(0);
		assertTrue(akkhaMagic.getLoadout().getWeapon().getLname().contains("trident"),
			"the magic kit follows Akkha, the mob that gets maged: " + akkhaMagic.getLoadout().getWeapon().getName()
				+ " / " + akkhaMagic.getSpellName() + " = " + akkhaMagic.getDps());
		assertEquals("arceuus", roster.groupBook, "a powered staff everywhere: " + roster.bookReason);
	}
}

package com.ll.optimizer;

import com.ll.data.*;
import com.ll.engine.*;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Ladder steps obey the task's rules (ISS-01M677A58TRKYM8HJB58SBRQBP, Andrew
 * 2026-10-30: "Yes, filter them"): under Budget Cutter a melee ladder at Vardorvis
 * offered a Scythe of Vitur at 1.09b. Prices come from the data, never literals,
 * so a market move cannot quietly make a case pass.
 */
class LadderRulesTest {
    private static Tables data;
    private static Monster vardorvis;
    private final LoadoutOptimizer optimizer = new LoadoutOptimizer();

    @BeforeAll
    static void load() {
        data = new DataService().load();
        vardorvis = data.searchMonsters("vardorvis", 1).get(0);
    }

    private static Gear item(String name) {
        for (Slot slot : Slot.values()) {
            for (Gear g : data.getGearItems(slot)) if (g.name.equals(name)) return g;
        }
        throw new AssertionError(name + " is in the data");
    }

    private static Kit wearing(Gear... items) {
        EnumMap<Slot, Gear> gear = new EnumMap<>(Slot.class);
        for (Gear g : items) gear.put(g.slot, g);
        return new Kit(gear);
    }

    private static Req request(Monster mob, Rules rules) {
        Req request = new Req(mob, Style.MELEE, Levels.MAXED, PrayerBonuses.NONE, null, 0,
            CandidateMode.ALL_STANDARD, false, false, Owned.EMPTY, RequirementProfile.MAXED, 10);
        return rules == null ? request : request.withSetRules(rules);
    }

    private static Rules atMost(String stat, double value) {
        return Rules.of(List.of(new Rules.Rule(stat, "<=", value)), Set.of(), null);
    }

    private static Dps shown(Req request, Kit set) {
        return new Calc().calculate(request, set);
    }

    private static List<Service.Step> rungs(Service.Ladder ladder) {
        List<Service.Step> all = new ArrayList<>(ladder.up);
        all.addAll(ladder.down);
        all.addAll(ladder.upMore);
        all.addAll(ladder.downMore);
        if (ladder.all != null) all.addAll(ladder.all);
        return all;
    }

    private static Set<String> names(List<Dps> steps, Slot slot) {
        return steps.stream().map(s -> s.getLoadout().get(slot).name).collect(Collectors.toSet());
    }

    private static Dps stepWearing(List<Dps> steps, Gear item) {
        return steps.stream().filter(s -> s.getLoadout().get(item.slot).id == item.id).findFirst().orElse(null);
    }

    @Test
    @DisplayName("a slot's steps under a task's rules all keep them, and the same search with no rules still offers the rest")
    void stepsKeepTheRules() {
        Gear whip = item("Abyssal whip");
        Gear fits = item("Warrior ring");
        Gear dear = item("Berserker ring");
        assertTrue(dear.getPriceOrZero() > fits.getPriceOrZero(), "the data still prices them apart");
        Kit set = wearing(whip, item("Ring of shadows"));
        Rules cap = atMost("price", whip.getPriceOrZero() + fits.getPriceOrZero());

        Req free = request(vardorvis, null);
        Set<String> offered = names(optimizer.slotSwaps(data, free, shown(free, set), Slot.RING), Slot.RING);
        assertTrue(offered.contains(dear.name), "no rules: every step is still offered");

        Req ruled = request(vardorvis, cap);
        List<Dps> steps = optimizer.slotSwaps(data, ruled, shown(ruled, set), Slot.RING);
        Set<String> kept = names(steps, Slot.RING);
        assertTrue(kept.contains(fits.name), "a ring that fits stays");
        assertFalse(kept.contains(dear.name), "over the cap");
        assertFalse(kept.contains("Berserker ring (i)"), "the imbued one counts its base");
        for (Dps step : steps) assertTrue(cap.holds(step.getLoadout()), step.getLoadout().get(Slot.RING).name);
    }

    @Test
    @DisplayName("a weapon step whose best shield breaks a rule stays on the ladder with a shield that keeps it")
    void weaponStepRepicksItsShield() {
        Gear whip = item("Abyssal whip");
        Kit set = wearing(item("Dragon scimitar"));
        Req free = request(vardorvis, null);
        Dps best = stepWearing(optimizer.slotSwaps(data, free, shown(free, set), Slot.WEAPON), whip);
        assertNotNull(best, "the whip is a step");
        Gear bestShield = best.getLoadout().get(Slot.SHIELD);
        assertNotNull(bestShield, "a one-hander brings its best shield");
        double limit = Rules.total(best.getLoadout(), "str") - 1;

        Req ruled = request(vardorvis, atMost("str", limit));
        Dps step = stepWearing(optimizer.slotSwaps(data, ruled, shown(ruled, set), Slot.WEAPON), whip);
        assertNotNull(step, "the whip stays on the ladder");
        assertTrue(Rules.total(step.getLoadout(), "str") <= limit);
        assertNotEquals(bestShield.id, step.getLoadout().get(Slot.SHIELD) == null ? -1 : step.getLoadout().get(Slot.SHIELD).id);
    }

    @Test
    @DisplayName("a rule every shield in the pool breaks still leaves the one-handers, wearing what the set wears")
    void aRuleThePoolBreaksKeepsOneHanders() {
        Req ruled = request(vardorvis, atMost("weight", 0));
        List<Dps> steps = optimizer.slotSwaps(data, ruled, shown(ruled, wearing(item("Imbued tephra"))), Slot.WEAPON);
        assertFalse(steps.isEmpty(), "the weightless one-handers are still steps");
        for (Dps step : steps) assertNull(step.getLoadout().get(Slot.SHIELD), step.getLoadout().getWeapon().name);
    }

    @Test
    @DisplayName("a task that needs the worn shield keeps its one-hander steps, each with that shield, and loses the two-handers")
    void aRuleAboutTheShieldKeepsOneHanders() {
        Monster kbd = data.searchMonsters("king black dragon", 1).get(0);
        // The task's own terms: antifire up, so no dragonfire lock narrows the shield
        // pool. The search itself finds no set here today (the score cut drops the
        // shield), so this holds the ladder's side for when it does.
        Req ruled = request(kbd, CombatAchievements.byId(166).rulesFor(List.of(kbd))).withAntifirePotion(true);
        Gear antiDragon = item("Anti-dragon shield");
        List<Dps> steps = optimizer.slotSwaps(data, ruled, shown(ruled, wearing(item("Dragon scimitar"), antiDragon)), Slot.WEAPON);
        Dps whip = stepWearing(steps, item("Abyssal whip"));
        assertNotNull(whip, "the whip stays on the ladder");
        assertEquals(antiDragon.id, whip.getLoadout().get(Slot.SHIELD).id);
        assertNull(stepWearing(steps, item("Elder maul")), "a two-hander cannot wear the shield the task needs");
    }

    @Test
    @DisplayName("every ladder step Vardorvis shows under Budget Cutter keeps the 2m, and there is still a ladder")
    void everyShownStepKeepsTheRule() throws Exception {
        Rules budget = CombatAchievements.byId(493).rulesFor(List.of(vardorvis));
        Map<Integer, Integer> bank = new HashMap<>();
        for (String name : List.of("Lightbearer", "Dragon claws", "Abyssal whip", "Berserker ring (i)", "Seers ring (i)")) {
            bank.put(item(name).id, 1);
        }
        ComputeParams p = new ComputeParams();
        p.setRules = budget;
        Service service = new Service(data);
        try {
            var done = new CompletableFuture<Map<Style, Service.Pick>>();
            service.bestPerStyle(vardorvis, Levels.MAXED, Levels.MAXED, Prayers.ALL, RequirementProfile.MAXED,
                new Owned(bank, true), 1, p, Collections.emptyMap(), Collections.emptySet(), Collections.emptyMap(), null, 0,
                Collections.<Integer>emptySet(), done::complete);
            int steps = 0;
            for (var style : done.get(5, TimeUnit.MINUTES).entrySet()) {
                for (var slot : style.getValue().ladder.entrySet()) {
                    for (Service.Step rung : rungs(slot.getValue())) {
                        assertNotNull(rung.set, "a solo step carries its set");
                        steps++;
                        assertTrue(budget.holds(rung.set.getLoadout()), style.getKey() + " " + slot.getKey() + " " + rung.item.name
                            + " " + (long) Rules.total(rung.set.getLoadout(), "price"));
                    }
                }
            }
            assertTrue(steps > 0, "the owned side's ladder is still there");
        } finally {
            service.shutdown();
        }
    }

    @Test
    @DisplayName("a group step one member's rules refuse is dropped for the group, not averaged in as a 0")
    void groupDropsARefusedStep() {
        Gear whip = item("Abyssal whip");
        Gear glory = item("Amulet of glory");
        Gear shadows = item("Ring of shadows");
        Gear dear = item("Berserker ring");
        Gear cheap = item("Warrior ring");
        assertTrue(glory.getPriceOrZero() > 0 && cheap.getPriceOrZero() + glory.getPriceOrZero() < dear.getPriceOrZero(), "the data still prices them apart");
        // The dear ring fits the plain set exactly; on the set with an amulet too it does not.
        Rules cap = atMost("price", whip.getPriceOrZero() + dear.getPriceOrZero());
        // Owned, so a halved step would still show, as a step down.
        List<Service.Step> steps = groupRingSteps(cap, new Owned(Map.of(dear.id, 1, cheap.id, 1), true),
            wearing(whip, shadows), wearing(whip, shadows, glory));
        assertFalse(steps.isEmpty(), "the group's ring ladder is still there");
        for (Service.Step step : steps) {
            assertNotEquals(dear.name, step.item.name, "refused on the second member's set");
            assertTrue(step.pm[0] > 0 && step.pm[1] > 0, step.item.name + " has a number for every member");
        }
    }

    @Test
    @DisplayName("a group step a member already wears is no refusal: it stays for the others")
    void groupKeepsAStepAMemberWears() {
        Gear whip = item("Abyssal whip");
        Gear shadows = item("Ring of shadows");
        Gear ring = item("Warrior ring");
        Rules cap = atMost("price", whip.getPriceOrZero() + ring.getPriceOrZero());
        List<Service.Step> steps = groupRingSteps(cap, new Owned(Map.of(ring.id, 1), true),
            wearing(whip, shadows), wearing(whip, shadows), wearing(whip, ring));
        assertTrue(steps.stream().anyMatch(step -> step.item.id == ring.id), "the two in Ring of shadows can still take it");
    }

    // The ring steps of a group strip: one member per set, all under the rules.
    private static List<Service.Step> groupRingSteps(Rules rules, Owned owned, Kit... sets) {
        String[] names = {"vardorvis", "general graardor", "commander zilyana"};
        List<Monster> mobs = new ArrayList<>();
        List<Req> rq = new ArrayList<>();
        List<List<Dps>> bests = new ArrayList<>();
        List<Map<Style, Service.Pick>> pm = new ArrayList<>();
        double[] weights = new double[sets.length];
        for (int j = 0; j < sets.length; j++) {
            mobs.add(data.searchMonsters(names[j], 1).get(0));
            rq.add(request(mobs.get(j), rules));
            Dps set = shown(rq.get(j), sets[j]);
            bests.add(List.of(set));
            pm.add(Map.of(Style.MELEE, result(set)));
            weights[j] = 1;
        }
        var side = new Service.SharedSide(rq, bests, weights);
        side.shared = sets[0];
        Service service = new Service(data);
        try {
            var ctx = service.buildContext(Levels.MAXED, Levels.MAXED, Prayers.ALL, RequirementProfile.MAXED, owned, 1,
                new ComputeParams(), Map.of(), Set.of(), Map.of(), Map.of(), Map.of(), Set.of());
            Service.Ladder rings = service.groupLadderFor(ctx, side, mobs, pm, Style.MELEE).get(Slot.RING);
            return rings == null ? List.of() : rungs(rings);
        } finally {
            service.shutdown();
        }
    }

    private static Service.Pick result(Dps set) {
        return new Service.Pick(List.of(set), set, null, null, "", "", null, null, List.of(), List.of(), false, false);
    }
}

package com.ll.optimizer;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.engine.Style;
import com.ll.engine.Owned;
import com.ll.engine.Levels;
import com.ll.engine.Prayers;
import com.ll.engine.RequirementProfile;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Assert;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * The Lightbearer's stat line is empty, so it can never win the ring
 * slot on dps - its value is doubled spec regen. The arbitration prices
 * both ring candidates on the TOTAL (set dps + spec dps-added) and the
 * argmax wins (field report 2026-08-08: "it can be really impactful in
 * fights with big spec utility").
 */
public class LightbearerArbitrationTest {
	private static Tables data;

	@BeforeClass
	public static void load() {
		data = new DataService().load();
	}

	private static Gear byName(String lname) {
		for (Gear g : data.getGearItems()) {
			// The charged version: an uncharged one is its variant now
			// (ISS-01M5QQV2TGQ5X730T0JJ75S1RD) and no pin can wear it.
			if (g.getLname().equals(lname) && g.isStandardGear() && !data.isVariant(g.getId())) {
				return g;
			}
		}
		throw new AssertionError("corpus is missing: " + lname);
	}

	private static Service.Pick melee(Monster monster,
		Map<Integer, Integer> owned) throws Exception {
		Service service = new Service(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
			ServiceCalls.bestPerStyle(service, monster,
				Levels.MAXED, Levels.MAXED, Prayers.ALL,
				RequirementProfile.MAXED, new Owned(owned, true), 1,
				false, false, "", new java.util.EnumMap<>(Style.class), -1,
				com.ll.engine.Req.DEFAULT_RISK_BUDGET_GP,
				false, false, Collections.emptySet(), 0,
				Collections.emptyMap(), null, Collections.emptySet(),
				results -> {
					out.set(results);
					done.countDown();
				});
			Assert.assertTrue("compute timed out", done.await(120, TimeUnit.SECONDS));
			return out.get().get(Style.MELEE);
		} finally {
			service.shutdown();
		}
	}

	@Test
	public void aPinnedSpecWeaponOverridesTheAutoPick() throws Exception {
		// Field request 2026-08-09: "i'm unable to pin to the spec slot."
		// A pinned melee spec forces the melee card to it, even when the
		// model would pick something else - and never starves the ranged
		// card of its own free spec (the pin serves only melee here).
		// The pin forces the spec on EVERY style card, not just its own
		// (field report 2026-08-09: a pinned RANGED Tonalztics ignored on
		// the melee card read as "the pin doesn't take") - specs compete
		// cross-style, so the ranged pin must ride the MELEE card too. This
		// is the user's exact scenario (a simmed Tonalztics of ralos).
		Monster rex = data.searchMonsters("dagannoth rex", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(byName("abyssal whip").getId(), 1);
		int tonalId = byName("tonalztics of ralos").getId();
		Service service = new Service(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
			ServiceCalls.bestPerStyle(service, rex,
				Levels.MAXED, Levels.MAXED, Prayers.ALL,
				RequirementProfile.MAXED, new Owned(owned, true), 1,
				false, false, "", new java.util.EnumMap<>(Style.class), -1,
				com.ll.engine.Req.DEFAULT_RISK_BUDGET_GP,
				false, false, Collections.singleton(tonalId), 0,
				Collections.emptyMap(), null, tonalId, Collections.emptySet(),
				results -> { out.set(results); done.countDown(); });
			Assert.assertTrue("timed out", done.await(120, TimeUnit.SECONDS));
			Service.Pick melee = out.get().get(Style.MELEE);
			Assert.assertNotNull("the melee card must carry the cross-style pin",
				melee.specWeapon);
			Assert.assertEquals("the pinned Tonalztics rides the melee spec slot too",
				tonalId, melee.specWeapon.getId());
		} finally {
			service.shutdown();
		}
	}

	@Test
	public void aPinnedSpecShowsEvenWhenItAddsNothing() throws Exception {
		// Field report 2026-08-09: pinning the Tonalztics on a set it does
		// not help showed NOTHING for the spec ("it would be great if that
		// was more clear"). A pin is the player's explicit choice - it must
		// display with its honest number, even ~0.00, not vanish. A goblin
		// dies before any spec fires, so a pinned DDS adds ~0 here.
		Monster goblin = data.searchMonsters("goblin", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		for (String n : new String[]{"abyssal whip", "dragon dagger"}) {
			owned.put(byName(n).getId(), 1);
		}
		int daggerId = byName("dragon dagger").getId();
		Service service = new Service(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
			ServiceCalls.bestPerStyle(service, goblin,
				Levels.MAXED, Levels.MAXED, Prayers.ALL,
				RequirementProfile.MAXED, new Owned(owned, true), 1,
				false, false, "", new java.util.EnumMap<>(Style.class), -1,
				com.ll.engine.Req.DEFAULT_RISK_BUDGET_GP,
				false, false, Collections.emptySet(), 0,
				Collections.emptyMap(), null, daggerId, Collections.emptySet(),
				results -> { out.set(results); done.countDown(); });
			Assert.assertTrue("timed out", done.await(120, TimeUnit.SECONDS));
			Service.Pick melee = out.get().get(Style.MELEE);
			Assert.assertNotNull("the pinned spec must still show", melee.specWeapon);
			Assert.assertEquals(daggerId, melee.specWeapon.getId());
			Assert.assertTrue("its honest ~0 value is displayed, not hidden",
				melee.sda >= 0);
		} finally {
			service.shutdown();
		}
	}

	@Test
	public void lightbearerWinsALongFightWhenTheRingCostsNoDps() throws Exception {
		// Ring of dueling and the Lightbearer are both stat-less: equal set
		// dps, so the doubled regen's extra claws are pure profit and the
		// Lightbearer MUST take the slot at a long fight.
		Monster nex = data.searchMonsters("nex", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		for (String n : new String[]{"abyssal whip", "dragon claws",
			"ring of dueling", "lightbearer"}) {
			owned.put(byName(n).getId(), 1);
		}
		Service.Pick melee = melee(nex, owned);
		Assert.assertNotNull(melee);
		Gear ring = melee.owned.get(0).getLoadout().get(com.ll.data.Slot.RING);
		Assert.assertNotNull("a ring must be worn", ring);
		Assert.assertTrue("doubled regen with no dps cost must take the slot, was: "
			+ ring.label(), ring.getLname().contains("lightbearer"));
		Assert.assertNotNull("the claws still ride as the spec", melee.specWeapon);
	}

	@Test
	public void aDpsRingKeepsTheSlotWhenSpecValueIsTiny() throws Exception {
		// A goblin dies before a second spec fires - the Berserker ring's
		// strength is worth more than regen nobody uses.
		Monster goblin = data.searchMonsters("goblin", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		for (String n : new String[]{"abyssal whip", "dragon claws",
			"berserker ring (i)", "lightbearer"}) {
			owned.put(byName(n).getId(), 1);
		}
		Service.Pick melee = melee(goblin, owned);
		Assert.assertNotNull(melee);
		Gear ring = melee.owned.get(0).getLoadout().get(com.ll.data.Slot.RING);
		Assert.assertNotNull(ring);
		Assert.assertTrue("no spec value, no swap - the dps ring stands, was: "
			+ ring.label(), ring.getLname().contains("berserker"));
	}

	@Test
	public void flooredBossesYieldNoDrainValue() throws Exception {
		// The same high-defence dummy twice: once synthetic (unfloored),
		// once wearing Verzik's id - whose defence_floors.json floor is
		// its own base, so the drain block must contribute NOTHING and
		// the DWH prices at damage mode alone (competitor audit
		// 2026-08-08: without the clamp, drain fishing overvalued drain
		// specs at floored bosses).
		com.ll.data.MonsterDefences def =
			new com.ll.data.MonsterDefences(150, 150, 150, 100, 0, 60, 60, 60);
		com.ll.data.Monster unfloored = new com.ll.data.Monster(
			-42, "Drain Dummy", "", 500, 800, 3, 350, 200, 0,
			def, null, java.util.Collections.emptyList(), false, "", 0);
		com.ll.data.Monster floored = new com.ll.data.Monster(
			8372, "Verzik Dummy", "", 500, 800, 3, 350, 200, 0,
			def, null, java.util.Collections.emptyList(), false, "", 0);

		Service service = new Service(data);
		try {
			double[] added = new double[2];
			com.ll.data.Monster[] dummies = {unfloored, floored};
			for (int i = 0; i < 2; i++) {
				com.ll.engine.Req request =
					com.ll.engine.TestRequests.of(dummies[i],
						Style.MELEE, Levels.MAXED,
						com.ll.engine.PrayerBonuses.bestAvailable(Levels.MAXED),
						null, 0, com.ll.engine.CandidateMode.ALL_STANDARD,
						true, false, Owned.EMPTY, 1);
				java.util.EnumMap<com.ll.data.Slot, Gear> worn =
					new java.util.EnumMap<>(com.ll.data.Slot.class);
				worn.put(com.ll.data.Slot.WEAPON, byName("abyssal whip"));
				com.ll.engine.Dps main = new com.ll.engine.Calc()
					.calculate(request, new com.ll.engine.Kit(worn));
				java.util.EnumMap<com.ll.data.Slot, Gear> specWorn =
					new java.util.EnumMap<>(com.ll.data.Slot.class);
				specWorn.put(com.ll.data.Slot.WEAPON, byName("dragon warhammer"));
				com.ll.engine.Dps specBase = new com.ll.engine.Calc()
					.calculate(request, new com.ll.engine.Kit(specWorn));
				com.ll.engine.SpecialAttack dwh =
					com.ll.engine.SpecialAttack.match(byName("dragon warhammer"));
				double expected = dwh.expectedDamage(specBase, dummies[i], Levels.MAXED);
				added[i] = service.sda(new com.ll.engine.Calc(),
					dwh, specBase, expected, request, main, false);
			}
			Assert.assertTrue("the floor must strip the drain value: unfloored "
				+ added[0] + " vs floored " + added[1], added[0] > added[1] + 1e-9);
		} finally {
			service.shutdown();
		}
	}

	@Test
	public void doubledRegenRaisesDrainValueWhenTheBudgetLimitsFishing() throws Exception {
		// A synthetic high-defence dummy: the DWH land chance is low, so
		// P(landed) = 1-(1-p)^attempts is budget-bound - exactly where the
		// Lightbearer's extra specs buy real drain probability. v1 priced
		// ONE attempt, making drain value blind to regen.
		com.ll.data.Monster dummy = new com.ll.data.Monster(
			-42, "Drain Dummy", "", 500, 800, 3, 350, 200, 0,
			new com.ll.data.MonsterDefences(150, 150, 150, 100, 0, 60, 60, 60),
			null, java.util.Collections.emptyList(), false, "", 0);
		com.ll.engine.Req request =
			com.ll.engine.TestRequests.of(dummy,
				Style.MELEE, Levels.MAXED,
				com.ll.engine.PrayerBonuses.bestAvailable(Levels.MAXED),
				null, 0, com.ll.engine.CandidateMode.ALL_STANDARD,
				true, false, Owned.EMPTY, 1);

		java.util.EnumMap<com.ll.data.Slot, Gear> worn =
			new java.util.EnumMap<>(com.ll.data.Slot.class);
		worn.put(com.ll.data.Slot.WEAPON, byName("abyssal whip"));
		com.ll.engine.Dps main = new com.ll.engine.Calc()
			.calculate(request, new com.ll.engine.Kit(worn));
		Assert.assertNotNull(main);

		java.util.EnumMap<com.ll.data.Slot, Gear> specWorn =
			new java.util.EnumMap<>(com.ll.data.Slot.class);
		specWorn.put(com.ll.data.Slot.WEAPON, byName("dragon warhammer"));
		com.ll.engine.Dps specBase = new com.ll.engine.Calc()
			.calculate(request, new com.ll.engine.Kit(specWorn));
		Assert.assertNotNull(specBase);
		com.ll.engine.SpecialAttack dwh =
			com.ll.engine.SpecialAttack.match(byName("dragon warhammer"));
		Assert.assertNotNull(dwh);
		double expected = dwh.expectedDamage(specBase, dummy, Levels.MAXED);

		Service service = new Service(data);
		try {
			double without = service.sda(new com.ll.engine.Calc(),
				dwh, specBase, expected, request, main, false);
			double with = service.sda(new com.ll.engine.Calc(),
				dwh, specBase, expected, request, main, true);
			Assert.assertTrue("more attempts must buy drain probability: "
				+ without + " -> " + with, with > without + 1e-9);
		} finally {
			service.shutdown();
		}
	}
}

package com.ll.optimizer;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.engine.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Andrew 2026-10-30: "when i sim lightbearer i'm not seeing how it compares
 * with my ring swaps" (ISS-01M65RVX7GAEXPRYHWW529ZQ19). The ring ladder is
 * priced with the spec, so the stat-less Lightbearer stands as a step.
 */
class LightbearerLadderTest {
	private static Tables data;
	private static Monster cerberus;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		cerberus = data.searchMonsters("cerberus", 1).get(0);
	}

	private static int id(String name) {
		return data.getGearItems().stream().filter(g -> g.getLname().equals(name) && g.isStandardGear() && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError(name)).getId();
	}

	private static Service.Pick melee(Map<Integer, Integer> owned) throws Exception {
		ComputeParams p = new ComputeParams();
		p.maxSwaps = 3;
		Service service = new Service(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
			service.bestPerStyle(cerberus, Levels.MAXED, Levels.MAXED, Prayers.ALL,
				RequirementProfile.MAXED, new Owned(owned, true), 7, p, Collections.emptyMap(),
				Collections.emptySet(), Collections.emptyMap(), null, 0, Collections.<Integer>emptySet(), r -> {
					out.set(r);
					done.countDown();
				});
			assertTrue(done.await(300, TimeUnit.SECONDS));
			return out.get().get(Style.MELEE);
		} finally {
			service.shutdown();
		}
	}

	private static List<Service.Step> steps(Service.Ladder ladder) {
		List<Service.Step> all = new ArrayList<>();
		all.addAll(ladder.up);
		all.addAll(ladder.down);
		all.addAll(ladder.upMore);
		all.addAll(ladder.downMore);
		return all;
	}

	@Test
	@DisplayName("with dragon claws in play, the ring ladder is priced with the spec and lists the owned Lightbearer as a step against the dps rings")
	void lightbearerIsARingStep() throws Exception {
		Map<Integer, Integer> owned = new HashMap<>();
		for (String name : new String[]{"abyssal whip", "avernic defender", "bandos chestplate", "bandos tassets", "dragon claws",
			"ultor ring", "berserker ring (i)", "lightbearer"}) {
			owned.put(id(name), 1);
		}
		Service.Pick melee = melee(owned);
		assertNotNull(melee.spec, "the claws seat a spec");
		Service.Ladder ring = melee.ladder.get(Slot.RING);
		assertNotNull(ring, "a ring ladder");
		assertTrue(ring.spec, "priced with the spec");
		Gear worn = melee.owned.get(0).loadout.get(Slot.RING);
		List<String> names = new ArrayList<>();
		for (Service.Step r : steps(ring)) names.add(r.item.getLname());
		String other = worn.getLname().equals("lightbearer") ? "ultor ring" : "lightbearer";
		assertTrue(names.contains(other), "the ring the arbitration did not seat is a step: worn " + worn.getLname() + ", steps " + names);
	}
}

package com.ll.optimizer;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.engine.Style;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.engine.Req;
import com.ll.engine.Levels;
import com.ll.engine.Owned;
import com.ll.engine.Prayers;
import com.ll.engine.RequirementProfile;
import net.runelite.api.Skill;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field report 2026-08-27: "it's saying my bis on obor is a rune scimitar but
 * my attack is only 10 so i can't use that."
 *
 * <p>The ceiling gated on RequirementProfile.MAXED, so it named gear the player
 * could not wear and quoted a DPS that can never occur - reaching the 40 Attack
 * a rune scimitar needs changes the number it was quoting. It now uses the same
 * requirement profile as the Yours side, leaving OWNERSHIP as the only
 * difference between the two, which is the gap the comparison exists to show.
 *
 * <p>The goldens cannot catch this: FixtureBank is a maxed account, where the
 * two requirement profiles agree.
 */
class LowLevelCeilingTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	/** A fresh account: 10 Attack, nothing trained, every quest unstarted. */
	private static RequirementProfile freshAccount() {
		Map<Skill, Integer> levels = new HashMap<>();
		for (Skill s : Skill.values()) {
			levels.put(s, 1);
		}
		levels.put(Skill.ATTACK, 10);
		levels.put(Skill.HITPOINTS, 10);
		return new RequirementProfile(levels, Collections.emptySet());
	}

	@Test
	@DisplayName("the BiS ceiling never names gear the player cannot equip")
	void ceilingRespectsThePlayersRequirements() throws Exception {
		Monster obor = data.searchMonsters("obor", 1).get(0);
		RequirementProfile fresh = freshAccount();
		Levels levels = new Levels(10, 1, 1, 10, 1, 1, 1);

		Service service = new Service(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<Style, Service.Pick>> out =
				new AtomicReference<>();
			ServiceCalls.bestPerStyle(service, obor,
				levels, levels, Prayers.ALL,
				fresh, new Owned(new HashMap<>(), true), 0,
				false, false, "", new EnumMap<>(Style.class), -1,
				Req.DEFAULT_RISK_BUDGET_GP, false, false,
				Collections.emptySet(), 0,
				Collections.emptyMap(), null, 0, Collections.emptySet(),
				r -> {
					out.set(r);
					done.countDown();
				});
			assertTrue(done.await(300, TimeUnit.SECONDS), "the Obor query timed out");

			Service.Pick melee = out.get().get(Style.MELEE);
			assertNotNull(melee, "no melee result for Obor");
			assertNotNull(melee.overallBest, "no game-best set for Obor");

			for (Slot slot : Slot.values()) {
				Gear worn = melee.overallBest.getLoadout().get(slot);
				if (worn == null) {
					continue;
				}
				// Levels only: the ceiling never trims on the quest log (2026-09-09).
				assertTrue(fresh.withAllQuests().canEquip(worn.getRequirements()),
					"the ceiling put on " + worn.getName()
						+ ", which a 10 Attack account cannot equip");
			}
		} finally {
			service.shutdown();
		}
	}
}

package com.ll.optimizer;

import com.ll.data.DataService;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.engine.Style;
import com.ll.engine.ComputeParams;
import com.ll.engine.MultiTool;
import com.ll.engine.Owned;
import com.ll.engine.Levels;
import com.ll.engine.Prayers;
import com.ll.engine.RequirementProfile;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The Multi card's rows (Andrew 2026-10-19): with the Multi switch on, a
 * multi-able mob's compute also ranks the three multi tools - the best
 * ancient burst/barrage set, the best chinchompa set, the venator bow
 * set - each a full per-target Pick; a mob outside the multi
 * list computes nothing extra, and a tool the player does not own has
 * no Yours side.
 */
class MultiToolsTest {
	private static final int BLACK_CHIN = 11959;
	private static final int VENATOR = 27610;
	private static final int ADAMANT_ARROW = 890;
	private static final int DRAGON_2H = 7158;
	private static final int DRAGON_CLAWS = 13652;
	private static final int BLOOD_RUNE = 565;
	private static final int DEATH_RUNE = 560;
	private static final int WATER_RUNE = 555;
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static Map<Style, Service.Pick> compute(String query, Map<Integer, Integer> owned, boolean multiView) throws Exception {
		return compute(query, owned, multiView, 3);
	}

	private static Map<Style, Service.Pick> compute(String query, Map<Integer, Integer> owned, boolean multiView, int stack) throws Exception {
		Monster mob = data.searchMonsters(query, 1).get(0);
		Service service = new Service(data);
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
		ComputeParams p = new ComputeParams();
		p.multiView = multiView;
		p.multiStack = stack;
		service.bestPerStyle(mob, Levels.MAXED, Levels.MAXED, Prayers.ALL,
			RequirementProfile.MAXED, new Owned(owned, true), 1, p,
			Collections.emptyMap(), Collections.emptySet(), Collections.emptyMap(), null, 0,
			Collections.<Integer>emptySet(), result -> {
				out.set(result);
				done.countDown();
			});
		assertTrue(done.await(120, TimeUnit.SECONDS), "compute timed out");
		return out.get();
	}

	private static Map<Integer, Integer> kit(boolean chins, boolean venator, boolean runes) {
		Map<Integer, Integer> owned = new HashMap<>();
		for (String name : new String[]{"rune scimitar", "rune full helm", "rune platebody", "rune platelegs",
			"ancient staff", "mystic robe top", "mystic robe bottom", "magic shortbow", "black d'hide body", "black d'hide chaps"}) {
			data.getGearItems().stream().filter(g -> g.getLname().equals(name) && g.isStandardGear())
				.findFirst().ifPresent(g -> owned.put(g.getId(), 1));
		}
		if (chins) {
			owned.put(BLACK_CHIN, 5000);
		}
		if (venator) {
			// The bow fires arrows (wiki: any arrow up to dragon); without
			// them the owned row is rightly empty.
			owned.put(VENATOR, 1);
			owned.put(ADAMANT_ARROW, 1000);
		}
		if (runes) {
			owned.put(BLOOD_RUNE, 1000);
			owned.put(DEATH_RUNE, 1000);
			owned.put(WATER_RUNE, 1000);
		}
		return owned;
	}

	private static Map<String, Service.Pick> tools(Map<Style, Service.Pick> results) {
		for (Service.Pick r : results.values()) {
			if (r.multiTools != null) {
				return r.multiTools;
			}
		}
		return null;
	}

	@Test
	@DisplayName("Greater Nechryaels with the switch on rank barrage, chins, the venator bow and Hallowfell, each a per-target set")
	void nechryaelsHaveThreeTools() throws Exception {
		Map<String, Service.Pick> tools = tools(compute("greater nechryael", kit(true, true, true), true));
		assertNotNull(tools, "the multi tools ride the results");
		assertEquals(4, tools.size(), "barrage, chins, venator and Hallowfell (ISS-01M5TPEWE9AQM3B55ZH02PHGE4)");
		assertEquals(MultiTool.HALLOWFELL_SWORD, tools.get(MultiTool.HALLOWFELL.key).overallBest.getLoadout().get(Slot.WEAPON).getId(), "the ceiling wields Hallowfell");
		Service.Pick barrage = tools.get(MultiTool.BARRAGE.key);
		assertEquals("Ice Barrage", barrage.owned.get(0).getSpellName(), "a maxed mage barrages");
		assertEquals(BLACK_CHIN, tools.get(MultiTool.CHINS.key).owned.get(0).getLoadout().get(Slot.WEAPON).getId());
		assertEquals(VENATOR, tools.get(MultiTool.VENATOR.key).owned.get(0).getLoadout().get(Slot.WEAPON).getId());
		assertEquals(VENATOR, tools.get(MultiTool.VENATOR.key).overallBest.getLoadout().get(Slot.WEAPON).getId(), "the ceiling wears it too");
	}

	@Test
	@DisplayName("a tool you do not own has no Yours side; the ceiling still shows it")
	void unownedToolHasNoYours() throws Exception {
		Map<String, Service.Pick> tools = tools(compute("greater nechryael", kit(true, false, true), true));
		assertNotNull(tools);
		assertTrue(tools.get(MultiTool.VENATOR.key).owned.isEmpty(), "no venator bow, no Yours row");
		assertNotNull(tools.get(MultiTool.VENATOR.key).overallBest);
		assertFalse(tools.get(MultiTool.CHINS.key).owned.isEmpty());
	}

	@Test
	@DisplayName("at a stack of nine the chins row's spec is the d2h over the claws; at one it is not (Andrew 2026-10-19)")
	void multiSpecAtTheStack() throws Exception {
		Map<Integer, Integer> owned = kit(true, false, false);
		owned.put(DRAGON_2H, 1);
		owned.put(DRAGON_CLAWS, 1);
		// At three the claws' four hits per 50% still edge three Powerstabs
		// per 60%; at nine the stack is decisive.
		Service.Pick atNine = tools(compute("greater nechryael", owned, true, 9)).get(MultiTool.CHINS.key);
		assertNotNull(atNine.specWeapon, "a spec rides the chins row");
		assertEquals(DRAGON_2H, atNine.specWeapon.getId(), "Powerstab hits the whole stack");
		Service.Pick atOne = tools(compute("greater nechryael", owned, true, 1)).get(MultiTool.CHINS.key);
		assertNotEquals(DRAGON_2H, atOne.specWeapon == null ? 0 : atOne.specWeapon.getId(), "one target: the claws win as ever");
	}

	@Test
	@DisplayName("the switch off, or a mob outside the multi list, computes no tools")
	void offOrNotMultiAble() throws Exception {
		assertNull(tools(compute("greater nechryael", kit(true, true, true), false)), "switch off");
		assertNull(tools(compute("vorkath", kit(true, true, true), true)), "Vorkath is single-way");
	}
}

package com.ll.optimizer;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.engine.CandidateMode;
import com.ll.engine.Style;
import com.ll.engine.Dps;
import com.ll.engine.Incoming;
import com.ll.engine.LoadoutOptimizer;
import com.ll.engine.Req;
import com.ll.engine.Owned;
import com.ll.engine.Levels;
import com.ll.engine.PrayerBonuses;
import com.ll.engine.Prayers;
import com.ll.engine.RequirementProfile;
import com.ll.engine.TestRequests;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The dev-mode defensive modes (ISS-01M5G5CZC9SK46499FACRSJ8ZT), Andrew's
 * definitions: Tanky = the minimum DTPS, Balanced = the best DTPS/DPS -
 * least damage taken per damage dealt. Graardor ranged is the July
 * reference case; the pool is every buyable item (budget, no bank).
 */
class OptimizeModeTest {
	private static Tables data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static Service.Pick run(String mob, Style style,
		Service.OptimizeMode mode) throws Exception {
		Monster monster = data.searchMonsters(mob, 1).get(0);
		Service service = new Service(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
			com.ll.engine.ComputeParams p = new com.ll.engine.ComputeParams();
			p.specWeapon = false;
			p.upgradeBudgetGp = 2_000_000_000;
			p.optimizeMode = mode.name();
			service.bestPerStyle(monster, Levels.MAXED, Levels.MAXED, Prayers.ALL,
				RequirementProfile.MAXED, Owned.EMPTY, 1, p,
				Collections.emptyMap(), Collections.emptySet(), Collections.emptyMap(), null, 0,
				Collections.<Integer>emptySet(), result -> {
					out.set(result);
					done.countDown();
				});
			assertTrue(done.await(300, TimeUnit.SECONDS), "compute finished");
			return out.get().get(style);
		} finally {
			service.shutdown();
		}
	}

	private static double dtps(String mob, Service.Pick result) {
		return Incoming.calculate(data.searchMonsters(mob, 1).get(0),
			result.owned.get(0).getLoadout(), 99, 99, 0).tot;
	}

	@Test
	@DisplayName("a defense-weighted beam can pick pure-defence gear (ring of suffering over archers ring)")
	void weightedBeamSeesDefenceGear() {
		Monster graardor = data.searchMonsters("general graardor", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(861, 1);    // magic shortbow
		owned.put(892, 500);  // rune arrows
		owned.put(11771, 1);  // archers ring (i)
		owned.put(19710, 1);  // ring of suffering (i)
		Req base = TestRequests.of(graardor, Style.RANGED, Levels.MAXED,
			PrayerBonuses.bestAvailable(Levels.MAXED, Prayers.ALL), null, 0,
			CandidateMode.OWNED_ONLY, true, false, new Owned(data.canonicalizeOwned(owned), true), 1);
		LoadoutOptimizer optimizer = new LoadoutOptimizer();
		Gear offence = optimizer.optimize(data, base).get(0).getLoadout().get(Slot.RING);
		Dps tanky = optimizer.optimize(data, base.withDefenseWeight(50)).get(0);
		assertEquals("Archers ring (i)", offence.getName());
		assertEquals("Ring of suffering (i)", tanky.getLoadout().get(Slot.RING).getName());
	}

	@Test
	@DisplayName("Tanky takes the least damage, Balanced has the best DTPS/DPS, Max DPS deals the most")
	void modesHonourTheirObjectives() throws Exception {
		String mob = "general graardor";
		Service.Pick max = run(mob, Style.RANGED, Service.OptimizeMode.MAX_DPS);
		Service.Pick balanced = run(mob, Style.RANGED, Service.OptimizeMode.BALANCED);
		Service.Pick tanky = run(mob, Style.RANGED, Service.OptimizeMode.TANKY);
		assertNull(max.modeTrade, "Max DPS makes no trade");
		double dMax = max.owned.get(0).getDps();
		assertTrue(dMax >= balanced.owned.get(0).getDps() - 1e-9);
		assertTrue(dMax >= tanky.owned.get(0).getDps() - 1e-9);
		assertTrue(dtps(mob, tanky) <= dtps(mob, max) + 1e-9);
		assertTrue(dtps(mob, tanky) <= dtps(mob, balanced) + 1e-9);
		double rMax = dtps(mob, max) / dMax;
		double rBalanced = dtps(mob, balanced) / balanced.owned.get(0).getDps();
		double rTanky = dtps(mob, tanky) / tanky.owned.get(0).getDps();
		assertTrue(rBalanced <= rMax + 1e-9, "Balanced's DTPS/DPS beats Max DPS's");
		assertTrue(rBalanced <= rTanky + 1e-9, "and Tanky's");
		assertTrue(dtps(mob, tanky) < dtps(mob, max) - 1e-6, "Graardor ranged has a real trade to make");
		assertNotNull(tanky.modeTrade);
		assertNull(tanky.modeTrade.reason);
		assertTrue(tanky.modeTrade.dmgCutPct > 0, "the card can show the damage cut");
		assertTrue(tanky.modeTrade.dpsLossPct >= 0, "and the DPS cost");
		assertEquals(Service.OptimizeMode.TANKY, tanky.modeTrade.mode);
	}

	@Test
	@DisplayName("a partly modeled monster keeps Max DPS and says why")
	void partialCoverageKeepsMaxDps() throws Exception {
		Service.Pick max = run("blue dragon", Style.MELEE, Service.OptimizeMode.MAX_DPS);
		Service.Pick tanky = run("blue dragon", Style.MELEE, Service.OptimizeMode.TANKY);
		assertNotNull(tanky.modeTrade);
		assertEquals("partial damage data", tanky.modeTrade.reason);
		assertEquals(max.owned.get(0).getDps(), tanky.owned.get(0).getDps(), 1e-9);
	}

	@Test
	@DisplayName("when the max-DPS set takes ~0 damage, every mode keeps it")
	void zeroDamageKeepsMaxDps() throws Exception {
		// One magic attack, prayed off entirely.
		Service.Pick max = run("aberrant spectre", Style.MELEE, Service.OptimizeMode.MAX_DPS);
		Service.Pick balanced = run("aberrant spectre", Style.MELEE, Service.OptimizeMode.BALANCED);
		assertNotNull(balanced.modeTrade);
		assertEquals("takes ~0 damage", balanced.modeTrade.reason);
		assertEquals(max.owned.get(0).getDps(), balanced.owned.get(0).getDps(), 1e-9);
	}
}

package com.ll.optimizer;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.engine.Style;
import com.ll.engine.Req;
import com.ll.engine.Owned;
import com.ll.engine.Levels;
import com.ll.engine.RequirementProfile;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Assert;
import org.junit.Test;

public class OptimizerServiceTest {
	@Test
	public void defenceDrainMakesTheWarhammerTheSpecPickOnTankyBosses() throws Exception {
		Tables data = new DataService().load();
		// Dagannoth Rex (255 defence, 255 hp; not a GWD boss, whose carried
		// god protection would take the one Inventory slot): a drain pays off over the
		// whole kill, so the warhammer wins. A fire giant (120 defence, 130
		// hp) dies before a drain earns back its lost hits, so the dagger's
		// burst wins. A goblin dies in one attack - no spec beats just
		// attacking, so none is carried (value-over-replacement).
		Monster rex = data.searchMonsters("dagannoth rex", 1).get(0);
		Monster fireGiant = data.searchMonsters("fire giant", 1).get(0);
		Monster goblin = data.searchMonsters("goblin", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1);   // whip - main weapon
		owned.put(1215, 1);   // dragon dagger - burst spec
		owned.put(13576, 1);  // dragon warhammer - drain spec
		// Super combat potion: this scenario's "a goblin dies in one attack"
		// premise depends on the boosted max hit. Boosts now gate on ownership
		// (2026-08-25), so the bank has to actually hold the potion the test
		// assumes - otherwise the goblin survives and a spec DOES pay.
		owned.put(12695, 1);
		Service service = new Service(data);
		try {
			Assert.assertEquals("Dragon warhammer", specPick(service, rex, owned));
			Assert.assertEquals("Dragon dagger", specPick(service, fireGiant, owned));
			Assert.assertNull("a one-hit kill is not worth a spec slot",
				specPick(service, goblin, owned));
		} finally {
			service.shutdown();
		}
	}

	@Test
	public void togglingAConditionMidLoadAbandonsTheStaleComputationAndDeliversTheNewOne() throws Exception {
		Tables data = new DataService().load();
		Monster graardor = data.searchMonsters("general graardor", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1); // abyssal whip
		Service service = new Service(data);
		try {
			CountDownLatch fresh = new CountDownLatch(1);
			java.util.concurrent.atomic.AtomicInteger staleDelivered = new java.util.concurrent.atomic.AtomicInteger();
			// Stale request (off-task), immediately superseded by the toggle.
			com.ll.optimizer.ServiceCalls.bestPerStyle(service, graardor, Levels.MAXED, Levels.MAXED,
				com.ll.engine.Prayers.ALL, RequirementProfile.MAXED,
				new Owned(owned, true), owned.hashCode(), false, false, "",
				java.util.Collections.emptySet(), -1, Req.DEFAULT_RISK_BUDGET_GP, false, java.util.Collections.emptySet(), 0, results -> staleDelivered.incrementAndGet());
			// The toggle: same monster, on-task, fired before the stale run ends.
			com.ll.optimizer.ServiceCalls.bestPerStyle(service, graardor, Levels.MAXED, Levels.MAXED,
				com.ll.engine.Prayers.ALL, RequirementProfile.MAXED,
				new Owned(owned, true), owned.hashCode(), false, true, "",
				java.util.Collections.emptySet(), -1, Req.DEFAULT_RISK_BUDGET_GP, false, java.util.Collections.emptySet(), 0, results -> fresh.countDown());
			Assert.assertTrue(fresh.await(120, TimeUnit.SECONDS));
			Assert.assertEquals("the superseded request must never deliver", 0, staleDelivered.get());
		} finally {
			service.shutdown();
		}
	}

	private static String specPick(Service service, Monster monster,
		Map<Integer, Integer> owned) throws Exception {
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
		com.ll.optimizer.ServiceCalls.bestPerStyle(service, monster, Levels.MAXED, Levels.MAXED, com.ll.engine.Prayers.ALL, RequirementProfile.MAXED,
			new Owned(owned, true), owned.hashCode(), false, false, "", java.util.Collections.emptySet(), -1, Req.DEFAULT_RISK_BUDGET_GP, false, java.util.Collections.emptySet(), 0, results -> {
				out.set(results);
				done.countDown();
			});
		Assert.assertTrue(done.await(120, TimeUnit.SECONDS));
		Service.Pick melee = out.get().get(Style.MELEE);
		// A spec that adds nothing over just attacking is not carried (the
		// value-over-replacement model): null means "no spec worth a slot".
		return melee == null || melee.spec == null ? null : melee.spec.getDisplayName();
	}

	@Test
	public void pinningOneStyleReusesTheOtherStylesCachedAnswers() throws Exception {
		Tables data = new DataService().load();
		Monster goblin = data.searchMonsters("goblin", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1); // abyssal whip
		owned.put(1215, 1); // dragon dagger - a pinnable melee weapon
		Service service = new Service(data);
		try {
			Map<Style, Service.Pick> first =
				resultsFor(service, goblin, owned, java.util.Collections.emptyMap());
			// Pin the dagger for MELEE only: the ranged and magic answers are
			// unchanged queries and must come back as the SAME cached objects,
			// not fresh recomputes.
			Map<Style, Map<com.ll.data.Slot, Integer>> pins =
				java.util.Map.of(Style.MELEE,
					java.util.Map.of(com.ll.data.Slot.WEAPON, 1215));
			Map<Style, Service.Pick> pinned =
				resultsFor(service, goblin, owned, pins);
			Assert.assertSame("ranged must be the cached result",
				first.get(Style.RANGED), pinned.get(Style.RANGED));
			Assert.assertSame("magic must be the cached result",
				first.get(Style.MAGIC), pinned.get(Style.MAGIC));
			Assert.assertNotSame("melee must be recomputed around the pin",
				first.get(Style.MELEE), pinned.get(Style.MELEE));
			Assert.assertEquals("the pin must be honored", 1215,
				pinned.get(Style.MELEE).owned.get(0).getLoadout().getWeapon().getId());
		} finally {
			service.shutdown();
		}
	}

	private static Map<Style, Service.Pick> resultsFor(
		Service service, Monster monster, Map<Integer, Integer> owned,
		Map<Style, Map<com.ll.data.Slot, Integer>> pins) throws Exception {
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
		com.ll.optimizer.ServiceCalls.bestPerStyle(service, monster, Levels.MAXED, Levels.MAXED,
			com.ll.engine.Prayers.ALL, RequirementProfile.MAXED,
			new Owned(owned, true), 1, false, false, "",
			java.util.Collections.emptySet(), -1, Req.DEFAULT_RISK_BUDGET_GP,
			false, java.util.Collections.emptySet(), 0, 			pins, null, results -> {
				out.set(results);
				done.countDown();
			});
		Assert.assertTrue(done.await(120, TimeUnit.SECONDS));
		return out.get();
	}

	@Test
	public void aStyleScopedExclusionRecomputesOnlyThatStyle() throws Exception {
		Tables data = new DataService().load();
		Monster goblin = data.searchMonsters("goblin", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1); // abyssal whip
		owned.put(1333, 1); // rune scimitar - the fallback once the whip is excluded
		Service service = new Service(data);
		try {
			Map<Style, Set<Integer>> none = uniformExclusions(java.util.Collections.emptySet());
			Map<Style, Service.Pick> first =
				resultsForExcluding(service, goblin, owned, none);
			Assert.assertEquals("whip wins melee before the exclusion", 4151,
				first.get(Style.MELEE).owned.get(0).getLoadout().getWeapon().getId());

			// Exclude the whip for the MELEE card only: ranged and magic are
			// unchanged queries and must come back as the same cached objects.
			Map<Style, Set<Integer>> meleeOnly = uniformExclusions(java.util.Collections.emptySet());
			meleeOnly.put(Style.MELEE, Set.of(4151));
			Map<Style, Service.Pick> excluded =
				resultsForExcluding(service, goblin, owned, meleeOnly);
			Assert.assertNotEquals("the melee card must drop the excluded whip", 4151,
				excluded.get(Style.MELEE).owned.get(0).getLoadout().getWeapon().getId());
			Assert.assertSame("ranged must be the cached result",
				first.get(Style.RANGED), excluded.get(Style.RANGED));
			Assert.assertSame("magic must be the cached result",
				first.get(Style.MAGIC), excluded.get(Style.MAGIC));
		} finally {
			service.shutdown();
		}
	}

	private static Map<Style, Set<Integer>> uniformExclusions(Set<Integer> set) {
		Map<Style, Set<Integer>> byStyle = new java.util.EnumMap<>(Style.class);
		for (Style style : Style.concreteValues()) {
			byStyle.put(style, set);
		}
		return byStyle;
	}

	private static Map<Style, Service.Pick> resultsForExcluding(
		Service service, Monster monster, Map<Integer, Integer> owned,
		Map<Style, Set<Integer>> excludedByStyle) throws Exception {
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
		com.ll.optimizer.ServiceCalls.bestPerStyle(service, monster, Levels.MAXED, Levels.MAXED,
			com.ll.engine.Prayers.ALL, RequirementProfile.MAXED,
			new Owned(owned, true), 1, false, false, "",
			excludedByStyle, -1, Req.DEFAULT_RISK_BUDGET_GP,
			false, false, java.util.Collections.emptySet(), 0, 			java.util.Collections.emptyMap(), null, java.util.Collections.emptySet(), results -> {
				out.set(results);
				done.countDown();
			});
		Assert.assertTrue(done.await(120, TimeUnit.SECONDS));
		return out.get();
	}

	@Test
	public void crossStyleSpecWeaponsCompeteOnEverySet() throws Exception {
		// Field request 2026-07-17: "sometimes you want to use magic +
		// chally" - the spec swap is its own weapon switch, so a MELEE
		// spec weapon must surface on the MAGIC set when it is the best
		// special owned. Owned: a trident (the magic set) + a dragon
		// dagger (melee spec) and nothing else spec-worthy.
		Tables data = new DataService().load();
		Monster monster = data.searchMonsters("ankou", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(11907, 1);  // trident of the seas
		owned.put(1215, 1);   // dragon dagger
		Service service = new Service(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
			com.ll.optimizer.ServiceCalls.bestPerStyle(service, monster, Levels.MAXED, Levels.MAXED,
				com.ll.engine.Prayers.ALL, RequirementProfile.MAXED,
				new Owned(owned, true), 1, false, false, "",
				java.util.Collections.emptySet(), -1,
				Req.DEFAULT_RISK_BUDGET_GP,
				false, java.util.Collections.emptySet(), 0,
								java.util.Collections.emptyMap(), null, results -> {
					out.set(results);
					done.countDown();
				});
			Assert.assertTrue(done.await(120, TimeUnit.SECONDS));
			Service.Pick magic = out.get().get(Style.MAGIC);
			Assert.assertNotNull(magic);
			Assert.assertFalse("premise: the trident set exists", magic.owned.isEmpty());
			Assert.assertNotNull("the melee dagger specs for the magic set", magic.spec);
			Assert.assertEquals(1215, magic.specWeapon.getId());
			Assert.assertTrue(magic.specExpectedDamage > 0);
		} finally {
			service.shutdown();
		}
	}

	@Test
	public void ownedSpecWeaponSurfacesOnTheStyleResult() throws Exception {
		Tables data = new DataService().load();
		// A fire giant, not a goblin: enough HP that a spec earns its slot
		// (a goblin dies in one hit, so the value model carries no spec).
		Monster monster = data.searchMonsters("fire giant", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1);   // abyssal whip - the sustained-DPS weapon
		owned.put(1215, 1);   // dragon dagger - the spec weapon
		Service service = new Service(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<Style, Service.Pick>> out = new AtomicReference<>();
			com.ll.optimizer.ServiceCalls.bestPerStyle(service, monster, Levels.MAXED, Levels.MAXED, com.ll.engine.Prayers.ALL, RequirementProfile.MAXED,
				new Owned(owned, true), 1, false, false, "", java.util.Collections.emptySet(), -1, Req.DEFAULT_RISK_BUDGET_GP, false, java.util.Collections.emptySet(), 0, results -> {
					out.set(results);
					done.countDown();
				});
			Assert.assertTrue(done.await(60, TimeUnit.SECONDS));

			Service.Pick melee = out.get().get(Style.MELEE);
			Assert.assertNotNull(melee);
			Assert.assertFalse(melee.owned.isEmpty());
			// The whip wins sustained DPS; the dagger is still surfaced as
			// the spec weapon with a positive expected special-attack hit.
			Assert.assertNotNull(melee.spec);
			Assert.assertEquals("Dragon dagger", melee.spec.getDisplayName());
			Assert.assertEquals(1215, melee.specWeapon.getId());
			Assert.assertTrue(melee.specExpectedDamage > 0);
			// The win-over-replacement value is surfaced and positive.
			Assert.assertTrue("the spec must add positive dps to be carried",
				melee.sda > 0);
			// The game-best section carries its own spec - the strongest
			// special attack that exists, regardless of ownership.
			Assert.assertNotNull(melee.gameSpec);
			Assert.assertNotNull(melee.gameSpecWeapon);
			Assert.assertTrue(melee.gameSpecExpectedDamage >= melee.specExpectedDamage);
			// Both sides of the Yours|BiS toggle carry their own defensive
			// story - the BiS DTPS is computed vs the BiS armour, not yours.
			Assert.assertNotNull(melee.incoming);
			Assert.assertNotNull(melee.gameIncoming);
			Assert.assertTrue(melee.gameIncoming.unprayedDps > 0);
		} finally {
			service.shutdown();
		}
	}
}

