        Monster mob = data.getMonsters().stream()
            .filter(m -> m.getName().equalsIgnoreCase("Crazy archaeologist")).findFirst().orElseThrow(AssertionError::new);
        var done = new CompletableFuture<Map<Style, Service.Pick>>();
