		owned.put(13576, 1);  // dragon warhammer
		for (Gear g : data.getGearItems()) {
			if ((g.getLname().equals("ring of dueling")
				|| g.getLname().equals("lightbearer")) && g.isStandardGear()) {
				owned.put(g.getId(), 1);
