	private static com.ll.data.MonsterGroups.MonsterGroup tdGroup(Tables data) {
		return com.ll.data.MonsterGroups.load(data).stream()
			.filter(g -> g.getName().equals("Tormented Demons"))
			.findFirst().orElseThrow(() -> new AssertionError("no TD group"));
	}

	/** The style a result's attack-type string rolls under. */
	private static Style styleOfAttack(String attackType) {
		if (attackType != null && attackType.startsWith("ranged")) {
			return Style.RANGED;
		}
		if (attackType != null && attackType.startsWith("magic")) {
			return Style.MAGIC;
		}
		return Style.MELEE;
	}

	@Test
	public void benchCarriesThePerMobSwap() throws Exception {
		// The bench (default 1, no spec weapon owned -> a free swap slot):
		// Vorkath (750hp, undead) anchors the shared neck to the salve;
		// the goblin's better neck (torture) should ride the BENCH and be
		// WORN only against the goblin - per-mob combinations over one
		// carried kit.
		Tables data = new DataService().load();
		Monster vorkath = data.searchMonsters("vorkath", 1).get(0);
		Monster goblin = data.searchMonsters("goblin", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1);   // abyssal whip
		owned.put(12018, 1);  // salve amulet(ei)
		owned.put(19553, 1);  // amulet of torture
		Service service = new Service(data);
		try {
			RosterResultView roster = run(service, Arrays.asList(vorkath, goblin), owned);
			Service.Pick vsVorkath = roster.result.pm.get(0).get(Style.MELEE);
			Service.Pick vsGoblin = roster.result.pm.get(1).get(Style.MELEE);
			Gear vorkathNeck = vsVorkath.owned.get(0).getLoadout().get(Slot.NECK);
			Gear goblinNeck = vsGoblin.owned.get(0).getLoadout().get(Slot.NECK);
			Assert.assertEquals("the 750hp undead anchors the salve",
				"salve amulet(ei)", vorkathNeck.getLname());
			Assert.assertEquals("the goblin wears the benched torture",
				"amulet of torture", goblinNeck.getLname());
			// The bench is a per-mob BACKPACK: it holds what is NOT worn -
			// the torture waits vs Vorkath, the displaced salve vs the
			// goblin, and a worn item never duplicates into it.
			Assert.assertTrue("the torture waits on the bench vs Vorkath",
				vsVorkath.bench.stream().anyMatch(i -> i.getId() == 19553));
			Assert.assertTrue(vsVorkath.bench.stream().noneMatch(i -> i.getId() == 12018));
			Assert.assertTrue("the displaced salve rides the bench vs the goblin",
				vsGoblin.bench.stream().anyMatch(i -> i.getId() == 12018));
			Assert.assertTrue(vsGoblin.bench.stream().noneMatch(i -> i.getId() == 19553));
		} finally {
			service.shutdown();
		}
	}

	/** Thin holder so the helper can return the typed roster result. */
	private static final class RosterResultView {
		final Service.RosterResult result;

		RosterResultView(Service.RosterResult result) {
			this.result = result;
		}
	}
}

package com.ll.optimizer;

import com.ll.data.DataService;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.data.Spell;
import com.ll.engine.Style;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

/** A mixed roster reads each member's OWN pins (ISS-01M4Y2VJ8DWBBKFR1HP9NR45NG).
 * Apathy (Discord, 2026-10-09): "Pinning a new spell sdhould change the
 * spell of the set." Until this issue computeRoster handed the optimizer
 * the FIRST member's pins, pinned spell and pinned spec for everyone. */
class RosterPinsTest {
	private static final int WHIP = 4151;
	private static final int DRAGON_SCIMITAR = 4587;
	private static Tables data;
	private static Monster graardor;
	private static Monster fireGiant;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		graardor = data.searchMonsters("general graardor", 1).get(0);
		fireGiant = data.searchMonsters("fire giant", 1).get(0);
	}

	@Test
	@DisplayName("a spell pinned on the second member's profile is cast against that member only")
	void spellPinnedOnTheSecondMember() throws Exception {
		Spell fireBolt = spell("Fire Bolt");
		Map<Integer, Spell> spellOf =
			Collections.singletonMap(fireGiant.profileId(), fireBolt);
		Service service = new Service(data);
		try {
			Service.RosterResult roster = ServiceCalls.runRosterPinned(service,
				Arrays.asList(graardor, fireGiant), owned(), 1,
				Collections.emptyMap(), spellOf, Collections.emptyMap());
			assertEquals("Fire Bolt", spellAgainst(roster, 1), "the fire giant's magic set casts the pin");
			assertNotEquals("Fire Bolt", spellAgainst(roster, 0), "Graardor's magic set keeps its own spell");
		} finally {
			service.shutdown();
		}
	}

	@Test
	@DisplayName("an item pinned on the second member's weapon slot is worn against that member only")
	void itemPinnedOnTheSecondMember() throws Exception {
		Map<Slot, Integer> weapon = new EnumMap<>(Slot.class);
		weapon.put(Slot.WEAPON, DRAGON_SCIMITAR);
		Map<Style, Map<Slot, Integer>> melee = new EnumMap<>(Style.class);
		melee.put(Style.MELEE, weapon);
		Map<Integer, Map<Style, Map<Slot, Integer>>> pinsByMob =
			Collections.singletonMap(fireGiant.profileId(), melee);
		Service service = new Service(data);
		try {
			Service.RosterResult roster = ServiceCalls.runRosterPinned(service,
				Arrays.asList(graardor, fireGiant), owned(), 1,
				pinsByMob, Collections.emptyMap(), Collections.emptyMap());
			assertEquals(DRAGON_SCIMITAR, weaponAgainst(roster, 1), "the fire giant wears the pin");
			assertEquals(WHIP, weaponAgainst(roster, 0), "Graardor keeps the whip");
		} finally {
			service.shutdown();
		}
	}

	private static Map<Integer, Integer> owned() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(WHIP, 1);
		owned.put(DRAGON_SCIMITAR, 1);
		owned.put(1387, 1);     // staff of fire
		owned.put(12002, 1);    // occult necklace
		owned.put(554, 1000);   // fire
		owned.put(562, 1000);   // chaos
		owned.put(560, 1000);   // death
		owned.put(565, 1000);   // blood
		return owned;
	}

	private static Spell spell(String name) {
		return data.getSpells().stream().filter(s -> s.getName().equals(name))
			.findFirst().orElseThrow();
	}

	private static String spellAgainst(Service.RosterResult roster, int member) {
		return roster.pm.get(member).get(Style.MAGIC).owned.get(0).getSpellName();
	}

	private static int weaponAgainst(Service.RosterResult roster, int member) {
		return roster.pm.get(member).get(Style.MELEE).owned.get(0)
			.getLoadout().get(Slot.WEAPON).getId();
	}
}

package com.ll.optimizer;

import com.ll.data.DataService;
import com.ll.data.Gear;
import com.ll.data.Slot;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.engine.Style;
import com.ll.engine.Dps;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

/**
 * No answer may wear a shield under a two-handed weapon - anywhere.
 * Field report 2026-08-15 (twice): the Moons of Peril roster's Eclipse
 * Moon BiS wore Scythe of vitur WITH an Avernic defender. The
 * birthplace was the kit pass's slot unification (withSlot carries no
 * 2h guard), with a second hole in the dps-neutral utility swap; this
 * test walks EVERY set the roster answer publishes.
 */
public class RosterSlotLegalityTest {
	@Test
	public void moonsRosterNeverWearsAShieldUnderATwoHander() throws Exception {
		Tables data = new DataService().load();
		List<Monster> moons = List.of(
			data.searchMonsters("blood moon", 1).get(0),
			data.searchMonsters("blue moon", 1).get(0),
			data.searchMonsters("eclipse moon", 1).get(0));
		Service service = new Service(data);
		Service.RosterResult roster = ServiceCalls.runRoster(
			service, moons, Collections.emptyMap(), 3, Collections.emptyMap());
		Assert.assertNotNull(roster);
		int checked = 0;
		for (int i = 0; i < roster.mobs.size(); i++) {
			Map<Style, Service.Pick> styles = roster.pm.get(i);
			for (Map.Entry<Style, Service.Pick> e : styles.entrySet()) {
				Service.Pick result = e.getValue();
				if (result.overallBest != null) {
					assertLegal(roster.mobs.get(i), e.getKey(), "BiS", result.overallBest);
					checked++;
				}
				if (result.owned != null && !result.owned.isEmpty()) {
					assertLegal(roster.mobs.get(i), e.getKey(), "Yours", result.owned.get(0));
					checked++;
				}
			}
		}
		Assert.assertTrue("the roster answered something", checked > 0);
	}

	private static void assertLegal(Monster mob, Style style,
		String side, Dps result) {
		Gear weapon = result.getLoadout().getWeapon();
		Gear shield = result.getLoadout().get(Slot.SHIELD);
		if (weapon != null && weapon.isTwoh()) {
			Assert.assertNull(mob.label() + " " + style + " " + side + " wears "
					+ weapon.label() + " (two-handed) WITH " + (shield == null ? "" : shield.label()),
				shield);
		}
	}
}

package com.ll.optimizer;

import com.ll.data.DataService;
import com.ll.data.Tables;
import com.ll.data.Monster;
import com.ll.engine.Style;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

/**
 * Field report 2026-08-05: the Abyssal Sire roster (Respiratory system +
 * Phase 1 + Phase 3) rendered "-" for the ranged and magic style buttons
 * while every member answers all three styles when searched alone. A dash
 * means the style's Pick is absent for the lensed mob, which the
 * roster path only produces when a whole style came back empty - so this
 * pins the invariant: any style a mob can answer alone, it must also
 * answer inside a roster.
 */
public class RosterStyleCoverageTest {
	/** A style-complete midgame kit: one real weapon per style plus
	 * enough armour that every optimize has genuine candidates. */
	private static Map<Integer, Integer> styleCompleteKit() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1);   // abyssal whip
		owned.put(12926, 1);  // toxic blowpipe (charged)
		owned.put(11907, 1);  // trident of the seas
		owned.put(11832, 1);  // bandos chestplate
		owned.put(11834, 1);  // bandos tassets
		owned.put(10828, 1);  // helm of neitiznot
		owned.put(6585, 1);   // amulet of fury
		owned.put(11840, 1);  // dragon boots
		owned.put(2503, 1);   // black d'hide body
		owned.put(2497, 1);   // black d'hide chaps
		owned.put(4091, 1);   // mystic robe top
		owned.put(4093, 1);   // mystic robe bottom
		return owned;
	}

	@Test
	public void everyStyleASingleAnswersSurvivesTheRoster() throws Exception {
		Tables data = new DataService().load();
		Monster vents = data.searchMonsters("respiratory system", 1).get(0);
		Monster phase1 = sire(data, "Phase 1");
		Monster phase3 = sire(data, "Phase 3 (stage 2)");
		List<Monster> mobs = new ArrayList<>(List.of(vents, phase1, phase3));

		Service service = new Service(data);
		// The shared client-call harness, at the screenshot's Inventory: 3.
		Service.RosterResult roster = ServiceCalls.runRoster(
			service, mobs, styleCompleteKit(), 3, Collections.emptyMap());
		Assert.assertNotNull("roster returned null (superseded?)", roster);

		for (int j = 0; j < mobs.size(); j++) {
			Map<Style, Service.Pick> byStyle = roster.pm.get(j);
			for (Style style : Style.concreteValues()) {
				Service.Pick sr = byStyle.get(style);
				Assert.assertNotNull(
					mobs.get(j).label() + " lost its " + style + " answer inside the roster"
						+ " (fine alone, dash in the roster - the field bug)",
					sr);
				if (style != Style.MELEE) {
					Assert.assertFalse(
						mobs.get(j).label() + " " + style + " owned list is empty in the roster",
						sr.owned == null || sr.owned.isEmpty());
				}
			}
		}
	}

	@Test
	public void fallbackAnswersNeverMasqueradeAsKitAnswers() throws Exception {
		// Inventory 1: the kit carries at most one cross-style weapon, so at
		// least one style per mob must be a tab-only fallback. The dash fix
		// keeps that style's numbers visible; the kitBacked flag keeps it
		// out of the mob row (field bug 2026-08-06: the vents row showed a
		// whole ranged set on a melee kit).
		Tables data = new DataService().load();
		Monster vents = data.searchMonsters("respiratory system", 1).get(0);
		Monster phase1 = sire(data, "Phase 1");
		List<Monster> mobs = new ArrayList<>(List.of(vents, phase1));

		Service service = new Service(data);
		Service.RosterResult roster = ServiceCalls.runRoster(
			service, mobs, styleCompleteKit(), 1, Collections.emptyMap());
		Assert.assertNotNull(roster);

		for (int j = 0; j < mobs.size(); j++) {
			boolean anyKitBacked = false;
			boolean anyFallbackWithNumbers = false;
			for (Service.Pick sr : roster.pm.get(j).values()) {
				if (sr == null) {
					continue;
				}
				anyKitBacked |= sr.okb;
				anyFallbackWithNumbers |= !sr.okb
					&& sr.owned != null && !sr.owned.isEmpty();
			}
			Assert.assertTrue(mobs.get(j).label()
				+ " has no kit-backed style at all - the row would have nothing honest to show",
				anyKitBacked);
			Assert.assertTrue(mobs.get(j).label()
				+ " kept no fallback numbers - the style tabs would dash again",
				anyFallbackWithNumbers);
		}
	}

	private static Monster sire(Tables data, String version) {
		return data.searchMonsters("abyssal sire", 6).stream()
			.filter(m -> version.equals(m.getVersion()))
			.findFirst().orElseThrow(() -> new AssertionError("missing Sire " + version));
	}
}

