/**
 * The style strip wraps (ISS-01M5TS5CBHSDS00XQSQYJ19XW8, Andrew 2026-10-25: "i
 * don't see a hallowfeell dps option only magic, venator, chins"): four 64 px
 * tabs are wider than the side panel, and a plain FlowLayout lays the last one
 * out past the edge.
 */
class StyleStripWrapTest {
	private static final int PANEL = 225;

	private static JPanel strip(int tabs) {
		JPanel strip = ResultCards.styleStrip();
		for (int i = 0; i < tabs; i++) {
			JPanel cell = new JPanel();
			cell.setPreferredSize(new Dimension(64, 26));
			strip.add(cell);
		}
		strip.setSize(PANEL, 200);
		strip.doLayout();
		return strip;
	}

	@Test
	@DisplayName("four tabs at the side panel's width all sit inside the strip")
	void fourTabsFit() {
		for (Component cell : strip(4).getComponents()) {
			assertTrue(cell.getX() + cell.getWidth() <= PANEL, "a tab at x=" + cell.getX() + " runs past " + PANEL);
		}
	}

	@Test
	@DisplayName("three tabs still share one row")
	void threeTabsOneRow() {
		Component[] cells = strip(3).getComponents();
		for (Component cell : cells) { assertEquals(cells[0].getY(), cell.getY()); }
	}
}

package com.ll.render;

import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/** Andrew, 2026-09-02: "too many different output numbers" on a sea
 * card - the row said 10.34, the trip total 17.98, the tab 18.38. One
 * ledger whose parts sum to the tab, with the row's number named. */
class TripLedgerTest {
	private static Map<String, Object> cannon(String tier, String who, double dps, String blocked) {
		Map<String, Object> c = new java.util.LinkedHashMap<>();
		c.put("tier", tier);
		c.put("firedBy", who);
		c.put("dps", dps);
		if (blocked != null) {
			c.put("blocked", blocked);
		}
		return c;
	}

	private static Map<String, Object> ship(String station, Map<String, Object>... cannons) {
		return Map.of("station", station, "cannons", List.of(cannons));
	}

	private static final Map<String, Object> SIDE = Map.of("dps", 9.94, "spec", Map.of("dpsAdded", 0.40));

	@Test
	@DisplayName("set, spec and cannons sum to the tab number; the gear line is the row's number")
	void sumsToTheTab() {
		String html = ResultCards.tripLedger(
			ship("helm", cannon("rune", "crew", 4.02, null), cannon("rune", "crew", 4.02, null)), SIDE, true);
		assertTrue(html.contains("18.38"), html);
		assertTrue(html.contains("10.34"), html);
		assertFalse(html.contains("17.98"), html);
		assertTrue(html.contains("rune, crew"), html);
	}

	@Test
	@DisplayName("a manned trip counts cannons only and says why the gear is not attacking")
	void manned() {
		String html = ResultCards.tripLedger(
			ship("cannon", cannon("rune", "player", 5.10, null), cannon("rune", "crew", 4.02, null)), SIDE, true);
		assertTrue(html.contains("manning"), html);
		assertTrue(html.contains("9.12"), html);
		assertFalse(html.contains("9.94"), html);
	}

	@Test
	@DisplayName("a blocked cannon shows its reason and adds nothing")
	void blocked() {
		String html = ResultCards.tripLedger(
			ship("helm", cannon("rune", "crew", 0, "Crew needs Privateering 40")), SIDE, true);
		assertTrue(html.contains("Crew needs Privateering 40"), html);
		assertTrue(html.contains("10.34"), html);
	}

	@Test
	@DisplayName("the collapsed ledger is the total line alone, and the total says total")
	void collapsedIsTheTotalOnly() {
		Map<String, Object> ship = ship("helm", cannon("rune", "crew", 4.02, null), cannon("rune", "crew", 4.02, null));
		String full = ResultCards.tripLedger(ship, SIDE, true);
		String collapsed = ResultCards.tripLedger(ship, SIDE, false);
		assertTrue(full.contains("= total") && !full.contains("= trip"), full);
		assertTrue(collapsed.contains("18.38"), collapsed);
		assertFalse(collapsed.contains("cannon 1"), collapsed);
		assertFalse(collapsed.contains("9.94"), collapsed);
		assertEquals(1, collapsed.split("<tr>").length - 1, "one row");
	}
}

package com.ll.render;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The surface's prose lives in text.tsv and is read by key (Ui.text): a key
 * the source names but the file lacks would render as "null" in a tooltip
 * nobody hovers in a test, so this pins the two to each other both ways.
 */
class UiTextTest {
	// Every main source: since slim 16 the model and engine read the table too.
	private static final Path RENDER = Paths.get("src/main/java/com/ll");

	/** Every key the render sources ask Ui.text for, with the file naming it:
	 * Ui.text("key"), or text("key") where Ui is statically imported. */
	private static List<String[]> referencedKeys() throws IOException {
		List<String[]> keys = new ArrayList<>();
		Pattern call = Pattern.compile("(?<![\\w.])(?:Ui\\.)?text\\(\"([^\"]+)\"\\)");
		try (Stream<Path> files = Files.walk(RENDER)) {
			for (Path file : (Iterable<Path>) files.filter(p -> p.toString().endsWith(".java"))::iterator) {
				Matcher m = call.matcher(new String(Files.readAllBytes(file), StandardCharsets.UTF_8));
				while (m.find()) {
					keys.add(new String[]{m.group(1), file.getFileName().toString()});
				}
			}
		}
		assertFalse(keys.isEmpty(), "no Ui.text(...) calls found under " + RENDER);
		return keys;
	}

	@Test
	@DisplayName("every key the source asks for resolves to a non-blank text")
	void everyReferencedKeyResolves() throws IOException {
		for (String[] key : referencedKeys()) {
			String text = Ui.text(key[0]);
			assertNotNull(text, key[1] + " asks for \"" + key[0] + "\", which text.tsv does not hold");
			assertFalse(text.isBlank(), key[0] + " is blank");
		}
	}

	@Test
	@DisplayName("every text.tsv key is asked for somewhere, so the file carries no dead prose")
	void everyKeyIsReferenced() throws IOException {
		Map<String, String> table = Ui.tsv("text.tsv");
		assertFalse(table.isEmpty(), "text.tsv missing or empty");
		TreeSet<String> referenced = new TreeSet<>();
		for (String[] key : referencedKeys()) {
			referenced.add(key[0]);
		}
		for (Map.Entry<String, String> row : table.entrySet()) {
			assertTrue(referenced.contains(row.getKey()), "text.tsv key \"" + row.getKey() + "\" is never asked for");
			// The tofu-glyph gate (scripts/check_glyphs.py) reads Java literals
			// only, so the file keeps itself to plain ASCII here.
			assertTrue(row.getValue().chars().allMatch(c -> c < 128), row.getKey() + " carries a non-ASCII glyph");
		}
	}

	@Test
	@DisplayName("the loader reads key-tab-value rows and skips comments, as the mood routes rely on")
	void loaderShape() {
		Map<String, String> routes = Ui.tsv("mood_routes.tsv");
		assertEquals("zulrah", routes.get("Zulrah"));
		assertFalse(routes.containsKey("# monster-name prefix -> compute-animation pool"), "comment lines skipped");
		assertTrue(Ui.tsv("no-such-file.tsv").isEmpty(), "a missing resource reads as empty, never throws");
	}
}

package com.ll.render;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/** Andrew 2026-09-02: the Wiki calc chip lost its "you will see this
 * number in their engine" line on cards without a spec or thrall fold.
 * The ledger is the subtext that says we know what they will show. */
class WikiCalcTipTest {
	@Test
	@DisplayName("the Wiki calc tooltip always names the set dps the calculator will show")
	void tipAlwaysCarriesTheLedger() {
		Map<String, Object> yours = new LinkedHashMap<>();
		yours.put("dps", 6.344);
		Map<String, Object> melee = new LinkedHashMap<>();
		melee.put("yours", yours);
		melee.put("tabDps", 6.344);
		Map<String, Object> styles = new LinkedHashMap<>();
		styles.put("melee", melee);
		Map<String, Object> mob = new LinkedHashMap<>();
		mob.put("styles", styles);
		Map<String, Object> params = new LinkedHashMap<>();
		params.put("lensIndex", 0);
		params.put("selectedTab", "melee");
		Map<String, Object> entry = new LinkedHashMap<>();
		entry.put("params", params);
		entry.put("mobs", List.of(mob));
		Map<String, Object> page = new LinkedHashMap<>();
		page.put("entries", List.of(entry));
		String tip = RenderSurface.wikiCalcTip(page);
		assertTrue(tip.contains("what the calc shows"), tip);
		assertTrue(tip.contains("6.344"), tip);
		assertFalse(tip.contains("Invocation"), "a land mob has no raid level line");
		// A ToA mob at the card's raid level says so (Andrew 2026-09-02).
		mob.put("invocationScaled", true);
		params.put("toaInvocation", 300);
		String toa = RenderSurface.wikiCalcTip(page);
		assertTrue(toa.contains("opens at Invocation 300"), toa);
	}
}

package com.ll.testsupport;

import java.util.HashMap;
import java.util.Map;
import net.runelite.client.config.ConfigManager;
import org.mockito.Mockito;

/**
 * A ConfigManager test double whose get/set/unsetConfiguration methods are
 * backed by an in-memory map - the same fake pattern proven on goal-planner:
 * real stores run against this instead of parallel fake store classes.
 */
public final class InMemoryConfigManager {
	private InMemoryConfigManager() {
	}

	public static ConfigManager create() {
		ConfigManager mock = Mockito.mock(ConfigManager.class);
		Map<String, String> store = new HashMap<>();

		Mockito.when(mock.getConfiguration(Mockito.anyString(), Mockito.anyString()))
			.thenAnswer(inv -> store.get(inv.getArgument(0) + "." + inv.getArgument(1)));
		// Stub the STRING overload specifically: javac resolves
		// setConfiguration(group, key, someString) to (String,String,String),
		// and a stub on the (String,String,Object) overload would not match it.
		Mockito.doAnswer(inv -> {
			store.put(inv.getArgument(0) + "." + inv.getArgument(1), inv.getArgument(2));
			return null;
		}).when(mock).setConfiguration(Mockito.anyString(), Mockito.anyString(), Mockito.anyString());
		Mockito.doAnswer(inv -> {
			store.remove(inv.getArgument(0) + "." + inv.getArgument(1));
			return null;
		}).when(mock).unsetConfiguration(Mockito.anyString(), Mockito.anyString());

		return mock;
	}
}

package com.ll.ui;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The thumbnail's wiki file name comes from the bundled corpus, never
 * from guessing at the wiki's naming conventions - that is what keeps a
 * monster picture to exactly ONE request. These exercise the resolution
 * against the real corpus; none of them touch the network.
 */
class MonsterIconsTest {
	private final MonsterIcons icons = new MonsterIcons(null);

	@Test
	@DisplayName("a versioned mob resolves to its own per-form picture")
	void perFormImage() {
		assertEquals("Abyssal demon (Catacombs of Kourend).png",
			icons.wikiFile("Abyssal demon", "Catacombs of Kourend"));
		assertEquals("Zulrah (magma).png", icons.wikiFile("Zulrah", "Magma"));
		assertEquals("Zulrah (tanzanite).png", icons.wikiFile("Zulrah", "Tanzanite"));
	}

	@Test
	@DisplayName("no version falls back to the plain picture when the mob has one")
	void plainPreferredForBareName() {
		// The corpus lists the Catacombs form FIRST, so first-wins would
		// hand a plain "abyssal demon" search the wrong picture.
		assertEquals("Abyssal demon.png", icons.wikiFile("Abyssal demon", ""));
		assertEquals("Vorkath.png", icons.wikiFile("Vorkath", ""));
	}

	@Test
	@DisplayName("no version and no plain picture falls back to a form")
	void formFallbackWhenNoPlainImage() {
		// Zulrah is only ever a coloured form - any of them beats no icon.
		assertTrue(icons.wikiFile("Zulrah", "").startsWith("Zulrah ("),
			"expected a Zulrah form image");
	}

	@Test
	@DisplayName("an unknown version falls back to the mob's picture")
	void unknownVersionFallsBack() {
		assertEquals("Vorkath.png", icons.wikiFile("Vorkath", "Not a real form"));
	}

	@Test
	@DisplayName("lookup is case-insensitive")
	void caseInsensitive() {
		assertEquals("Vorkath.png", icons.wikiFile("vORKATH", ""));
	}

	@Test
	@DisplayName("a mob the corpus does not name gets no request at all")
	void missResolvesToNull() {
		assertNull(icons.wikiFile("Definitely not a monster", ""));
	}
}

package com.ll.ui;

import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.assertFalse;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Properties;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The issue report's version is build-stamped from build.gradle via
 * processResources; runelite-plugin.properties is still hand-bumped at
 * release. This pins the two together so the desync class that shipped
 * "v0.3.3" reports from a 0.3.4 client (field report 2026-08-07) fails
 * the gate instead of reaching users.
 */
class VersionStampTest {
	@Test
	@DisplayName("the report's stamped version matches runelite-plugin.properties")
	void stampMatchesPluginProperties() throws Exception {
		Properties plugin = new Properties();
		plugin.load(Files.newInputStream(Path.of("runelite-plugin.properties")));
		String released = plugin.getProperty("version");
		assertNotNull(released, "runelite-plugin.properties must declare a version");
		assertEquals(released, com.ll.PluginVersion.VERSION,
			"build.gradle's version (the stamp) and runelite-plugin.properties"
				+ " have drifted - bump them together");
		assertNotEquals("unknown", com.ll.PluginVersion.VERSION,
			"the stamped resource must be readable at runtime");
	}

	@Test
	@DisplayName("hub builds never show ${version}: the source fallback matches build.gradle and the stamp is never a placeholder")
	void fallbackMatchesBuild() throws Exception {
		String gradle = java.nio.file.Files.readString(java.nio.file.Path.of("build.gradle"));
		java.util.regex.Matcher m = java.util.regex.Pattern.compile("version = '([^']+)'").matcher(gradle);
		assertTrue(m.find(), "build.gradle declares the version");
		assertEquals(m.group(1), com.ll.PluginVersion.FALLBACK, "bump FALLBACK with the release");
		assertFalse(com.ll.PluginVersion.VERSION.contains("${"), com.ll.PluginVersion.VERSION);
		assertEquals(com.ll.PluginVersion.FALLBACK, com.ll.PluginVersion.stamp("version=${version}"));
		assertEquals("9.9.9", com.ll.PluginVersion.stamp("version=9.9.9"));
	}
}
